package home

import (
	"encoding/base64"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// This file is shared, unchanged, by every Samouraï home realm.
//
// A gallery is a named list of cards. gnoweb's CSP only paints images from a
// few hosts (YouTube thumbnails are not among them) but it allows
// data:image/svg+xml, so every card is a poster drawn here, on chain, and
// linked to its video or site.
//
// A gallery is written in one Set-like call as lines of
//
//	kind | title | meta | url [| description]
//
// The optional description becomes the card's hover text.
// and rendered wherever the layout says :gallery.<name>:.

const (
	galleryPrefix = "gallery."
	cardsPerRow   = 3
	maxCards      = 48
	maxTitleLen   = 80
	maxMetaLen    = 80
	maxDescLen    = 200
)

type card struct {
	kind, title, meta, url string
	desc                   string // hover text, optional
	label                  string // overrides the kind's label when set
}

var galleries = avl.NewTree() // name -> []card

type style struct {
	label, glyph, accent, shade string
	video                       bool
}

var styles = map[string]style{
	"report":        {"CONTRIBUTION REPORT", "報", "#e63946", "#3a1014", true},
	"gno":           {"GNO.LAND · FILMED BY SAMOURAÏ", "道", "#2ec4b6", "#0d2e2b", true},
	"webtrip":       {"WEB TRIP · SERIES", "旅", "#ff7aa2", "#3a1422", true},
	"peerdev":       {"PEER DEV · GNO TUTORIAL", "学", "#4ea8de", "#0f2536", true},
	"event":         {"EVENT", "祭", "#f4a261", "#3a2412", true},
	"festival":      {"FESTIVAL · BY SAMOURAÏ", "祭", "#f4a261", "#3a2412", false},
	"film":          {"FILM · DIRECTED BY THE CREW", "映", "#b388eb", "#261a36", true},
	"product":       {"PRODUCT", "作", "#e9c46a", "#352b10", false},
	"memba":         {"MEMBA · PRODUCT", "組", "#e9c46a", "#352b10", false},
	"game":          {"ARCADE · PLAY IN MEMBA", "遊", "#8ac926", "#1c2a0b", true},
	"oss":           {"OPEN SOURCE · GITHUB", "源", "#a8b3bd", "#1b2026", false},
	"member":        {"SAMOURAÏ · CREW", "侍", "#e63946", "#2a1012", false},
	"member-media":  {"SAMOURAÏ · MEDIA", "映", "#b388eb", "#261a36", false},
	"member-alumni": {"SAMOURAÏ · ALUMNI", "侍", "#9aa0a6", "#1d1f22", false},
}

func styleOf(kind string) style {
	if s, ok := styles[kind]; ok {
		return s
	}
	return style{strings.ToUpper(kind), "侍", "#e63946", "#2a1012", false}
}

// SetGallery replaces a whole gallery from its line format.
func SetGallery(cur realm, name, spec string) {
	assertAdmin(cur)
	if !validSlug(name) {
		panic("invalid gallery name: " + name)
	}
	cards := parseGallery(spec)
	rev++
	galleries.Set(name, cards)
}

// DeleteGallery removes a gallery.
func DeleteGallery(cur realm, name string) {
	assertAdmin(cur)
	if _, removed := galleries.Remove(name); !removed {
		panic("no such gallery: " + name)
	}
	rev++
}

func parseGallery(spec string) []card {
	var cards []card
	for _, line := range strings.Split(spec, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		f := strings.Split(line, "|")
		if len(f) != 4 && len(f) != 5 {
			panic("gallery line needs 4 or 5 fields (kind | title | meta | url [| description]): " + line)
		}
		c := card{
			kind:  strings.TrimSpace(f[0]),
			title: strings.TrimSpace(f[1]),
			meta:  strings.TrimSpace(f[2]),
			url:   strings.TrimSpace(f[3]),
		}
		if len(f) == 5 {
			c.desc = strings.TrimSpace(f[4])
			if len(c.desc) > maxDescLen || strings.ContainsAny(c.desc, "\"\\") {
				panic("gallery description must be at most 200 bytes, without quotes or backslashes: " + line)
			}
		}
		if !validSlug(c.kind) || c.title == "" || len(c.title) > maxTitleLen || len(c.meta) > maxMetaLen {
			panic("bad gallery line: " + line)
		}
		if !strings.HasPrefix(c.url, "https://") && !strings.HasPrefix(c.url, "/") {
			panic("gallery url must be https:// or a /path: " + c.url)
		}
		if strings.ContainsAny(c.url, " ()<>\"") {
			panic("gallery url has characters markdown would break on: " + c.url)
		}
		cards = append(cards, c)
	}
	if len(cards) == 0 || len(cards) > maxCards {
		panic("a gallery holds 1 to 48 cards")
	}
	return cards
}

// renderGallery lays cards out cardsPerRow to a row, each one a poster that
// links to its target.
func renderGallery(name string) (string, bool) {
	v := galleries.Get(name)
	if v == nil {
		return "", false
	}
	cards := v.([]card)
	var b strings.Builder
	for i := 0; i < len(cards); i += cardsPerRow {
		b.WriteString("<gno-columns>\n")
		for j := i; j < i+cardsPerRow; j++ {
			if j > i {
				b.WriteString("<gno-columns-sep />\n")
			}
			if j < len(cards) {
				c := cards[j]
				b.WriteString("[![" + mdText(c.title) + "](" + posterURI(c) + ")](" + c.url + linkTitle(c.desc) + ")\n")
			}
		}
		b.WriteString("</gno-columns>\n\n")
	}
	return strings.TrimSuffix(b.String(), "\n\n"), true
}

// linkTitle renders an optional markdown link title, which gnoweb emits as
// the link's hover text.
func linkTitle(desc string) string {
	if desc == "" {
		return ""
	}
	return ` "` + desc + `"`
}

// mdText keeps a title from closing the markdown image alt text early.
func mdText(s string) string {
	return strings.NewReplacer("[", "(", "]", ")").Replace(s)
}

func xmlText(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&#39;").Replace(s)
}

// wrap splits s into at most two lines of about width runes; the second line
// is cut with an ellipsis when the title is longer.
func wrap(s string, width int) []string {
	words := strings.Fields(s)
	var lines []string
	cur := ""
	for _, w := range words {
		if cur == "" {
			cur = w
		} else if runeLen(cur)+1+runeLen(w) <= width {
			cur += " " + w
		} else {
			lines = append(lines, cur)
			cur = w
		}
	}
	if cur != "" {
		lines = append(lines, cur)
	}
	if len(lines) > 2 {
		second := []rune(strings.Join(lines[1:], " "))
		if len(second) > width {
			second = append(second[:width-1], '…')
		}
		lines = []string{lines[0], string(second)}
	}
	return lines
}

func runeLen(s string) int { return len([]rune(s)) }

// clip cuts s to at most n runes, ending with an ellipsis when it had to cut.
func clip(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(append(r[:n-1], '…'))
}

func posterURI(c card) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(poster(c)))
}

// poster draws a 320x180 card: a dark gradient, a rising sun in the kind's
// accent (a play button for videos), a large kanji watermark, the kind label,
// the title on up to two lines and a meta line.
func poster(c card) string {
	st := styleOf(c.kind)
	if c.label != "" {
		st.label = c.label
	}
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180" viewBox="0 0 320 180">`)
	b.WriteString(`<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#121212"/><stop offset="1" stop-color="` + st.shade + `"/></linearGradient></defs>`)
	b.WriteString(`<rect width="320" height="180" rx="14" fill="url(#g)"/>`)
	b.WriteString(`<text x="306" y="170" text-anchor="end" font-family="serif" font-size="120" fill="#ffffff" fill-opacity=".06">` + st.glyph + `</text>`)
	b.WriteString(`<circle cx="268" cy="52" r="30" fill="` + st.accent + `"/>`)
	if st.video {
		b.WriteString(`<path d="M260 38 L282 52 L260 66 Z" fill="#121212"/>`)
	} else {
		b.WriteString(`<path d="M256 52 H280 M272 44 L280 52 L272 60" stroke="#121212" stroke-width="4" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`)
	}
	b.WriteString(`<rect x="18" y="20" width="3" height="12" fill="` + st.accent + `"/>`)
	b.WriteString(`<text x="27" y="31" font-family="ui-monospace,Menlo,monospace" font-size="10" letter-spacing="1.5" fill="` + st.accent + `">` + xmlText(st.label) + `</text>`)
	lines := wrap(c.title, 24)
	y := 108
	if len(lines) == 1 {
		y = 126
	}
	for _, l := range lines {
		b.WriteString(`<text x="18" y="` + itoa(y) + `" font-family="system-ui,-apple-system,Segoe UI,sans-serif" font-weight="700" font-size="20" fill="#ffffff">` + xmlText(l) + `</text>`)
		y += 25
	}
	// The meta line hugs the bottom-right corner: gnoweb draws its
	// external-link badge over the bottom-left one.
	b.WriteString(`<text x="304" y="164" text-anchor="end" font-family="ui-monospace,Menlo,monospace" font-size="11" fill="#bdbdbd">` + xmlText(clip(c.meta, 40)) + `</text>`)
	b.WriteString(`</svg>`)
	return b.String()
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var d []byte
	for n > 0 {
		d = append([]byte{byte('0' + n%10)}, d...)
		n /= 10
	}
	return string(d)
}

// Package home is zôÖma's profile page on gno.land.
//
// gnoweb renders a profile by calling Render("") on the realm at exactly
// /r/<namespace>/home, so this path carries no /vN suffix.
//
// The page is assembled from SLOTS: named markdown fragments, one Set
// transaction each. The slot named "layout" is the template; every :slug:
// placeholder in it is replaced by the slot of that name, in a single pass.
// init seeds every slot from content.gno, so the page is complete the block
// it goes live and later edits are data, not redeploys.
//
// One thing on this page is not written by its owner: visitors can send a
// heart (<3), one per address, and the page counts them.
package home

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// admin is the only address allowed to edit slots.
const admin = address("g1747t5m2f08plqjlrjk2q0qld7465hxz8gkx59c")

const (
	layoutSlug = "layout"
	maxSlugLen = 64
	maxRecent  = 7
)

type slot struct {
	body    string
	rev     int
	updated int64
}

var (
	slots = avl.NewTree() // slug -> *slot
	rev   int             // total slot writes

	hearts = avl.NewTree() // address string -> int64 height of the heart
	recent []address        // newest first, at most maxRecent
)

// reservedSlugs are placeholders computed at render time. A slot may not take
// one of these names, so nothing a slot says can shadow chain state.
var reservedSlugs = []string{"chainid", "height", "hearts", "hero", "realm", "rev"}

func init() {
	for _, s := range defaultSlots {
		rev++
		slots.Set(s.slug, &slot{body: s.body, rev: rev, updated: runtime.ChainHeight()})
	}
	for _, g := range defaultGalleries {
		galleries.Set(g.name, parseGallery(g.spec))
	}
}

func assertAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("restricted to admin")
	}
}

func validSlug(slug string) bool {
	if len(slug) == 0 || len(slug) > maxSlugLen {
		return false
	}
	for i := 0; i < len(slug); i++ {
		c := slug[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-' || c == '_' || c == '.') {
			return false
		}
	}
	return true
}

func assertWritableSlug(slug string) {
	if !validSlug(slug) {
		panic("invalid slug: want 1-" + strconv.Itoa(maxSlugLen) + " bytes of [a-z0-9._-], got " + strconv.Quote(slug))
	}
	for _, r := range reservedSlugs {
		if slug == r {
			panic("reserved slug: " + slug)
		}
	}
	if strings.HasPrefix(slug, galleryPrefix) {
		panic("reserved slug: " + galleryPrefix + "* renders a gallery, use SetGallery")
	}
}

// Set creates or replaces one slot.
func Set(cur realm, slug, body string) {
	assertAdmin(cur)
	assertWritableSlug(slug)
	rev++
	slots.Set(slug, &slot{body: body, rev: rev, updated: runtime.ChainHeight()})
}

// Append adds to the end of a slot, creating it when absent, for bodies too
// large for one transaction.
func Append(cur realm, slug, body string) {
	assertAdmin(cur)
	assertWritableSlug(slug)
	prev := ""
	if v := slots.Get(slug); v != nil {
		prev = v.(*slot).body
	}
	rev++
	slots.Set(slug, &slot{body: prev + body, rev: rev, updated: runtime.ChainHeight()})
}

// Delete removes a slot. Deleting "layout" falls back to the built-in layout.
func Delete(cur realm, slug string) {
	assertAdmin(cur)
	if _, removed := slots.Remove(slug); !removed {
		panic("no such slot: " + slug)
	}
	rev++
}

// Get returns a slot body, or "" when the slot does not exist.
func Get(slug string) string {
	if v := slots.Get(slug); v != nil {
		return v.(*slot).body
	}
	return ""
}

// Revision is the total number of slot writes accepted.
func Revision() int { return rev }

// Heart records one <3 from the caller. Each address can send exactly one.
func Heart(cur realm) {
	from := cur.Previous().Address()
	if hearts.Has(from.String()) {
		panic("already sent: one <3 per address")
	}
	hearts.Set(from.String(), runtime.ChainHeight())

	recent = append([]address{from}, recent...)
	if len(recent) > maxRecent {
		recent = recent[:maxRecent]
	}
}

// Hearts returns how many distinct addresses sent a <3.
func Hearts() int { return hearts.Size() }

// HasHeart reports whether addr already sent a <3.
func HasHeart(addr address) bool { return hearts.Has(addr.String()) }

package home

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice   = testutils.TestAddress("alice")
	bob     = testutils.TestAddress("bob")
	mallory = testutils.TestAddress("mallory")
)

func reset() {
	galleries = avl.NewTree()
	slots = avl.NewTree()
	rev = 0
	hearts = avl.NewTree()
	recent = nil
}

func seed(slug, body string) {
	rev++
	slots.Set(slug, &slot{body: body, rev: rev})
}

func TestDefaultPageRendersEverySection(t *testing.T) {
	// State as left by init: every default slot, no heart yet.
	page := Render("")
	for _, want := range []string{"data:image/svg+xml;base64,", "Founder, CEO & CTO", "## 今 Now", "## 組 Inside Memba", "BARRICADE", "256 merged pull requests", "Paris P2P Festival", "Contributing on Gno since | 2022", "## 源 Open source", "(https://www.youtube.com/watch?v=aG4M37FX4II)", "**0** hearts so far.", "gno.land/r/g1747t5m2f08plqjlrjk2q0qld7465hxz8gkx59c/home"} {
		uassert.True(t, strings.Contains(page, want), "missing: "+want)
	}
	for _, s := range defaultSlots {
		uassert.False(t, strings.Contains(page, ":"+s.slug+":"), "unfilled placeholder :"+s.slug+":")
	}
	for _, g := range defaultGalleries {
		uassert.False(t, strings.Contains(page, ":gallery."+g.name+":"), "unfilled gallery :gallery."+g.name+":")
	}
	uassert.False(t, strings.Contains(page, ":hero:"))
}

func TestSetGetDelete(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(admin))

	Set(cross(cur), "bio", "Building on gno.")
	uassert.Equal(t, "Building on gno.", Get("bio"))
	Append(cross(cur), "bio", " Still.")
	uassert.Equal(t, "Building on gno. Still.", Get("bio"))
	uassert.Equal(t, 2, Revision())

	Delete(cross(cur), "bio")
	uassert.Equal(t, "", Get("bio"))
	uassert.AbortsWithMessage(t, cur, "no such slot: bio", func() {
		Delete(cross(cur), "bio")
	})
}

func TestWritesAreAdminOnly(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(mallory))
	uassert.AbortsWithMessage(t, cur, "restricted to admin", func() { Set(cross(cur), "bio", "pwned") })
	uassert.AbortsWithMessage(t, cur, "restricted to admin", func() { Append(cross(cur), "bio", "pwned") })
	uassert.AbortsWithMessage(t, cur, "restricted to admin", func() { Delete(cross(cur), "bio") })
}

func TestSlugRules(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(admin))
	uassert.AbortsContains(t, cur, "invalid slug", func() { Set(cross(cur), "Bad", "x") })
	uassert.AbortsContains(t, cur, "invalid slug", func() { Set(cross(cur), "a:b", "x") })
	uassert.AbortsContains(t, cur, "invalid slug", func() { Set(cross(cur), "", "x") })
	uassert.AbortsWithMessage(t, cur, "reserved slug: hearts", func() { Set(cross(cur), "hearts", "fake 9999") })
	uassert.AbortsContains(t, cur, "reserved slug: gallery.", func() { Set(cross(cur), "gallery.x", "fake") })
}

func TestFillIsSinglePass(t *testing.T) {
	reset()
	seed("layout", "A :a: B :missing: C 10:30 :b:")
	seed("a", "[:b:]")
	seed("b", "bee")
	uassert.Equal(t, "A [:b:] B :missing: C 10:30 bee", Render(""))
}

func TestFallbackLayout(t *testing.T) {
	reset()
	seed("bio", "hi")
	uassert.True(t, strings.HasPrefix(Render(""), "# zôÖma\n\nhi\n\n**0** hearts"))
}

func TestHeartOncePerAddress(cur realm, t *testing.T) {
	reset()
	seed("layout", ":hearts:")

	testing.SetRealm(testing.NewUserRealm(alice))
	Heart(cross(cur))
	uassert.Equal(t, 1, Hearts())
	uassert.True(t, HasHeart(alice))
	uassert.AbortsWithMessage(t, cur, "already sent: one <3 per address", func() { Heart(cross(cur)) })

	testing.SetRealm(testing.NewUserRealm(bob))
	Heart(cross(cur))
	uassert.Equal(t, 2, Hearts())
	uassert.Equal(t, bob, recent[0], "newest first")

	page := Render("")
	uassert.True(t, strings.Contains(page, "**2** hearts so far."))
	uassert.True(t, strings.Contains(page, "/u/"+bob.String()))
	uassert.True(t, strings.Contains(Render("hearts"), "/u/"+alice.String()))
}

func TestRecentIsBounded(cur realm, t *testing.T) {
	reset()
	for i := 0; i < maxRecent+3; i++ {
		testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("fan" + string(rune('a'+i)))))
		Heart(cross(cur))
	}
	uassert.Equal(t, maxRecent+3, Hearts())
	uassert.Equal(t, maxRecent, len(recent))
}

func TestOtherViews(t *testing.T) {
	reset()
	seed("bio", "hello")
	uassert.True(t, strings.Contains(Render("slots"), "[bio]"))
	uassert.True(t, strings.Contains(Render("slots/bio"), "hello"))
	uassert.True(t, strings.Contains(Render("slots/nope"), "Not found"))
	uassert.True(t, strings.Contains(Render("nope"), "Not found"))
}

func TestGallery(cur realm, t *testing.T) {
	reset()
	seed("layout", ":gallery.demo:")

	testing.SetRealm(testing.NewUserRealm(mallory))
	uassert.AbortsWithMessage(t, cur, "restricted to admin", func() {
		SetGallery(cross(cur), "demo", "film | A | b | https://x.y")
	})

	testing.SetRealm(testing.NewUserRealm(admin))
	uassert.AbortsContains(t, cur, "needs 4 or 5 fields", func() { SetGallery(cross(cur), "demo", "film | A | b") })
	uassert.AbortsContains(t, cur, "must be https://", func() { SetGallery(cross(cur), "demo", "film | A | b | javascript:alert(1)") })
	uassert.AbortsContains(t, cur, "markdown would break", func() { SetGallery(cross(cur), "demo", "film | A | b | https://x.y/a)b") })

	SetGallery(cross(cur), "demo", "# comment\nfilm | One <&> | meta | https://a.b/1\nproduct | Two | m | /r/x\nevent | Three | m | https://a.b/3\nreport | Four | m | https://a.b/4")
	page := Render("")
	uassert.Equal(t, 2, strings.Count(page, "<gno-columns>"), "3 per row")
	uassert.Equal(t, 4, strings.Count(page, "data:image/svg+xml;base64,"))
	uassert.True(t, strings.Contains(page, "](https://a.b/1)"))
	uassert.True(t, strings.Contains(page, "](/r/x)"))

	// Titles are XML-escaped inside the poster.
	svg := poster(card{kind: "film", title: "One <&>", meta: "m", url: "https://a.b"})
	uassert.True(t, strings.Contains(svg, "One &lt;&amp;&gt;"))

	// An optional fifth field becomes the link's hover text.
	SetGallery(cross(cur), "demo", "memba | DAO Management | m | https://a.b/dao | Vote, execute, create.")
	uassert.True(t, strings.Contains(Render(""), `](https://a.b/dao "Vote, execute, create.")`))
	uassert.Equal(t, "MEMBA · PRODUCT", styleOf("memba").label, "every seeded kind has its own style")
	uassert.AbortsContains(t, cur, "without quotes", func() {
		SetGallery(cross(cur), "demo", "memba | A | m | https://a.b | say \"hi\"")
	})

	DeleteGallery(cross(cur), "demo")
	uassert.Equal(t, ":gallery.demo:", Render(""), "a missing gallery stays visible")
}

func TestWrap(t *testing.T) {
	uassert.Equal(t, 1, len(wrap("Short title", 24)))
	lines := wrap("The Underground Sistine Chapel is a very long title indeed", 24)
	uassert.Equal(t, 2, len(lines))
	uassert.True(t, strings.HasSuffix(lines[1], "…"))
}

package home

import (
	"strconv"
	"strings"

	"chain/runtime"
)

const (
	realmPath = "gno.land/r/g1747t5m2f08plqjlrjk2q0qld7465hxz8gkx59c/home"
	webPath   = "/r/g1747t5m2f08plqjlrjk2q0qld7465hxz8gkx59c/home"
)

// fallbackLayout renders when the layout slot is deleted.
const fallbackLayout = "# zôÖma\n\n:bio:\n\n:hearts:\n"

// Render serves:
//
//	""             the profile page
//	"slots"        the slot index
//	"slots/<slug>" one slot's raw markdown
//	"hearts"       everyone who sent a <3
func Render(path string) string {
	switch {
	case path == "":
		return renderPage()
	case path == "slots":
		return renderIndex()
	case strings.HasPrefix(path, "slots/"):
		return renderSlot(strings.TrimPrefix(path, "slots/"))
	case path == "hearts":
		return renderHearts()
	}
	return "# Not found\n\nNo such path: " + strconv.Quote(path) + "\n\n[Back home](" + webPath + ")\n"
}

func renderPage() string {
	layout := Get(layoutSlug)
	if layout == "" {
		layout = fallbackLayout
	}
	return fill(layout)
}

// fill replaces every :slug: in s, in one left-to-right pass. Replacement text
// is never rescanned, so a slot cannot expand into another slot. A placeholder
// with no value stays verbatim: a missing section should be visible.
func fill(s string) string {
	var b strings.Builder
	for {
		i := strings.IndexByte(s, ':')
		if i < 0 {
			b.WriteString(s)
			return b.String()
		}
		b.WriteString(s[:i])
		s = s[i:]
		j := strings.IndexByte(s[1:], ':')
		if j < 0 {
			b.WriteString(s)
			return b.String()
		}
		slug := s[1 : j+1]
		if v, ok := lookup(slug); ok {
			b.WriteString(v)
			s = s[j+2:]
			continue
		}
		// Not a placeholder: emit the first ':' and rescan from the next one,
		// so "a:b :bio:" still finds :bio:.
		b.WriteString(":")
		s = s[1:]
	}
}

func lookup(slug string) (string, bool) {
	if !validSlug(slug) {
		return "", false
	}
	switch slug {
	case "chainid":
		return runtime.ChainID(), true
	case "height":
		return strconv.FormatInt(runtime.ChainHeight(), 10), true
	case "hearts":
		return heartsBlock(), true
	case "hero":
		return heroImage(), true
	case "realm":
		return realmPath, true
	case "rev":
		return strconv.Itoa(rev), true
	}
	if strings.HasPrefix(slug, galleryPrefix) {
		return renderGallery(strings.TrimPrefix(slug, galleryPrefix))
	}
	if v := slots.Get(slug); v != nil {
		return v.(*slot).body, true
	}
	return "", false
}

func heartsBlock() string {
	n := hearts.Size()
	var b strings.Builder
	b.WriteString("**")
	b.WriteString(strconv.Itoa(n))
	if n == 1 {
		b.WriteString("** heart so far.")
	} else {
		b.WriteString("** hearts so far.")
	}
	b.WriteString(" [Send yours](" + webPath + "$help&func=Heart): one transaction, one per address, forever on chain.")
	if len(recent) > 0 {
		b.WriteString("\n\nLatest: ")
		for i, a := range recent {
			if i > 0 {
				b.WriteString(" · ")
			}
			b.WriteString(userLink(a))
		}
		b.WriteString(" · [all](" + webPath + ":hearts)")
	}
	return b.String()
}

// userLink renders an address as a short link to its gno.land profile.
func userLink(a address) string {
	s := a.String()
	short := s
	if len(s) > 12 {
		short = s[:7] + "…" + s[len(s)-4:]
	}
	return "[" + short + "](/u/" + s + ")"
}

func renderHearts() string {
	var b strings.Builder
	b.WriteString("# <3\n\n")
	b.WriteString(strconv.Itoa(hearts.Size()) + " address(es) sent a heart. [Send yours](" + webPath + "$help&func=Heart).\n\n")
	if hearts.Size() == 0 {
		b.WriteString("_Be the first._\n")
		return b.String()
	}
	b.WriteString("| from | block |\n| --- | ---: |\n")
	hearts.Iterate("", "", func(key string, value any) bool {
		b.WriteString("| " + userLink(address(key)) + " | " + strconv.FormatInt(value.(int64), 10) + " |\n")
		return false
	})
	b.WriteString("\n[Back home](" + webPath + ")\n")
	return b.String()
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# Slots\n\nrev " + strconv.Itoa(rev) + " · " + strconv.Itoa(slots.Size()) + " slot(s)\n\n")
	b.WriteString("| slot | bytes | rev | height |\n| --- | ---: | ---: | ---: |\n")
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*slot)
		b.WriteString("| [" + key + "](" + webPath + ":slots/" + key + ") | " +
			strconv.Itoa(len(s.body)) + " | " + strconv.Itoa(s.rev) + " | " +
			strconv.FormatInt(s.updated, 10) + " |\n")
		return false
	})
	return b.String()
}

func renderSlot(slug string) string {
	v := slots.Get(slug)
	if v == nil {
		return "# Not found\n\nNo slot named " + strconv.Quote(slug) + ".\n\n[Slot index](" + webPath + ":slots)\n"
	}
	s := v.(*slot)
	body := s.body
	if !strings.HasSuffix(body, "\n") {
		body += "\n"
	}
	return "# " + slug + "\n\n" + strconv.Itoa(len(s.body)) + " bytes · rev " + strconv.Itoa(s.rev) +
		" · written at height " + strconv.FormatInt(s.updated, 10) + "\n\n````\n" + body + "````\n"
}

// Package ui is the shared display vocabulary for r/moul realms: the small set
// of rendering decisions that every realm was making on its own, made once.
//
// It deliberately does NOT re-export markdown primitives. Headings, bold,
// lists, code blocks and links already have an owner in
// [p/moul/md](/p/moul/md/v0); import that alongside this package. What lives
// here is only what had no owner and was therefore copy-pasted:
//
//   - Addr: one address shortening for the whole namespace. Eleven realms had
//     their own shortAddr with four different truncation rules, so the same
//     account rendered differently depending on which realm you opened.
//   - Inline / Cell / Excerpt: markdown escaping, delegated to
//     [p/nt/markdown/sanitize](/p/nt/markdown/sanitize/v0). Eight realms
//     hand-rolled a seven-pair strings.NewReplacer that misses most of what
//     the real escaper handles. Excerpt adds the length cap those previews
//     also need, in the order that is safe: cut, then escape.
//   - Action: a clickable call link instead of prose telling the reader to go
//     type a function name.
//   - Table, Empty, Podium: the last recurring scraps.
//
// # Escaping contract
//
// Table cells and Action titles are markdown, not plain text. Anything that
// came from a user must go through [Cell] (inside a table) or [Inline]
// (anywhere else) before it is handed to this package. Output of [Addr],
// [AddrFull] and [Podium] is already safe and must NOT be escaped again.
package ui

import (
	"strings"

	"gno.land/p/moul/helplink/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Ellipsis is the character placed between the kept head and tail of a
// shortened string.
const Ellipsis = "…"

// Head and Tail are how many characters [Addr] and [Short] keep on each side.
//
// A gno.land address is 40 characters ("g1" plus 38 of bech32 data), so
// 8+1+4 renders it as g1manfre…dlf5: enough of the head to recognise a
// familiar account, enough of the tail to tell two similar ones apart.
const (
	Head = 8
	Tail = 4
)

// minShorten is the length below which shortening cannot save a character:
// Head + len(Ellipsis) + Tail. Strings at or under it are returned unchanged,
// which is why the rule never produces output longer than its input.
const minShorten = Head + 1 + Tail

// Addr renders an address shortened and in backticks: `g1manfre…dlf5`.
//
// This is the default way to show an address. It is monospace (an address is
// opaque data, not prose), and the backticks make it inert markdown, so it is
// safe in a table cell or anywhere else without further escaping.
func Addr(a address) string {
	return md.InlineCode(AddrText(a))
}

// AddrFull renders an address in full, in backticks. Use it where the reader
// needs to copy the value; use [Addr] everywhere else.
func AddrFull(a address) string {
	return md.InlineCode(a.String())
}

// AddrText renders an address shortened, with no backticks. Use it inside a
// link title or another construct where backticks would not render.
func AddrText(a address) string {
	return Short(a.String())
}

// AddrOf is [Addr] for an address already in its string form, which is how
// realms hold one when it is an avl key or a stored field.
func AddrOf(s string) string {
	return md.InlineCode(Short(s))
}

// Short shortens any string with the house rule: unchanged when shortening
// would not save a character, otherwise head + ellipsis + tail.
//
// It is the same rule [Addr] uses, exposed for the non-address strings realms
// also truncate: URLs, handles, commitment hashes.
func Short(s string) string {
	return ShortN(s, Head, Tail)
}

// ShortN is [Short] with an explicit head and tail. A negative head or tail is
// treated as zero. When head+tail cannot save a character against the input,
// the input is returned unchanged.
func ShortN(s string, head, tail int) string {
	if head < 0 {
		head = 0
	}
	if tail < 0 {
		tail = 0
	}
	// Count runes, not bytes: slicing a multi-byte string by byte offset
	// splits a rune and emits replacement characters.
	r := []rune(s)
	if len(r) <= head+1+tail {
		return s
	}
	return string(r[:head]) + Ellipsis + string(r[len(r)-tail:])
}

// Inline escapes user-supplied text for an inline markdown context: a
// sentence, a list item, a link title.
//
// It delegates to sanitize.InlineText, which strips bidi and zero-width
// characters, folds newlines to spaces so the text cannot escape its line,
// and applies the full CommonMark inline escape. Never concatenate
// user-supplied text into rendered output without this.
func Inline(s string) string {
	return sanitize.InlineText(s)
}

// Cell escapes user-supplied text for a markdown table cell: [Inline] plus
// tab and pipe handling, so the value cannot open a new column.
func Cell(s string) string {
	return sanitize.TableCell(s)
}

// Excerpt is [Inline] for a string too long to show whole: it keeps the first
// width runes, appends [Ellipsis], and escapes what it kept.
//
// Use it for a preview of user-written prose where only the beginning carries
// meaning: the first line of a post in an index, a note on a board, a comment
// in a list. For an identifier whose tail has to stay recognisable, an
// address, a hash, a URL, use [Short] instead, which keeps both ends.
//
// The order is the whole point, and it is what a call site gets wrong.
// Escaping inserts backslashes, so cutting an ALREADY-escaped string can
// strand a trailing lone backslash that escapes whatever chrome follows it.
// Excerpt cuts first, on a rune boundary so a multi-byte character is never
// split, then escapes. [Ellipsis] stays outside the escaper: it is this
// package's chrome, not the user's text.
func Excerpt(s string, width int) string {
	if width < 0 {
		width = 0
	}
	r := []rune(s)
	// The same threshold as [ShortN] with no tail: cutting is only worth doing
	// when it saves a character, so a string one rune over is kept whole.
	if len(r) <= width+1 {
		return Inline(s)
	}
	return Inline(string(r[:width])) + Ellipsis
}

// Action renders a clickable call to a function of the current realm.
//
//	ui.Action("Play cell 4", "Move", "gameID", "7", "cell", "4")
//
// Arguments are key/value pairs, as in p/moul/txlink. The title is escaped,
// which is the one thing helplink.Func does not do.
func Action(title, fn string, args ...string) string {
	return helplink.Func(Inline(title), fn, args...)
}

// ActionIn is [Action] against another realm, given as the full package path
// that realm declares on the module line of its gnomod.toml.
//
// This doc deliberately contains no example path, not even a placeholder one.
// gnopm scans doc comments the way it scans imports, so any package path
// spelled out in a comment becomes a dependency of the package holding it: one
// that is neither live nor in the workspace BLOCKS publishing this package and
// everything that imports it, and naming a live one is no better, since it
// drags an unrelated realm into every publish plan. This comment previously
// named a path that deversioning had already removed, which blocked the whole
// ui dependency tree on every chain.
func ActionIn(pkgPath, title, fn string, args ...string) string {
	return helplink.Realm(pkgPath).Func(Inline(title), fn, args...)
}

// Empty renders the placeholder shown where a list would be: an italic line,
// newline-terminated, so it drops into a Render body as-is.
//
//	ui.Empty("No games yet.")  // "_No games yet._\n"
//
// The message is realm chrome, not user input, and is not escaped.
func Empty(msg string) string {
	return md.Italic(msg) + "\n"
}

// Podium returns the medal for a zero-based rank, or "" past third place.
func Podium(rank int) string {
	switch rank {
	case 0:
		return "\U0001F947" // 🥇
	case 1:
		return "\U0001F948" // 🥈
	case 2:
		return "\U0001F949" // 🥉
	default:
		return ""
	}
}

// Table accumulates markdown table rows and renders them.
//
// Cells are markdown, not plain text: pass [Addr] and friends straight
// through, and wrap anything user-supplied in [Cell] first.
//
// Table renders the GFM table itself rather than delegating to
// [p/moul/mdtable](/p/moul/mdtable/v0), which unconditionally rewrites "|" to
// "&#124;" in every cell. Stacked on [Cell], which already emits the GFM
// escape "\|", that double-escapes into a stray backslash ("a\&#124;b"). One
// escaping stage is the only way to get this right, and it has to be the one
// that knows whether the text is user input.
//
//	t := ui.NewTable("#", "X", "O", "Status")
//	t.Row("7", ui.Addr(x), ui.Addr(o), "Turn: X")
//	return t.String()
type Table struct {
	headers []string
	rows    [][]string
}

// NewTable starts a table with the given header cells.
func NewTable(headers ...string) *Table {
	return &Table{headers: headers}
}

// Row appends a row and returns the table, so calls can be chained.
//
// A row with fewer cells than there are headers is padded with empty cells; a
// longer row is kept as-is, which renders as a ragged table rather than
// silently dropping data.
func (t *Table) Row(cells ...string) *Table {
	if n := len(t.headers); len(cells) < n {
		padded := make([]string, n)
		copy(padded, cells)
		cells = padded
	}
	t.rows = append(t.rows, cells)
	return t
}

// Len reports how many rows have been added.
func (t *Table) Len() int { return len(t.rows) }

// String renders the table. A table with no rows renders as "", so a caller
// can fall back to [Empty] with a single check on [Table.Len].
func (t *Table) String() string {
	if len(t.rows) == 0 {
		return ""
	}
	var sb strings.Builder
	sb.WriteString("| " + strings.Join(t.headers, " | ") + " |\n")
	sb.WriteString("|" + strings.Repeat(" --- |", len(t.headers)) + "\n")
	for _, r := range t.rows {
		sb.WriteString("| " + strings.Join(r, " | ") + " |\n")
	}
	return sb.String()
}

// OrEmpty renders the table, or the placeholder when it has no rows.
func (t *Table) OrEmpty(msg string) string {
	if len(t.rows) == 0 {
		return Empty(msg)
	}
	return t.String()
}

// Join concatenates parts, skipping empty ones, with sep between them. It is
// the small piece of glue every Render needs to assemble optional sections
// without emitting stray separators.
func Join(sep string, parts ...string) string {
	kept := make([]string, 0, len(parts))
	for _, p := range parts {
		if p != "" {
			kept = append(kept, p)
		}
	}
	return strings.Join(kept, sep)
}

package ui

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestShortN(t *testing.T) {
	cases := []struct {
		name       string
		in         string
		head, tail int
		want       string
	}{
		{"empty", "", 8, 4, ""},
		{"shorter than the rule", "abc", 8, 4, "abc"},
		{"exactly at the threshold", "0123456789abc", 8, 4, "0123456789abc"},
		{"one over the threshold", "0123456789abcd", 8, 4, "01234567…abcd"},
		{"gno address", "g1manfred47kzduec920z88wfr64ylksmdcedlf5", 8, 4, "g1manfre…dlf5"},
		{"head only", "0123456789abcd", 6, 0, "012345…"},
		{"tail only", "0123456789abcd", 0, 4, "…abcd"},
		{"negative clamps to zero", "0123456789abcd", -3, -3, "…"},
		{"multibyte is not split", "éééééééééééééé", 2, 2, "éé…éé"},
	}
	for _, tc := range cases {
		got := ShortN(tc.in, tc.head, tc.tail)
		uassert.Equal(t, tc.want, got, tc.name)
	}
}

// ShortN must never make a string longer: that is the property the four
// divergent shortAddr implementations disagreed on.
func TestShortNeverGrows(t *testing.T) {
	inputs := []string{"", "a", "abcdefghijkl", "0123456789abc", "0123456789abcd", strings.Repeat("x", 100)}
	for _, in := range inputs {
		got := Short(in)
		uassert.True(t, len([]rune(got)) <= len([]rune(in)), "Short("+in+") grew the input")
	}
}

func TestAddr(t *testing.T) {
	a := testutils.TestAddress("alice")
	full := a.String()

	uassert.Equal(t, "`"+full+"`", AddrFull(a))
	uassert.Equal(t, Short(full), AddrText(a))
	uassert.Equal(t, "`"+Short(full)+"`", Addr(a))

	// The shortened form keeps the recognisable head and the distinguishing tail.
	uassert.True(t, strings.HasPrefix(AddrText(a), full[:Head]), "head is kept")
	uassert.True(t, strings.HasSuffix(AddrText(a), full[len(full)-Tail:]), "tail is kept")
	uassert.True(t, strings.Contains(AddrText(a), Ellipsis), "ellipsis is present")
}

// Two different addresses must not collide once shortened, or the display is
// worse than useless.
func TestAddrOf(t *testing.T) {
	a := testutils.TestAddress("alice")
	uassert.Equal(t, Addr(a), AddrOf(a.String()))
}

func TestAddrDistinguishes(t *testing.T) {
	seen := map[string]bool{}
	for _, name := range []string{"alice", "bob", "carol", "dave", "eve"} {
		s := AddrText(testutils.TestAddress(name))
		uassert.False(t, seen[s], "shortened address collision on "+name)
		seen[s] = true
	}
}

func TestInlineEscapes(t *testing.T) {
	// The seven pairs the hand-rolled escapeInline copies covered.
	for _, meta := range []string{"*", "_", "[", "]", "`", "\\"} {
		got := Inline("a" + meta + "b")
		uassert.True(t, strings.Contains(got, "\\"+meta), "Inline did not escape "+meta)
	}
	// And the one they all missed: a newline lets user text escape its line.
	uassert.False(t, strings.Contains(Inline("a\nb"), "\n"), "Inline must fold newlines")
}

func TestCellEscapesPipe(t *testing.T) {
	got := Cell("a|b")
	uassert.False(t, strings.Contains(got, " |"), "a bare pipe would open a new column")
	uassert.True(t, strings.Contains(got, "\\|"), "pipe must be escaped")
}

func TestEmpty(t *testing.T) {
	uassert.Equal(t, "*No games yet.*\n", Empty("No games yet."))
}

func TestPodium(t *testing.T) {
	cases := []struct {
		rank int
		want string
	}{
		{0, "\U0001F947"},
		{1, "\U0001F948"},
		{2, "\U0001F949"},
		{3, ""},
		{99, ""},
		{-1, ""},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, Podium(tc.rank))
	}
}

func TestTable(t *testing.T) {
	tbl := NewTable("#", "who", "score")
	uassert.Equal(t, 0, tbl.Len())
	uassert.Equal(t, "", tbl.String())
	uassert.Equal(t, "*nobody yet.*\n", tbl.OrEmpty("nobody yet."))

	tbl.Row("1", "`g1abc…wxyz`", "42").Row("2", "`g1def…uvwx`", "7")
	uassert.Equal(t, 2, tbl.Len())

	want := "| # | who | score |\n" +
		"| --- | --- | --- |\n" +
		"| 1 | `g1abc…wxyz` | 42 |\n" +
		"| 2 | `g1def…uvwx` | 7 |\n"
	uassert.Equal(t, want, tbl.String())
	uassert.Equal(t, want, tbl.OrEmpty("nobody yet."))
}

// A short row is padded rather than producing a table the renderer misreads.
func TestTableShortRowIsPadded(t *testing.T) {
	tbl := NewTable("a", "b", "c")
	tbl.Row("1")
	uassert.Equal(t, "| a | b | c |\n| --- | --- | --- |\n| 1 |  |  |\n", tbl.String())
}

// A cell escaped with Cell must survive Table untouched: stacking Cell on an
// escaper that also rewrites "|" produced "a\\&#124;b" in the guestbook port.
func TestTableDoesNotDoubleEscape(t *testing.T) {
	tbl := NewTable("msg")
	tbl.Row(Cell("a|b"))
	got := tbl.String()
	uassert.True(t, strings.Contains(got, `a\|b`), "expected the GFM pipe escape, got: "+got)
	uassert.False(t, strings.Contains(got, "&#124;"), "cell was escaped twice: "+got)
}

func TestJoin(t *testing.T) {
	uassert.Equal(t, "a\n\nb", Join("\n\n", "a", "", "b"))
	uassert.Equal(t, "", Join("\n\n", "", ""))
	uassert.Equal(t, "solo", Join("\n\n", "solo"))
}

// Action must produce a markdown link whose target carries the function name
// and the key/value arguments, and must escape the title (which helplink
// itself does not).
func TestAction(t *testing.T) {
	got := Action("Play cell 4", "Move", "gameID", "7", "cell", "4")
	uassert.True(t, strings.HasPrefix(got, "[Play cell 4]("), "expected a markdown link, got: "+got)
	uassert.True(t, strings.Contains(got, "Move"), "link must name the function")
	uassert.True(t, strings.Contains(got, "gameID=7"), "link must carry the args")
	uassert.True(t, strings.Contains(got, "cell=4"), "link must carry the args")

	esc := Action("a*b", "Fn")
	uassert.True(t, strings.HasPrefix(esc, "[a\\*b]("), "title must be escaped, got: "+esc)
}

func TestActionIn(t *testing.T) {
	got := ActionIn("gno.land/r/moul/gns/v0", "Say hi", "Hello", "name", "moul")
	uassert.True(t, strings.Contains(got, "/r/moul/gns/v0"), "must target the named realm, got: "+got)
	uassert.True(t, strings.Contains(got, "Hello"), "must name the function")
}

func TestExcerpt(t *testing.T) {
	cases := []struct {
		name  string
		in    string
		width int
		want  string
	}{
		{"empty", "", 10, ""},
		{"shorter than the width", "hello", 10, "hello"},
		{"one over is kept whole, as ShortN does", "0123456789a", 10, "0123456789a"},
		{"two over is cut", "0123456789ab", 10, "0123456789…"},
		{"zero width", "hello", 0, "…"},
		{"negative width clamps to zero", "hello", -3, "…"},
		// The cut counts runes. A byte slice at 10 would split the 11th 'é'
		// and put invalid UTF-8 on the page.
		{"multibyte is not split", strings.Repeat("é", 20), 10, strings.Repeat("é", 10) + "…"},
		// The escaping half: what is kept is escaped, the ellipsis is not.
		{"escapes what it keeps", "[link](url) and more", 11, "\\[link\\]\\(url\\)…"},
		{"newline cannot escape the line", "one\ntwo", 10, "one two"},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, Excerpt(tc.in, tc.width), tc.name)
	}
}

// Excerpt must never leave a trailing lone backslash: that is the bug that
// comes from escaping first and cutting second, and it escapes whatever the
// caller appends after the excerpt.
func TestExcerptNeverStrandsABackslash(t *testing.T) {
	// Each of these ends, at some width, on a character the escaper backslashes.
	for _, in := range []string{
		"....................", "********************", "[[[[[[[[[[[[[[[[[[[[",
		"!!!!!!!!!!!!!!!!!!!!", "<<<<<<<<<<<<<<<<<<<<", "--------------------",
	} {
		for width := 0; width <= 15; width++ {
			got := Excerpt(in, width)
			body := strings.TrimSuffix(got, Ellipsis)
			trailing := 0
			for i := len(body) - 1; i >= 0 && body[i] == '\\'; i-- {
				trailing++
			}
			uassert.Equal(t, 0, trailing%2, "odd run of trailing backslashes in Excerpt("+in+")")
		}
	}
}

// Package blog is moul's personal blog on gno.land: one realm, one author,
// posts that live in chain storage rather than in the code.
//
// # The shape
//
// A post is markdown plus four fields (slug, title, date, tags). Writing one
// is a single Set transaction, so publishing never redeploys the realm and
// fixing a typo costs one small call instead of a new package path.
//
// The reader-facing paths are deliberately short, because they get pasted into
// other people's chats:
//
//	gno.land/r/moul/blog             the index, newest first
//	gno.land/r/moul/blog:<slug>      one post
//	gno.land/r/moul/blog:t/<tag>     every post carrying a tag
//
// # Ordering without sort
//
// gno has no sort.Slice, and avl.Tree iterates by key. So posts live in two
// trees: `posts` keyed by slug, for the O(log n) lookup a permalink needs, and
// `order` keyed by "<date>/<slug>", walked in reverse for newest-first. The
// date is YYYY-MM-DD precisely so that lexical order is chronological order,
// which is what makes the second tree free.
//
// # Versioning
//
// gnomod.toml declares private = true, which lets the creator re-add the
// package at this exact path. That redeploy re-runs init() and WIPES every
// post here, so the markdown kept off chain is the source of truth and
// tools/gnoblog pushes it back. Trading that risk for a stable URL is the
// whole design: a /v1 would break every link already shared, a redeploy does
// not, and Manifest() makes restoring the content one diff.
package blog

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// author is the only address allowed to write. Deliberately a constant rather
// than transferable ownership: this is one person's blog, and the same address
// is the only one the chain lets redeploy the realm anyway, so a second owner
// could publish posts it could never restore after a wipe.
const author = address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")

// realmPath is this realm's own path, used to build the links Render emits.
const realmPath = "gno.land/r/moul/blog"

// maxSlugLen bounds a slug so a permalink stays typable and a key stays cheap.
const maxSlugLen = 64

// excerptLen is how much of a post body the index shows.
const excerptLen = 200

// introKey is the manifest key of the index header. It starts with '!', which
// validSlug rejects, so it can never collide with a post.
const introKey = "!intro"

// introSlug is refused as a post slug. Not because this realm needs it: the
// intro lives in its own variable. It is refused so that the local half stays
// representable, where a post is <slug>.md and the header is intro.md. A post
// published at this slug by a hand-written transaction would have no file it
// could live in, and tools/gnoblog would report it as an extra forever.
const introSlug = "intro"

type post struct {
	slug    string
	title   string
	date    string // YYYY-MM-DD, the sort key
	tags    string // comma-separated, normalized by splitTags
	body    string // raw markdown, authored by `author`, rendered unescaped
	rev     int    // rev at the time of the last write to this post
	updated int64  // block height of the last write
}

var (
	posts = avl.NewTree() // slug             -> *post
	order = avl.NewTree() // "<date>/<slug>"  -> *post
	intro string          // markdown shown above the index
	rev   int             // total writes accepted, bumped by every mutation
)

func assertAuthor(cur realm) {
	if cur.Previous().Address() != author {
		panic("restricted to the author")
	}
}

// validSlug reports whether slug is a legal permalink: 1..maxSlugLen bytes of
// [a-z0-9._-]. The character set excludes ':' and '/' so a slug can never
// break out of its own render path, and excludes uppercase so a post has
// exactly one URL.
func validSlug(slug string) bool {
	if len(slug) == 0 || len(slug) > maxSlugLen {
		return false
	}
	for i := 0; i < len(slug); i++ {
		c := slug[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '-', c == '_', c == '.':
		default:
			return false
		}
	}
	return true
}

// validDate reports whether date is exactly YYYY-MM-DD. The format is not
// cosmetic: `order` relies on lexical order being chronological order, so a
// date of any other shape would silently sort into the wrong place.
func validDate(date string) bool {
	if len(date) != 10 {
		return false
	}
	for i := 0; i < 10; i++ {
		c := date[i]
		if i == 4 || i == 7 {
			if c != '-' {
				return false
			}
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

// orderKey is the key a post takes in `order`. The slug is appended so two
// posts published on the same day do not collide.
func orderKey(date, slug string) string { return date + "/" + slug }

// splitTags normalizes a comma-separated tag list: trimmed, lowercased,
// deduplicated, empties dropped. It returns the canonical string that gets
// stored, so the hash a client computes locally matches the one on chain.
func splitTags(tags string) []string {
	var out []string
	for _, t := range strings.Split(tags, ",") {
		t = strings.ToLower(strings.TrimSpace(t))
		if t == "" {
			continue
		}
		dup := false
		for _, seen := range out {
			if seen == t {
				dup = true
				break
			}
		}
		if !dup {
			out = append(out, t)
		}
	}
	return out
}

func joinTags(tags []string) string { return strings.Join(tags, ",") }

// record is the canonical serialization a post hashes to. Both this realm and
// tools/gnoblog build it the same way, which is what lets one Manifest() read
// decide whether a local file needs a transaction at all.
func record(title, date, tags, body string) string {
	return title + "\n" + date + "\n" + tags + "\n" + body
}

func hashOf(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

// Set creates or replaces the post at slug. This is the ordinary publish: one
// post, one transaction, idempotent.
//
// Changing the date moves the post in the index, so the old order entry is
// removed before the new one is written.
func Set(cur realm, slug, title, date, tags, body string) {
	assertAuthor(cur)
	if !validSlug(slug) {
		panic("invalid slug: want 1-" + strconv.Itoa(maxSlugLen) + " bytes of [a-z0-9._-], got " + strconv.Quote(slug))
	}
	if slug == introSlug {
		panic("reserved slug: " + introSlug + " names the index header, set it with SetIntro")
	}
	if !validDate(date) {
		panic("invalid date: want YYYY-MM-DD, got " + strconv.Quote(date))
	}
	title = strings.TrimSpace(title)
	if title == "" {
		panic("a post needs a title")
	}

	if v := posts.Get(slug); v != nil {
		order.Remove(orderKey(v.(*post).date, slug))
	}

	rev++
	p := &post{
		slug:    slug,
		title:   title,
		date:    date,
		tags:    joinTags(splitTags(tags)),
		body:    body,
		rev:     rev,
		updated: runtime.ChainHeight(),
	}
	posts.Set(slug, p)
	order.Set(orderKey(date, slug), p)
}

// Append adds to the end of a post's body. It exists for a body too large to
// fit in one transaction: Set the first chunk, Append the rest. An ordinary
// edit uses Set, which is idempotent and therefore safe to retry.
func Append(cur realm, slug, body string) {
	assertAuthor(cur)
	v := posts.Get(slug)
	if v == nil {
		panic("no such post: " + strconv.Quote(slug))
	}
	p := v.(*post)
	rev++
	p.body += body
	p.rev = rev
	p.updated = runtime.ChainHeight()
}

// Delete removes a post and its index entry.
func Delete(cur realm, slug string) {
	assertAuthor(cur)
	v, removed := posts.Remove(slug)
	if !removed {
		panic("no such post: " + strconv.Quote(slug))
	}
	order.Remove(orderKey(v.(*post).date, slug))
	rev++
}

// SetIntro replaces the markdown shown above the index. Passing "" restores
// the built-in header.
func SetIntro(cur realm, body string) {
	assertAuthor(cur)
	rev++
	intro = body
}

// Get returns a post's raw markdown body, or "" when there is no such post.
func Get(slug string) string {
	v := posts.Get(slug)
	if v == nil {
		return ""
	}
	return v.(*post).body
}

// Count returns the number of published posts.
func Count() int { return posts.Size() }

// Revision returns the total number of writes this realm has accepted. It
// changes on every mutation, so a client can cheaply tell "nothing moved".
func Revision() int { return rev }

// Manifest returns one tab-separated line per post, plus one for the intro:
//
//	<slug>\t<rev>\t<date>\t<len of body>\t<sha256 of the canonical record>
//
// It is the diff surface tools/gnoblog reads with a single vm/qeval: the hash
// covers the title, date, tags and body together, so one read says exactly
// which local file needs a transaction without downloading a single body.
//
// The intro is reported under the key "!intro" with an empty date. '!' is not
// a legal slug character, so that row can never be confused with a post.
func Manifest() string {
	var b strings.Builder

	b.WriteString(introKey)
	b.WriteString("\t0\t\t")
	b.WriteString(strconv.Itoa(len(intro)))
	b.WriteString("\t")
	b.WriteString(hashOf(intro))
	b.WriteString("\n")

	posts.Iterate("", "", func(key string, value any) bool {
		p := value.(*post)
		b.WriteString(p.slug)
		b.WriteString("\t")
		b.WriteString(strconv.Itoa(p.rev))
		b.WriteString("\t")
		b.WriteString(p.date)
		b.WriteString("\t")
		b.WriteString(strconv.Itoa(len(p.body)))
		b.WriteString("\t")
		b.WriteString(hashOf(record(p.title, p.date, p.tags, p.body)))
		b.WriteString("\n")
		return false
	})
	return b.String()
}

package blog

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/uassert/v0"
)

// reset empties every package-level variable. ExampleRender runs after every
// Test in this package and would otherwise render whatever they left behind,
// so both the tests and the example start from here.
func reset() {
	posts = avl.NewTree()
	order = avl.NewTree()
	intro = ""
	rev = 0
}

// seed writes a post without going through Set, so a caller needs no
// `cur realm` and the example stays a plain function.
func seed(slug, title, date, tags, body string) {
	rev++
	p := &post{
		slug:  slug,
		title: title,
		date:  date,
		tags:  joinTags(splitTags(tags)),
		body:  body,
		rev:   rev,
	}
	posts.Set(slug, p)
	order.Set(orderKey(date, slug), p)
}

func TestValidSlug(t *testing.T) {
	for _, tc := range []struct {
		slug string
		want bool
	}{
		{"mygnoscan", true},
		{"a", true},
		{"hello-world.2", true},
		{"under_score", true},
		{"", false},
		{"Caps", false},
		{"has space", false},
		{"colon:here", false},
		{"slash/here", false},
		{"!intro", false},
		{strings.Repeat("a", maxSlugLen), true},
		{strings.Repeat("a", maxSlugLen+1), false},
	} {
		uassert.Equal(t, tc.want, validSlug(tc.slug), "validSlug("+tc.slug+")")
	}
}

func TestValidDate(t *testing.T) {
	for _, tc := range []struct {
		date string
		want bool
	}{
		{"2026-09-23", true},
		{"0000-00-00", true}, // shape only: ordering is all this field is for
		{"2026-9-23", false},
		{"2026/09/23", false},
		{"2026-09-233", false},
		{"", false},
	} {
		uassert.Equal(t, tc.want, validDate(tc.date), "validDate("+tc.date+")")
	}
}

func TestSplitTagsNormalizes(t *testing.T) {
	for _, tc := range []struct{ in, want string }{
		{"", ""},
		{"gno", "gno"},
		{" Gno , TOOLING ", "gno,tooling"},
		{"gno,gno,gno", "gno"},
		{"gno,,tooling", "gno,tooling"},
	} {
		uassert.Equal(t, tc.want, joinTags(splitTags(tc.in)), "splitTags("+tc.in+")")
	}
}

// A post published earlier must render below one published later, which is
// the only thing the second tree exists to guarantee.
func TestIndexIsNewestFirst(t *testing.T) {
	reset()
	seed("older", "Older", "2026-01-01", "", "First.")
	seed("newer", "Newer", "2026-09-23", "", "Second.")

	out := Render("")
	iNew := strings.Index(out, "Newer")
	iOld := strings.Index(out, "Older")
	uassert.True(t, iNew >= 0 && iOld >= 0, "both posts render")
	uassert.True(t, iNew < iOld, "the newer post renders first")
}

// Re-dating a post has to move it, not leave a ghost entry behind at the old
// key. Set is the only path that can do this, so it is checked through Set.
func TestRedatingMovesTheIndexEntry(t *testing.T) {
	reset()
	seed("a", "A", "2026-01-01", "", "Body A.")
	uassert.Equal(t, 1, order.Size(), "one order entry")

	// Emulate Set's re-key without needing a realm: remove then re-add.
	p := posts.Get("a").(*post)
	order.Remove(orderKey(p.date, "a"))
	p.date = "2026-12-31"
	order.Set(orderKey(p.date, "a"), p)

	uassert.Equal(t, 1, order.Size(), "still one order entry, not two")
	uassert.True(t, strings.Contains(Render(""), "2026-12-31"), "the new date renders")
}

func TestRenderPostAndNotFound(t *testing.T) {
	reset()
	seed("mygnoscan", "Sharing mygnoscan", "2026-09-23", "mygnoscan,tooling", "## Why\n\nBecause it is useful.")

	out := Render("mygnoscan")
	uassert.True(t, strings.Contains(out, "# Sharing mygnoscan"), "title renders as the H1")
	uassert.True(t, strings.Contains(out, "Because it is useful."), "body renders verbatim")
	uassert.True(t, strings.Contains(out, "## Why"), "markdown in the body is not escaped")

	missing := Render("nope")
	uassert.True(t, strings.Contains(missing, "Not found"), "an unknown slug is a 404, not the index")
}

func TestRenderTagFiltersAndReportsEmpty(t *testing.T) {
	reset()
	seed("a", "A", "2026-01-01", "tooling", "Body A.")
	seed("b", "B", "2026-01-02", "chain", "Body B.")

	out := Render("t/tooling")
	uassert.True(t, strings.Contains(out, "A"), "the tagged post is listed")
	uassert.False(t, strings.Contains(out, "](/r/moul/blog:b)"), "the untagged post is not")

	empty := Render("t/nothing")
	uassert.True(t, strings.Contains(empty, "No post carries this tag."), "an unused tag says so")
}

// The manifest is the whole diff protocol. A change to any of the four fields
// the record covers has to change the hash, or gnoblog reports a stale post as
// up to date and the fix never gets pushed.
func TestManifestHashCoversEveryField(t *testing.T) {
	base := record("T", "2026-01-01", "a", "body")
	for _, tc := range []struct {
		name string
		got  string
	}{
		{"title", record("T2", "2026-01-01", "a", "body")},
		{"date", record("T", "2026-01-02", "a", "body")},
		{"tags", record("T", "2026-01-01", "b", "body")},
		{"body", record("T", "2026-01-01", "a", "body2")},
	} {
		uassert.NotEqual(t, hashOf(base), hashOf(tc.got), "changing the "+tc.name+" changes the hash")
	}
}

func TestManifestShape(t *testing.T) {
	reset()
	seed("a", "A", "2026-01-01", "tooling", "Body A.")

	lines := strings.Split(strings.TrimRight(Manifest(), "\n"), "\n")
	uassert.Equal(t, 2, len(lines), "one intro row plus one post row")
	uassert.True(t, strings.HasPrefix(lines[0], introKey+"\t"), "the intro row comes first")

	f := strings.Split(lines[1], "\t")
	uassert.Equal(t, 5, len(f), "five tab-separated fields")
	uassert.Equal(t, "a", f[0], "slug")
	uassert.Equal(t, "2026-01-01", f[2], "date")
	uassert.Equal(t, "7", f[3], "body length")
	uassert.Equal(t, hashOf(record("A", "2026-01-01", "tooling", "Body A.")), f[4], "record hash")
}

func TestFirstLineSkipsHeadings(t *testing.T) {
	uassert.Equal(t, "The prose.", firstLine("# Title\n\n## Sub\n\nThe prose.\n"))
	uassert.Equal(t, "", firstLine("# Only a heading\n"))
}

func TestIntroDefaultsAndOverrides(t *testing.T) {
	reset()
	uassert.True(t, strings.Contains(Render(""), "moul's blog"), "the built-in header shows before SetIntro")

	intro = "# Something else"
	uassert.True(t, strings.Contains(Render(""), "Something else"), "a set intro replaces it")
	uassert.False(t, strings.Contains(Render(""), "moul's blog"), "and the default is gone")
}

package blog

import (
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
)

// linkPrefix is what a permalink starts with. gnoweb addresses a realm's
// render path with ':' after the package path, so this is realmPath with the
// leading "gno.land" dropped and the separator appended.
const linkPrefix = "/r/moul/blog:"

// defaultIntro is the header shown before SetIntro has ever been called, i.e.
// right after the first deploy or after a redeploy wiped the state.
const defaultIntro = "# moul's blog\n\nNotes on gno.land, from the person building on it.\n"

// Render serves three views:
//
//	""         the index, newest first
//	"<slug>"   one post
//	"t/<tag>"  every post carrying a tag
func Render(path string) string {
	path = strings.TrimSpace(path)
	switch {
	case path == "":
		return renderIndex()
	case strings.HasPrefix(path, "t/"):
		return renderTag(strings.TrimPrefix(path, "t/"))
	default:
		return renderPost(path)
	}
}

func header() string {
	if intro == "" {
		return defaultIntro
	}
	return strings.TrimRight(intro, "\n") + "\n"
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString(header())

	if posts.Size() == 0 {
		b.WriteString("\n")
		b.WriteString(ui.Empty("Nothing published yet."))
		return b.String()
	}

	// order is keyed by "<date>/<slug>", so walking it backwards is
	// newest-first without a sort the language does not have.
	order.ReverseIterate("", "", func(_ string, value any) bool {
		b.WriteString("\n")
		b.WriteString(entry(value.(*post)))
		return false
	})
	return b.String()
}

func renderTag(tag string) string {
	tag = strings.ToLower(strings.TrimSpace(tag))

	var b strings.Builder
	b.WriteString("# Tagged ")
	b.WriteString(ui.Inline(tag))
	b.WriteString("\n")

	found := 0
	order.ReverseIterate("", "", func(_ string, value any) bool {
		p := value.(*post)
		if !hasTag(p, tag) {
			return false
		}
		found++
		b.WriteString("\n")
		b.WriteString(entry(p))
		return false
	})
	if found == 0 {
		b.WriteString("\n")
		b.WriteString(ui.Empty("No post carries this tag."))
	}
	b.WriteString("\n[← all posts](" + linkPrefix + ")\n")
	return b.String()
}

func renderPost(slug string) string {
	v := posts.Get(slug)
	if v == nil {
		return "# Not found\n\nNo post at " + strconv.Quote(ui.Inline(slug)) +
			".\n\n[← all posts](" + linkPrefix + ")\n"
	}
	p := v.(*post)

	var b strings.Builder
	b.WriteString("# ")
	b.WriteString(ui.Inline(p.title))
	b.WriteString("\n\n")
	b.WriteString(byline(p))
	b.WriteString("\n\n")
	// The body is markdown written by `author`, who is also the only address
	// that can call Set. It is the post, so it renders verbatim: escaping it
	// would turn every heading and link in it into literal text.
	b.WriteString(strings.TrimRight(p.body, "\n"))
	b.WriteString("\n\n---\n\n[← all posts](" + linkPrefix + ")\n")
	return b.String()
}

// entry is one row of a listing: linked title, byline, excerpt.
func entry(p *post) string {
	var b strings.Builder
	b.WriteString("## [")
	b.WriteString(ui.Inline(p.title))
	b.WriteString("](")
	b.WriteString(linkPrefix)
	b.WriteString(p.slug)
	b.WriteString(")\n\n")
	b.WriteString(byline(p))
	b.WriteString("\n\n")
	b.WriteString(ui.Excerpt(firstLine(p.body), excerptLen))
	b.WriteString("\n")
	return b.String()
}

// byline is the date plus the post's tags as links, on one line.
func byline(p *post) string {
	var b strings.Builder
	b.WriteString(p.date)
	for _, t := range splitTags(p.tags) {
		b.WriteString(" · [#")
		b.WriteString(ui.Inline(t))
		b.WriteString("](")
		b.WriteString(linkPrefix)
		b.WriteString("t/")
		b.WriteString(t)
		b.WriteString(")")
	}
	return b.String()
}

func hasTag(p *post, tag string) bool {
	for _, t := range splitTags(p.tags) {
		if t == tag {
			return true
		}
	}
	return false
}

// firstLine returns the first non-empty, non-heading line of a body, which is
// what an excerpt should show: a post that opens with "## Something" would
// otherwise preview its own heading.
func firstLine(body string) string {
	for _, line := range strings.Split(body, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		return line
	}
	return ""
}

