// ExampleRender pins the index. It seeds state directly (rather than through
// Set) so the example takes no `cur realm`, and it resets first because an
// example runs after every Test in the package and would otherwise render what
// they left behind.
func ExampleRender() {
	reset()
	seed("mygnoscan", "Sharing mygnoscan", "2026-09-23", "mygnoscan,tooling", "An unfinished BI tool for gno.land.")
	seed("hello", "Hello", "2026-09-01", "meta", "Starting a blog on chain.")
	print(Render(""))
	// Output:
	// # moul's blog
	//
	// Notes on gno.land, from the person building on it.
	//
	// ## [Sharing mygnoscan](/r/moul/blog:mygnoscan)
	//
	// 2026-09-23 · [#mygnoscan](/r/moul/blog:t/mygnoscan) · [#tooling](/r/moul/blog:t/tooling)
	//
	// An unfinished BI tool for gno\.land\.
	//
	// ## [Hello](/r/moul/blog:hello)
	//
	// 2026-09-01 · [#meta](/r/moul/blog:t/meta)
	//
	// Starting a blog on chain\.
}

package blog

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var stranger = testutils.TestAddress("stranger")

// Everything here goes through the real crossing functions rather than seed(),
// because the author check, the re-key on a date change and the panic messages
// only exist on that path and are exactly what a typo would break on a
// permanent path.

func TestSetPublishesAndRenders(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(author))
	Set(cross(cur), "hello", "Hello", "2026-09-23", "Gno, tooling", "The body.")

	uassert.Equal(t, 1, Count(), "one post")
	uassert.Equal(t, "The body.", Get("hello"), "the body round-trips")
	uassert.True(t, strings.Contains(Render("hello"), "# Hello"), "it renders")
	// Tags are normalized on write, not on read, so the hash the tool computed
	// locally is the hash the manifest reports.
	uassert.True(t, strings.Contains(Manifest(), "\t"+hashOf(record("Hello", "2026-09-23", "gno,tooling", "The body."))),
		"the manifest hashes the normalized record")
}

func TestOnlyTheAuthorMayWrite(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(stranger))
	// AbortsWithMessage, not PanicsWithMessage: a panic that crosses a realm
	// boundary becomes an abort, which recover() cannot catch, so asserting it
	// as a panic does not fail the assertion, it kills the whole test binary.
	uassert.AbortsWithMessage(t, cur, "restricted to the author", func() {
		Set(cross(cur), "nope", "Nope", "2026-09-23", "", "Body.")
	})
	uassert.AbortsWithMessage(t, cur, "restricted to the author", func() {
		SetIntro(cross(cur), "mine now")
	})
	uassert.Equal(t, 0, Count(), "nothing was written")
}

// The one case a second tree can get wrong: re-dating a post must MOVE its
// index entry, not leave a ghost at the old key rendering the post twice.
func TestSetRedatingMovesTheIndexEntry(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(author))
	Set(cross(cur), "a", "A", "2026-01-01", "", "Body A.")
	Set(cross(cur), "a", "A", "2026-12-31", "", "Body A.")

	uassert.Equal(t, 1, Count(), "still one post")
	out := Render("")
	uassert.Equal(t, 1, strings.Count(out, "](/r/moul/blog:a)"), "listed exactly once")
	uassert.True(t, strings.Contains(out, "2026-12-31"), "under the new date")
	uassert.False(t, strings.Contains(out, "2026-01-01"), "and not the old one")
}

func TestSetRejectsWhatTheToolRejects(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(author))
	uassert.AbortsContains(t, cur, "invalid slug", func() {
		Set(cross(cur), "Caps", "T", "2026-09-23", "", "Body.")
	})
	uassert.AbortsContains(t, cur, "reserved slug", func() {
		Set(cross(cur), introSlug, "T", "2026-09-23", "", "Body.")
	})
	uassert.AbortsContains(t, cur, "invalid date", func() {
		Set(cross(cur), "ok", "T", "23-09-2026", "", "Body.")
	})
	uassert.AbortsContains(t, cur, "a post needs a title", func() {
		Set(cross(cur), "ok", "  ", "2026-09-23", "", "Body.")
	})
	uassert.Equal(t, 0, Count(), "none of them was written")
}

func TestAppendAndDelete(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(author))
	Set(cross(cur), "long", "Long", "2026-09-23", "", "First half.")
	Append(cross(cur), "long", " Second half.")
	uassert.Equal(t, "First half. Second half.", Get("long"), "append concatenates, it does not replace")

	uassert.AbortsWithMessage(t, cur, `no such post: "ghost"`, func() {
		Append(cross(cur), "ghost", "x")
	})

	Delete(cross(cur), "long")
	uassert.Equal(t, 0, Count(), "deleted")
	uassert.True(t, strings.Contains(Render(""), "Nothing published yet."), "and gone from the index")
	uassert.AbortsWithMessage(t, cur, `no such post: "long"`, func() {
		Delete(cross(cur), "long")
	})
}

func TestRevisionMovesOnEveryWrite(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(author))
	uassert.Equal(t, 0, Revision(), "a fresh realm is at zero")
	Set(cross(cur), "a", "A", "2026-09-23", "", "Body.")
	Append(cross(cur), "a", "!")
	SetIntro(cross(cur), "# Header")
	Delete(cross(cur), "a")
	uassert.Equal(t, 4, Revision(), "one per mutation, so a client can tell nothing moved")
}

package home

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// The crew roster lists everyone who built with samcrew, whether or not they
// have a gno.land identity yet.
//
// A member belongs to a team (engineering, media, ...) and starts with a
// public link, usually their GitHub profile. Once they have an on-chain
// identity, the admin runs LinkProfile: the card then links to their home
// realm (or /u/<address>), is marked ON CHAIN, and the member can write their
// own line with SetLine.

const (
	maxCrew      = 96 // each card costs render gas; keeps Render("") far below the query ceiling
	maxIDLen     = 32
	maxHandleLen = 32
	maxRoleLen   = 40
	maxLineLen   = 160
)

type member struct {
	id     string // stable key, [a-z0-9._-]
	handle string // shown on the card
	role   string
	team   string // [a-z0-9._-], groups the cards
	url    string // public link used until the member is on chain
	addr   address
	home   string // "/r/..." home realm, preferred link once set
	line   string
	order  int
	joined int64
}

var (
	crew      = avl.NewTree() // id -> *member
	byAddr    = avl.NewTree() // address string -> id, for SetLine
	nextOrder int
)

// oneLine rejects text that would break out of its markdown or SVG slot.
func oneLine(field, s string, max int) {
	if len(s) > max {
		panic(field + " too long: max " + strconv.Itoa(max) + " bytes")
	}
	if strings.ContainsAny(s, "|\n\r") {
		panic(field + " must be one line without '|'")
	}
}

func validURL(u string) bool {
	return (strings.HasPrefix(u, "https://") || strings.HasPrefix(u, "/") && !strings.HasPrefix(u, "//")) &&
		len(u) <= 200 && !strings.ContainsAny(u, " ()<>\"|\\\n\r")
}

// mdEscape turns member-written text into plain text: every character that
// markdown could read as a link, image, emphasis, code or HTML is escaped.
func mdEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		if strings.ContainsRune("\\`*_[]()<>!#|~{}", r) {
			b.WriteByte('\\')
		}
		b.WriteRune(r)
	}
	return b.String()
}

func addMember(id, handle, role, team, url string) {
	if len(id) > maxIDLen || !validSlug(id) {
		panic("invalid member id: want 1-32 bytes of [a-z0-9._-]")
	}
	if crew.Has(id) {
		panic("already in the crew: " + id)
	}
	if crew.Size() >= maxCrew {
		panic("the roster is full: " + strconv.Itoa(maxCrew) + " members")
	}
	m := &member{id: id}
	setIdentity(m, handle, role, team, url)
	nextOrder++
	m.order = nextOrder
	m.joined = runtime.ChainHeight()
	crew.Set(id, m)
}

func setIdentity(m *member, handle, role, team, url string) {
	if handle == "" {
		panic("handle required")
	}
	oneLine("handle", handle, maxHandleLen)
	oneLine("role", role, maxRoleLen)
	if len(team) > maxIDLen || !validSlug(team) {
		panic("invalid team: want 1-32 bytes of [a-z0-9._-]")
	}
	if !validURL(url) {
		panic("link must be https:// or a /path, without spaces or markdown characters")
	}
	m.handle, m.role, m.team, m.url = handle, role, team, url
}

func mustMember(id string) *member {
	v := crew.Get(id)
	if v == nil {
		panic("not in the crew: " + id)
	}
	return v.(*member)
}

// AddMember puts someone on the roster, in a team, linked to a public page.
func AddMember(cur realm, id, handle, role, team, url string) {
	assertAdmin(cur)
	addMember(id, handle, role, team, url)
}

// UpdateMember changes a member's handle, role, team and public link.
func UpdateMember(cur realm, id, handle, role, team, url string) {
	assertAdmin(cur)
	setIdentity(mustMember(id), handle, role, team, url)
}

// LinkProfile ties a member to their gno.land identity. home is their home
// realm path ("/r/..."), or "" to link to /u/<addr>. From then on the member
// can write their own line with SetLine.
func LinkProfile(cur realm, id string, addr address, home string) {
	assertAdmin(cur)
	m := mustMember(id)
	if !addr.IsValid() {
		panic("invalid address")
	}
	if home != "" && (!strings.HasPrefix(home, "/r/") || strings.ContainsAny(home, " ()<>\"|\\\n\r")) {
		panic("home must be a /r/... path")
	}
	if other := byAddr.Get(addr.String()); other != nil && other.(string) != id {
		panic("address already linked to " + other.(string))
	}
	if m.addr != "" {
		byAddr.Remove(m.addr.String())
	}
	if m.addr != addr {
		m.line = "" // a line belongs to the address that wrote it
	}
	m.addr, m.home = addr, home
	byAddr.Set(addr.String(), id)
}

// ClearLine removes a member's line, for moderation.
func ClearLine(cur realm, id string) {
	assertAdmin(cur)
	mustMember(id).line = ""
}

// RemoveMember takes someone off the roster.
func RemoveMember(cur realm, id string) {
	assertAdmin(cur)
	m := mustMember(id)
	if m.addr != "" {
		byAddr.Remove(m.addr.String())
	}
	crew.Remove(id)
}

// SetLine lets a crew member with a linked profile write their own line. It
// renders as plain text: markdown in it is escaped.
func SetLine(cur realm, line string) {
	caller := cur.Previous().Address()
	v := byAddr.Get(caller.String())
	if v == nil {
		panic("no crew profile linked to " + caller.String())
	}
	oneLine("line", line, maxLineLen)
	mustMember(v.(string)).line = line
}

// IsMember reports whether addr is linked to a crew profile.
func IsMember(addr address) bool { return byAddr.Has(addr.String()) }

// CrewSize returns the number of members on the roster.
func CrewSize() int { return crew.Size() }

// link is where a member's card points: home realm, then on-chain profile,
// then their public link.
func (m *member) link() string {
	switch {
	case m.home != "":
		return m.home
	case m.addr != "":
		return "/u/" + m.addr.String()
	}
	return m.url
}

// teamTitles names the known teams; any other team shows its raw name.
var teamTitles = map[string]string{
	"engineering": "Engineering crew",
	"media":       "Media crew",
	"alumni":      "Alumni",
}

// teamKinds picks the poster style of a team's cards.
var teamKinds = map[string]string{
	"media":  "member-media",
	"alumni": "member-alumni",
}

// crewTable shows the roster team by team, teams in the order their first
// member joined, members in the order they joined: one poster each, then the
// lines they wrote themselves.
func crewTable() string {
	if crew.Size() == 0 {
		return "_The roster is empty._"
	}
	members := make([]*member, 0, crew.Size())
	crew.Iterate("", "", func(_ string, v any) bool {
		m := v.(*member)
		i := len(members)
		members = append(members, m)
		for i > 0 && members[i-1].order > m.order {
			members[i] = members[i-1]
			i--
		}
		members[i] = m
		return false
	})

	var teams []string
	byTeam := map[string][]*member{}
	for _, m := range members {
		if _, ok := byTeam[m.team]; !ok {
			teams = append(teams, m.team)
		}
		byTeam[m.team] = append(byTeam[m.team], m)
	}

	var b strings.Builder
	onChain := 0
	var counts []string
	for _, team := range teams {
		group := byTeam[team]
		title := teamTitles[team]
		if title == "" {
			title = team
		}
		counts = append(counts, strconv.Itoa(len(group))+" "+strings.ToLower(strings.TrimSuffix(title, " crew")))
		b.WriteString("**" + title + "**")
		if team == "alumni" {
			b.WriteString(": former crew members who built gno with us.")
		}
		b.WriteString("\n\n")
		kind := teamKinds[team]
		if kind == "" {
			kind = "member"
		}
		for i := 0; i < len(group); i += cardsPerRow {
			b.WriteString("<gno-columns>\n")
			for j := i; j < i+cardsPerRow; j++ {
				if j > i {
					b.WriteString("<gno-columns-sep />\n")
				}
				if j >= len(group) {
					continue
				}
				m := group[j]
				n := strconv.Itoa(j + 1)
				if j < 9 {
					n = "0" + n
				}
				label := strings.ToUpper(strings.TrimSuffix(title, " crew")) + " · " + n
				if m.addr != "" {
					label += " · ON CHAIN"
					onChain++
				}
				c := card{kind: kind, title: m.handle, meta: m.role, url: m.link(), label: label}
				b.WriteString("[![" + mdText(m.handle) + "](" + posterURI(c) + ")](" + c.url + ")\n")
			}
			b.WriteString("</gno-columns>\n\n")
		}
	}

	b.WriteString("*" + strconv.Itoa(len(members)) + " samurai (" + strings.Join(counts, ", ") + "), " +
		strconv.Itoa(onChain) + " on chain so far. A card links to its owner's public page until they have a gno.land profile.*")

	var lines strings.Builder
	for _, m := range members {
		if m.line != "" {
			lines.WriteString("- **[" + mdText(m.handle) + "](" + m.link() + ")**: " + mdEscape(m.line) + "\n")
		}
	}
	if lines.Len() > 0 {
		b.WriteString("\n\n**In their own words.**\n\n" + lines.String())
	}
	b.WriteString("\n*Crew members on chain write their own line with [SetLine](" + webPath + "$help&func=SetLine).*")
	return b.String()
}

package home

import (
	"encoding/base64"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// This file is shared, unchanged, by every Samouraï home realm.
//
// A gallery is a named list of cards. gnoweb's CSP only paints images from a
// few hosts (YouTube thumbnails are not among them) but it allows
// data:image/svg+xml, so every card is a poster drawn here, on chain, and
// linked to its video or site.
//
// A gallery is written in one Set-like call as lines of
//
//	kind | title | meta | url [| description]
//
// The optional description becomes the card's hover text.
// and rendered wherever the layout says :gallery.<name>:.

const (
	galleryPrefix = "gallery."
	cardsPerRow   = 3
	maxCards      = 48
	maxTitleLen   = 80
	maxMetaLen    = 80
	maxDescLen    = 200
)

type card struct {
	kind, title, meta, url string
	desc                   string // hover text, optional
	label                  string // overrides the kind's label when set
}

var galleries = avl.NewTree() // name -> []card

type style struct {
	label, glyph, accent, shade string
	video                       bool
}

var styles = map[string]style{
	"report":        {"CONTRIBUTION REPORT", "報", "#e63946", "#3a1014", true},
	"gno":           {"GNO.LAND · FILMED BY SAMOURAÏ", "道", "#2ec4b6", "#0d2e2b", true},
	"webtrip":       {"WEB TRIP · SERIES", "旅", "#ff7aa2", "#3a1422", true},
	"peerdev":       {"PEER DEV · GNO TUTORIAL", "学", "#4ea8de", "#0f2536", true},
	"event":         {"EVENT", "祭", "#f4a261", "#3a2412", true},
	"festival":      {"FESTIVAL · BY SAMOURAÏ", "祭", "#f4a261", "#3a2412", false},
	"film":          {"FILM · DIRECTED BY THE CREW", "映", "#b388eb", "#261a36", true},
	"product":       {"PRODUCT", "作", "#e9c46a", "#352b10", false},
	"memba":         {"MEMBA · PRODUCT", "組", "#e9c46a", "#352b10", false},
	"game":          {"ARCADE · PLAY IN MEMBA", "遊", "#8ac926", "#1c2a0b", true},
	"oss":           {"OPEN SOURCE · GITHUB", "源", "#a8b3bd", "#1b2026", false},
	"blog":          {"BLOG · SAMOURAI.WORLD", "記", "#e8e2d8", "#2a2620", false},
	"member":        {"SAMOURAÏ · CREW", "侍", "#e63946", "#2a1012", false},
	"member-media":  {"SAMOURAÏ · MEDIA", "映", "#b388eb", "#261a36", false},
	"member-alumni": {"SAMOURAÏ · ALUMNI", "侍", "#9aa0a6", "#1d1f22", false},
}

func styleOf(kind string) style {
	if s, ok := styles[kind]; ok {
		return s
	}
	return style{strings.ToUpper(kind), "侍", "#e63946", "#2a1012", false}
}

// SetGallery replaces a whole gallery from its line format.
func SetGallery(cur realm, name, spec string) {
	assertAdmin(cur)
	if !validSlug(name) {
		panic("invalid gallery name: " + name)
	}
	cards := parseGallery(spec)
	rev++
	galleries.Set(name, cards)
}

// DeleteGallery removes a gallery.
func DeleteGallery(cur realm, name string) {
	assertAdmin(cur)
	if _, removed := galleries.Remove(name); !removed {
		panic("no such gallery: " + name)
	}
	rev++
}

func parseGallery(spec string) []card {
	var cards []card
	for _, line := range strings.Split(spec, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		f := strings.Split(line, "|")
		if len(f) != 4 && len(f) != 5 {
			panic("gallery line needs 4 or 5 fields (kind | title | meta | url [| description]): " + line)
		}
		c := card{
			kind:  strings.TrimSpace(f[0]),
			title: strings.TrimSpace(f[1]),
			meta:  strings.TrimSpace(f[2]),
			url:   strings.TrimSpace(f[3]),
		}
		if len(f) == 5 {
			c.desc = strings.TrimSpace(f[4])
			if len(c.desc) > maxDescLen || strings.ContainsAny(c.desc, "\"\\") {
				panic("gallery description must be at most 200 bytes, without quotes or backslashes: " + line)
			}
		}
		if !validSlug(c.kind) || c.title == "" || len(c.title) > maxTitleLen || len(c.meta) > maxMetaLen {
			panic("bad gallery line: " + line)
		}
		if !strings.HasPrefix(c.url, "https://") && (!strings.HasPrefix(c.url, "/") || strings.HasPrefix(c.url, "//")) {
			panic("gallery url must be https:// or a /path: " + c.url)
		}
		if strings.ContainsAny(c.url, " ()<>\"\\") {
			panic("gallery url has characters markdown would break on: " + c.url)
		}
		cards = append(cards, c)
	}
	if len(cards) == 0 || len(cards) > maxCards {
		panic("a gallery holds 1 to 48 cards")
	}
	return cards
}

// renderGallery lays cards out cardsPerRow to a row, each one a poster that
// links to its target.
func renderGallery(name string) (string, bool) {
	v := galleries.Get(name)
	if v == nil {
		return "", false
	}
	cards := v.([]card)
	var b strings.Builder
	for i := 0; i < len(cards); i += cardsPerRow {
		b.WriteString("<gno-columns>\n")
		for j := i; j < i+cardsPerRow; j++ {
			if j > i {
				b.WriteString("<gno-columns-sep />\n")
			}
			if j < len(cards) {
				c := cards[j]
				b.WriteString("[![" + mdText(c.title) + "](" + posterURI(c) + ")](" + c.url + linkTitle(c.desc) + ")\n")
			}
		}
		b.WriteString("</gno-columns>\n\n")
	}
	return strings.TrimSuffix(b.String(), "\n\n"), true
}

// linkTitle renders an optional markdown link title, which gnoweb emits as
// the link's hover text.
func linkTitle(desc string) string {
	if desc == "" {
		return ""
	}
	return ` "` + desc + `"`
}

// mdText keeps a title from closing the markdown image alt text early.
func mdText(s string) string {
	return strings.NewReplacer("[", "(", "]", ")", "\\", "/").Replace(s)
}

func xmlText(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", "\"", "&quot;", "'", "&#39;").Replace(s)
}

// wrap splits s into at most two lines of about width runes; the second line
// is cut with an ellipsis when the title is longer.
func wrap(s string, width int) []string {
	words := strings.Fields(s)
	var lines []string
	cur := ""
	for _, w := range words {
		if cur == "" {
			cur = w
		} else if runeLen(cur)+1+runeLen(w) <= width {
			cur += " " + w
		} else {
			lines = append(lines, cur)
			cur = w
		}
	}
	if cur != "" {
		lines = append(lines, cur)
	}
	if len(lines) > 2 {
		second := []rune(strings.Join(lines[1:], " "))
		if len(second) > width {
			second = append(second[:width-1], '…')
		}
		lines = []string{lines[0], string(second)}
	}
	return lines
}

func runeLen(s string) int { return len([]rune(s)) }

// clip cuts s to at most n runes, ending with an ellipsis when it had to cut.
func clip(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(append(r[:n-1], '…'))
}

func posterURI(c card) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(poster(c)))
}

// poster draws a 320x180 card: a dark gradient, a rising sun in the kind's
// accent (a play button for videos), a large kanji watermark, the kind label,
// the title on up to two lines and a meta line.
func poster(c card) string {
	st := styleOf(c.kind)
	if c.label != "" {
		st.label = c.label
	}
	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180" viewBox="0 0 320 180">`)
	b.WriteString(`<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#121212"/><stop offset="1" stop-color="` + st.shade + `"/></linearGradient></defs>`)
	b.WriteString(`<rect width="320" height="180" rx="14" fill="url(#g)"/>`)
	b.WriteString(`<text x="306" y="170" text-anchor="end" font-family="serif" font-size="120" fill="#ffffff" fill-opacity=".06">` + st.glyph + `</text>`)
	b.WriteString(`<circle cx="268" cy="52" r="30" fill="` + st.accent + `"/>`)
	if st.video {
		b.WriteString(`<path d="M260 38 L282 52 L260 66 Z" fill="#121212"/>`)
	} else {
		b.WriteString(`<path d="M256 52 H280 M272 44 L280 52 L272 60" stroke="#121212" stroke-width="4" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`)
	}
	b.WriteString(`<rect x="18" y="20" width="3" height="12" fill="` + st.accent + `"/>`)
	b.WriteString(`<text x="27" y="31" font-family="ui-monospace,Menlo,monospace" font-size="10" letter-spacing="1.5" fill="` + st.accent + `">` + xmlText(st.label) + `</text>`)
	lines := wrap(c.title, 24)
	y := 108
	if len(lines) == 1 {
		y = 126
	}
	for _, l := range lines {
		b.WriteString(`<text x="18" y="` + itoa(y) + `" font-family="system-ui,-apple-system,Segoe UI,sans-serif" font-weight="700" font-size="20" fill="#ffffff">` + xmlText(l) + `</text>`)
		y += 25
	}
	// The meta line hugs the bottom-right corner: gnoweb draws its
	// external-link badge over the bottom-left one.
	b.WriteString(`<text x="304" y="164" text-anchor="end" font-family="ui-monospace,Menlo,monospace" font-size="11" fill="#bdbdbd">` + xmlText(clip(c.meta, 40)) + `</text>`)
	b.WriteString(`</svg>`)
	return b.String()
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var d []byte
	for n > 0 {
		d = append([]byte{byte('0' + n%10)}, d...)
		n /= 10
	}
	return string(d)
}

// Package home is samcrew's page on gno.land, served at /u/samcrew.
//
// The page is assembled from SLOTS (named markdown fragments, one Set each);
// the slot named "layout" is the template and every :slug: in it is filled in
// a single pass. The crew roster is not a slot: see crew.gno.
//
// The admin starts as the samcrew namespace multisig and moves with a
// two-step ProposeAdmin / AcceptAdmin, so it can later be handed to the DAO.
package home

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

const (
	layoutSlug = "layout"
	maxSlugLen = 64
)

type slot struct {
	body    string
	rev     int
	updated int64
}

var (
	admin        = address("g136j0m08pkm2lwwde9dmlx8uee26llent9s5cpf") // samcrew namespace, 2-of-3
	pendingAdmin address

	slots = avl.NewTree() // slug -> *slot
	rev   int
)

var reservedSlugs = []string{"chainid", "crew", "height", "hero", "realm", "rev"}

func init() {
	h := runtime.ChainHeight()
	for _, s := range defaultSlots() {
		rev++
		slots.Set(s.slug, &slot{body: s.body, rev: rev, updated: h})
	}
	for _, g := range defaultGalleries() {
		galleries.Set(g.name, parseGallery(g.spec))
	}
	for _, m := range defaultCrew() {
		addMember(m.id, m.handle, m.role, m.team, m.url)
	}
	for _, p := range defaultProfiles() {
		m := mustMember(p.id)
		m.addr, m.home, m.line = p.addr, p.home, p.line
		byAddr.Set(p.addr.String(), p.id)
	}
}

// ---------------------------------------------------------------------------
// Admin

func assertAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("restricted to admin")
	}
}

// Admin returns the current admin address.
func Admin() address { return admin }

// ProposeAdmin starts a handover. Nothing changes until the new address calls
// AcceptAdmin, so a typo cannot lock the page.
func ProposeAdmin(cur realm, next address) {
	assertAdmin(cur)
	if !next.IsValid() {
		panic("invalid address")
	}
	pendingAdmin = next
}

// AcceptAdmin completes a handover started by ProposeAdmin.
func AcceptAdmin(cur realm) {
	caller := cur.Previous().Address()
	if pendingAdmin == "" || caller != pendingAdmin {
		panic("restricted to the proposed admin")
	}
	admin = caller
	pendingAdmin = ""
}

// ---------------------------------------------------------------------------
// Slots

func validSlug(slug string) bool {
	if len(slug) == 0 || len(slug) > maxSlugLen {
		return false
	}
	for i := 0; i < len(slug); i++ {
		c := slug[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-' || c == '_' || c == '.') {
			return false
		}
	}
	return true
}

func assertWritableSlug(slug string) {
	if !validSlug(slug) {
		panic("invalid slug: want 1-" + strconv.Itoa(maxSlugLen) + " bytes of [a-z0-9._-], got " + strconv.Quote(slug))
	}
	for _, r := range reservedSlugs {
		if slug == r {
			panic("reserved slug: " + slug)
		}
	}
	if strings.HasPrefix(slug, galleryPrefix) {
		panic("reserved slug: " + galleryPrefix + "* renders a gallery, use SetGallery")
	}
}

// Set creates or replaces one slot.
func Set(cur realm, slug, body string) {
	assertAdmin(cur)
	assertWritableSlug(slug)
	rev++
	slots.Set(slug, &slot{body: body, rev: rev, updated: runtime.ChainHeight()})
}

// Delete removes a slot. Deleting "layout" falls back to the built-in layout.
func Delete(cur realm, slug string) {
	assertAdmin(cur)
	if _, removed := slots.Remove(slug); !removed {
		panic("no such slot: " + slug)
	}
	rev++
}

// Get returns a slot body, or "" when the slot does not exist.
func Get(slug string) string {
	if v := slots.Get(slug); v != nil {
		return v.(*slot).body
	}
	return ""
}

package home

import (
	"strconv"
	"strings"

	"chain/runtime"
)

const (
	realmPath = "gno.land/r/samcrew/home"
	webPath   = "/r/samcrew/home"
)

const fallbackLayout = "# samcrew\n\n:intro:\n\n## The crew\n\n:crew:\n"

// Render serves:
//
//	""             the team page
//	"slots"        the slot index
//	"slots/<slug>" one slot's raw markdown
func Render(path string) string {
	switch {
	case path == "":
		return renderPage()
	case path == "slots":
		return renderIndex()
	case strings.HasPrefix(path, "slots/"):
		return renderSlot(strings.TrimPrefix(path, "slots/"))
	}
	// The path is not echoed: it comes from the visitor's URL.
	return "# Not found\n\nThis page does not exist.\n\n[Back home](" + webPath + ")\n"
}

func renderPage() string {
	layout := Get(layoutSlug)
	if layout == "" {
		layout = fallbackLayout
	}
	return fill(layout)
}

// fill replaces every :slug: in s, in one left-to-right pass. Replacement text
// is never rescanned, and an unknown placeholder stays verbatim.
func fill(s string) string {
	var b strings.Builder
	for {
		i := strings.IndexByte(s, ':')
		if i < 0 {
			b.WriteString(s)
			return b.String()
		}
		b.WriteString(s[:i])
		s = s[i:]
		j := strings.IndexByte(s[1:], ':')
		if j < 0 {
			b.WriteString(s)
			return b.String()
		}
		if v, ok := lookup(s[1 : j+1]); ok {
			b.WriteString(v)
			s = s[j+2:]
			continue
		}
		b.WriteString(":")
		s = s[1:]
	}
}

func lookup(slug string) (string, bool) {
	if !validSlug(slug) {
		return "", false
	}
	switch slug {
	case "chainid":
		return runtime.ChainID(), true
	case "crew":
		return crewTable(), true
	case "hero":
		return heroImage(), true
	case "height":
		return strconv.FormatInt(runtime.ChainHeight(), 10), true
	case "realm":
		return realmPath, true
	case "rev":
		return strconv.Itoa(rev), true
	}
	if strings.HasPrefix(slug, galleryPrefix) {
		return renderGallery(strings.TrimPrefix(slug, galleryPrefix))
	}
	if v := slots.Get(slug); v != nil {
		return v.(*slot).body, true
	}
	return "", false
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# Slots\n\nrev " + strconv.Itoa(rev) + " · " + strconv.Itoa(slots.Size()) + " slot(s) · admin " + admin.String() + "\n\n")
	b.WriteString("| slot | bytes | rev | height |\n| --- | ---: | ---: | ---: |\n")
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*slot)
		b.WriteString("| [" + key + "](" + webPath + ":slots/" + key + ") | " +
			strconv.Itoa(len(s.body)) + " | " + strconv.Itoa(s.rev) + " | " +
			strconv.FormatInt(s.updated, 10) + " |\n")
		return false
	})
	return b.String()
}

func renderSlot(slug string) string {
	v := slots.Get(slug)
	if v == nil {
		return "# Not found\n\nNo such slot.\n\n[Slot index](" + webPath + ":slots)\n"
	}
	s := v.(*slot)
	body := s.body
	if !strings.HasSuffix(body, "\n") {
		body += "\n"
	}
	return "# " + slug + "\n\n" + strconv.Itoa(len(s.body)) + " bytes · rev " + strconv.Itoa(s.rev) +
		" · written at height " + strconv.FormatInt(s.updated, 10) + "\n\n````\n" + body + "````\n"
}

// Package commit provides small, deterministic commitment helpers shared by
// the agent demos. On-chain realms store *commitments* to off-chain data
// (reports, patches, verdicts) rather than the data itself; this package is
// the one place that defines how those commitments are computed, so several
// realms agree on the scheme.
package commit

import (
	"crypto/sha256"
	"encoding/hex"
)

// Hash returns the hex-encoded SHA-256 over its parts, length-prefixed so
// that Hash("ab","c") != Hash("a","bc"). Use it to commit to structured
// off-chain material without revealing it.
func Hash(parts ...string) string {
	var buf []byte
	for _, p := range parts {
		buf = appendUvarint(buf, uint64(len(p)))
		buf = append(buf, p...)
	}
	sum := sha256.Sum256(buf)
	return hex.EncodeToString(sum[:])
}

// Verdict is the canonical commitment used by commit-reveal voting: a hidden
// boolean plus a salt. Reveal the same (verdict, salt) later and any observer
// can recompute this and confirm the vote was not changed after the fact.
func Verdict(verdict bool, salt string) string {
	v := "no"
	if verdict {
		v = "yes"
	}
	return Hash("verdict", v, salt)
}

// Short abbreviates a hex commitment for display.
func Short(h string) string {
	if len(h) <= 12 {
		return h
	}
	return h[:6] + "…" + h[len(h)-4:]
}

func appendUvarint(buf []byte, x uint64) []byte {
	for x >= 0x80 {
		buf = append(buf, byte(x)|0x80)
		x >>= 7
	}
	return append(buf, byte(x))
}

package commit

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
)

func TestHashDeterministicAndPrefixed(t *testing.T) {
	uassert.Equal(t, Hash("a", "bc"), Hash("a", "bc"))
	// length-prefixing prevents boundary collisions
	uassert.NotEqual(t, Hash("ab", "c"), Hash("a", "bc"))
	uassert.Equal(t, 64, len(Hash("x"))) // sha256 hex is 64 chars
}

func TestVerdictCommitReveal(t *testing.T) {
	c := Verdict(true, "salt-123")
	// reproducible from the revealed values
	uassert.Equal(t, c, Verdict(true, "salt-123"))
	// flipping the vote or the salt changes the commitment
	uassert.NotEqual(t, c, Verdict(false, "salt-123"))
	uassert.NotEqual(t, c, Verdict(true, "salt-999"))
}

func TestShort(t *testing.T) {
	uassert.Equal(t, "abc", Short("abc"))
	uassert.True(t, len(Short(Hash("x"))) < 20)
}

package forge

import "gno.land/p/nt/avl/v0"

// Change states.
const (
	StateOpen   = "open"
	StateMerged = "merged"
	StateClosed = "closed"
)

// Review verdicts.
const (
	VerdictApprove        = "approve"
	VerdictRequestChanges = "request-changes"
	VerdictComment        = "comment"
)

// Change is a change request (a pull request): a claim that TargetRef should be
// moved to include HeadOID, plus the reviews of that claim.
//
// Reviews are bound to the object id they reviewed, not to the change. Push a
// new head and every earlier approval stops counting: not by a policy toggle a
// maintainer can switch off, but because the approval names an object that is
// no longer what is being merged.
type Change struct {
	ID         int64
	Title      string
	Body       string
	Author     address
	SourceRepo string // forge repo id, or a mirror locator; "" means this repo
	SourceRef  string
	HeadOID    string
	TargetRef  string
	State      string
	CreatedAt  int64
	UpdatedAt  int64

	MergedOID string // the object TargetRef moved to
	MergedBy  address
	MergedAt  int64

	reviews     *avl.Tree // address string -> *Review (latest per reviewer)
	comments    *avl.Tree // padded id -> *Comment
	nextComment int64
}

// Review is one reviewer's verdict on one object id.
type Review struct {
	Reviewer address
	Verdict  string
	OID      string // the head the reviewer actually looked at
	Body     string
	Height   int64
}

// OpenChange files a change request. Permissionless, like an issue: the
// proposal costs its author gas and deposit, and costs a maintainer nothing
// until they choose to look.
func (r *Repo) OpenChange(actor address, height int64, title, body, sourceRepo, sourceRef, headOID, targetRef string) (*Change, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if title == "" || !ValidLine(title, MaxTitleLen) {
		return nil, ErrInvalidText
	}
	if !ValidText(body, MaxBodyLen) {
		return nil, ErrInvalidText
	}
	if sourceRepo != "" && !ValidRepoID(sourceRepo) && !ValidMirror(sourceRepo) {
		return nil, ErrInvalidRepoID
	}
	if sourceRef != "" && !ValidRefName(sourceRef) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(headOID) {
		return nil, ErrInvalidOID
	}
	if !ValidRefName(targetRef) {
		return nil, ErrInvalidRefName
	}
	c := &Change{
		ID:         r.nextChange,
		Title:      title,
		Body:       body,
		Author:     actor,
		SourceRepo: sourceRepo,
		SourceRef:  sourceRef,
		HeadOID:    headOID,
		TargetRef:  targetRef,
		State:      StateOpen,
		CreatedAt:  height,
		UpdatedAt:  height,
		reviews:    avl.NewTree(),
		comments:   avl.NewTree(),
	}
	r.changes.Set(seqKey(c.ID), c)
	r.nextChange++
	return c, nil
}

// UpdateChangeHead repoints an open change at a new object. The author may
// always update their own; a writer may update anyone's (the "maintainer pushed
// a fixup" case).
func (r *Repo) UpdateChangeHead(actor address, height, id int64, headOID string) error {
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	if c.Author != actor && !r.Can(actor, RoleWriter) {
		return ErrUnauthorized
	}
	if !ValidOID(headOID) {
		return ErrInvalidOID
	}
	if headOID == c.HeadOID {
		return ErrSameOID
	}
	c.HeadOID = headOID
	c.UpdatedAt = height
	return nil
}

// ReviewChange records a verdict against the change's current head. Anyone may
// review; only a writer's approval counts toward the merge policy (see
// CountApprovals): an unprivileged review is signal, not authority.
func (r *Repo) ReviewChange(actor address, height, id int64, verdict, body string) error {
	if r.Archived {
		return ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	switch verdict {
	case VerdictApprove, VerdictRequestChanges, VerdictComment:
	default:
		return ErrInvalidVerdict
	}
	if verdict == VerdictApprove && actor == c.Author && !r.AllowSelfApproval {
		return ErrSelfApproval
	}
	if !ValidText(body, MaxCommentLen) {
		return ErrInvalidText
	}
	c.reviews.Set(actor.String(), &Review{
		Reviewer: actor,
		Verdict:  verdict,
		OID:      c.HeadOID,
		Body:     body,
		Height:   height,
	})
	c.UpdatedAt = height
	return nil
}

// CommentChange appends a reply to a change request.
func (r *Repo) CommentChange(actor address, height, id int64, body string) (*Comment, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return nil, ErrChangeNotFound
	}
	if body == "" || !ValidText(body, MaxCommentLen) {
		return nil, ErrInvalidText
	}
	cm := &Comment{ID: c.nextComment, Author: actor, Body: body, CreatedAt: height}
	c.comments.Set(seqKey(cm.ID), cm)
	c.nextComment++
	c.UpdatedAt = height
	return cm, nil
}

// CloseChange withdraws or rejects a change. Author or maintainer.
func (r *Repo) CloseChange(actor address, height, id int64) error {
	c := r.Change(id)
	if c == nil {
		return ErrChangeNotFound
	}
	if c.State != StateOpen {
		return ErrChangeNotOpen
	}
	if c.Author != actor && !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	c.State = StateClosed
	c.UpdatedAt = height
	return nil
}

// CountApprovals counts approvals that still apply: cast by a writer or above,
// against the change's current head, and (unless the repo allows it) not the
// author's own.
func (r *Repo) CountApprovals(c *Change) int {
	n := 0
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		rv := value.(*Review)
		if rv.Verdict != VerdictApprove || rv.OID != c.HeadOID {
			return false
		}
		if rv.Reviewer == c.Author && !r.AllowSelfApproval {
			return false
		}
		if !r.Can(rv.Reviewer, RoleWriter) {
			return false
		}
		n++
		return false
	})
	return n
}

// CountBlocking counts writers who requested changes on the current head.
func (r *Repo) CountBlocking(c *Change) int {
	n := 0
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		rv := value.(*Review)
		if rv.Verdict == VerdictRequestChanges && rv.OID == c.HeadOID && r.Can(rv.Reviewer, RoleWriter) {
			n++
		}
		return false
	})
	return n
}

// MergeChange moves TargetRef to mergedOID and records the move as one more
// entry in the reference log, tagged with the change it came from.
//
// expectedTargetOID is a compare-and-swap on the target ref ("" when the ref
// does not exist yet): a change approved against one base cannot be merged onto
// a base that moved underneath it. mergedOID is computed off chain by whoever
// performs the merge: the chain records the claim, signed, ordered and
// attributed, and a client with the objects verifies that the result actually
// contains HeadOID.
func (r *Repo) MergeChange(actor address, height, id int64, expectedTargetOID, mergedOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	c := r.Change(id)
	if c == nil {
		return nil, ErrChangeNotFound
	}
	if c.State != StateOpen {
		return nil, ErrChangeNotOpen
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidOID(mergedOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	if r.CountBlocking(c) > 0 {
		return nil, ErrChangesRequested
	}
	if r.CountApprovals(c) < r.RequiredApprovals {
		return nil, ErrNotEnoughApproval
	}
	cur := r.Ref(c.TargetRef)
	switch {
	case cur == nil && expectedTargetOID != "":
		return nil, ErrRefNotFound
	case cur != nil && cur.OID != expectedTargetOID:
		return nil, ErrStaleRef
	case cur != nil && cur.OID == mergedOID:
		return nil, ErrSameOID
	}
	old := ""
	if cur != nil {
		old = cur.OID
	}
	r.refs.Set(c.TargetRef, &Ref{Name: c.TargetRef, OID: mergedOID, UpdatedAt: height, UpdatedBy: actor})
	e := r.appendLog(actor, height, c.TargetRef, old, mergedOID, KindMerge, c.ID, note)
	c.State = StateMerged
	c.MergedOID = mergedOID
	c.MergedBy = actor
	c.MergedAt = height
	c.UpdatedAt = height
	return e, nil
}

// Change returns a change by id, or nil.
func (r *Repo) Change(id int64) *Change {
	v := r.changes.Get(seqKey(id))
	if v == nil {
		return nil
	}
	return v.(*Change)
}

// IterateChanges walks change requests newest-first.
func (r *Repo) IterateChanges(offset, count int, cb func(*Change) bool) {
	if count <= 0 {
		count = r.changes.Size()
	}
	r.changes.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Change))
	})
}

// OpenChangeCount counts change requests still open.
func (r *Repo) OpenChangeCount() int {
	n := 0
	r.changes.Iterate("", "", func(_ string, value any) bool {
		if value.(*Change).State == StateOpen {
			n++
		}
		return false
	})
	return n
}

// ReviewCount is the number of reviewers who have weighed in (latest verdict
// per reviewer, on any head).
func (c *Change) ReviewCount() int { return c.reviews.Size() }

// Review returns a reviewer's latest verdict, or nil.
func (c *Change) Review(a address) *Review {
	v := c.reviews.Get(a.String())
	if v == nil {
		return nil
	}
	return v.(*Review)
}

// IterateReviews walks reviews in reviewer-address order.
func (c *Change) IterateReviews(cb func(*Review) bool) {
	c.reviews.Iterate("", "", func(_ string, value any) bool {
		return cb(value.(*Review))
	})
}

// CommentCount is the number of replies on the change.
func (c *Change) CommentCount() int { return c.comments.Size() }

// IterateComments walks replies oldest-first.
func (c *Change) IterateComments(offset, count int, cb func(*Comment) bool) {
	if count <= 0 {
		count = c.comments.Size()
	}
	c.comments.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Comment))
	})
}

// Stale reports whether a review no longer applies to the change's head.
func (c *Change) Stale(rv *Review) bool { return rv.OID != c.HeadOID }

// Package forge is the domain engine of an on-chain software forge: repos,
// roles, an append-only reference log, issues and change requests (pull
// requests), with no chain imports of its own.
//
// What it does NOT do, on purpose: store blobs, trees or packfiles. Git objects
// stay wherever git already puts them (a mirror, an IPFS CID, a peer) and this
// package records what a forge is actually trusted for and what git alone does
// not authenticate:
//
//  1. which object id a ref points at, in what order it got there, and who said
//     so: an append-only, hash-chained reference log (the same shape as
//     gittuf's reference state log, with consensus playing the notary);
//  2. who is allowed to move which ref, and under what review policy;
//  3. the social layer: issues, change requests, reviews: bound to addresses
//     rather than to platform accounts;
//  4. the merge decision itself, recorded as one more entry in the same log.
//
// The chain cannot see the object graph, so it cannot verify that a new tip
// descends from the old one. It does not pretend to: every ref move is a
// compare-and-swap against the tip the caller expected (git's
// --force-with-lease, moved somewhere the forge operator cannot rewrite), any
// move that abandons that discipline is recorded as a force, and ancestry is
// checked by a client that has the objects. Ordering, attribution and policy
// are on chain; proof is local.
//
// All state lives in avl trees so every listing is ordered and paginatable, and
// every mutation takes the actor and the block height from the caller: the
// package is pure, deterministic and unit-testable without a chain.
//
// Live demo: gno.land/r/moul/forge/v0.
package forge

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Role is a repo-scoped capability level. Roles are totally ordered: every
// check is "at least this role", so there is one comparison to audit.
type Role int

const (
	RoleNone       Role = iota // not a member
	RoleReader                 // explicit read (all repos are public in v0)
	RoleWriter                 // move non-protected refs, update own changes
	RoleMaintainer             // force-move refs, merge changes, triage issues
	RoleAdmin                  // manage members and repo settings
	RoleOwner                  // admin + transfer; at least one always exists
)

// String renders the role as the lowercase token used by the realm API.
func (r Role) String() string {
	switch r {
	case RoleReader:
		return "reader"
	case RoleWriter:
		return "writer"
	case RoleMaintainer:
		return "maintainer"
	case RoleAdmin:
		return "admin"
	case RoleOwner:
		return "owner"
	default:
		return "none"
	}
}

// ParseRole is the inverse of Role.String.
func ParseRole(s string) (Role, error) {
	switch s {
	case "none":
		return RoleNone, nil
	case "reader":
		return RoleReader, nil
	case "writer":
		return RoleWriter, nil
	case "maintainer":
		return RoleMaintainer, nil
	case "admin":
		return RoleAdmin, nil
	case "owner":
		return RoleOwner, nil
	}
	return RoleNone, ErrInvalidRole
}

// Forge is the top-level registry: repo id -> repo.
type Forge struct {
	repos *avl.Tree // "<namespace>/<name>" -> *Repo
}

// New returns an empty forge.
func New() *Forge {
	return &Forge{repos: avl.NewTree()}
}

// Repo is one repository. Nothing here is the code: Mirrors says where the
// objects can be fetched, Refs says what the objects are supposed to be.
type Repo struct {
	ID          string // "<namespace>/<name>", immutable
	Description string
	DefaultRef  string // fully-qualified, e.g. "refs/heads/main"
	Mirrors     []string
	ParentID    string // fork lineage, "" for a root repo
	CreatedAt   int64  // block height
	Archived    bool

	// Merge policy.
	RequiredApprovals int  // approvals needed to merge a change
	AllowSelfApproval bool // may the change author's own approval count

	members *avl.Tree // address string -> Role
	refs    *avl.Tree // ref name -> *Ref
	log     *avl.Tree // padded seq -> *LogEntry (append-only)
	issues  *avl.Tree // padded id -> *Issue
	changes *avl.Tree // padded id -> *Change

	head       string // digest of the last log entry ("" when the log is empty)
	nextSeq    int64
	nextIssue  int64
	nextChange int64
}

// CreateRepo registers a repo owned by actor.
func (f *Forge) CreateRepo(actor address, height int64, id, description, defaultRef string) (*Repo, error) {
	if !ValidRepoID(id) {
		return nil, ErrInvalidRepoID
	}
	if !ValidText(description, MaxDescLen) {
		return nil, ErrInvalidText
	}
	if defaultRef == "" {
		defaultRef = "refs/heads/main"
	}
	if !ValidRefName(defaultRef) {
		return nil, ErrInvalidRefName
	}
	if f.repos.Has(id) {
		return nil, ErrRepoExists
	}
	r := &Repo{
		ID:                id,
		Description:       description,
		DefaultRef:        defaultRef,
		CreatedAt:         height,
		RequiredApprovals: 1,
		members:           avl.NewTree(),
		refs:              avl.NewTree(),
		log:               avl.NewTree(),
		issues:            avl.NewTree(),
		changes:           avl.NewTree(),
	}
	r.members.Set(actor.String(), RoleOwner)
	f.repos.Set(id, r)
	return r, nil
}

// Fork registers newID as a fork of srcID and copies the parent's current refs
// into the child's log, so the fork records exactly what it forked from. The
// objects are not copied: they never were on chain: so the child inherits the
// parent's mirrors as its initial fetch locators.
func (f *Forge) Fork(actor address, height int64, srcID, newID string) (*Repo, error) {
	src := f.Repo(srcID)
	if src == nil {
		return nil, ErrRepoNotFound
	}
	child, err := f.CreateRepo(actor, height, newID, src.Description, src.DefaultRef)
	if err != nil {
		return nil, err
	}
	child.ParentID = srcID
	child.Mirrors = append([]string{}, src.Mirrors...)
	note := "fork of " + srcID + " at seq " + strconv.FormatInt(src.nextSeq, 10)
	if len(note) > MaxNoteLen {
		note = "fork of " + srcID
	}
	n := 0
	src.refs.Iterate("", "", func(key string, value any) bool {
		ref := value.(*Ref)
		child.appendLog(actor, height, ref.Name, "", ref.OID, KindCreate, 0, note)
		child.refs.Set(ref.Name, &Ref{Name: ref.Name, OID: ref.OID, UpdatedAt: height, UpdatedBy: actor})
		n++
		return n >= 32 // a fork records a snapshot, not an unbounded copy
	})
	return child, nil
}

// Repo returns the repo, or nil.
func (f *Forge) Repo(id string) *Repo {
	v := f.repos.Get(id)
	if v == nil {
		return nil
	}
	return v.(*Repo)
}

// HasRepo reports whether the id is taken.
func (f *Forge) HasRepo(id string) bool { return f.repos.Has(id) }

// Size is the number of repos.
func (f *Forge) Size() int { return f.repos.Size() }

// IterateRepos walks repos in id order, newest-last, and stops when cb returns
// true. offset/count page the walk; count <= 0 means "to the end".
func (f *Forge) IterateRepos(offset, count int, cb func(*Repo) bool) {
	if count <= 0 {
		count = f.repos.Size()
	}
	f.repos.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Repo))
	})
}

// IterateNamespace walks the repos of one namespace in id order.
func (f *Forge) IterateNamespace(ns string, cb func(*Repo) bool) {
	f.repos.Iterate(ns+"/", ns+"0", func(_ string, value any) bool { // '0' is '/'+1
		return cb(value.(*Repo))
	})
}

// RoleOf returns the member's role, RoleNone when not a member.
func (r *Repo) RoleOf(a address) Role {
	v := r.members.Get(a.String())
	if v == nil {
		return RoleNone
	}
	return v.(Role)
}

// Can reports whether a holds at least the given role.
func (r *Repo) Can(a address, min Role) bool { return r.RoleOf(a) >= min }

// MemberCount is the number of members with an explicit role.
func (r *Repo) MemberCount() int { return r.members.Size() }

// IterateMembers walks members in address order.
func (r *Repo) IterateMembers(cb func(addr string, role Role) bool) {
	r.members.Iterate("", "", func(key string, value any) bool {
		return cb(key, value.(Role))
	})
}

// SetMember grants or revokes a role. Admins manage members; only an owner may
// mint another owner, and the last owner cannot be demoted: a repo with no
// owner is a repo nobody can ever unarchive.
func (r *Repo) SetMember(actor address, target address, role Role) error {
	if role < RoleNone || role > RoleOwner {
		return ErrInvalidRole
	}
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if role == RoleOwner && !r.Can(actor, RoleOwner) {
		return ErrUnauthorized
	}
	cur := r.RoleOf(target)
	if cur == RoleOwner && role != RoleOwner {
		if !r.Can(actor, RoleOwner) {
			return ErrUnauthorized // an admin cannot demote an owner
		}
		if r.ownerCount() == 1 {
			return ErrLastOwner
		}
	}
	if role == RoleNone {
		r.members.Remove(target.String())
		return nil
	}
	r.members.Set(target.String(), role)
	return nil
}

func (r *Repo) ownerCount() int {
	n := 0
	r.members.Iterate("", "", func(_ string, value any) bool {
		if value.(Role) == RoleOwner {
			n++
		}
		return false
	})
	return n
}

// SetDescription updates the one-line description.
func (r *Repo) SetDescription(actor address, description string) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if !ValidText(description, MaxDescLen) {
		return ErrInvalidText
	}
	r.Description = description
	return nil
}

// SetMirrors replaces the fetch locators. The first one is the canonical
// remote; the rest are fallbacks. The chain records them, it never fetches.
func (r *Repo) SetMirrors(actor address, mirrors []string) error {
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if len(mirrors) > MaxMirrors {
		return ErrTooMany
	}
	for _, m := range mirrors {
		if !ValidMirror(m) {
			return ErrInvalidMirror
		}
	}
	r.Mirrors = append([]string{}, mirrors...)
	return nil
}

// SetDefaultRef points the repo at another default branch.
func (r *Repo) SetDefaultRef(actor address, name string) error {
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if !ValidRefName(name) {
		return ErrInvalidRefName
	}
	r.DefaultRef = name
	return nil
}

// SetPolicy sets the merge policy: how many approvals a change needs, and
// whether the author's own approval counts.
func (r *Repo) SetPolicy(actor address, requiredApprovals int, allowSelfApproval bool) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	if requiredApprovals < 0 || requiredApprovals > 16 {
		return ErrTooMany
	}
	r.RequiredApprovals = requiredApprovals
	r.AllowSelfApproval = allowSelfApproval
	return nil
}

// SetArchived freezes (or unfreezes) the repo. An archived repo takes no
// mutation except unarchiving: the log stays readable forever.
func (r *Repo) SetArchived(actor address, archived bool) error {
	if !r.Can(actor, RoleAdmin) {
		return ErrUnauthorized
	}
	r.Archived = archived
	return nil
}

// Counts for rendering.
func (r *Repo) RefCount() int    { return r.refs.Size() }
func (r *Repo) IssueCount() int  { return r.issues.Size() }
func (r *Repo) ChangeCount() int { return r.changes.Size() }

// seqKey zero-pads an id to a fixed width so avl keys sort numerically.
// ufmt has no width flags in gno, so the padding is done by hand: "%016d"
// silently returns the bare number and would sort 10 before 2.
func seqKey(n int64) string {
	s := strconv.FormatInt(n, 10)
	if len(s) >= 16 {
		return s
	}
	return strings.Repeat("0", 16-len(s)) + s
}

package forge

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/urequire/v0"
)

// Deterministic, checksum-valid test addresses.
var (
	alice = testutils.TestAddress("alice") // owner
	bob   = testutils.TestAddress("bob")   // maintainer
	carol = testutils.TestAddress("carol") // writer
	dave  = testutils.TestAddress("dave")  // reader
	eve   = testutils.TestAddress("eve")   // stranger
)

// oid builds a well-formed 40-hex object id out of one hex digit.
func oid(c string) string { return strings.Repeat(c, 40) }

// newRepo returns a repo owned by alice with the standard cast: bob
// maintainer, carol writer, dave reader, eve nothing.
func newRepo(t *testing.T) (*Forge, *Repo) {
	t.Helper()
	f := New()
	r, err := f.CreateRepo(alice, 100, "moul/forge", "an on-chain forge", "")
	urequire.NoError(t, err)
	urequire.NoError(t, r.SetMember(alice, bob, RoleMaintainer))
	urequire.NoError(t, r.SetMember(alice, carol, RoleWriter))
	urequire.NoError(t, r.SetMember(alice, dave, RoleReader))
	return f, r
}

package forge

import "gno.land/p/nt/avl/v0"

// Issue is a discussion thread bound to a repo. Anyone with an address may open
// one: the spam gate is not a moderator, it is that the author pays gas and
// locks the storage deposit for every byte they write.
type Issue struct {
	ID        int64
	Title     string
	Body      string
	Author    address
	Open      bool
	Labels    []string
	CreatedAt int64
	UpdatedAt int64

	comments    *avl.Tree // padded id -> *Comment
	nextComment int64
}

// Comment is one reply, on an issue or on a change request.
type Comment struct {
	ID        int64
	Author    address
	Body      string
	CreatedAt int64
}

// OpenIssue files an issue. Permissionless by design.
func (r *Repo) OpenIssue(actor address, height int64, title, body string, labels []string) (*Issue, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if title == "" || !ValidLine(title, MaxTitleLen) {
		return nil, ErrInvalidText
	}
	if !ValidText(body, MaxBodyLen) {
		return nil, ErrInvalidText
	}
	if err := checkLabels(labels); err != nil {
		return nil, err
	}
	i := &Issue{
		ID:        r.nextIssue,
		Title:     title,
		Body:      body,
		Author:    actor,
		Open:      true,
		Labels:    append([]string{}, labels...),
		CreatedAt: height,
		UpdatedAt: height,
		comments:  avl.NewTree(),
	}
	r.issues.Set(seqKey(i.ID), i)
	r.nextIssue++
	return i, nil
}

// CommentIssue appends a reply. Closed issues still take comments (closing is a
// triage state, not a gag); an archived repo takes none.
func (r *Repo) CommentIssue(actor address, height, id int64, body string) (*Comment, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return nil, ErrIssueNotFound
	}
	if body == "" || !ValidText(body, MaxCommentLen) {
		return nil, ErrInvalidText
	}
	c := &Comment{ID: i.nextComment, Author: actor, Body: body, CreatedAt: height}
	i.comments.Set(seqKey(c.ID), c)
	i.nextComment++
	i.UpdatedAt = height
	return c, nil
}

// SetIssueOpen closes or reopens an issue. The author can always close their
// own; maintainers can close anyone's.
func (r *Repo) SetIssueOpen(actor address, height, id int64, open bool) error {
	if r.Archived {
		return ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return ErrIssueNotFound
	}
	if i.Author != actor && !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	i.Open = open
	i.UpdatedAt = height
	return nil
}

// SetIssueLabels replaces an issue's labels. Triage is a maintainer action.
func (r *Repo) SetIssueLabels(actor address, height, id int64, labels []string) error {
	if r.Archived {
		return ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return ErrIssueNotFound
	}
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if err := checkLabels(labels); err != nil {
		return err
	}
	i.Labels = append([]string{}, labels...)
	i.UpdatedAt = height
	return nil
}

// Issue returns an issue by id, or nil.
func (r *Repo) Issue(id int64) *Issue {
	v := r.issues.Get(seqKey(id))
	if v == nil {
		return nil
	}
	return v.(*Issue)
}

// IterateIssues walks issues newest-first.
func (r *Repo) IterateIssues(offset, count int, cb func(*Issue) bool) {
	if count <= 0 {
		count = r.issues.Size()
	}
	r.issues.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Issue))
	})
}

// OpenIssueCount counts issues still open.
func (r *Repo) OpenIssueCount() int {
	n := 0
	r.issues.Iterate("", "", func(_ string, value any) bool {
		if value.(*Issue).Open {
			n++
		}
		return false
	})
	return n
}

// CommentCount is the number of replies on the issue.
func (i *Issue) CommentCount() int { return i.comments.Size() }

// IterateComments walks replies oldest-first.
func (i *Issue) IterateComments(offset, count int, cb func(*Comment) bool) {
	if count <= 0 {
		count = i.comments.Size()
	}
	i.comments.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Comment))
	})
}

func checkLabels(labels []string) error {
	if len(labels) > MaxLabels {
		return ErrTooMany
	}
	for _, l := range labels {
		if !ValidLabel(l) {
			return ErrInvalidText
		}
	}
	return nil
}

package forge

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
)

// Log entry kinds.
const (
	KindCreate = "create" // a ref that did not exist now points somewhere
	KindUpdate = "update" // compare-and-swap succeeded
	KindForce  = "force"  // the tip was replaced without a matching expectation
	KindDelete = "delete" // the ref is gone (the log is not)
	KindMerge  = "merge"  // an update performed by merging a change request
)

// Ref is the current state of one reference. The history of how it got here is
// in the repo log, which nothing can rewrite.
type Ref struct {
	Name      string
	OID       string
	UpdatedAt int64
	UpdatedBy address
}

// LogEntry is one link of the repo's reference log. The log is append-only and
// hash-chained: Digest commits to every earlier entry, so publishing a single
// digest (in a release note, a package manifest, a tweet) pins the entire
// history of every ref up to that point.
type LogEntry struct {
	Seq      int64
	Ref      string
	OldOID   string // "" when the ref did not exist
	NewOID   string // "" on delete
	Actor    address
	Height   int64
	Kind     string
	ChangeID int64 // the merged change, 0 otherwise
	Note     string
	Digest   string // hex sha256 over the previous digest and this entry
}

// EntryDigest computes the chain digest of e given the previous entry's digest.
// It is exported so an off-chain verifier can recompute the chain byte for byte
// from the values it read back; the field order below is the wire format and
// must not change within a version.
func EntryDigest(prev string, e *LogEntry) string {
	fields := []string{
		prev,
		strconv.FormatInt(e.Seq, 10),
		e.Ref,
		e.OldOID,
		e.NewOID,
		e.Actor.String(),
		strconv.FormatInt(e.Height, 10),
		e.Kind,
		strconv.FormatInt(e.ChangeID, 10),
		e.Note,
	}
	sum := sha256.Sum256([]byte(strings.Join(fields, "\n")))
	return hex.EncodeToString(sum[:])
}

// appendLog writes one entry and advances the chain head. Callers have already
// authorized and validated; this never fails.
func (r *Repo) appendLog(actor address, height int64, ref, oldOID, newOID, kind string, changeID int64, note string) *LogEntry {
	e := &LogEntry{
		Seq:      r.nextSeq,
		Ref:      ref,
		OldOID:   oldOID,
		NewOID:   newOID,
		Actor:    actor,
		Height:   height,
		Kind:     kind,
		ChangeID: changeID,
		Note:     note,
	}
	e.Digest = EntryDigest(r.head, e)
	r.log.Set(seqKey(e.Seq), e)
	r.head = e.Digest
	r.nextSeq++
	return e
}

// SetRef moves a ref by compare-and-swap: expectedOID must be the tip the
// caller last saw ("" to create a ref that does not exist yet). This is git's
// --force-with-lease, except the lease is held by consensus rather than by the
// server you are pushing to, so a concurrent push cannot be silently lost and a
// rewritten history cannot be presented as if it had always been that way.
//
// The chain cannot check that newOID descends from expectedOID: it has no
// objects. That check belongs to a client holding the repo, which is exactly
// why every move is recorded rather than merely applied.
func (r *Repo) SetRef(actor address, height int64, name, expectedOID, newOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleWriter) {
		return nil, ErrUnauthorized
	}
	if !ValidRefName(name) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(newOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	cur := r.Ref(name)
	switch {
	case cur == nil && expectedOID != "":
		return nil, ErrRefNotFound
	case cur != nil && expectedOID == "":
		return nil, ErrRefExists
	case cur != nil && cur.OID != expectedOID:
		return nil, ErrStaleRef
	case cur != nil && cur.OID == newOID:
		return nil, ErrSameOID
	}
	kind := KindUpdate
	old := ""
	if cur == nil {
		kind = KindCreate
	} else {
		old = cur.OID
	}
	r.refs.Set(name, &Ref{Name: name, OID: newOID, UpdatedAt: height, UpdatedBy: actor})
	return r.appendLog(actor, height, name, old, newOID, kind, 0, note), nil
}

// ForceSetRef moves a ref without an expectation. It needs RoleMaintainer and
// is permanently recorded as KindForce: the point is not to forbid a force-push
// (sometimes it is the right call) but to make one impossible to hide.
func (r *Repo) ForceSetRef(actor address, height int64, name, newOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidRefName(name) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(newOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	old := ""
	if cur := r.Ref(name); cur != nil {
		if cur.OID == newOID {
			return nil, ErrSameOID
		}
		old = cur.OID
	}
	r.refs.Set(name, &Ref{Name: name, OID: newOID, UpdatedAt: height, UpdatedBy: actor})
	return r.appendLog(actor, height, name, old, newOID, KindForce, 0, note), nil
}

// DeleteRef removes a ref by compare-and-swap. The ref disappears from the
// current state; the log keeps every object it ever pointed at.
//
// Maintainer-only for an economic reason as much as a safety one: on gno.land
// the storage-deposit refund goes to whoever frees the bytes, not to whoever
// paid for them (`receiver := caller` in the vm keeper's deposit path, gno
// master 2026-09-19), so an open delete path pays for vandalism.
func (r *Repo) DeleteRef(actor address, height int64, name, expectedOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	cur := r.Ref(name)
	if cur == nil {
		return nil, ErrRefNotFound
	}
	if cur.OID != expectedOID {
		return nil, ErrStaleRef
	}
	if name == r.DefaultRef {
		return nil, ErrUnauthorized // the default branch is not deletable
	}
	r.refs.Remove(name)
	return r.appendLog(actor, height, name, cur.OID, "", KindDelete, 0, note), nil
}

// Ref returns the current state of a ref, or nil.
func (r *Repo) Ref(name string) *Ref {
	v := r.refs.Get(name)
	if v == nil {
		return nil
	}
	return v.(*Ref)
}

// IterateRefs walks refs in name order.
func (r *Repo) IterateRefs(cb func(*Ref) bool) {
	r.refs.Iterate("", "", func(_ string, value any) bool {
		return cb(value.(*Ref))
	})
}

// LogHead is the digest of the last entry, "" for an empty log. Pin this value
// anywhere off chain and the whole history becomes falsifiable.
func (r *Repo) LogHead() string { return r.head }

// LogSize is the number of entries ever appended.
func (r *Repo) LogSize() int { return r.log.Size() }

// LogEntryAt returns one entry by sequence number, or nil.
func (r *Repo) LogEntryAt(seq int64) *LogEntry {
	v := r.log.Get(seqKey(seq))
	if v == nil {
		return nil
	}
	return v.(*LogEntry)
}

// IterateLog walks the log oldest-first.
func (r *Repo) IterateLog(offset, count int, cb func(*LogEntry) bool) {
	if count <= 0 {
		count = r.log.Size()
	}
	r.log.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*LogEntry))
	})
}

// IterateLogReverse walks the log newest-first, which is what a UI wants.
func (r *Repo) IterateLogReverse(offset, count int, cb func(*LogEntry) bool) {
	if count <= 0 {
		count = r.log.Size()
	}
	r.log.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*LogEntry))
	})
}

// VerifyLog recomputes the whole digest chain and reports the first entry whose
// digest does not follow from its predecessor. It should be impossible on a
// live chain: it is here because a transparency log nobody can verify is just
// a log, and a client should be running this against the values it read back.
func (r *Repo) VerifyLog() (bool, int64) {
	prev := ""
	bad := int64(-1)
	r.log.Iterate("", "", func(_ string, value any) bool {
		e := value.(*LogEntry)
		if EntryDigest(prev, e) != e.Digest {
			bad = e.Seq
			return true
		}
		prev = e.Digest
		return false
	})
	return bad < 0, bad
}

package forge

import "strings"

// Size caps. Every string the chain stores is bounded: an unbounded field is an
// unbounded storage deposit, and on gno.land the deposit is paid per byte by
// whoever writes it (100ugnot/byte at the time of writing).
const (
	MaxRepoPartLen = 39   // per side of "<namespace>/<name>"
	MaxRefNameLen  = 255  // git's own limit for a single ref name
	MaxTitleLen    = 200  // issue / change title
	MaxBodyLen     = 8192 // issue / change body
	MaxCommentLen  = 4096
	MaxDescLen     = 512
	MaxNoteLen     = 140 // single-line note attached to a log entry
	MaxMirrorLen   = 512
	MaxMirrors     = 8
	MaxLabels      = 10
	MaxLabelLen    = 32
)

// ValidOID reports whether s is a git object id: 40 (SHA-1) or 64 (SHA-256)
// lowercase hex characters. Case is fixed so the same object always has the
// same on-chain key and the same digest-chain input.
func ValidOID(s string) bool {
	if len(s) != 40 && len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// ValidRefName reports whether s is a fully-qualified ref name this forge
// accepts: a "refs/"-rooted subset of git-check-ref-format(1).
//
// Deliberately stricter than git: the name must be fully qualified, so there is
// never an ambiguity between "main" the branch and "main" the tag, and a client
// can map an on-chain name onto a local ref without a lookup table.
func ValidRefName(s string) bool {
	if s == "" || len(s) > MaxRefNameLen {
		return false
	}
	if !strings.HasPrefix(s, "refs/") {
		return false
	}
	if strings.Contains(s, "..") || strings.Contains(s, "@{") {
		return false
	}
	if strings.HasSuffix(s, "/") || strings.HasSuffix(s, ".") {
		return false
	}
	parts := strings.Split(s, "/")
	if len(parts) < 2 {
		return false
	}
	for _, p := range parts {
		if p == "" || p == "@" {
			return false
		}
		if strings.HasPrefix(p, ".") || strings.HasSuffix(p, ".lock") {
			return false
		}
		for i := 0; i < len(p); i++ {
			if !refByteOK(p[i]) {
				return false
			}
		}
	}
	return true
}

// refByteOK rejects the bytes git itself rejects in a ref component: ASCII
// control characters, space, DEL, and the pathspec/revision metacharacters.
func refByteOK(c byte) bool {
	if c <= 0x20 || c == 0x7f {
		return false
	}
	switch c {
	case '~', '^', ':', '?', '*', '[', '\\':
		return false
	}
	return true
}

// ValidRepoID reports whether s is "<namespace>/<name>". The name is always a
// lowercase slug; the namespace is either a slug (a claimed user name) or a
// bech32 address (the caller's own). The two shapes cannot collide: an address
// is 40 characters and a slug caps at MaxRepoPartLen, which is 39.
//
// This layer validates the SHAPE only. Whether the caller may claim a given
// namespace is an ownership question that needs a chain, so it belongs to the
// realm (see the realm's README).
func ValidRepoID(s string) bool {
	ns, name, ok := SplitRepoID(s)
	if !ok {
		return false
	}
	return (validSlug(ns) || AddressNamespace(ns)) && validSlug(name)
}

// SplitRepoID splits "<namespace>/<name>" into its two halves. It does not
// validate either half; ok is false only when the id is not two slash-separated
// non-empty parts.
func SplitRepoID(s string) (ns, name string, ok bool) {
	i := strings.Index(s, "/")
	if i <= 0 || i == len(s)-1 || strings.Count(s, "/") != 1 {
		return "", "", false
	}
	return s[:i], s[i+1:], true
}

// AddressNamespace reports whether ns is shaped like a gno bech32 address, the
// namespace every account owns without registering anything. The realm still
// checks that it is the CALLER's address; this only says which of the two
// ownership rules applies.
func AddressNamespace(ns string) bool {
	if len(ns) != 40 || !strings.HasPrefix(ns, "g1") {
		return false
	}
	for i := 2; i < len(ns); i++ {
		if !strings.ContainsRune(bech32Charset, rune(ns[i])) {
			return false
		}
	}
	return true
}

// bech32Charset is bech32's data alphabet: lowercase alphanumerics minus the
// four characters it drops to avoid transcription errors (1, b, i, o).
const bech32Charset = "023456789acdefghjklmnpqrstuvwxyz"

// validSlug: 1..MaxRepoPartLen chars, [a-z0-9] at both ends, [a-z0-9-_.] inside,
// no "..", no "--". Mixed case is rejected rather than folded: two ids that
// differ only in case would be two avl keys and one human-visible name.
func validSlug(s string) bool {
	if s == "" || len(s) > MaxRepoPartLen {
		return false
	}
	if !alnum(s[0]) || !alnum(s[len(s)-1]) {
		return false
	}
	if strings.Contains(s, "..") || strings.Contains(s, "--") {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if alnum(c) || c == '-' || c == '_' || c == '.' {
			continue
		}
		return false
	}
	return true
}

func alnum(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
}

// ValidText reports whether s fits in max bytes and carries no control
// characters other than newline and tab. Render output is markdown served by
// gnoweb, so a stray control byte is a rendering bug for every reader forever.
func ValidText(s string, max int) bool {
	if len(s) > max {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\n' || c == '\t' {
			continue
		}
		if c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// ValidLine reports whether s is single-line text within max bytes. Used for
// titles and for log-entry notes, which are fields of the digest chain: a
// newline there would let one note impersonate two.
func ValidLine(s string, max int) bool {
	if strings.ContainsAny(s, "\n\t") {
		return false
	}
	return ValidText(s, max)
}

// ValidMirror reports whether s looks like a fetch locator. The chain does not
// resolve it: it only records where the maintainers say the objects are: so
// the check is a shape check, not a promise that anything is reachable.
func ValidMirror(s string) bool {
	if !ValidLine(s, MaxMirrorLen) || s == "" {
		return false
	}
	for _, p := range []string{"https://", "http://", "git://", "ssh://", "ipfs://", "ipns://", "ar://", "rad://", "git@"} {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	return false
}

// ValidLabel reports whether s is an issue label.
func ValidLabel(s string) bool {
	return s != "" && ValidLine(s, MaxLabelLen) && !strings.Contains(s, ",")
}

package forge

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestValidOID(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"sha1", strings.Repeat("a", 40), true},
		{"sha256", strings.Repeat("0", 64), true},
		{"mixed hex", "0123456789abcdef0123456789abcdef01234567", true},
		{"empty", "", false},
		{"too short", strings.Repeat("a", 39), false},
		{"between lengths", strings.Repeat("a", 41), false},
		{"uppercase", strings.Repeat("A", 40), false},
		{"non hex", strings.Repeat("z", 40), false},
		{"abbreviated", "deadbeef", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidOID(tc.in), tc.name)
	}
}

func TestValidRefName(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"branch", "refs/heads/main", true},
		{"nested branch", "refs/heads/feat/on-chain-log", true},
		{"tag", "refs/tags/v1.0.0", true},
		{"stash-like", "refs/stash", true},
		{"unqualified", "main", false},
		{"empty", "", false},
		{"double slash", "refs/heads//main", false},
		{"double dot", "refs/heads/a..b", false},
		{"at brace", "refs/heads/a@{0}", false},
		{"trailing slash", "refs/heads/", false},
		{"trailing dot", "refs/heads/main.", false},
		{"dot prefix", "refs/heads/.hidden", false},
		{"lock suffix", "refs/heads/main.lock", false},
		{"space", "refs/heads/my branch", false},
		{"caret", "refs/heads/main^", false},
		{"colon", "refs/heads/a:b", false},
		{"tilde", "refs/heads/main~1", false},
		{"question", "refs/heads/what?", false},
		{"star", "refs/heads/*", false},
		{"backslash", "refs/heads/a\\b", false},
		{"control", "refs/heads/a\x01b", false},
		{"too long", "refs/heads/" + strings.Repeat("a", 300), false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidRefName(tc.in), tc.name)
	}
}

func TestValidRepoID(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"simple", "moul/forge", true},
		{"digits", "ns0/repo9", true},
		{"dots and dashes", "moul/gno-contracts.x", true},
		{"underscore", "moul/my_repo", true},
		{"no slash", "forge", false},
		{"two slashes", "a/b/c", false},
		{"empty ns", "/forge", false},
		{"empty name", "moul/", false},
		{"uppercase", "Moul/forge", false},
		{"leading dash", "moul/-forge", false},
		{"trailing dot", "moul/forge.", false},
		{"double dot", "moul/fo..rge", false},
		{"double dash", "moul/fo--rge", false},
		{"space", "moul/my forge", false},
		{"too long", "moul/" + strings.Repeat("a", 40), false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidRepoID(tc.in), tc.name)
	}
}

func TestAddressNamespace(t *testing.T) {
	addr := testutils.TestAddress("alice").String()
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"a real address", addr, true},
		{"wrong prefix", "x1" + addr[2:], false},
		{"too short", addr[:39], false},
		{"too long", addr + "a", false},
		{"bech32 drops b i o 1", "g1" + strings.Repeat("b", 38), false},
		{"uppercase", "G1" + addr[2:], false},
		{"a slug is not an address", "moul", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, AddressNamespace(tc.in), tc.name)
	}

	// An address namespace is a valid repo id, and it cannot collide with a
	// claimed name: 40 characters is past the slug cap.
	uassert.True(t, ValidRepoID(addr+"/forge"))
	uassert.False(t, ValidRepoID(strings.Repeat("a", 40)+"/forge"))
	uassert.False(t, ValidRepoID(addr+"/"+addr), "the name half is always a slug")
}

func TestSplitRepoID(t *testing.T) {
	ns, name, ok := SplitRepoID("moul/forge")
	uassert.True(t, ok)
	uassert.Equal(t, "moul", ns)
	uassert.Equal(t, "forge", name)

	for _, bad := range []string{"", "moul", "/forge", "moul/", "a/b/c"} {
		_, _, ok := SplitRepoID(bad)
		uassert.False(t, ok, bad)
	}
}

func TestValidTextAndLine(t *testing.T) {
	uassert.True(t, ValidText("hello\nworld\ttab", 64))
	uassert.False(t, ValidText("bell\x07", 64))
	uassert.False(t, ValidText("too long", 3))
	uassert.True(t, ValidText("", 3))

	uassert.True(t, ValidLine("a single line", 64))
	uassert.False(t, ValidLine("two\nlines", 64))
	uassert.False(t, ValidLine("a\ttab", 64))
}

func TestValidMirrorAndLabel(t *testing.T) {
	cases := []struct {
		in   string
		want bool
	}{
		{"https://github.com/moul/gno-contracts.git", true},
		{"git@github.com:moul/gno-contracts.git", true},
		{"ipfs://bafybeihdwdcefgh4dqkjv67uzcmw7ojee6xedzdetojuzjevtenxquvyku", true},
		{"rad://z3gqcJUoA1n9HaHKufZs5FCSGazv5", true},
		{"ar://1QKPaf1AmsK_tSSdUgtVDEYGLuQBOKTNr", true},
		{"ftp://example.com/repo.git", false},
		{"not a url", false},
		{"", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidMirror(tc.in), tc.in)
	}

	uassert.True(t, ValidLabel("bug"))
	uassert.False(t, ValidLabel(""))
	uassert.False(t, ValidLabel("a,b"))
	uassert.False(t, ValidLabel(strings.Repeat("x", 33)))
}

func TestParseRoleRoundTrip(t *testing.T) {
	for _, r := range []Role{RoleNone, RoleReader, RoleWriter, RoleMaintainer, RoleAdmin, RoleOwner} {
		got, err := ParseRole(r.String())
		uassert.NoError(t, err, r.String())
		uassert.Equal(t, int(r), int(got), r.String())
	}
	_, err := ParseRole("root")
	uassert.ErrorIs(t, err, ErrInvalidRole)
}

// Package grants is a grant board governed by a member set: anyone may ask
// the board for money, the members vote in the open, and the money leaves in
// tranches that each have to be earned by producing a proof the members
// accept.
//
// The package is pure. It holds no coins, reads no chain state and imports
// nothing from `chain`: the caller supplies the acting address and the block
// height, and the caller performs the transfer. That is what makes the whole
// state machine unit-testable without a node, and it is what lets the same
// board be driven by a realm, by a test, or by a different payment rail.
// Live board: gno.land/r/moul/grant/v0.
//
// # The shape of a grant
//
// A Request is a title, a body, and an ordered list of Milestones, each with
// its own amount. Approving a request does not pay anything: it only makes the
// first milestone claimable. To get a tranche the applicant submits a Proof
// (a URL, a hash, or plain text) and the members review that specific proof.
// A rejected proof does not kill the grant, it just closes one Attempt; the
// applicant submits another. Every attempt, accepted or not, stays on the
// record with the ballots that decided it.
//
// # Asking for someone else
//
// A request has an applicant, who files it and answers for it, and a
// beneficiary, who gets paid. SubmitFor separates the two and takes a reason
// for the detour; Submit is the common case where they are the same address.
//
// The split is not a convenience. An account with nothing in it cannot pay the
// gas to ask for its first coins, so on a board whose whole purpose is to fund
// empty accounts, "someone else files it" is the ONLY path that works. Both
// addresses are then barred from voting on the request, and either of them may
// submit a proof, for the same reason: the payee may not be able to transact
// at all until the first tranche lands.
//
// # Who may vote
//
// Every member, once, per decision. The party the decision is about is
// excluded: the applicant does not vote on their own grant, and the subject of
// a membership change does not vote on their own membership. The bar is a
// majority of the addresses that are actually eligible, recomputed on each
// ballot, so a board that grows mid-vote raises its own bar.
//
// # What this deliberately does not do
//
// No weights, no delegation, no quadratic anything, no deadline. A request
// with no majority either way simply stays Pending until someone breaks the
// tie or the applicant withdraws it. Those are all reasonable things to add on
// top; none of them is needed to show the shape.
package grants

import (
	"errors"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// Errors returned by the mutators. They are sentinels so a realm can map them
// onto its own messages, or simply panic with them.
var (
	ErrNotMember     = errors.New("grants: not a board member")
	ErrNotApplicant  = errors.New("grants: only the applicant may do this")
	ErrNoRequest     = errors.New("grants: no such request")
	ErrNoMilestone   = errors.New("grants: no such milestone")
	ErrNotPending    = errors.New("grants: the request is not pending")
	ErrNotApproved   = errors.New("grants: the request is not approved")
	ErrAlreadyVoted  = errors.New("grants: this member already voted")
	ErrConflict      = errors.New("grants: the party a decision is about may not vote on it")
	ErrOutOfOrder    = errors.New("grants: milestones are claimed in order")
	ErrProofPending  = errors.New("grants: a proof is already under review")
	ErrNoProof       = errors.New("grants: no proof is under review")
	ErrBadTitle      = errors.New("grants: title must be 1 to 100 characters")
	ErrBadBody       = errors.New("grants: body must be at most 2000 characters")
	ErrBadMilestones = errors.New("grants: a grant needs 1 to 10 milestones")
	ErrBadAmount     = errors.New("grants: every milestone must ask for a positive amount")
	ErrBadProof      = errors.New("grants: proof kind must be url, hash or text, with a reference")
	ErrBadReason     = errors.New("grants: reason must be at most 300 characters")
	ErrNeedReason    = errors.New("grants: filing for someone else needs a reason")
	ErrBadAddress    = errors.New("grants: invalid address")
	ErrIsMember      = errors.New("grants: already a board member")
	ErrLastMember    = errors.New("grants: the last member cannot be removed")
	ErrNothingSent   = errors.New("grants: a donation must be a positive amount")
	ErrUnderfunded   = errors.New("grants: the treasury cannot cover this tranche")
	ErrBadSpec       = errors.New("grants: milestones must read \"title:amount,title:amount\"")
)

// Limits every input is checked against. Exported so a UI can pre-validate.
const (
	MaxTitle      = 100
	MaxBody       = 2000
	MaxReason     = 300
	MaxRef        = 300
	MaxNote       = 500
	MaxMilestones = 10
)

// Status is where a request sits in its lifecycle.
type Status int

const (
	Pending   Status = iota // open for member ballots
	Approved                // carried; milestones can be earned
	Rejected                // a majority voted no
	Completed               // every milestone released
	Withdrawn               // the applicant pulled it before a decision
)

func (s Status) String() string {
	switch s {
	case Pending:
		return "pending"
	case Approved:
		return "approved"
	case Rejected:
		return "rejected"
	case Completed:
		return "completed"
	case Withdrawn:
		return "withdrawn"
	}
	return "unknown"
}

// Kind says what carrying a request actually does.
type Kind int

const (
	KindGrant  Kind = iota // pays out, milestone by milestone
	KindMember             // adds or removes a board member, immediately
)

func (k Kind) String() string {
	if k == KindMember {
		return "membership"
	}
	return "grant"
}

// Outcome is the result of one proof attempt.
type Outcome int

const (
	UnderReview Outcome = iota // members are still voting on this proof
	Accepted                   // the tranche is earned
	Refused                    // this proof did not convince; another may
)

func (o Outcome) String() string {
	switch o {
	case Accepted:
		return "accepted"
	case Refused:
		return "refused"
	}
	return "under review"
}

// Ballot is one member's vote on one decision, with the reason they gave.
// Reasons are not optional decoration: they are the only part of a vote that
// tells an applicant what to fix.
type Ballot struct {
	Voter   address
	Approve bool
	Reason  string
	Height  int64
}

// Proof is the evidence an applicant offers for one milestone. Kind is "url",
// "hash" or "text"; the board decides what it is worth.
type Proof struct {
	Kind   string
	Ref    string
	Note   string
	Height int64
}

// Attempt is one proof and the review it got. A milestone keeps every attempt,
// so a refused proof and the reasons it was refused stay readable forever.
type Attempt struct {
	Proof    Proof
	Reviews  []Ballot
	Outcome  Outcome
	ClosedAt int64
}

// Milestone is one tranche of a grant: what has to be shown, and what it pays.
type Milestone struct {
	Title      string
	Amount     int64 // in the smallest unit of whatever the realm pays in
	Attempts   []*Attempt
	Released   bool
	ReleasedAt int64
}

// Current returns the attempt still under review, or nil.
func (m *Milestone) Current() *Attempt {
	if len(m.Attempts) == 0 {
		return nil
	}
	last := m.Attempts[len(m.Attempts)-1]
	if last.Outcome == UnderReview {
		return last
	}
	return nil
}

// Request is a grant application or a membership change.
type Request struct {
	ID          int
	Kind        Kind
	Applicant   address // who filed it and answers for it
	Beneficiary address // who gets paid; equal to Applicant on a self request
	Reason      string  // why the applicant is asking on someone else's behalf
	Title       string
	Body        string
	Milestones  []*Milestone
	Subject     address // KindMember only: the address being added or removed
	Add         bool    // KindMember only: true adds, false removes
	Votes       []Ballot
	Status      Status
	CreatedAt   int64
	DecidedAt   int64
}

// OnBehalf reports whether this grant was filed by one address for another.
func (r *Request) OnBehalf() bool {
	return r.Kind == KindGrant && r.Beneficiary != r.Applicant
}

// Payee is the address a released tranche pays. It is the beneficiary, which
// is the applicant unless the request was filed for someone else.
func (r *Request) Payee() address {
	if r.Beneficiary.IsValid() {
		return r.Beneficiary
	}
	return r.Applicant
}

// Total is the sum of every milestone, released or not.
func (r *Request) Total() int64 {
	var n int64
	for _, m := range r.Milestones {
		n += m.Amount
	}
	return n
}

// Paid is what the milestones released so far add up to.
func (r *Request) Paid() int64 {
	var n int64
	for _, m := range r.Milestones {
		if m.Released {
			n += m.Amount
		}
	}
	return n
}

// Outstanding is what an approved request can still cost the treasury. It is
// zero for anything not approved, which is what makes it safe to sum across
// the board as the committed amount.
func (r *Request) Outstanding() int64 {
	if r.Status != Approved {
		return 0
	}
	return r.Total() - r.Paid()
}

// Next is the index of the first unreleased milestone, or -1 when the grant is
// fully paid. Milestones are earned in order.
func (r *Request) Next() int {
	for i, m := range r.Milestones {
		if !m.Released {
			return i
		}
	}
	return -1
}

// Tally counts the ballots cast on the request itself.
func (r *Request) Tally() (yes, no int) {
	return count(r.Votes)
}

// BallotOf returns the member's ballot on the request, or nil.
func (r *Request) BallotOf(voter address) *Ballot {
	return find(r.Votes, voter)
}

// Excludes reports whether addr is barred from voting on this request because
// the decision is about them.
//
// A grant excludes BOTH parties, not just the one who typed the transaction:
// letting a member be paid by a request a friend filed for them is the same
// conflict with one more step in it.
func (r *Request) Excludes(addr address) bool {
	if r.Kind == KindMember {
		return addr == r.Subject
	}
	return addr == r.Applicant || addr == r.Payee()
}

func count(bs []Ballot) (yes, no int) {
	for _, b := range bs {
		if b.Approve {
			yes++
		} else {
			no++
		}
	}
	return yes, no
}

func find(bs []Ballot, voter address) *Ballot {
	for i := range bs {
		if bs[i].Voter == voter {
			return &bs[i]
		}
	}
	return nil
}

// Board is the whole state of one grant program: who decides, and what has
// been asked of them.
type Board struct {
	members  *avl.Tree // address string -> int64 join height
	requests *avl.Tree // zero-padded id -> *Request
	nextID   int
}

// New returns a board whose founding members are the given addresses, all
// recorded as having joined at height 0. Duplicates and invalid addresses are
// skipped; a board with no members accepts no decisions until one is added, so
// callers normally pass at least one.
func New(founders ...address) *Board {
	b := &Board{members: avl.NewTree(), requests: avl.NewTree(), nextID: 1}
	for _, f := range founders {
		if f.IsValid() {
			b.members.Set(f.String(), int64(0))
		}
	}
	return b
}

// IsMember reports whether addr sits on the board.
func (b *Board) IsMember(addr address) bool { return b.members.Has(addr.String()) }

// MemberCount is the number of addresses on the board.
func (b *Board) MemberCount() int { return b.members.Size() }

// Members lists the board in address order, which is stable across calls.
func (b *Board) Members() []address {
	out := make([]address, 0, b.members.Size())
	b.members.Iterate("", "", func(k string, _ any) bool {
		out = append(out, address(k))
		return false
	})
	return out
}

// JoinedAt returns the height a member joined, or -1 for a non-member.
func (b *Board) JoinedAt(addr address) int64 {
	v := b.members.Get(addr.String())
	if v == nil {
		return -1
	}
	return v.(int64)
}

// Eligible is how many members may vote on a request: everyone but the parties
// the decision is about.
func (b *Board) Eligible(r *Request) int {
	n := 0
	b.members.Iterate("", "", func(k string, _ any) bool {
		if !r.Excludes(address(k)) {
			n++
		}
		return false
	})
	return n
}

// Majority is the number of concurring ballots a decision on r needs. It is
// recomputed on every ballot, so a board that changes size mid-vote moves its
// own bar rather than freezing a stale one.
func (b *Board) Majority(r *Request) int {
	n := b.Eligible(r)
	if n <= 0 {
		return 1 // an unreachable bar beats a bar of zero
	}
	return n/2 + 1
}

// Get returns a request by id, or nil.
func (b *Board) Get(id int) *Request {
	v := b.requests.Get(idKey(id))
	if v == nil {
		return nil
	}
	return v.(*Request)
}

// Size is the number of requests ever filed.
func (b *Board) Size() int { return b.requests.Size() }

// List returns every request in id order.
func (b *Board) List() []*Request {
	out := make([]*Request, 0, b.requests.Size())
	b.requests.Iterate("", "", func(_ string, v any) bool {
		out = append(out, v.(*Request))
		return false
	})
	return out
}

// Committed is what the treasury still owes on approved grants. A realm that
// keeps its balance at or above this number can always pay a released tranche.
func (b *Board) Committed() int64 {
	var n int64
	b.requests.Iterate("", "", func(_ string, v any) bool {
		n += v.(*Request).Outstanding()
		return false
	})
	return n
}

// Disbursed is everything the board has ever released.
func (b *Board) Disbursed() int64 {
	var n int64
	b.requests.Iterate("", "", func(_ string, v any) bool {
		n += v.(*Request).Paid()
		return false
	})
	return n
}

// idKey pads an id so avl iteration is numeric, not lexicographic: unpadded
// keys sort "1","10","2" and every listing would lose its order past nine
// entries. ufmt has no width flags in gno, so the padding is by hand.
func idKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 8 {
		s = "0" + s
	}
	return s
}

package grants

// This file holds every state transition of the board. Each one takes the
// acting address and the block height from the caller rather than reading
// them from the chain, which is what keeps the package pure and the whole
// lifecycle exercisable in a plain unit test.

// NewMilestone is a small constructor so callers do not build the struct (and
// its Attempts slice) by hand.
func NewMilestone(title string, amount int64) *Milestone {
	return &Milestone{Title: title, Amount: amount}
}

// Submit files a grant application for the applicant themselves. Anyone may
// apply; being a member is not required and does not help, since a member is
// barred from voting on their own request.
func (b *Board) Submit(applicant address, title, body string, ms []*Milestone, height int64) (*Request, error) {
	return b.SubmitFor(applicant, applicant, "", title, body, ms, height)
}

// SubmitFor files a grant application whose money goes to beneficiary rather
// than to the applicant, with a reason for the detour.
//
// The reason is required, and it is required because it is the only thing on
// the page that answers the question a reader will have: why is this person
// asking for someone else's money. The usual honest answer is that the payee
// has an empty account and cannot pay the gas to ask, which is exactly the
// case a grant board exists to serve and exactly the case an impersonation
// looks like. Making the claim explicit is what lets a member check it.
//
// Passing the applicant's own address is the same as Submit and needs no
// reason.
func (b *Board) SubmitFor(applicant, beneficiary address, reason, title, body string, ms []*Milestone, height int64) (*Request, error) {
	if !applicant.IsValid() || !beneficiary.IsValid() {
		return nil, ErrBadAddress
	}
	if len(reason) > MaxReason {
		return nil, ErrBadReason
	}
	if beneficiary != applicant && reason == "" {
		return nil, ErrNeedReason
	}
	if err := checkTitle(title); err != nil {
		return nil, err
	}
	if len(body) > MaxBody {
		return nil, ErrBadBody
	}
	if len(ms) == 0 || len(ms) > MaxMilestones {
		return nil, ErrBadMilestones
	}
	for _, m := range ms {
		if m == nil || m.Amount <= 0 {
			return nil, ErrBadAmount
		}
		if err := checkTitle(m.Title); err != nil {
			return nil, err
		}
	}
	return b.file(&Request{
		Kind:        KindGrant,
		Applicant:   applicant,
		Beneficiary: beneficiary,
		Reason:      reason,
		Title:       title,
		Body:        body,
		Milestones:  ms,
		CreatedAt:   height,
	}), nil
}

// SubmitMemberChange files a request to add or remove a board member. Only a
// member may file one: opening the board's own composition to anyone with a
// keypair is how a grant board gets captured.
func (b *Board) SubmitMemberChange(proposer, subject address, add bool, body string, height int64) (*Request, error) {
	if !b.IsMember(proposer) {
		return nil, ErrNotMember
	}
	if !subject.IsValid() {
		return nil, ErrBadAddress
	}
	if len(body) > MaxBody {
		return nil, ErrBadBody
	}
	switch {
	case add && b.IsMember(subject):
		return nil, ErrIsMember
	case !add && !b.IsMember(subject):
		return nil, ErrNotMember
	case !add && b.MemberCount() == 1:
		return nil, ErrLastMember
	}
	title := "Remove " + subject.String()
	if add {
		title = "Add " + subject.String()
	}
	return b.file(&Request{
		Kind:        KindMember,
		Applicant:   proposer,
		Beneficiary: proposer,
		Title:       title,
		Body:        body,
		Subject:     subject,
		Add:         add,
		CreatedAt:   height,
	}), nil
}

func (b *Board) file(r *Request) *Request {
	r.ID = b.nextID
	b.nextID++
	b.requests.Set(idKey(r.ID), r)
	return r
}

// Withdraw lets an applicant pull their own request before it is decided.
func (b *Board) Withdraw(caller address, id int, height int64) error {
	r := b.Get(id)
	if r == nil {
		return ErrNoRequest
	}
	if r.Applicant != caller {
		return ErrNotApplicant
	}
	if r.Status != Pending {
		return ErrNotPending
	}
	r.Status, r.DecidedAt = Withdrawn, height
	return nil
}

// Standing counts only the ballots of addresses that are members right now.
// Decisions use this, not Request.Tally: a ballot is a permanent record of
// what someone said, but it stops carrying weight the moment they leave the
// board. The two numbers differ exactly when a voter has since been removed,
// and a good renderer shows both.
func (b *Board) Standing(r *Request) (yes, no int) { return b.standing(r.Votes) }

// Decides previews what a ballot would do without casting it, so a caller can
// check a precondition it cannot roll back: a realm, for instance, refusing
// to let a grant carry that its treasury cannot cover. It reports false for a
// ballot that would be refused anyway.
func (b *Board) Decides(id int, voter address, approve bool) (bool, Status) {
	r := b.Get(id)
	if r == nil || r.Status != Pending {
		return false, Pending
	}
	if !b.IsMember(voter) || r.Excludes(voter) || r.BallotOf(voter) != nil {
		return false, Pending
	}
	yes, no := b.Standing(r)
	if approve {
		yes++
	} else {
		no++
	}
	switch m := b.Majority(r); {
	case yes >= m:
		return true, Approved
	case no >= m:
		return true, Rejected
	}
	return false, Pending
}

// ReviewDecides is Decides for a proof review: it reports whether this
// verdict would close the attempt under review, and how. A realm uses it to
// check, before recording anything, that it can actually pay a tranche it is
// about to release.
func (b *Board) ReviewDecides(id, idx int, voter address, accept bool) (bool, Outcome) {
	r := b.Get(id)
	if r == nil || r.Kind != KindGrant || r.Status != Approved {
		return false, UnderReview
	}
	if idx < 0 || idx >= len(r.Milestones) {
		return false, UnderReview
	}
	a := r.Milestones[idx].Current()
	if a == nil {
		return false, UnderReview
	}
	if !b.IsMember(voter) || r.Excludes(voter) || find(a.Reviews, voter) != nil {
		return false, UnderReview
	}
	yes, no := b.standing(a.Reviews)
	if accept {
		yes++
	} else {
		no++
	}
	switch m := b.Majority(r); {
	case yes >= m:
		return true, Accepted
	case no >= m:
		return true, Refused
	}
	return false, UnderReview
}

// standing counts ballots from current members only. See Standing.
func (b *Board) standing(bs []Ballot) (yes, no int) {
	for _, v := range bs {
		if !b.IsMember(v.Voter) {
			continue
		}
		if v.Approve {
			yes++
		} else {
			no++
		}
	}
	return yes, no
}

// Vote casts one member's ballot on a request and returns the status it left
// the request in. A member votes once; there is no changing your mind, which
// is the price of every ballot being a permanent public statement.
func (b *Board) Vote(voter address, id int, approve bool, reason string, height int64) (Status, error) {
	r := b.Get(id)
	if r == nil {
		return Pending, ErrNoRequest
	}
	if !b.IsMember(voter) {
		return r.Status, ErrNotMember
	}
	if r.Status != Pending {
		return r.Status, ErrNotPending
	}
	if r.Excludes(voter) {
		return r.Status, ErrConflict
	}
	if r.BallotOf(voter) != nil {
		return r.Status, ErrAlreadyVoted
	}
	if len(reason) > MaxReason {
		return r.Status, ErrBadReason
	}

	r.Votes = append(r.Votes, Ballot{Voter: voter, Approve: approve, Reason: reason, Height: height})

	yes, no := b.Standing(r)
	switch m := b.Majority(r); {
	case yes >= m:
		r.Status, r.DecidedAt = Approved, height
		if r.Kind == KindMember {
			b.applyMemberChange(r, height)
		}
	case no >= m:
		r.Status, r.DecidedAt = Rejected, height
	}
	return r.Status, nil
}

// applyMemberChange is the whole execution engine for KindMember: a carried
// membership request takes effect at once, with nothing to claim afterwards,
// so it goes straight from Approved to Completed.
func (b *Board) applyMemberChange(r *Request, height int64) {
	if r.Add {
		b.members.Set(r.Subject.String(), height)
	} else {
		b.members.Remove(r.Subject.String())
	}
	r.Status = Completed
}

// SubmitProof offers evidence for the next unreleased milestone of an
// approved grant. Milestones are earned in order, and only one proof is under
// review at a time.
//
// Either the applicant or the beneficiary may submit. On a request filed for
// an empty account, the payee cannot transact until the first tranche lands,
// so restricting this to the payee would strand the grant it was filed to
// unstick; restricting it to the filer would leave the payee unable to show
// their own work once they can.
func (b *Board) SubmitProof(caller address, id, idx int, p Proof) error {
	r := b.Get(id)
	if r == nil {
		return ErrNoRequest
	}
	if r.Kind != KindGrant || r.Status != Approved {
		return ErrNotApproved
	}
	if r.Applicant != caller && r.Payee() != caller {
		return ErrNotApplicant
	}
	if idx < 0 || idx >= len(r.Milestones) {
		return ErrNoMilestone
	}
	if idx != r.Next() {
		return ErrOutOfOrder
	}
	if err := checkProof(p); err != nil {
		return err
	}
	m := r.Milestones[idx]
	if m.Current() != nil {
		return ErrProofPending
	}
	m.Attempts = append(m.Attempts, &Attempt{Proof: p, Outcome: UnderReview})
	return nil
}

// Review casts a member's verdict on the proof currently under review and
// returns the outcome that verdict left the attempt in. Accepting it releases
// the tranche, which in this package means marking it Released and nothing
// more; moving the coins is the caller's job, and Request.Paid tells it how
// much it now owes. Refusing closes the attempt and lets the applicant try
// again with better evidence.
func (b *Board) Review(voter address, id, idx int, accept bool, reason string, height int64) (Outcome, error) {
	r := b.Get(id)
	if r == nil {
		return UnderReview, ErrNoRequest
	}
	if !b.IsMember(voter) {
		return UnderReview, ErrNotMember
	}
	if r.Kind != KindGrant || r.Status != Approved {
		return UnderReview, ErrNotApproved
	}
	if idx < 0 || idx >= len(r.Milestones) {
		return UnderReview, ErrNoMilestone
	}
	if r.Excludes(voter) {
		return UnderReview, ErrConflict
	}
	if len(reason) > MaxReason {
		return UnderReview, ErrBadReason
	}
	m := r.Milestones[idx]
	a := m.Current()
	if a == nil {
		return UnderReview, ErrNoProof
	}
	if find(a.Reviews, voter) != nil {
		return UnderReview, ErrAlreadyVoted
	}

	a.Reviews = append(a.Reviews, Ballot{Voter: voter, Approve: accept, Reason: reason, Height: height})

	yes, no := b.standing(a.Reviews)
	switch mj := b.Majority(r); {
	case yes >= mj:
		a.Outcome, a.ClosedAt = Accepted, height
		m.Released, m.ReleasedAt = true, height
		if r.Next() == -1 {
			r.Status = Completed
		}
	case no >= mj:
		a.Outcome, a.ClosedAt = Refused, height
	}
	return a.Outcome, nil
}

func checkTitle(s string) error {
	if len(s) == 0 || len(s) > MaxTitle {
		return ErrBadTitle
	}
	return nil
}

func checkProof(p Proof) error {
	switch p.Kind {
	case "url", "hash", "text":
	default:
		return ErrBadProof
	}
	if len(p.Ref) == 0 || len(p.Ref) > MaxRef || len(p.Note) > MaxNote {
		return ErrBadProof
	}
	return nil
}

package grants

import (
	"strconv"
	"strings"
)

// Program is a Board plus the money that moves around it: what came in, what
// went out, and the denomination it is all counted in.
//
// It still holds no coins and calls no banker. A realm hands it the current
// treasury balance whenever a decision depends on one, and executes the
// Payment it hands back. That split is the whole point: everything a grant
// program decides is testable without a node, and the realm on top is thin
// enough to read in one screen.
type Program struct {
	Board     *Board
	Denom     string
	Donations []Donation
	Payments  []Payment
}

// Donation is one top-up of the treasury, credited to a name.
type Donation struct {
	Height int64
	From   address
	Amount int64
}

// Payment is one released tranche. The ledger of these is a program's answer
// to "where did the money go".
type Payment struct {
	Height    int64
	Request   int
	Milestone int
	To        address
	Amount    int64
}

// NewProgram returns a program whose board is seated with founders. denom is
// the coin everything is counted in ("ugnot" on gno.land); it is carried so a
// renderer can label amounts without the realm telling it twice.
func NewProgram(denom string, founders ...address) *Program {
	return &Program{Board: New(founders...), Denom: denom}
}

// Fund records a top-up. The coins have already moved by the time this is
// called: a realm calls it to put a name next to a transfer that would
// otherwise be anonymous.
func (p *Program) Fund(from address, amount, height int64) error {
	if amount <= 0 {
		return ErrNothingSent
	}
	if !from.IsValid() {
		return ErrBadAddress
	}
	p.Donations = append(p.Donations, Donation{Height: height, From: from, Amount: amount})
	return nil
}

// Apply files a grant request from a milestone spec, "design:100,ship:400".
// See ParseMilestones for the grammar.
func (p *Program) Apply(applicant address, title, body, spec string, height int64) (*Request, error) {
	return p.ApplyFor(applicant, applicant, "", title, body, spec, height)
}

// ApplyFor is Apply for a request whose money goes to someone other than the
// address filing it. See Board.SubmitFor for why the reason is required.
func (p *Program) ApplyFor(applicant, beneficiary address, reason, title, body, spec string, height int64) (*Request, error) {
	ms, err := ParseMilestones(spec)
	if err != nil {
		return nil, err
	}
	return p.Board.SubmitFor(applicant, beneficiary, reason, title, body, ms, height)
}

// Review casts a member's verdict on the proof under review and, when that
// verdict releases the tranche, records the payment and hands it back for the
// caller to execute.
//
// balance is what the treasury holds right now. A verdict that would release
// more than that is refused with ErrUnderfunded and changes NOTHING: no
// ballot, no release, no payment. That ordering is the reason Board.Review is
// not called directly by a realm. A refusal is always free to record, since it
// costs the treasury nothing.
func (p *Program) Review(voter address, id, idx int, accept bool, reason string, height, balance int64) (Outcome, *Payment, error) {
	if releases, out := p.Board.ReviewDecides(id, idx, voter, accept); releases && out == Accepted {
		if amount := p.Board.Get(id).Milestones[idx].Amount; balance < amount {
			return UnderReview, nil, ErrUnderfunded
		}
	}

	out, err := p.Board.Review(voter, id, idx, accept, reason, height)
	if err != nil || out != Accepted {
		return out, nil, err
	}

	r := p.Board.Get(id)
	pay := Payment{
		Height:    height,
		Request:   id,
		Milestone: idx,
		To:        r.Payee(),
		Amount:    r.Milestones[idx].Amount,
	}
	p.Payments = append(p.Payments, pay)
	return out, &pay, nil
}

// Raised is everything ever donated through Fund.
func (p *Program) Raised() int64 {
	var n int64
	for _, d := range p.Donations {
		n += d.Amount
	}
	return n
}

// Disbursed is everything ever released.
func (p *Program) Disbursed() int64 { return p.Board.Disbursed() }

// Committed is what approved grants can still claim.
func (p *Program) Committed() int64 { return p.Board.Committed() }

// Available is balance minus what is already promised. It goes NEGATIVE when
// the board has approved more than the treasury holds, which is allowed on
// purpose: a board that can only approve what it already has cannot approve
// anything before a donor shows up. Renderers say so out loud.
func (p *Program) Available(balance int64) int64 { return balance - p.Committed() }

// ParseMilestones reads "design:100,ship:400" into milestones, amounts in the
// program's denomination, paid in the order written. A title may not contain a
// comma, and the amount is whatever follows the LAST colon, so
// "port gno:land tooling:250" parses the way it reads.
func ParseMilestones(spec string) ([]*Milestone, error) {
	out := []*Milestone{}
	for _, part := range strings.Split(spec, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		i := strings.LastIndex(part, ":")
		if i < 0 {
			return nil, ErrBadSpec
		}
		amount, err := strconv.ParseInt(strings.TrimSpace(part[i+1:]), 10, 64)
		if err != nil {
			return nil, ErrBadSpec
		}
		out = append(out, NewMilestone(strings.TrimSpace(part[:i]), amount))
	}
	if len(out) == 0 {
		return nil, ErrBadSpec
	}
	return out, nil
}

package grants

import (
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Renderer turns a Program into the three markdown pages a grant program
// needs: the board, one request, and the ledger. Everything that differs
// between one program and the next is a field, so a realm's whole Render is
// building this literal and calling it.
//
// Build it INSIDE Render rather than storing it in a realm global: Note is a
// func, and Balance has to be read fresh on every call anyway.
//
// # Escaping
//
// Everything a caller typed (titles, bodies, reasons, proofs, notes) is
// escaped here, once, through p/moul/kit/ui and p/nt/markdown/sanitize. A
// realm does not repeat it and must not pre-escape: escaping twice shows the
// backslashes. The realm's OWN fields below (Title, Intro, Notes, Footer) are
// chrome, are written by whoever deployed the realm, and are emitted as-is so
// they can carry markdown.
type Renderer struct {
	Program  *Program
	Title    string   // page heading
	Intro    string   // markdown under the heading, already wrapped
	Notes    []string // extra paragraphs on the board page: house rules, scope
	Path     string   // package path, for the gnokey examples
	Link     string   // gnoweb route prefix, e.g. "/r/moul/grant/v0"
	Treasury address  // where the money sits
	Balance  int64    // what it holds right now
	Footer   string   // closing paragraph on the board page

	// Note returns an extra callout for one request page, or "". Use it for
	// anything the library cannot know, such as a seeded request whose
	// applicant address has no key behind it.
	Note func(*Request) string
}

// Render serves the board at "", one request at "request/<id>", and the money
// trail at "ledger".
func (rr Renderer) Render(path string) string {
	path = strings.TrimSpace(path)
	switch {
	case path == "" || path == "/":
		return rr.index()
	case path == "ledger":
		return rr.ledger()
	case strings.HasPrefix(path, "request/"):
		return rr.request(strings.TrimPrefix(path, "request/"))
	}
	return "# " + rr.Title + "\n\nNo page `" + path + "`. Try [the board](" + rr.Link +
		") or [the ledger](" + rr.Link + ":ledger).\n"
}

func (rr Renderer) index() string {
	p := rr.Program
	var b strings.Builder
	b.WriteString("# " + rr.Title + "\n\n")
	if rr.Intro != "" {
		b.WriteString(rr.Intro + "\n\n")
	}
	for _, n := range rr.Notes {
		b.WriteString(n + "\n\n")
	}

	b.WriteString("## Treasury\n\n")
	b.WriteString("| Field | Value |\n|---|---|\n")
	b.WriteString("| Address | " + ui.AddrFull(rr.Treasury) + " |\n")
	b.WriteString("| Balance | " + rr.amount(rr.Balance) + " |\n")
	b.WriteString("| Promised | " + rr.amount(p.Committed()) + " |\n")
	b.WriteString("| Unpromised | " + rr.amount(p.Available(rr.Balance)) + " |\n")
	b.WriteString("| Donated | " + rr.amount(p.Raised()) + " |\n")
	b.WriteString("| Paid out | " + rr.amount(p.Disbursed()) + " |\n\n")
	if short := -p.Available(rr.Balance); short > 0 {
		b.WriteString("The board has promised " + rr.amount(short) + " more than it holds. Approving a\n")
		b.WriteString("grant does not escrow anything, so a tranche can come due against an empty\n")
		b.WriteString("treasury; a review that would release one is refused until the money is there.\n")
		b.WriteString("Top it up with `Fund`, or by sending coins straight to the address above.\n\n")
	}

	b.WriteString("## Board\n\n")
	b.WriteString("A decision needs a majority of the members eligible to cast a ballot on it,\n")
	b.WriteString("recomputed every time: the party a decision is about never votes on it, so an\n")
	b.WriteString("applicant who sits on the board shrinks the room rather than packing it.\n\n")
	b.WriteString("| Member | Joined at height |\n|---|---|\n")
	for _, m := range p.Board.Members() {
		b.WriteString("| " + ui.AddrFull(m) + " | " + i64(p.Board.JoinedAt(m)) + " |\n")
	}
	b.WriteString("\n")

	b.WriteString("## Requests\n\n")
	all := p.Board.List()
	if len(all) == 0 {
		b.WriteString("Nothing has been asked of this board yet. `Apply` is open to anyone.\n\n")
	} else {
		b.WriteString("| # | Kind | Title | For | Asking | Status | Ballots |\n|---|---|---|---|---|---|---|\n")
		for _, r := range all {
			yes, no := p.Board.Standing(r)
			b.WriteString("| [" + strconv.Itoa(r.ID) + "](" + rr.Link + ":request/" + strconv.Itoa(r.ID) + ")" +
				" | " + r.Kind.String() +
				" | " + ui.Cell(r.Title) +
				" | " + rr.who(r) +
				" | " + rr.ask(r) +
				" | " + r.Status.String() +
				" | " + strconv.Itoa(yes) + " for, " + strconv.Itoa(no) + " against" +
				" |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Where the money went\n\n")
	b.WriteString("[The ledger](" + rr.Link + ":ledger) lists every donation in and every tranche\n")
	b.WriteString("out, with the height, the payee and the milestone it paid for.\n\n")

	b.WriteString("## Calling it\n\n")
	b.WriteString("```sh\n")
	b.WriteString("# put money in\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func Fund -send 5000000" + p.Denom + " ...\n")
	b.WriteString("# ask for some\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func Apply \\\n")
	b.WriteString("  -args 'Port the thing' -args 'why it matters' -args 'design:100,ship:400' ...\n")
	b.WriteString("# ask on behalf of someone who cannot pay the gas to ask\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func ApplyFor \\\n")
	b.WriteString("  -args g1... -args 'their account is empty' \\\n")
	b.WriteString("  -args 'Port the thing' -args 'why it matters' -args 'design:100,ship:400' ...\n")
	b.WriteString("# decide (members only)\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func Vote -args 1 -args true -args 'reason' ...\n")
	b.WriteString("# show your work, then get paid for it\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func SubmitProof \\\n")
	b.WriteString("  -args 1 -args 0 -args url -args 'https://...' -args 'what it is' ...\n")
	b.WriteString("gnokey maketx call -pkgpath " + rr.Path + " -func Review -args 1 -args 0 -args true -args 'looks done' ...\n")
	b.WriteString("```\n")
	if rr.Footer != "" {
		b.WriteString("\n" + rr.Footer + "\n")
	}
	return b.String()
}

func (rr Renderer) request(raw string) string {
	id, err := strconv.Atoi(raw)
	if err != nil {
		return "# " + rr.Title + "\n\n`" + raw + "` is not a request number.\n"
	}
	r := rr.Program.Board.Get(id)
	if r == nil {
		return "# " + rr.Title + "\n\nThere is no request " + raw + ".\n"
	}
	board := rr.Program.Board

	var b strings.Builder
	b.WriteString("# Request " + strconv.Itoa(r.ID) + ": " + ui.Inline(r.Title) + "\n\n")
	b.WriteString("| Field | Value |\n|---|---|\n")
	b.WriteString("| Kind | " + r.Kind.String() + " |\n")
	b.WriteString("| Applicant | " + ui.AddrFull(r.Applicant) + " |\n")
	if r.OnBehalf() {
		b.WriteString("| Beneficiary | " + ui.AddrFull(r.Beneficiary) + " |\n")
	}
	if r.Kind == KindMember {
		b.WriteString("| Subject | " + ui.AddrFull(r.Subject) + " |\n")
		b.WriteString("| Effect | " + addRemove(r.Add) + " |\n")
	}
	b.WriteString("| Status | " + r.Status.String() + " |\n")
	b.WriteString("| Filed at height | " + i64(r.CreatedAt) + " |\n")
	if r.DecidedAt != 0 {
		b.WriteString("| Decided at height | " + i64(r.DecidedAt) + " |\n")
	}
	if r.Kind == KindGrant {
		b.WriteString("| Asking | " + rr.amount(r.Total()) + " |\n")
		b.WriteString("| Paid so far | " + rr.amount(r.Paid()) + " |\n")
		b.WriteString("| Still owed | " + rr.amount(r.Outstanding()) + " |\n")
	}
	b.WriteString("\n")

	if r.OnBehalf() {
		b.WriteString("## Filed for someone else\n\n")
		b.WriteString("The applicant is not the payee: every tranche of this request pays\n")
		b.WriteString(ui.AddrFull(r.Beneficiary) + ". Both addresses are barred from voting on it, and\n")
		b.WriteString("either may submit a proof. The reason given:\n\n")
		b.WriteString("> " + ui.Inline(r.Reason) + "\n\n")
		b.WriteString("Nothing checks that reason. It is a claim by the applicant, and the point of\n")
		b.WriteString("printing it here is that a member can check it before voting.\n\n")
	}

	if rr.Note != nil {
		if note := rr.Note(r); note != "" {
			b.WriteString(note + "\n\n")
		}
	}

	if r.Body != "" {
		b.WriteString("## The ask\n\n" + block(r.Body) + "\n\n")
	}

	b.WriteString("## Ballots\n\n")
	yes, no := board.Standing(r)
	recorded, against := r.Tally()
	b.WriteString("Needs " + strconv.Itoa(board.Majority(r)) + " of " + strconv.Itoa(board.Eligible(r)) +
		" eligible members. Standing: " + strconv.Itoa(yes) + " for, " + strconv.Itoa(no) + " against.\n")
	if recorded != yes || against != no {
		b.WriteString("On the record: " + strconv.Itoa(recorded) + " for, " + strconv.Itoa(against) +
			" against. The difference is ballots cast by people who have since left the board;\n")
		b.WriteString("they stay on the record and stop counting.\n")
	}
	b.WriteString("\n")
	if len(r.Votes) == 0 {
		b.WriteString("Nobody has voted yet.\n\n")
	} else {
		b.WriteString(rr.ballots(r.Votes, "for", "against"))
	}

	if r.Kind != KindGrant {
		return b.String()
	}

	b.WriteString("## Milestones\n\n")
	b.WriteString("Earned in order. The applicant submits a proof, the board reviews that proof,\n")
	b.WriteString("and the verdict that carries also moves the coins.\n\n")
	for i, m := range r.Milestones {
		b.WriteString("### " + strconv.Itoa(i+1) + ". " + ui.Inline(m.Title) + ": " + rr.amount(m.Amount) + "\n\n")
		b.WriteString(milestoneState(r, i, m) + "\n\n")
		for j, a := range m.Attempts {
			b.WriteString("**Proof " + strconv.Itoa(j+1) + "** (" + a.Proof.Kind + ", height " +
				i64(a.Proof.Height) + ", " + a.Outcome.String() + ")\n\n")
			b.WriteString(fence(a.Proof.Ref) + "\n\n")
			if a.Proof.Note != "" {
				b.WriteString(block(a.Proof.Note) + "\n\n")
			}
			if len(a.Reviews) == 0 {
				b.WriteString("No review yet.\n\n")
				continue
			}
			b.WriteString(rr.ballots(a.Reviews, "accept", "refuse"))
		}
	}
	return b.String()
}

func (rr Renderer) ledger() string {
	p := rr.Program
	var b strings.Builder
	b.WriteString("# " + rr.Title + ": the ledger\n\n")
	b.WriteString("Every coin in and every coin out, in the order it happened. Coins sent\n")
	b.WriteString("straight to " + ui.AddrFull(rr.Treasury) + " land in the treasury\n")
	b.WriteString("without appearing here, which is why `Fund` exists: it is the same transfer\n")
	b.WriteString("with a name attached.\n\n")

	b.WriteString("## In\n\n")
	if len(p.Donations) == 0 {
		b.WriteString("Nothing donated through `Fund` yet.\n\n")
	} else {
		b.WriteString("| Height | From | Amount |\n|---|---|---|\n")
		for _, d := range p.Donations {
			b.WriteString("| " + i64(d.Height) + " | " + ui.AddrFull(d.From) + " | " + rr.amount(d.Amount) + " |\n")
		}
		b.WriteString("\nTotal in: " + rr.amount(p.Raised()) + "\n\n")
	}

	b.WriteString("## Out\n\n")
	if len(p.Payments) == 0 {
		b.WriteString("No tranche has been released yet.\n\n")
	} else {
		b.WriteString("| Height | Request | Milestone | To | Amount |\n|---|---|---|---|---|\n")
		for _, pay := range p.Payments {
			b.WriteString("| " + i64(pay.Height) +
				" | [" + strconv.Itoa(pay.Request) + "](" + rr.Link + ":request/" + strconv.Itoa(pay.Request) + ")" +
				" | " + strconv.Itoa(pay.Milestone+1) +
				" | " + ui.AddrFull(pay.To) +
				" | " + rr.amount(pay.Amount) + " |\n")
		}
		b.WriteString("\nTotal out: " + rr.amount(p.Disbursed()) + "\n\n")
	}

	b.WriteString("Balance now: " + rr.amount(rr.Balance) + ". [Back to the board](" + rr.Link + ").\n")
	return b.String()
}

// ballots renders one decision's ballots, marking anyone who has since left
// the board: their vote stays on the record and stops counting.
func (rr Renderer) ballots(bs []Ballot, forLabel, againstLabel string) string {
	var b strings.Builder
	b.WriteString("| Member | Vote | Height | Reason |\n|---|---|---|---|\n")
	for _, v := range bs {
		who := ui.AddrFull(v.Voter)
		if !rr.Program.Board.IsMember(v.Voter) {
			who += " (left the board)"
		}
		vote := againstLabel
		if v.Approve {
			vote = forLabel
		}
		b.WriteString("| " + who + " | " + vote + " | " + i64(v.Height) + " | " + orDash(ui.Cell(v.Reason)) + " |\n")
	}
	b.WriteString("\n")
	return b.String()
}

func (rr Renderer) amount(n int64) string { return strconv.FormatInt(n, 10) + " " + rr.Program.Denom }

// who is the board index's "For" column: who this request would pay, marked
// when that is not the address that filed it.
func (rr Renderer) who(r *Request) string {
	if r.Kind == KindMember {
		return "-"
	}
	if r.OnBehalf() {
		return ui.Addr(r.Beneficiary) + " (filed by " + ui.AddrText(r.Applicant) + ")"
	}
	return ui.Addr(r.Applicant)
}

func (rr Renderer) ask(r *Request) string {
	if r.Kind == KindMember {
		return "nothing"
	}
	return rr.amount(r.Total())
}

func milestoneState(r *Request, i int, m *Milestone) string {
	switch {
	case m.Released:
		return "Released at height " + i64(m.ReleasedAt) + ", paid to " + ui.AddrFull(r.Payee()) + "."
	case r.Status != Approved:
		return "Locked: the request is " + r.Status.String() + "."
	case m.Current() != nil:
		return "A proof is under review."
	case i == r.Next():
		return "Waiting on a proof from the applicant."
	}
	return "Locked until milestone " + strconv.Itoa(r.Next()+1) + " is released."
}

func addRemove(add bool) string {
	if add {
		return "add to the board"
	}
	return "remove from the board"
}

// block and fence escape a multi-line, user-written string for its slot and
// then trim the sanitizer's own trailing newlines.
//
// The trim is not cosmetic. gno collapses two consecutive blank lines in an
// Example's output the way Go does, so any page that emits one can never be
// pinned by an ExampleRender, and the only test that proves a whole page is
// the one that stops working.
func block(s string) string { return strings.TrimSpace(sanitize.Block(s)) }

func fence(s string) string { return strings.TrimSpace(sanitize.CodeBlock(s)) }

func i64(n int64) string { return strconv.FormatInt(n, 10) }

func orDash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

