package gns

import (
	"testing"
)

// Local assertion helpers.
//
// We deliberately avoid gno.land/p/nt/uassert here: when this realm is compiled
// as an EXTERNAL package (outside the gno examples module) the working-tree copy
// of uassert/v0 fails to preprocess with the pinned gno binary. These helpers
// depend only on the standard testing package.
//
// GNS mutations PANIC with stable error values (see the error_* set) to revert
// state, per gno semantics. A recover() inside this same realm package cannot
// catch a crossing-boundary abort (only a pure p/ package frame can). Rejection
// invariants are therefore unit-tested against the internal, non-crossing
// helpers that produce the errors (authorize, priceFor, available, ...), and a
// few end-to-end abort behaviours are covered by filetests.

func eqStr(t *testing.T, want, got, ctx string) {
	t.Helper()
	if want != got {
		t.Errorf("%s: want %q, got %q", ctx, want, got)
	}
}

func eqInt(t *testing.T, want, got int64, ctx string) {
	t.Helper()
	if want != got {
		t.Errorf("%s: want %d, got %d", ctx, want, got)
	}
}

func isTrue(t *testing.T, v bool, ctx string) {
	t.Helper()
	if !v {
		t.Errorf("%s: want true", ctx)
	}
}

func isFalse(t *testing.T, v bool, ctx string) {
	t.Helper()
	if v {
		t.Errorf("%s: want false", ctx)
	}
}

func noErr(t *testing.T, err error, ctx string) {
	t.Helper()
	if err != nil {
		t.Errorf("%s: unexpected error %v", ctx, err)
	}
}

func isErr(t *testing.T, err error, ctx string) {
	t.Helper()
	if err == nil {
		t.Errorf("%s: expected error, got nil", ctx)
	}
}

// errIs asserts err matches want by stable code (Error() string).
func errIs(t *testing.T, err, want error, ctx string) {
	t.Helper()
	if err == nil {
		t.Errorf("%s: expected error %v, got nil", ctx, want)
		return
	}
	if err.Error() != want.Error() {
		t.Errorf("%s: expected %q, got %q", ctx, want.Error(), err.Error())
	}
}

// Package gns implements GNS (Gno Name Service): an ENS-equivalent naming
// system expressed as a single Gno-native realm.
//
// The design goal is NOT byte-for-byte ENS compatibility. Instead it provides
// the same user-facing capabilities (registration, renewal, expiry/grace,
// forward & reverse resolution, primary names, typed + arbitrary records,
// subnames with policies, delegated operators, pagination and
// events) through ONE realm, ONE ownership model, ONE record model, ONE
// authorization function and ONE registration lifecycle.
//
// Key deviations from a naive port of the spec, forced by gno semantics:
//
//   - State-mutating exported functions are "crossing" functions: they take
//     `cur realm` as the first parameter and PANIC (abort) on failure rather
//     than returning an error, because in gno only a panic/abort reverts state.
//     Failures panic with a stable machine-readable code (see the error_* set).
//   - Persistent, enumerable collections use avl.Tree (ordered, paginatable)
//     instead of Go maps, so every listing API is bounded and cursor-based.
//   - Names are stored string-native (canonical "label.parent"), not namehashed.
//
// See README.md for the full compatibility statement.
package gns

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// ---------------------------------------------------------------------------
// 2. Constants
// ---------------------------------------------------------------------------

const (
	maxLabelLen = 63
	maxNameLen  = 255
	maxDepth    = 16

	sep = "|" // index-key separator; never appears in names or bech32 addresses
)

// Registration-policy modes.
const (
	ModeClosed    = "closed"
	ModeOwner     = "owner"
	ModeOpen      = "open"
	ModeAllowlist = "allowlist"
	ModePaid      = "paid"
