	}
	handle, ok := HandleOf(bob)
	if !ok || handle != "moul" {
		t.Fatalf("HandleOf(bob) = %q, %v; want moul, true", handle, ok)
	}

	testing.SetRealm(testing.NewUserRealm(bob))
