func TestRenderNewestFirstAndPagination(cur realm, t *testing.T) {
	resetWall()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("dave")))

	// 25 posts -> 2 pages (20 + 5).
	for i := 0; i < 25; i++ {
		Post(cross(cur), "msg"+itoa(i))
	}

	if got := Count(); got != 25 {
		t.Fatalf("Count() = %d, want 25", got)
	}

	page1 := Render("")
	// Newest (msg24) must appear before older (msg5) on page 1.
	i24 := strings.Index(page1, "msg24")
	i5 := strings.Index(page1, "msg5")
	if i24 < 0 || i5 < 0 {
		t.Fatalf("page 1 missing expected posts: msg24=%d msg5=%d", i24, i5)
	}
	if i24 > i5 {
		t.Errorf("page 1 not newest-first: msg24 at %d should precede msg5 at %d", i24, i5)
	}
	if !strings.Contains(page1, "page 1 of 2") {
		t.Errorf("page 1 header wrong, got:\n%s", page1)
	}

	// Page 2 via query form must contain the oldest post.
	page2 := Render("?page=2")
	if !strings.Contains(page2, "msg0") {
		t.Errorf("page 2 should contain oldest msg0, got:\n%s", page2)
	}
	if !strings.Contains(page2, "page 2 of 2") {
		t.Errorf("page 2 header wrong, got:\n%s", page2)
	}

	// Path form "/2" should equal query form "?page=2".
	if Render("/2") != page2 {
		t.Errorf("path form /2 differs from query form ?page=2")
	}
}

func TestParsePage(t *testing.T) {
	cases := []struct {
		in   string
		want int
	}{
		{"", 1},
		{"?page=3", 3},
		{"?p=4", 4},
		{"/2", 2},
		{"5", 5},
		{"?page=abc", 1},
		{"garbage", 1},
	}
	for _, c := range cases {
		if got := parsePage(c.in); got != c.want {
			t.Errorf("parsePage(%q) = %d, want %d", c.in, got, c.want)
		}
	}
}

// itoa is a tiny local int->string helper for building test messages.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

package moodstone

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
)

// Entry holds a single mood log.
type Entry struct {
	Author address
	Mood   string
	Note   string
	Block  int64
}

var entries []Entry

var validMoods = []string{"happy", "sad", "excited", "calm", "anxious", "angry", "neutral"}

func isValid(mood string) bool {
	for _, m := range validMoods {
		if m == mood {
			return true
		}
	}
	return false
}

func emoji(mood string) string {
	switch mood {
	case "happy":
		return "😊"
	case "sad":
		return "😢"
	case "excited":
		return "🎉"
	case "calm":
		return "😌"
	case "anxious":
		return "😰"
	case "angry":
		return "😠"
	case "neutral":
		return "😐"
	}
	return "❓"
}

func bar(count, total int) string {
	if total == 0 {
		return strings.Repeat("░", 20)
	}
	filled := (count * 20) / total
	return strings.Repeat("▓", filled) + strings.Repeat("░", 20-filled)
}

// LogMood records the caller's current mood with an optional note.
// mood must be one of: happy sad excited calm anxious angry neutral
func LogMood(_ realm, mood, note string) {
	mood = strings.ToLower(strings.TrimSpace(mood))
	if !isValid(mood) {
		panic("invalid mood; choose from: " + strings.Join(validMoods, ", "))
	}
	entries = append(entries, Entry{
		Author: unsafe.OriginCaller(),
		Mood:   mood,
		Note:   strings.TrimSpace(note),
		Block:  runtime.ChainHeight(),
	})
}

// TotalEntries returns the total number of mood logs on record.
func TotalEntries() int {
	return len(entries)
}

// MoodCount returns how many times the given mood has been logged.
func MoodCount(mood string) int {
	mood = strings.ToLower(strings.TrimSpace(mood))
	n := 0
	for _, e := range entries {
		if e.Mood == mood {
			n++
		}
	}
	return n
}

// DominantMood returns the most-logged mood, or "none" if no entries.
func DominantMood() string {
	if len(entries) == 0 {
		return "none"
	}
	counts := make(map[string]int)
	for _, e := range entries {
		counts[e.Mood]++
	}
	best := ""
	bestN := 0
	for _, m := range validMoods {
		if counts[m] > bestN {
			bestN = counts[m]
			best = m
		}
	}
	return best
}

func Render(path string) string {
	out := "# 🪨 Moodstone — On-chain Mood Tracker\n\n"
	out += "> Log how you feel. Watch how the community feels. Immutably, on Gno.\n\n"

	total := len(entries)

	// Community stats table
	out += "## 📊 Community Vibes\n\n"
	if total == 0 {
		out += "*No moods logged yet — be the first!*\n\n"
	} else {
		counts := make(map[string]int)
		for _, e := range entries {
			counts[e.Mood]++
		}
		out += "| Mood | Count | Distribution |\n"
		out += "|------|-------|--------------|\n"
		for _, m := range validMoods {
			c := counts[m]
			pct := 0
			if total > 0 {
				pct = (c * 100) / total
			}
			out += "| " + emoji(m) + " " + m + " | " + strconv.Itoa(c) +
				" | `" + bar(c, total) + "` " + strconv.Itoa(pct) + "% |\n"
		}
		dom := DominantMood()
		out += "\n**Total entries:** " + strconv.Itoa(total) +
			" · **Dominant mood:** " + emoji(dom) + " " + dom + "\n\n"
	}

	// Recent entries (newest first, max 10)
	out += "## 📝 Recent Entries\n\n"
	if total == 0 {
		out += "*Nothing here yet.*\n\n"
	} else {
		start := total - 10
		if start < 0 {
			start = 0
		}
		for i := total - 1; i >= start; i-- {
			e := entries[i]
			line := "- " + emoji(e.Mood) + " **" + e.Mood + "**"
			if e.Note != "" {
				line += ": *" + e.Note + "*"
			}
			line += " — " + ui.Addr(e.Author) + " at block " +
				strconv.FormatInt(e.Block, 10)
			out += line + "\n"
		}
		out += "\n"
	}

	// How to use
	out += "## 🚀 How to Use\n\n"
	out += "```bash\n"
	out += "gnokey maketx call \\\n"
	out += "  -pkgpath gno.land/r/g12cs4cehujpffpjpywmkqj43m6u5ya53nj69sjz/moodstone \\\n"
	out += "  -func LogMood \\\n"
	out += "  -args 'happy' -args 'Just shipped something awesome!'\n"
	out += "```\n\n"
	out += "**Valid moods:** " + strings.Join(validMoods, " · ") + "\n"

