package sparklinedemo

// ExampleRender pins the realm's Render output as a testable example.
func ExampleRender() {
	print(Render(""))
	// Output:
	// # Sparklines
	//
	// A numeric series as one line of block characters, demoing the [`p/moul/x/daily/sparkline`](/p/moul/x/daily/sparkline/v0) library.
	//
	// ## A series
	//
	// `▁▁▂▄▃▅█▆▅▃▂▁`
	//
	// `3, 5, 9, 14, 12, 18, 25, 21, 16, 11, 7, 4`
	//
	// Scaled between its own bounds, `3` and `25`. The shape is the point; the axis is not.
	//
	// ## The ramp
	//
	// `▁▂▃▄▅▆▇█` — eight levels, low to high.
	//
	// | value | 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7 |
	// |---|---|---|---|---|---|---|---|---|
	// | level | `▁` | `▂` | `▃` | `▄` | `▅` | `▆` | `▇` | `█` |
	//
	// ## A flat series
	//
	// `▅▅▅▅` — `1000, 1000, 1000, 1000`
	//
	// Mid-ramp, not along the floor. A series that never moves has no shape, but drawing it at the bottom would claim it was *zero*, which is a different thing and a wrong one.
	//
	// ## Negatives
	//
	// `▁▃▄▅█▅▂` — `-8, -3, 0, 4, 9, 2, -5`
	//
	// Nothing special: the window is the minimum and maximum, wherever zero happens to fall.
	//
	// ## A fixed window clamps
	//
	// `-20, 0, 25, 50, 75, 100, 140` against `0..100`:
	//
	// `▁▁▂▄▆██`
	//
	// `-20` pins to the floor and `140` to the ceiling. Choosing the window keeps a percentage readable, and one outlier cannot flatten the rest of the picture — or break the realm that drew it.
	//
	// ## Rounding is floor
	//
	// | value in `0..100` | level |
	// |---|---|
	// | 0 | `▁` |
	// | 14 | `▁` |
	// | 50 | `▄` |
	// | 85 | `▆` |
	// | 99 | `▇` |
	// | 100 | `█` |
	//
	// Only the maximum itself reaches the top of the ramp, so the peak of a series is always visually distinct.
	//
	// ## Why integers
	//
	// Scaling is integer division throughout. Render output has to be byte-identical on every validating node, and floating point is the usual way that quietly stops being true.
}

// Package sparklinedemo is a small gnoweb demo of the block-character series
// renderer provided by the [p/moul/x/daily/sparkline](/p/moul/x/daily/sparkline/v0)
// library: it sparks a few fixed series and shows the three behaviours worth
// knowing before using it in a realm — flat series, clamping, and floor
// rounding.
//
// It contains no rendering logic of its own. Stateless, so Render is
// deterministic.
package sparklinedemo

import (
	"strconv"
	"strings"

	"gno.land/p/moul/x/daily/sparkline/v0"
)

// series are fixed rather than derived from chain state: a demo whose output
// moved with the block height could not be pinned by an example test.
var (
	traffic = []int{3, 5, 9, 14, 12, 18, 25, 21, 16, 11, 7, 4}
	flat    = []int{1000, 1000, 1000, 1000}
	swing   = []int{-8, -3, 0, 4, 9, 2, -5}
	pct     = []int{-20, 0, 25, 50, 75, 100, 140}
)

// Render renders the demo for gnoweb.
//
//	Render("") / Render("/") -> the full demo
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Sparklines\n\n")
	b.WriteString("A numeric series as one line of block characters, demoing the ")
	b.WriteString("[`p/moul/x/daily/sparkline`](/p/moul/x/daily/sparkline/v0) library.\n\n")

	b.WriteString("## A series\n\n")
	lo, hi, _ := sparkline.Bounds(traffic)
	b.WriteString("`" + sparkline.Ints(traffic) + "`\n\n")
	b.WriteString(ints(traffic) + "\n\n")
	b.WriteString("Scaled between its own bounds, `" + strconv.Itoa(lo) + "` and `" +
		strconv.Itoa(hi) + "`. The shape is the point; the axis is not.\n\n")

	b.WriteString("## The ramp\n\n")
	b.WriteString("`" + sparkline.Levels + "` — eight levels, low to high.\n\n")
	b.WriteString("| value | 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7 |\n")
	b.WriteString("|---|---|---|---|---|---|---|---|---|\n")
	b.WriteString("| level |")
	for v := 0; v <= 7; v++ {
		b.WriteString(" `" + sparkline.Scaled([]int{v}, 0, 7) + "` |")
	}
	b.WriteString("\n\n")

	b.WriteString("## A flat series\n\n")
	b.WriteString("`" + sparkline.Ints(flat) + "` — " + ints(flat) + "\n\n")
	b.WriteString("Mid-ramp, not along the floor. A series that never moves has no ")
	b.WriteString("shape, but drawing it at the bottom would claim it was *zero*, ")
	b.WriteString("which is a different thing and a wrong one.\n\n")

	b.WriteString("## Negatives\n\n")
	b.WriteString("`" + sparkline.Ints(swing) + "` — " + ints(swing) + "\n\n")
	b.WriteString("Nothing special: the window is the minimum and maximum, wherever ")
	b.WriteString("zero happens to fall.\n\n")

	b.WriteString("## A fixed window clamps\n\n")
	b.WriteString(ints(pct) + " against `0..100`:\n\n")
	b.WriteString("`" + sparkline.Scaled(pct, 0, 100) + "`\n\n")
	b.WriteString("`-20` pins to the floor and `140` to the ceiling. Choosing the ")
	b.WriteString("window keeps a percentage readable, and one outlier cannot flatten ")
	b.WriteString("the rest of the picture — or break the realm that drew it.\n\n")

	b.WriteString("## Rounding is floor\n\n")
	b.WriteString("| value in `0..100` | level |\n")
	b.WriteString("|---|---|\n")
	for _, v := range []int{0, 14, 50, 85, 99, 100} {
		b.WriteString("| " + strconv.Itoa(v) + " | `" +
			sparkline.Scaled([]int{v}, 0, 100) + "` |\n")
	}
	b.WriteString("\nOnly the maximum itself reaches the top of the ramp, so the peak ")
	b.WriteString("of a series is always visually distinct.\n\n")

	b.WriteString("## Why integers\n\n")
	b.WriteString("Scaling is integer division throughout. Render output has to be ")
	b.WriteString("byte-identical on every validating node, and floating point is the ")
	b.WriteString("usual way that quietly stops being true.\n")

	return b.String()
}

// ints formats a series as `a, b, c` for the prose around each sparkline.
func ints(values []int) string {
	parts := make([]string, len(values))
	for i, v := range values {
		parts[i] = strconv.Itoa(v)
	}
	return "`" + strings.Join(parts, ", ") + "`"
}

// Package streaks is an on-chain habit-streak tracker. Call CheckIn() again
// within graceBlocks of your last check-in and the streak keeps growing; let
// the gap run past that and it resets to zero on your next check-in. Gno has
// no wall clock, so "again soon enough" is measured in blocks rather than
// calendar days — graceBlocks is the tunable stand-in for "before tomorrow".
package streaks

import (
	"sort"
	"strconv"

	"chain/runtime"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/nt/avl/v0"
)

// graceBlocks is the max block gap between two check-ins that still counts
// as consecutive. A gap larger than this lapses the streak.
const graceBlocks int64 = 100

// record is the persisted streak state for one address.
type record struct {
	owner      address
	current    int64
	longest    int64
	total      int64
	lastHeight int64
}

var streaks avl.Tree // owner address string -> *record

func get(owner address) (*record, bool) {
	v, ok := streaks.Get(owner.String()).(*record)
	return v, ok
}

// project reports the record's current streak as of height without
// mutating it: once the gap since lastHeight exceeds graceBlocks the streak
// reads as lapsed, even though the stored value only resets on the next
// actual check-in.
func project(r *record, height int64) (current int64, alive bool) {
	if height-r.lastHeight > graceBlocks {
		return 0, false
	}
	return r.current, true
}

// checkin is the non-crossing core of CheckIn, kept separate so unit tests
// can drive it directly by address and height.
func checkin(owner address, height int64) string {
	r, ok := get(owner)
	if !ok {
		r = &record{owner: owner}
		streaks.Set(owner.String(), r)
	} else {
		if height <= r.lastHeight {
			panic("already checked in at this block height")
		}
		if height-r.lastHeight > graceBlocks {
			r.current = 0
		}
	}
	r.current++
	if r.current > r.longest {
		r.longest = r.current
	}
	r.lastHeight = height
	r.total++
	return "checked in — current streak: " + strconv.FormatInt(r.current, 10) + " 🔥"
}

// CheckIn records a check-in for the caller at the current block height.
func CheckIn(cur realm) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return checkin(cur.Previous().Address(), runtime.ChainHeight())
}

// CurrentStreak returns addr's live current streak, 0 if it has lapsed or
// addr has never checked in.
func CurrentStreak(addr string) int64 {
	r, ok := get(address(addr))
	if !ok {
		return 0
	}
	current, _ := project(r, runtime.ChainHeight())
	return current
}

// LongestStreak returns addr's best streak ever, 0 if it has never checked in.
func LongestStreak(addr string) int64 {
	r, ok := get(address(addr))
	if !ok {
		return 0
	}
	return r.longest
}

// byRank orders the leaderboard by longest streak, then current streak, then
// owner address — fully deterministic regardless of avl iteration order.
type byRank []*record

func (b byRank) Len() int      { return len(b) }
func (b byRank) Swap(i, j int) { b[i], b[j] = b[j], b[i] }
func (b byRank) Less(i, j int) bool {
	if b[i].longest != b[j].longest {
		return b[i].longest > b[j].longest
	}
	if b[i].current != b[j].current {
		return b[i].current > b[j].current
	}
	return b[i].owner.String() < b[j].owner.String()
}

func renderDetail(r *record, height int64) string {
	current, alive := project(r, height)
	status := "🔥 active"
	if !alive {
		status = "💤 lapsed"
	}
	out := "## " + ui.Addr(r.owner) + "\n\n"
	out += "- Status: " + status + "\n"
	out += "- Current streak: " + strconv.FormatInt(current, 10) + "\n"
	out += "- Longest streak: " + strconv.FormatInt(r.longest, 10) + "\n"
	out += "- Total check-ins: " + strconv.FormatInt(r.total, 10) + "\n"
	out += "- Last check-in at block " + strconv.FormatInt(r.lastHeight, 10) + "\n"
	return out
}

// Render shows either the full leaderboard (path == "") or a single
// address's detail card when path is a bech32 address.
func Render(path string) string {
	height := runtime.ChainHeight()

	out := "# 🔥 Streaks\n\n"
	out += "An on-chain habit-streak tracker. Call `CheckIn()` again within " +
		strconv.FormatInt(graceBlocks, 10) + " blocks of your last check-in to keep it alive; " +
		"wait longer than that and it resets to zero on your next check-in.\n\n"

	if path != "" {
		r, ok := get(address(path))
		if !ok {
			return out + "_No check-ins yet for `" + path + "`._\n"
		}
		return out + renderDetail(r, height)
	}

	var rows []*record
	streaks.Iterate("", "", func(_ string, v any) bool {
		rows = append(rows, v.(*record))
		return false
	})
	if len(rows) == 0 {
		out += "_Nobody has checked in yet. Be the first!_\n"
		return out
	}
	sort.Stable(byRank(rows))

	out += "| Rank | Address | Status | Current | Longest | Total |\n"
	out += "| ---: | :--- | :--- | ---: | ---: | ---: |\n"
	for i, r := range rows {
		current, alive := project(r, height)
		status := "🔥"
		if !alive {
			status = "💤"
		}
		out += "| " + strconv.Itoa(i+1) + " | " + ui.Addr(r.owner) + " | " + status +
			" | " + strconv.FormatInt(current, 10) + " | " + strconv.FormatInt(r.longest, 10) +
			" | " + strconv.FormatInt(r.total, 10) + " |\n"
	}
	out += "\n_View a single address at `?<address>`._\n"
	return out
}

package streaks

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
)

func resetState() {
	streaks = avl.Tree{}
}

func TestCheckinFirstTimeStartsStreak(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")

	checkin(alice, 100)

	r, ok := get(alice)
	if !ok {
		t.Fatal("expected a record after first check-in")
	}
	if r.current != 1 || r.longest != 1 || r.total != 1 {
		t.Fatalf("expected current=1 longest=1 total=1, got current=%d longest=%d total=%d", r.current, r.longest, r.total)
	}
}

func TestCheckinWithinGraceExtendsStreak(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")

	checkin(alice, 100)
	checkin(alice, 150) // gap of 50 <= graceBlocks(100)
	checkin(alice, 200) // gap of 50 again

	r, _ := get(alice)
	if r.current != 3 {
		t.Fatalf("expected streak of 3, got %d", r.current)
	}
	if r.longest != 3 {
		t.Fatalf("expected longest of 3, got %d", r.longest)
	}
}

func TestCheckinAfterGraceResetsStreak(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")

	checkin(alice, 100)
	checkin(alice, 150)
	checkin(alice, 400) // gap of 250 > graceBlocks(100): lapsed

	r, _ := get(alice)
	if r.current != 1 {
		t.Fatalf("expected streak reset to 1, got %d", r.current)
	}
	if r.longest != 2 {
		t.Fatalf("expected longest to stay at 2, got %d", r.longest)
	}
	if r.total != 3 {
		t.Fatalf("expected total check-ins of 3, got %d", r.total)
	}
}

func TestCheckinSameOrEarlierHeightPanics(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	checkin(alice, 100)

	defer func() {
		if r := recover(); r == nil {
			t.Fatal("expected panic checking in at a non-later height")
		}
	}()
	checkin(alice, 100)
}

func TestProjectReportsLapsedWithoutMutating(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	checkin(alice, 100)

	r, _ := get(alice)
	current, alive := project(r, 100+graceBlocks+1)
	if alive || current != 0 {
		t.Fatalf("expected lapsed projection (0, false), got (%d, %v)", current, alive)
	}
	// Stored state must be untouched by a read-only projection.
	if r.current != 1 {
		t.Fatalf("project must not mutate stored state, got current=%d", r.current)
	}
}

func TestCurrentStreakAndLongestStreakQueries(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	checkin(alice, 100)
	checkin(alice, 150)

	if got := LongestStreak(alice.String()); got != 2 {
		t.Fatalf("LongestStreak() = %d, want 2", got)
	}
	if got := LongestStreak(testutils.TestAddress("bob").String()); got != 0 {
		t.Fatalf("LongestStreak() for unknown address = %d, want 0", got)
	}
}

func TestRenderShowsEmptyThenLeaderboardThenDetail(t *testing.T) {
	resetState()
	if !strings.Contains(Render(""), "Nobody has checked in yet") {
		t.Fatal("expected empty-state placeholder")
	}

	alice := testutils.TestAddress("alice")
	checkin(alice, 100)

	out := Render("")
	if !strings.Contains(out, "Rank") {
		t.Fatal("expected leaderboard table in root render")
	}

	detail := Render(alice.String())
	if !strings.Contains(detail, "Current streak") {
		t.Fatal("expected detail card to show current streak")
	}

	if !strings.Contains(Render(testutils.TestAddress("bob").String()), "No check-ins yet") {
		t.Fatal("expected placeholder for an address with no check-ins")
	}
}

// TestCheckInViaCrossingCall smoke-tests the exported, realm-crossing entry
// point end to end (as an on-chain caller would invoke it).
func TestCheckInViaCrossingCall(cur realm, t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	msg := CheckIn(cross(cur))
	if !strings.Contains(msg, "checked in") {
		t.Fatalf("expected check-in confirmation, got %q", msg)
	}
	if _, ok := get(alice); !ok {
		t.Fatal("expected a record to be persisted for caller")
	}
}

// Package tamagotchi is an on-chain virtual pet. Hatch one, then keep it
// alive by Feeding, Playing and letting it Sleep — hunger, happiness and
// energy all decay with block height, and neglect too long kills the pet.
// Hatching again after a death starts a fresh pet but keeps your lifetime
// stats, so the leaderboard rewards long-term care, not just luck.
package tamagotchi

import (
	"sort"
	"strconv"

	"chain/runtime"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/nt/avl/v0"
)

// pet is the persisted record for one owner's tamagotchi.
type pet struct {
	owner      address
	name       string
	born       int64
	lastUpdate int64
	hunger     int // 0 (full) .. 100 (starving)
	happiness  int // 0 (miserable) .. 100 (joyful)
	energy     int // 0 (exhausted) .. 100 (energetic)
	alive      bool
	deaths     int
	feeds      int
	plays      int
}

var pets avl.Tree // owner address string -> *pet

func clamp(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

func get(owner address) (*pet, bool) {
	v := pets.Get(owner.String())
	if v == nil {
		return nil, false
	}
	return v.(*pet), true
}

// tick applies stat decay for blocks elapsed since the pet's last update and
// kills it if any stat has bottomed/topped out. Mutates and persists.
func (p *pet) tick(height int64) {
	if !p.alive {
		return
	}
	elapsed := int(height - p.lastUpdate)
	if elapsed <= 0 {
		return
	}
	p.hunger = clamp(p.hunger+elapsed, 0, 100)
	p.happiness = clamp(p.happiness-elapsed/2, 0, 100)
	p.energy = clamp(p.energy-elapsed/3, 0, 100)
	p.lastUpdate = height
	if p.hunger >= 100 || p.happiness <= 0 || p.energy <= 0 {
		p.alive = false
		p.deaths++
	}
}

// project computes display stats as of height without mutating the pet, so
// Render can show a live-looking view without writing state on a query.
func project(p *pet, height int64) (hunger, happiness, energy int, alive bool) {
	if !p.alive {
		return p.hunger, p.happiness, p.energy, false
	}
	elapsed := int(height - p.lastUpdate)
	if elapsed < 0 {
		elapsed = 0
	}
	hunger = clamp(p.hunger+elapsed, 0, 100)
	happiness = clamp(p.happiness-elapsed/2, 0, 100)
	energy = clamp(p.energy-elapsed/3, 0, 100)
	alive = hunger < 100 && happiness > 0 && energy > 0
	return
}

func ageStageName(born, height int64) string {
	switch age := height - born; {
	case age < 10:
		return "🥚 Egg"
	case age < 50:
		return "🐣 Baby"
	case age < 200:
		return "🐤 Teen"
	default:
		return "🐓 Adult"
	}
}

// requireLivingPet ticks and fetches the caller's pet, panicking with a
// friendly message if there is none or it has died.
func requireLivingPet(owner address, height int64) *pet {
	p, ok := get(owner)
	if !ok {
		panic("you don't have a pet yet — call Hatch(name) first")
	}
	p.tick(height)
	if !p.alive {
		panic(p.name + " has died of neglect. Call Hatch(name) to start over.")
	}
	return p
}

// hatch is the non-crossing core of Hatch, kept separate so unit tests can
// exercise its panics directly without going through a realm-crossing call.
func hatch(owner address, name string, height int64) string {
	if name == "" {
		panic("name cannot be empty")
	}

	deaths, feeds, plays := 0, 0, 0
	if existing, ok := get(owner); ok {
		if existing.alive {
			existing.tick(height)
		}
		if existing.alive {
			panic("you already have a living pet: " + existing.name)
		}
		deaths, feeds, plays = existing.deaths, existing.feeds, existing.plays
	}

	pets.Set(owner.String(), &pet{
		owner:      owner,
		name:       name,
		born:       height,
		lastUpdate: height,
		hunger:     20,
		happiness:  80,
		energy:     80,
		alive:      true,
		deaths:     deaths,
		feeds:      feeds,
		plays:      plays,
	})
	return "🥚 " + name + " has hatched!"
}

// Hatch creates a new pet for the caller. Lifetime feeds/plays/deaths carry
// over from any previous pet so the leaderboard tracks long-term care.
func Hatch(cur realm, name string) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return hatch(cur.Previous().Address(), name, runtime.ChainHeight())
}

// feed is the non-crossing core of Feed.
func feed(owner address, height int64) string {
	p := requireLivingPet(owner, height)
	p.hunger = clamp(p.hunger-30, 0, 100)
	p.energy = clamp(p.energy+5, 0, 100)
	p.feeds++
	return p.name + " munches happily. Hunger: " + strconv.Itoa(p.hunger) + "/100"
}

// Feed reduces hunger and gives a small energy boost.
func Feed(cur realm) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return feed(cur.Previous().Address(), runtime.ChainHeight())
}

// play is the non-crossing core of Play.
func play(owner address, height int64) string {
	p := requireLivingPet(owner, height)
	if p.energy < 10 {
		return p.name + " is too tired to play — try Sleep() first."
	}
	p.happiness = clamp(p.happiness+20, 0, 100)
	p.energy = clamp(p.energy-10, 0, 100)
	p.hunger = clamp(p.hunger+5, 0, 100)
	p.plays++
	return p.name + " had a blast! Happiness: " + strconv.Itoa(p.happiness) + "/100"
}

// Play boosts happiness at the cost of energy and a bit of hunger. Refuses
// to run a tired pet into the ground — rest first.
func Play(cur realm) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return play(cur.Previous().Address(), runtime.ChainHeight())
}

// sleep is the non-crossing core of Sleep.
func sleep(owner address, height int64) string {
	p := requireLivingPet(owner, height)
	p.energy = clamp(p.energy+40, 0, 100)
	p.hunger = clamp(p.hunger+5, 0, 100)
	return p.name + " takes a nap. Energy: " + strconv.Itoa(p.energy) + "/100"
}

// Sleep restores energy at the cost of a little hunger.
func Sleep(cur realm) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	return sleep(cur.Previous().Address(), runtime.ChainHeight())
}

// byAliveThenOwner ranks living pets before dead ones, then orders each
// group by owner address so the leaderboard is fully deterministic.
type byAliveThenOwner []*pet

func (r byAliveThenOwner) Len() int      { return len(r) }
func (r byAliveThenOwner) Swap(i, j int) { r[i], r[j] = r[j], r[i] }
func (r byAliveThenOwner) Less(i, j int) bool {
	if r[i].alive != r[j].alive {
		return r[i].alive
	}
	return r[i].owner.String() < r[j].owner.String()
}

func bar(v int) string {
	filled := v / 10
	out := ""
	for i := 0; i < 10; i++ {
		if i < filled {
			out += "█"
		} else {
			out += "░"
		}
	}
	return out
}

func renderCard(p *pet, height int64) string {
	hunger, happiness, energy, alive := project(p, height)
	out := "## " + p.name + " — owned by " + ui.Addr(p.owner) + "\n\n"
	if !alive {
		out += "💀 **Deceased.** Owner can `Hatch(name)` a new pet.\n\n"
		return out
	}
	out += ageStageName(p.born, height) + " · age **" + strconv.Itoa(int(height-p.born)) + "** blocks\n\n"
	out += "- Hunger:    " + bar(100-hunger) + " (" + strconv.Itoa(hunger) + "/100 — lower is better)\n"
	out += "- Happiness: " + bar(happiness) + " (" + strconv.Itoa(happiness) + "/100)\n"
	out += "- Energy:    " + bar(energy) + " (" + strconv.Itoa(energy) + "/100)\n\n"
	return out
}

// Render shows either every pet ever hatched (path == "") or a single pet's
// detail card when path is a bech32 owner address.
func Render(path string) string {
	height := runtime.ChainHeight()

	out := "# 🐣 Tamagotchi\n\n"
	out += "A tiny on-chain pet. `Hatch(\"name\")` to start, then keep it alive with " +
		"`Feed()`, `Play()` and `Sleep()` — stats decay every block, so neglect kills it.\n\n"

	if path != "" {
		owner := address(path)
		p, ok := get(owner)
		if !ok {
			return out + "_No pet found for `" + path + "`._\n"
		}
		return out + renderCard(p, height)
	}

	var rows []*pet
	pets.Iterate("", "", func(_ string, v any) bool {
		rows = append(rows, v.(*pet))
		return false
	})
	if len(rows) == 0 {
		out += "_No pets hatched yet. Be the first!_\n"
		return out
	}
	sort.Stable(byAliveThenOwner(rows))

	out += "| Pet | Owner | Status | Feeds | Plays | Deaths |\n"
	out += "| :--- | :--- | :--- | ---: | ---: | ---: |\n"
	for _, p := range rows {
		_, _, _, alive := project(p, height)
		status := "🐤 alive"
		if !alive {
			status = "💀 dead"
		}
		out += "| " + p.name + " | " + ui.Addr(p.owner) + " | " + status +
			" | " + strconv.Itoa(p.feeds) + " | " + strconv.Itoa(p.plays) +
			" | " + strconv.Itoa(p.deaths) + " |\n"
	}
	out += "\n_View a single pet at `?<owner-address>`._\n"
	return out
}

package tamagotchi

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
)

func resetState() {
	pets = avl.Tree{}
}

func TestClamp(t *testing.T) {
	if clamp(150, 0, 100) != 100 {
		t.Fatal("clamp should cap at hi")
	}
	if clamp(-5, 0, 100) != 0 {
		t.Fatal("clamp should floor at lo")
	}
	if clamp(50, 0, 100) != 50 {
		t.Fatal("clamp should pass through in-range values")
	}
}

func TestHatchCreatesLivingPet(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")

	hatch(alice, "Fluffy", 100)

	p, ok := get(alice)
	if !ok || !p.alive {
		t.Fatal("expected a living pet after hatch")
	}
	if p.name != "Fluffy" {
		t.Fatalf("expected name Fluffy, got %s", p.name)
	}
}

func TestHatchTwiceWhileAlivePanics(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	hatch(alice, "Fluffy", 100)

	defer func() {
		if r := recover(); r == nil {
			t.Fatal("expected panic hatching a second living pet")
		}
	}()
	hatch(alice, "Again", 101)
}

func TestHatchAfterDeathKeepsLifetimeStats(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	hatch(alice, "Fluffy", 0)
	feed(alice, 0)

	p, _ := get(alice)
	p.alive = false
	p.deaths = 1

	hatch(alice, "Fluffy2", 10)

	p, _ = get(alice)
	if p.feeds != 1 || p.deaths != 1 {
		t.Fatalf("expected lifetime stats to carry over, got feeds=%d deaths=%d", p.feeds, p.deaths)
	}
	if !p.alive {
		t.Fatal("expected the new pet to be alive")
	}
}

func TestFeedReducesHunger(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	hatch(alice, "Fluffy", 100)

	p, _ := get(alice)
	p.hunger = 60

	feed(alice, 100)
	if p.hunger != 30 {
		t.Fatalf("expected hunger 30 after feed, got %d", p.hunger)
	}
	if p.feeds != 1 {
		t.Fatalf("expected feeds counter to increment, got %d", p.feeds)
	}
}

func TestPlayRefusesWhenTooTired(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	hatch(alice, "Fluffy", 100)

	p, _ := get(alice)
	p.energy = 5

	out := play(alice, 100)
	if !strings.Contains(out, "too tired") {
		t.Fatalf("expected too-tired message, got %q", out)
	}
	if p.plays != 0 {
		t.Fatal("play should not have counted while too tired")
	}
}

func TestNeglectKillsPet(t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	hatch(alice, "Fluffy", 0)

	defer func() {
		if r := recover(); r == nil {
			t.Fatal("expected panic acting on a neglected/dead pet")
		}
	}()
	// Feed re-ticks against a much later height, starving the pet to death.
	feed(alice, 1000)
}

func TestFeedWithoutPetPanics(t *testing.T) {
	resetState()
	bob := testutils.TestAddress("bob")

	defer func() {
		if r := recover(); r == nil {
			t.Fatal("expected panic feeding without a pet")
		}
	}()
	feed(bob, 100)
}

func TestRenderShowsEmptyThenPet(t *testing.T) {
	resetState()
	if !strings.Contains(Render(""), "No pets hatched yet") {
		t.Fatal("expected empty-state placeholder")
	}

	alice := testutils.TestAddress("alice")
	hatch(alice, "Fluffy", 100)

	out := Render("")
	if !strings.Contains(out, "Fluffy") {
		t.Fatal("expected pet name in leaderboard render")
	}

	detail := Render(alice.String())
	if !strings.Contains(detail, "Hunger") {
		t.Fatal("expected detail card to show hunger stat")
	}
}

// TestHatchViaCrossingCall smoke-tests the exported, realm-crossing entry
// point end to end (as an on-chain caller would invoke it).
func TestHatchViaCrossingCall(cur realm, t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	msg := Hatch(cross(cur), "Fluffy")
	if !strings.Contains(msg, "hatched") {
		t.Fatalf("expected hatch confirmation, got %q", msg)
	}
	if _, ok := get(alice); !ok {
		t.Fatal("expected pet to be persisted for caller")
	}
}

// Package tipjar is a public tip jar. Anyone can send real ugnot with an
// optional message via Tip; the realm keeps a running leaderboard of the
// most generous tippers and a feed of the most recent tips, both shown in
// Render. Only the deployer (captured as owner at init time) can Withdraw
// the accumulated balance. State-mutating functions are crossing functions
// (`cur realm`) per the gno 0.9 interrealm convention.
package tipjar

import (
	"sort"
	"strconv"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/nt/avl/v0"
)

const (
	denom         = "ugnot"
	maxRecent     = 10
	maxMessageLen = 140
)

// tipperStats is the persisted, accumulated record for one tipper.
type tipperStats struct {
	addr        address
	total       int64
	count       int
	lastMessage string
	lastHeight  int64
}

// tipEntry is one line in the recent-tips feed.
type tipEntry struct {
	from    address
	amount  int64
	message string
	height  int64
}

var (
	owner address // captured deployer, set once in init

	tippers avl.Tree // address string -> *tipperStats
	recent  []tipEntry

	totalReceived int64
	withdrawn     int64
	tipCount      int
)

func init() {
	owner = unsafe.OriginCaller()
}

// get returns the stored *tipperStats for addr, creating one if absent.
func get(addr address) *tipperStats {
	key := addr.String()
	if v := tippers.Get(key); v != nil {
		return v.(*tipperStats)
	}
	ts := &tipperStats{addr: addr}
	tippers.Set(key, ts)
	return ts
}

// Tip credits the caller's OriginSend ugnot to the jar and records it
// against their running total. Only an EOA calling directly via MsgCall may
// tip — see the payment-guard note on IsUserCall vs IsUser.
func Tip(cur realm, message string) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("only an EOA via MsgCall can tip")
	}
	if len(message) > maxMessageLen {
		panic("message too long (max " + strconv.Itoa(maxMessageLen) + " chars)")
	}

	amount := unsafe.OriginSend().AmountOf(denom)
	if amount <= 0 {
		panic("send some ugnot to tip")
	}

	from := prev.Address()
	height := runtime.ChainHeight()

	ts := get(from)
	ts.total += amount
	ts.count++
	ts.lastMessage = message
	ts.lastHeight = height

	totalReceived += amount
	tipCount++

	recent = append(recent, tipEntry{from: from, amount: amount, message: message, height: height})
	if len(recent) > maxRecent {
		recent = recent[len(recent)-maxRecent:]
	}

	chain.Emit("Tip", "from", from.String(), "amount", strconv.FormatInt(amount, 10), "message", message)
	return "thanks for the " + strconv.FormatInt(amount, 10) + "ugnot tip!"
}

// Balance reports the ugnot still held by the jar (received minus withdrawn).
func Balance() int64 {
	return totalReceived - withdrawn
}

// Withdraw sends amount ugnot from the jar to the owner. Owner-only.
func Withdraw(cur realm, amount int64) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if cur.Previous().Address() != owner {
		panic("only the owner can withdraw")
	}
	if amount <= 0 {
		panic("amount must be positive")
	}
	if amount > Balance() {
		panic("amount exceeds available balance")
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), owner, chain.NewCoins(chain.NewCoin(denom, amount)))
	withdrawn += amount

	chain.Emit("Withdraw", "amount", strconv.FormatInt(amount, 10))
}

// byTotal implements sort.Interface, ranking tippers by total tipped
// descending, ties broken by tip count then address for a fully
// deterministic order.
type byTotal struct {
	stats []*tipperStats
}

func (b byTotal) Len() int      { return len(b.stats) }
func (b byTotal) Swap(i, j int) { b.stats[i], b.stats[j] = b.stats[j], b.stats[i] }
func (b byTotal) Less(i, j int) bool {
	if b.stats[i].total != b.stats[j].total {
		return b.stats[i].total > b.stats[j].total
	}
	if b.stats[i].count != b.stats[j].count {
		return b.stats[i].count > b.stats[j].count
	}
	return b.stats[i].addr.String() < b.stats[j].addr.String()
}

// leaderboard collects all tippers ranked by total tipped descending.
func leaderboard() []*tipperStats {
	stats := make([]*tipperStats, 0, tippers.Size())
	tippers.Iterate("", "", func(_ string, v any) bool {
		stats = append(stats, v.(*tipperStats))
		return false
	})
	sort.Stable(byTotal{stats: stats})
	return stats
}

// display returns a shortened address for table display.
func display(addr address) string {
	s := addr.String()
	if len(s) > 12 {
		return s[:8] + "…" + s[len(s)-4:]
	}
	return s
}

// Render shows the jar's balance, the tipper leaderboard, and a feed of the
// most recent tips.
func Render(path string) string {
	out := "# 🫙 Tip Jar\n\n"
	out += "Send ugnot with `Tip(message)` to leave a tip and a note. " +
		"The owner can withdraw the accumulated balance with `Withdraw(amount)`.\n\n"

	out += "**Balance:** " + strconv.FormatInt(Balance(), 10) + "ugnot" +
		"  ·  **Total tips:** " + strconv.Itoa(tipCount) +
		"  ·  **All-time received:** " + strconv.FormatInt(totalReceived, 10) + "ugnot\n\n"

	stats := leaderboard()
	out += "## Leaderboard\n\n"
	if len(stats) == 0 {
		out += "_No tips yet. Be the first!_\n\n"
	} else {
		out += "| Rank | Tipper | Total tipped | Tips |\n"
		out += "| ---: | :--- | ---: | ---: |\n"
		for i, ts := range stats {
			rankCell := ui.Podium(i)
			if rankCell == "" {
				rankCell = strconv.Itoa(i + 1)
			}
			out += "| " + rankCell +
				" | " + display(ts.addr) +
				" | " + strconv.FormatInt(ts.total, 10) + "ugnot" +
				" | " + strconv.Itoa(ts.count) + " |\n"
		}
		out += "\n"
	}

	out += "## Recent tips\n\n"
	if len(recent) == 0 {
		out += "_Nothing yet._\n"
		return out
	}
	for i := len(recent) - 1; i >= 0; i-- {
		e := recent[i]
		out += "- **" + display(e.from) + "** tipped " + strconv.FormatInt(e.amount, 10) +
			"ugnot at block " + strconv.FormatInt(e.height, 10)
		if e.message != "" {
			out += ": _" + e.message + "_"
		}
		out += "\n"
	}
	return out
}

package tipjar

import (
	"strings"
	"testing"

	"chain"
	"chain/banker"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
)

var realmAddr = chain.PackageAddress("gno.land/r/moul/x/daily/tipjar/v1")

// reset clears package globals between tests, pinning owner to a known test
// address rather than whatever init() captured from the test harness.
func reset() {
	owner = testutils.TestAddress("owner")
	tippers = avl.Tree{}
	recent = nil
	totalReceived = 0
	withdrawn = 0
	tipCount = 0
}

// fund simulates a tipper sending `amount` ugnot alongside the tx: the
// runtime deposits it at the realm's address first, then unsafe.OriginSend
// reports it to the crossing function. SetRealm is call-frame scoped (see
// build.md), so the caller must still SetRealm directly before crossing.
func fund(amount int64) {
	testing.IssueCoins(realmAddr, chain.Coins{{denom, amount}})
	testing.SetOriginSend(chain.Coins{{denom, amount}})
}

func TestTipCreditsAndTracks(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")

	fund(500)
	testing.SetRealm(testing.NewUserRealm(alice))
	Tip(cross(cur), "gm")

	if got := Balance(); got != 500 {
		t.Fatalf("Balance() = %d, want 500", got)
	}
	if tipCount != 1 {
		t.Fatalf("tipCount = %d, want 1", tipCount)
	}
	ts := get(alice)
	if ts.total != 500 || ts.count != 1 || ts.lastMessage != "gm" {
		t.Fatalf("unexpected tipper stats: %+v", ts)
	}

	fund(250)
	testing.SetRealm(testing.NewUserRealm(alice))
	Tip(cross(cur), "again")
	if got := get(alice).total; got != 750 {
		t.Fatalf("cumulative total = %d, want 750", got)
	}
	if got := Balance(); got != 750 {
		t.Fatalf("Balance() after second tip = %d, want 750", got)
	}
}

func TestTipRejectsZeroAmount(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	rec := revive(func() { Tip(cross(cur), "freeloading") })
	if rec == nil {
		t.Fatal("expected panic when tipping with no ugnot sent")
	}
}

func TestTipRejectsNonUserCall(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/g1attacker/relay"))

	rec := revive(func() { Tip(cross(cur), "sneaky") })
	if rec == nil {
		t.Fatal("expected panic when the caller isn't an EOA via MsgCall")
	}
}

func TestWithdrawOwnerOnly(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	mallory := testutils.TestAddress("mallory")

	fund(1000)
	testing.SetRealm(testing.NewUserRealm(alice))
	Tip(cross(cur), "for the jar")

	testing.SetRealm(testing.NewUserRealm(mallory))
	rec := revive(func() { Withdraw(cross(cur), 100) })
	if rec == nil {
		t.Fatal("expected panic when a non-owner withdraws")
	}

	testing.SetRealm(testing.NewUserRealm(owner))
	Withdraw(cross(cur), 400)

	if got := Balance(); got != 600 {
		t.Fatalf("Balance() after withdraw = %d, want 600", got)
	}
	ro := banker.NewReadonlyBanker()
	if got := ro.GetCoins(owner).AmountOf(denom); got != 400 {
		t.Fatalf("owner received = %d, want 400", got)
	}

	rec = revive(func() { Withdraw(cross(cur), 10000) })
	if rec == nil {
		t.Fatal("expected panic when withdrawing more than the balance")
	}
}

func TestRenderShowsLeaderboardAndFeed(cur realm, t *testing.T) {
	reset()
	if !strings.Contains(Render(""), "No tips yet") {
		t.Fatal("expected empty-jar placeholder")
	}

	alice := testutils.TestAddress("alice")
	fund(300)
	testing.SetRealm(testing.NewUserRealm(alice))
	Tip(cross(cur), "nice work")

	out := Render("")
	if !strings.Contains(out, "Leaderboard") {
		t.Fatal("expected leaderboard section")
	}
	if !strings.Contains(out, "nice work") {
		t.Fatal("expected the tip message in the recent-tips feed")
	}
}

// Package urlshort is a simple on-chain URL alias registry.
//
// Callers register an `alias -> url` mapping they own. An alias can only be
// claimed once; the owner may later update the target URL, but nobody else can
// overwrite an alias they do not own. A per-alias click counter is bumped every
// time the alias is resolved through Render("/<alias>").
package urlshort

import (
	"strings"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/nt/avl/v0"
)

// entry is the persisted record for a single alias.
type entry struct {
	url    string
	owner  address
	note   string
	clicks int
}

// aliases maps alias (string) -> *entry, kept in an avl.Tree for deterministic
// iteration order in Render.
var aliases avl.Tree

// isAlphanumeric reports whether s is non-empty and made only of [0-9A-Za-z].
func isAlphanumeric(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		switch {
		case c >= '0' && c <= '9':
		case c >= 'a' && c <= 'z':
		case c >= 'A' && c <= 'Z':
		default:
			return false
		}
	}
	return true
}

// Shorten registers `alias -> url` owned by the caller.
//
// Rules:
//   - alias must be non-empty and alphanumeric;
//   - url must be non-empty;
//   - if the alias is unclaimed, it is created owned by the caller;
//   - if it is already claimed by the caller, the url/note are updated;
//   - if it is claimed by someone else, the call aborts.
func Shorten(cur realm, alias string, url string, note string) {
	if !isAlphanumeric(alias) {
		panic("alias must be non-empty and alphanumeric")
	}
	if url == "" {
		panic("url must be non-empty")
	}

	caller := unsafe.PreviousRealm().Address()

	if v := aliases.Get(alias); v != nil {
		e := v.(*entry)
		if e.owner != caller {
			panic("alias already taken by another owner")
		}
		e.url = url
		e.note = note
		chain.Emit("AliasUpdated", "alias", alias, "owner", caller.String())
		return
	}

	e := &entry{url: url, owner: caller, note: note, clicks: 0}
	aliases.Set(alias, e)
	chain.Emit("AliasCreated", "alias", alias, "owner", caller.String())
}

// Remove deletes an alias owned by the caller. Aborts if the alias does not
// exist or the caller is not the owner.
func Remove(cur realm, alias string) {
	v := aliases.Get(alias)
	if v == nil {
		panic("alias not found")
	}
	e := v.(*entry)
	caller := unsafe.PreviousRealm().Address()
	if e.owner != caller {
		panic("only the owner can remove an alias")
	}
	aliases.Remove(alias)
	chain.Emit("AliasRemoved", "alias", alias, "owner", caller.String())
}

// Lookup returns the target url for an alias and whether it exists. It is a
// read-only helper and does NOT increment the click counter.
func Lookup(alias string) (string, bool) {
	v := aliases.Get(alias)
	if v == nil {
		return "", false
	}
	return v.(*entry).url, true
}

// Render renders Markdown. The root path lists every alias; "/<alias>" shows a
// single alias detail and bumps its click counter.
func Render(path string) string {
	if path == "" || path == "/" {
		return renderIndex()
	}

	alias := strings.TrimPrefix(path, "/")
	v := aliases.Get(alias)
	if v == nil {
		return "# URL Shortener\n\nNo alias named `" + alias + "`.\n\n[← all aliases](/)\n"
	}

	e := v.(*entry)
	e.clicks++

	var b strings.Builder
	b.WriteString("# 🔗 " + alias + "\n\n")
	b.WriteString("**Target:** <" + e.url + ">\n\n")
	b.WriteString("**Owner:** " + e.owner.String() + "\n\n")
	if e.note != "" {
		b.WriteString("**Note:** " + e.note + "\n\n")
	}
	b.WriteString("**Clicks:** " + itoa(e.clicks) + "\n\n")
	b.WriteString("[← all aliases](/)\n")
	return b.String()
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# 🔗 URL Shortener\n\n")

	if aliases.Size() == 0 {
		b.WriteString("_No aliases registered yet._\n\n")
		b.WriteString("Call `Shorten(alias, url, note)` to register one.\n")
		return b.String()
	}

	b.WriteString("| Alias | Target | Owner | Clicks |\n")
	b.WriteString("|-------|--------|-------|--------|\n")
	aliases.Iterate("", "", func(key string, value interface{}) bool {
		e := value.(*entry)
		b.WriteString("| [" + key + "](/" + key + ") | <" + e.url + "> | " +
			ui.Addr(e.owner) + " | " + itoa(e.clicks) + " |\n")
		return false
	})
	b.WriteString("\nTotal aliases: " + itoa(aliases.Size()) + "\n")
	return b.String()
}

// itoa converts a non-negative int to its decimal string without importing
// strconv (kept minimal & deterministic).
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

package urlshort

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestIsAlphanumeric(t *testing.T) {
	cases := []struct {
		in   string
		want bool
	}{
		{"", false},
		{"abc", true},
		{"ABC123", true},
		{"a b", false},
		{"a-b", false},
		{"under_score", false},
		{"9", true},
	}
	for _, c := range cases {
		if got := isAlphanumeric(c.in); got != c.want {
			t.Errorf("isAlphanumeric(%q) = %v, want %v", c.in, got, c.want)
		}
	}
}

func TestItoa(t *testing.T) {
	cases := []struct {
		in   int
		want string
	}{
		{0, "0"},
		{7, "7"},
		{42, "42"},
		{1000, "1000"},
	}
	for _, c := range cases {
		if got := itoa(c.in); got != c.want {
			t.Errorf("itoa(%d) = %q, want %q", c.in, got, c.want)
		}
	}
}

func TestShortenAndRender(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	Shorten(cross(cur), "gno", "https://gno.land", "the chain")

	url, ok := Lookup("gno")
	uassert.True(t, ok, "alias should exist")
	uassert.Equal(t, "https://gno.land", url)

	// Detail render bumps the click counter.
	out := Render("/gno")
	uassert.True(t, strings.Contains(out, "https://gno.land"), "detail shows url")
	uassert.True(t, strings.Contains(out, "Clicks:** 1"), "click counted")

	// Index lists the alias.
	idx := Render("/")
	uassert.True(t, strings.Contains(idx, "[gno](/gno)"), "index lists alias")
}

func TestShortenOwnershipRules(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice2")
	bob := testutils.TestAddress("bob2")

	testing.SetRealm(testing.NewUserRealm(alice))
	Shorten(cross(cur), "mine", "https://a.example", "")

	// Bob cannot overwrite alice's alias.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "alias already taken by another owner", func() {
		Shorten(cross(cur), "mine", "https://b.example", "")
	})

	// Alice can update her own.
	testing.SetRealm(testing.NewUserRealm(alice))
	Shorten(cross(cur), "mine", "https://a2.example", "updated")
	url, _ := Lookup("mine")
	uassert.Equal(t, "https://a2.example", url)

	// Invalid alias aborts.
	uassert.AbortsWithMessage(t, cur, "alias must be non-empty and alphanumeric", func() {
		Shorten(cross(cur), "bad alias", "https://x.example", "")
	})

	// Empty url aborts.
	uassert.AbortsWithMessage(t, cur, "url must be non-empty", func() {
		Shorten(cross(cur), "okalias", "", "")
	})
}

func TestRemoveRules(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice3")
	bob := testutils.TestAddress("bob3")

	testing.SetRealm(testing.NewUserRealm(alice))
	Shorten(cross(cur), "rm", "https://rm.example", "")

	// Bob cannot remove alice's alias.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsWithMessage(t, cur, "only the owner can remove an alias", func() {
		Remove(cross(cur), "rm")
	})

	// Alice removes her own.
	testing.SetRealm(testing.NewUserRealm(alice))
	Remove(cross(cur), "rm")
	_, ok := Lookup("rm")
	uassert.False(t, ok, "alias should be gone")
}

// Package grc20faucet issues two free GRC20 tokens, RED and BLUE, and gives
// them away on request.
//
// It exists so that anything needing a token to experiment on has one that is
// worthless, unlimited and shared. Both tokens are registered in
// gno.land/r/nt/grc20reg/v0, which is what lets another realm find and move
// them by key without importing this package: that indirection is the whole
// point, and it is what gno.land/r/moul/x/grc20wrapdemo/v0 wraps.
//
// Two tokens rather than one, because the interesting patterns start at two: a
// meta-token over a pair needs a pair.
package grc20faucet

import (
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// Tokens are exported so an importing realm can read them directly; the
// ledgers stay private, since they carry unrestricted mint and burn.
var (
	Red  *grc20.Token
	Blue *grc20.Token

	redLedger  *grc20.PrivateLedger
	blueLedger *grc20.PrivateLedger

	// RedKey and BlueKey are the grc20reg lookup keys, the way a realm that
	// does NOT import this package refers to these tokens.
	RedKey  string
	BlueKey string

	lastClaim = avl.NewTree() // address -> block height of its last claim
)

const (
	decimals = 4

	// ClaimAmount is minted of EACH token per claim: 100.0000 units.
	ClaimAmount = int64(1_000_000)

	// ClaimEvery is the cooldown, in blocks, between two claims by the same
	// account. Free money with no cooldown is a spam vector, not a faucet.
	ClaimEvery = int64(100)
)

func init(cur realm) {
	Red, redLedger = grc20.NewToken("Red Token", "RED", decimals, 0, cur)
	Blue, blueLedger = grc20.NewToken("Blue Token", "BLUE", decimals, 1, cur)
	RedKey = grc20reg.Register(cross(cur), Red, "red")
	BlueKey = grc20reg.Register(cross(cur), Blue, "blue")
}

// Claim mints ClaimAmount of both RED and BLUE to the caller.
func Claim(cur realm) {
	who := caller(cur)
	now := runtime.ChainHeight()
	if next, ok := NextClaim(who); ok && now < next {
		panic(ufmt.Sprintf("too soon: next claim at block %d, current %d", next, now))
	}
	lastClaim.Set(who.String(), now)
	checkErr(redLedger.Mint(who, ClaimAmount))
	checkErr(blueLedger.Mint(who, ClaimAmount))
}

// NextClaim returns the block height at which `who` may claim again, and
// whether they have ever claimed at all.
func NextClaim(who address) (int64, bool) {
	v := lastClaim.Get(who.String())
	if v == nil {
		return 0, false
	}
	return v.(int64) + ClaimEvery, true
}

// Transfer moves the caller's own units of `symbol`.
func Transfer(cur realm, symbol string, to address, amount int64) {
	checkErr(ledgerOf(symbol).CallerTeller().Transfer(0, cur, to, amount))
}

// Approve lets `spender` draw `amount` of `symbol` from the caller's balance.
//
// This is the call that makes every wrapper in grc20wrapdemo work: the wrapper
// realm has no authority over anybody's tokens until its address is named here.
func Approve(cur realm, symbol string, spender address, amount int64) {
	checkErr(ledgerOf(symbol).CallerTeller().Approve(0, cur, spender, amount))
}

// TransferFrom spends an allowance the caller was granted.
func TransferFrom(cur realm, symbol string, from, to address, amount int64) {
	checkErr(ledgerOf(symbol).CallerTeller().TransferFrom(0, cur, from, to, amount))
}

// BalanceOf returns `owner`'s balance of `symbol`.
func BalanceOf(symbol string, owner address) int64 {
	return tokenOf(symbol).BalanceOf(owner)
}

// Allowance returns what `owner` let `spender` draw of `symbol`.
func Allowance(symbol string, owner, spender address) int64 {
	return tokenOf(symbol).Allowance(owner, spender)
}

// TotalSupply returns how much of `symbol` has been claimed so far.
func TotalSupply(symbol string) int64 {
	return tokenOf(symbol).TotalSupply()
}

func tokenOf(symbol string) *grc20.Token {
	switch symbol {
	case "RED":
		return Red
	case "BLUE":
		return Blue
	}
	panic("unknown symbol " + symbol + " (RED or BLUE)")
}

func ledgerOf(symbol string) *grc20.PrivateLedger {
	switch symbol {
	case "RED":
		return redLedger
	case "BLUE":
		return blueLedger
	}
	panic("unknown symbol " + symbol + " (RED or BLUE)")
}

// caller is the account or realm that crossed into this one.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("grc20faucet: stale realm token")
	}
	return cur.Previous().Address()
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

func Render(path string) string {
	s := "# GRC20 faucet: RED and BLUE\n\n"
	s += "Two worthless tokens to experiment on. `Claim` gives you "
	s += ufmt.Sprintf("%d of each, once every %d blocks.\n\n", ClaimAmount, ClaimEvery)

	s += "| token | symbol | decimals | supply | registry key |\n"
	s += "|---|---|---|---|---|\n"
	s += ufmt.Sprintf("| %s | RED | %d | %d | `%s` |\n",
		Red.GetName(), Red.GetDecimals(), Red.TotalSupply(), RedKey)
	s += ufmt.Sprintf("| %s | BLUE | %d | %d | `%s` |\n",
		Blue.GetName(), Blue.GetDecimals(), Blue.TotalSupply(), BlueKey)

	s += "\n## Use it\n\n"
	s += "```\n"
	s += "gnokey maketx call -pkgpath gno.land/r/moul/x/grc20faucet/v0 -func Claim ...\n"
	s += "gnokey maketx call -pkgpath gno.land/r/moul/x/grc20faucet/v0 -func Approve \\\n"
	s += "  -args RED -args <spender> -args 1000000 ...\n"
	s += "```\n\n"
	s += "Both tokens are registered in [grc20reg](/r/nt/grc20reg/v0), so a realm can\n"
	s += "move them by key without importing this one. That is what\n"
	s += "[grc20wrapdemo](/r/moul/x/grc20wrapdemo/v0) does with them.\n"

	if path != "" {
		s += "\n---\n\n"
		s += ufmt.Sprintf("Balance of `%s`: RED %d, BLUE %d\n",
			path, Red.BalanceOf(address(path)), Blue.BalanceOf(address(path)))
	}
	return s
}

