package reaper

import (
	"strings"

	"gno.land/p/moul/x/storagecost/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Every Example in this file is a *query*, and that is a constraint rather
// than a choice: an example function takes no arguments, so it never receives
// a `cur realm` and can never call Post, Reap or Compact. What is left is
// exactly the surface a reader of the live realm has without a key, so each
// one carries the `vm/qeval` line that produces the same answer on chain:
//
//	gnokey query vm/qeval -remote https://rpc.gno.land \
//	  -data 'gno.land/r/moul/x/reaper/v0.<expr>'
//
// The board is empty by the time these run, because every Test in this
// package drains what it posted and examples run after all of them.

// ExampleRender pins the page's skeleton: the title, the two sections that are
// always present, and the footer crediting the two packages that own the parts
// this realm does not.
//
//	vm/qrender  gno.land/r/moul/x/reaper/v0:
//
// It deliberately prints only the invariant lines. Everything interesting on
// the page is priced from the current block height and the notes outstanding,
// and an Example runs after every Test in the package and sees whatever state
// they left. The variable half is pinned by TestRenderShowsTheBountyAndTheReapLink
// instead, which controls the board first.
func ExampleRender() {
	for _, line := range strings.Split(Render(""), "\n") {
		switch {
		case strings.HasPrefix(line, "# "),
			strings.HasPrefix(line, "## "),
			strings.HasPrefix(line, "A noticeboard"),
			strings.HasPrefix(line, "The arithmetic is"):
			print(line + "\n")
		}
	}
	// Output:
	// # Reaper
	// A noticeboard whose garbage is a standing bounty. Posting a note locks a storage deposit. Once the note expires, anyone can delete it and the chain refunds that deposit **to whoever signs the deleting transaction**.
	// ## On the table right now
	// ## Board
	// The arithmetic is [p/moul/x/storagecost](/p/moul/x/storagecost/v0); the storage is [p/moul/ulist](/p/moul/ulist/v1), whose `Compact` reclaims dead nodes without moving a live index. Byte figures on this page are estimates from payload length: no stdlib call exposes a realm's real locked storage.
}

// ExampleReapable is the poll a reaping bot runs before it spends anything:
// three counters, three queries, no key and no gas.
//
//	vm/qeval  gno.land/r/moul/x/reaper/v0.Live()
//	vm/qeval  gno.land/r/moul/x/reaper/v0.Reapable()
//	vm/qeval  gno.land/r/moul/x/reaper/v0.Compactable()
//
// Reapable and Compactable are separate numbers because reaping and
// compacting are separate transactions, and compaction returns nothing at all
// while a live note still sits below the dead ones. A bot that sees
// `reapable 0, compactable 0` should not sign anything, which is the answer
// here.
func ExampleReapable() {
	print(ufmt.Sprintf("live %d, reapable %d, compactable %d\n",
		Live(), Reapable(), Compactable()))
	// Output:
	// live 0, reapable 0, compactable 0
}

// ExampleBounty is the single query that decides whether reaping is worth
// doing, and on an empty board it has to refuse to advertise a profit.
//
//	vm/qeval  gno.land/r/moul/x/reaper/v0.Bounty().String()
//
// Fee is what the reaping transaction costs at the floor gas price, and the
// chain charges it whether or not anything is freed. BreakEven turns that fee
// back into bytes: free fewer than 50 and the reaper is paying to tidy up.
// That threshold, not the size of the board, is what makes the mechanism a
// market rather than a chore.
func ExampleBounty() {
	print(Bounty().String() + "\n")
	// Output:
	// 0 bytes, refunds 0 GNOT against 0.005 GNOT of gas, break-even 50 bytes: not worth it yet
}

// ExampleBounty_worth is the same query answered by a board worth draining:
// ten expired notes of a kilobyte each.
//
// It recomputes the quote instead of posting, because an example has no
// `cur realm` to post with. The arithmetic is the one Bounty applies, so the
// numbers are the ones the live query would return with that board on it.
//
// This is the whole concept in two lines. The poster locked 1.8944 GNOT to
// occupy that space; a stranger who never posted anything spends 0.005 GNOT of
// gas to delete it and the chain hands them the deposit. Nobody minted a
// token, and no pool was funded.
func ExampleBounty_worth() {
	q := storagecost.EvaluateAtFloor(storagecost.EstimateBytes(10*1024), gasWantedReap)
	print(q.String() + "\n")
	print(ufmt.Sprintf("the reaper is paid %dx what the transaction costs\n", q.Refund/q.Fee))
	// Output:
	// 18944 bytes, refunds 1.8944 GNOT against 0.005 GNOT of gas, break-even 50 bytes: worth 1.8894 GNOT
	// the reaper is paid 378x what the transaction costs
}

// Package reaper is a noticeboard whose garbage is a standing bounty.
//
// Anyone can post a note with an expiry. Posting locks a storage deposit, paid
// by the poster. Once a note expires, anyone at all can delete it, and the
// chain refunds that deposit to whoever signed the deleting transaction. So
// the poster pays to occupy space and a stranger is paid to reclaim it.
//
// Nothing here is a token, a reward pool or an emission schedule. The incentive
// is the chain's own storage accounting, which already works this way for every
// realm on gno.land; this realm only makes it legible. Reap and Compact are
// permissionless because the expiry predicate is checked on chain, so the
// worst a malicious reaper can do is waste their own gas.
//
// Two collaborators own the parts this realm does not:
//
//   - gno.land/p/moul/ulist/v1 stores the notes and owns compaction. Its
//     Delete is a soft delete that leaves a dead tree node behind, and its
//     Compact frees those nodes without moving any live index.
//   - gno.land/p/moul/x/storagecost/v0 owns the arithmetic: what a byte
//     refunds, and how many bytes a transaction must free to pay for itself.
//   - gno.land/p/moul/kit/ui/v0 owns display: the escaping, the length cap
//     and the address format. A note body is arbitrary bytes chosen by
//     whoever paid to post it and is rendered back to every reader, so it is
//     attacker-controlled input in a markdown slot. Render never emits a body
//     unescaped; ui.Excerpt is what makes that true, and it delegates to
//     p/nt/markdown/sanitize.
//
// The realm deliberately cannot see its own byte count. No stdlib call exposes
// a realm's locked storage, so every figure Render shows is an estimate from
// payload length. The authoritative numbers are the chain's, in the
// StorageDepositEvent and StorageUnlockEvent each transaction emits.
package reaper

import (
	"strings"

	"chain/runtime"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/ulist/v1"
	"gno.land/p/moul/x/storagecost/v0"
	"gno.land/p/nt/ufmt/v0"
)

// gasWantedReap is the gas ceiling a reaping transaction is assumed to ask
// for, used only to price the advertised bounty. It is the measured cost of a
// ten-note reap rounded up; a caller reaping more notes should re-price with
// storagecost.EvaluateAtFloor directly rather than trust this.
const gasWantedReap int64 = 5_000_000

// maxBody caps a note so one poster cannot lock an unbounded deposit in a
// single call, which would also make the gas cost of reaping it unpredictable.
const maxBody = 4096

// Note is one posting. Body is what costs storage; the rest is bookkeeping
// that makes the incentive visible in Render.
type Note struct {
	Body    string
	Author  address
	Posted  int64 // block height
	Expires int64 // block height; reapable once ChainHeight passes it
}

// notes is append-addressed: an index is stable for the life of the realm,
// which is what lets Compact reclaim dead nodes without renumbering.
var notes = ulist.New()

// Post adds a note that becomes reapable ttl blocks from now, and locks the
// storage deposit for it against the caller.
//
// A ttl of zero is allowed and makes the note reapable immediately, which is
// the cheapest way to demonstrate the mechanism.
func Post(cur realm, body string, ttl int64) int {
	if body == "" {
		panic("reaper: empty note")
	}
	if len(body) > maxBody {
		panic(ufmt.Sprintf("reaper: note too long, %d bytes against a %d cap", len(body), maxBody))
	}
	if ttl < 0 {
		panic("reaper: negative ttl")
	}
	height := runtime.ChainHeight()
	notes.Append(&Note{
		Body:    body,
		Author:  cur.Previous().Address(),
		Posted:  height,
		Expires: height + ttl,
	})
	return notes.TotalSize() - 1
}

// Reap deletes up to limit expired notes and returns how many it deleted.
//
// Permissionless by design. The storage deposit freed goes to whoever signed
// this transaction, so a stranger keeping the board tidy is paid for it out of
// the deposits the posters locked. A note that has not expired is skipped, not
// refused, so a reaper never has to guess which indices are ripe.
//
// It walks from the highest index down, which is not cosmetic. In the backing
// list the oldest indices are the ancestors of the newest, so a node can only
// be freed once everything below it is dead. Reaping oldest-first with a
// binding limit therefore never creates a dead tail and leaves Compactable at
// zero, stranding the tree structure, which measures at roughly two thirds of
// what an entry costs. Reaping newest-first makes each batch immediately
// compactable. Every candidate is expired either way, so the order changes
// only who gets paid how much, and it is measured: see the ulist package doc.
func Reap(cur realm, limit int) int {
	if limit <= 0 {
		panic("reaper: limit must be positive")
	}
	height := runtime.ChainHeight()
	reaped := 0
	for i := notes.TotalSize() - 1; i >= 0 && reaped < limit; i-- {
		n, ok := noteAt(i)
		if !ok || n.Expires > height {
			continue
		}
		notes.MustDelete(i)
		reaped++
	}
	return reaped
}

// Compact frees the tree nodes that reaping left behind and returns how many.
//
// Also permissionless, and also paid the same way. It is a separate call
// because it is a separate economic decision, and a surprisingly large one: on
// chain, compacting a drained board returned about three times what deleting
// the notes themselves did, because a list node costs more than the note it
// carries. But it returns nothing at all while any live note sits below the
// dead ones, so the two calls are worth batching in that order: reap, then
// compact. Compactable says how much is actually there, for free.
func Compact(cur realm) int {
	return notes.Compact()
}

// Reapable counts the notes that have expired and not yet been reaped.
func Reapable() int {
	height := runtime.ChainHeight()
	count := 0
	total := notes.TotalSize()
	for i := 0; i < total; i++ {
		n, ok := noteAt(i)
		if ok && n.Expires <= height {
			count++
		}
	}
	return count
}

// Compactable reports how many dead tree nodes a Compact would free.
func Compactable() int { return notes.Compactable() }

// Live counts the notes still holding storage.
func Live() int { return notes.Size() }

// Bounty prices what is currently on the table for a reaper, at the default
// storage price and the floor gas price.
//
// The byte figure is an estimate from payload length, never the chain's own
// accounting. Treat it as an advertisement, not a settlement.
func Bounty() storagecost.Quote {
	height := runtime.ChainHeight()
	var payload int64
	total := notes.TotalSize()
	for i := 0; i < total; i++ {
		n, ok := noteAt(i)
		if ok && n.Expires <= height {
			payload += int64(len(n.Body))
		}
	}
	return storagecost.EvaluateAtFloor(storagecost.EstimateBytes(payload), gasWantedReap)
}

// noteAt reads index i, reporting whether a live note is there. A reaped or
// compacted index reads as absent.
func noteAt(i int) (*Note, bool) {
	v := notes.Get(i)
	if v == nil {
		return nil, false
	}
	n, ok := v.(*Note)
	return n, ok
}

func Render(path string) string {
	var b strings.Builder

	b.WriteString(md.H1("Reaper"))
	b.WriteString("\nA noticeboard whose garbage is a standing bounty. Posting a note locks a storage deposit. Once the note expires, anyone can delete it and the chain refunds that deposit **to whoever signs the deleting transaction**.\n\n")

	quote := Bounty()
	b.WriteString(md.H2("On the table right now"))
	b.WriteString("\n")

	reapable := Reapable()
	if reapable == 0 {
		b.WriteString("Nothing has expired. Every note here is still paid for.\n\n")
	} else {
		b.WriteString(md.BulletList([]string{
			ufmt.Sprintf("**%d expired notes**, about %d bytes of state", reapable, quote.Bytes),
			ufmt.Sprintf("refunds roughly **%s** to the reaper", storagecost.FormatGNOT(quote.Refund)),
			ufmt.Sprintf("against **%s** of gas at the floor price, break-even at %d bytes", storagecost.FormatGNOT(quote.Fee), quote.BreakEven),
			ufmt.Sprintf("verdict: **%s**", verdictWord(quote)),
		}))
		b.WriteString("\n")
		b.WriteString(ui.Action("Reap them", "Reap", "limit", "100") + "\n\n")
	}

	if dead := Compactable(); dead > 0 {
		b.WriteString(md.H2("Compaction available"))
		b.WriteString(ufmt.Sprintf("\n%d dead tree nodes are reclaimable. Compacting frees fewer bytes per unit of gas than reaping does, so it is worth doing in batches.\n\n%s\n\n",
			dead, ui.Action("Compact", "Compact")))
	}

	b.WriteString(md.H2("Board"))
	b.WriteString("\n")
	if notes.Size() == 0 {
		b.WriteString("Empty. " + ui.Action("Post the first note", "Post", "body", "hello", "ttl", "0") + "\n\n")
	} else {
		height := runtime.ChainHeight()
		rows := []string{}
		total := notes.TotalSize()
		for i := 0; i < total; i++ {
			n, ok := noteAt(i)
			if !ok {
				continue
			}
			state := ufmt.Sprintf("expires at %d", n.Expires)
			if n.Expires <= height {
				state = "**reapable**"
			}
			rows = append(rows, ufmt.Sprintf("`#%d` %s | %d bytes by %s, %s",
				i, summarize(n.Body), len(n.Body), ui.Addr(n.Author), state))
		}
		b.WriteString(md.BulletList(rows))
		b.WriteString("\n")
	}

	b.WriteString(md.HorizontalRule())
	b.WriteString("\nThe arithmetic is [p/moul/x/storagecost](/p/moul/x/storagecost/v0); the storage is [p/moul/ulist](/p/moul/ulist/v1), whose `Compact` reclaims dead nodes without moving a live index. Byte figures on this page are estimates from payload length: no stdlib call exposes a realm's real locked storage.\n")

	return b.String()
}

func verdictWord(q storagecost.Quote) string {
	if q.Worth() {
		return "worth " + storagecost.FormatGNOT(q.Net)
	}
	return "not worth the gas yet"
}

// summarize is the board's one-line view of a note.
//
// A body is whatever bytes a poster paid to store, so on the board it is
// attacker-controlled input in an inline markdown slot. ui.Excerpt owns both
// halves of that: the rune-boundary cut and the escaping, in the order that is
// safe. This realm shipped a hand-rolled version that did neither, and the
// replacement for it is one call.
func summarize(body string) string {
	const width = 48
	// Cosmetic, not a defense: "|" is the column separator of the row this
	// lands in. The escaper deliberately leaves pipes literal, which is right,
	// since a lone pipe cannot open a GFM table with no delimiter row.
	return ui.Excerpt(strings.ReplaceAll(body, "|", " "), width)
}

package reaper

import (
	"strings"
	"testing"
	"unicode/utf8"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/x/storagecost/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	poster = testutils.TestAddress("poster")
	// stranger never posts, it only deletes. The whole point of the realm is
	// that this is the address the chain pays.
	stranger = testutils.TestAddress("stranger")
)

// ttlFuture is the ttl used for a note that must not be reapable yet. It is a
// named constant because clear has to outrun it.
const ttlFuture = 1000

// clear empties the board so a test starts from a known state, whatever ran
// before it.
//
// gno resets the block height for each test function but keeps realm state, so
// a test that left an unexpired note behind cannot be cleaned up by a later
// test skipping heights: the later test's clock starts over. Every test that
// posts a future-dated note therefore drains it before returning, and clear
// asserts an empty board rather than trusting that.
//
// clear cannot reset TotalSize, which is append-addressed for the life of the
// realm, so tests assert on Live and Reapable and never on absolute indices.
func clear(cur realm, t *testing.T) {
	t.Helper()
	drain(cur)
	uassert.Equal(t, 0, Live())
	uassert.Equal(t, 0, Reapable())
}

// drain expires everything outstanding and reaps it.
func drain(cur realm) {
	testing.SkipHeights(ttlFuture + 1)
	testing.SetRealm(testing.NewUserRealm(stranger))
	for Reapable() > 0 {
		Reap(cross(cur), 1000)
	}
	Compact(cross(cur))
}

func TestPostLocksAndReapFrees(cur realm, t *testing.T) {
	clear(cur, t)

	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), "first", 0)
	Post(cross(cur), "second", 0)
	uassert.Equal(t, 2, Live())
	uassert.Equal(t, 2, Reapable())

	// A stranger who posted nothing may reap, and that is the point.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 2, Reap(cross(cur), 100))
	uassert.Equal(t, 0, Live())
	uassert.Equal(t, 0, Reapable())
}

func TestReapSkipsUnexpiredAndHonoursLimit(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))

	Post(cross(cur), "ripe one", 0)
	Post(cross(cur), "ripe two", 0)
	Post(cross(cur), "not yet", ttlFuture)
	uassert.Equal(t, 3, Live())
	uassert.Equal(t, 2, Reapable())

	// The limit caps the work, so a reaper can size a transaction to its gas.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 1, Reap(cross(cur), 1))
	uassert.Equal(t, 1, Reapable())

	// The unexpired note survives a reap that asks for everything.
	uassert.Equal(t, 1, Reap(cross(cur), 100))
	uassert.Equal(t, 0, Reapable())
	uassert.Equal(t, 1, Live())

	// Leave nothing behind: the next test's height starts over and could not
	// expire this note.
	drain(cur)
}

func TestReapOfNothingIsNotAnError(cur realm, t *testing.T) {
	clear(cur, t)
	// A bot that races another bot to the same notes must not revert, or it
	// loses its gas to an abort instead of merely earning nothing.
	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 0, Reap(cross(cur), 100))
}

func TestCompactFollowsReaping(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	for i := 0; i < 8; i++ {
		Post(cross(cur), "note", 0)
	}

	// Nothing is reclaimable until something has been reaped.
	uassert.Equal(t, 0, Compactable())

	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 8, Reap(cross(cur), 100))
	uassert.True(t, Compactable() > 0)

	freed := Compact(cross(cur))
	uassert.True(t, freed > 0)
	uassert.Equal(t, 0, Compactable())
	// Compacting twice is not an error, it just frees nothing.
	uassert.Equal(t, 0, Compact(cross(cur)))
}

func TestPostRejectsBadInput(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))

	uassert.AbortsWithMessage(t, cur, "reaper: empty note", func() {
		Post(cross(cur), "", 0)
	})
	uassert.AbortsWithMessage(t, cur, "reaper: negative ttl", func() {
		Post(cross(cur), "fine", -1)
	})
	// The cap keeps one call from locking an unbounded deposit.
	uassert.AbortsWithMessage(t, cur, "reaper: note too long, 4097 bytes against a 4096 cap", func() {
		Post(cross(cur), strings.Repeat("x", maxBody+1), 0)
	})
	uassert.AbortsWithMessage(t, cur, "reaper: limit must be positive", func() {
		Reap(cross(cur), 0)
	})
}

func TestBountyPricesWhatIsOnTheTable(cur realm, t *testing.T) {
	clear(cur, t)

	// An empty board advertises nothing, and must not claim a profit.
	empty := Bounty()
	uassert.Equal(t, int64(0), empty.Bytes)
	uassert.Equal(t, int64(0), empty.Refund)
	uassert.False(t, empty.Worth())

	testing.SetRealm(testing.NewUserRealm(poster))
	body := strings.Repeat("x", 1024)
	for i := 0; i < 10; i++ {
		Post(cross(cur), body, 0)
	}

	// Ten 1 KB notes, priced through the same estimate the library documents.
	q := Bounty()
	uassert.Equal(t, storagecost.EstimateBytes(10*1024), q.Bytes)
	uassert.Equal(t, storagecost.Refund(q.Bytes, storagecost.DefaultStoragePrice), q.Refund)
	uassert.True(t, q.Worth())

	// Once reaped, nothing is on the table.
	testing.SetRealm(testing.NewUserRealm(stranger))
	Reap(cross(cur), 100)
	uassert.Equal(t, int64(0), Bounty().Bytes)
}

func TestRenderShowsTheBountyAndTheReapLink(cur realm, t *testing.T) {
	clear(cur, t)

	// Empty board: an invitation, and no bounty claimed.
	out := Render("")
	uassert.True(t, strings.Contains(out, "# Reaper"), out)
	uassert.True(t, strings.Contains(out, "Nothing has expired"), out)
	uassert.True(t, strings.Contains(out, "Post the first note"), out)

	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), strings.Repeat("y", 1024), 0)

	out = Render("")
	uassert.True(t, strings.Contains(out, "1 expired notes"), out)
	uassert.True(t, strings.Contains(out, "refunds roughly **0.1894 GNOT**"), out)
	// The reap link must be a help link for the right function with the right
	// argument, or the button on the page does nothing useful. txlink builds
	// it relative to the current realm, so there is no path to get wrong.
	uassert.True(t, strings.Contains(out, "$help&func=Reap&limit=100"), out)
	// The author is named, in the house address format, which is what makes
	// "the poster paid" visible without 40 opaque characters per row.
	uassert.True(t, strings.Contains(out, ui.Addr(poster)), out)
	uassert.True(t, strings.Contains(out, "**reapable**"), out)

	// A long note is summarized rather than dumped into the table.
	uassert.True(t, strings.Contains(out, ui.Ellipsis), out)
	uassert.False(t, strings.Contains(out, strings.Repeat("y", 200)), "body should be truncated")
}

func TestRenderNeverEmitsTwoBlankLines(cur realm, t *testing.T) {
	// gno collapses two consecutive blank lines, so output containing them can
	// never be pinned by an Example. This test is what lets ExampleRender stay
	// meaningful.
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), "one", 0)
	Post(cross(cur), "two", ttlFuture)
	testing.SetRealm(testing.NewUserRealm(stranger))
	Reap(cross(cur), 1)

	for _, path := range []string{"", "anything"} {
		out := Render(path)
		uassert.False(t, strings.Contains(out, "\n\n\n"), "blank-line run in Render("+path+")")
	}

	drain(cur)
}

func TestReapWalksNewestFirstSoCompactionHasWork(cur realm, t *testing.T) {
	// The ordering is economic, not cosmetic: in the backing list the oldest
	// indices are the ancestors of the newest, so a partial reap that took the
	// oldest first would leave nothing compactable and strand the tree
	// structure, which costs more than the notes do.
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	for i := 0; i < 16; i++ {
		Post(cross(cur), "note", 0)
	}
	first := notes.TotalSize() - 16
	last := notes.TotalSize() - 1

	testing.SetRealm(testing.NewUserRealm(stranger))
	uassert.Equal(t, 4, Reap(cross(cur), 4))

	// The four highest indices went, and the four lowest survived.
	uassert.Equal(t, nil, notes.Get(last))
	uassert.True(t, notes.Get(first) != nil)

	// Which is the whole point: there is something to compact after one batch.
	uassert.True(t, Compactable() > 0)

	drain(cur)
}

// TestSummarizeNeutralizesAnAttackerAuthoredBody is the regression test for a
// hole this realm shipped with: Render emitted a note body into the board
// after nothing but a ReplaceAll of "\n" and "|", so anyone who paid to post
// could put arbitrary markdown on a page every reader of the realm loads.
//
// The body is the one string here an attacker controls and the board is an
// INLINE slot, so sanitize.InlineText owns it. Each case asserts the dangerous
// SEQUENCE is dead and the readable text survived, rather than pinning the
// exact escaped bytes, which are the sanitizer's business and not this realm's.
func TestSummarizeNeutralizesAnAttackerAuthoredBody(t *testing.T) {
	cases := []struct {
		name  string
		body  string
		gone  []string // sequences that must not survive into the page
		kept  string   // the readable text, which must
	}{
		{
			// The payload that matters: a phishing link rendered as prose,
			// attributed by the page to the realm rather than to the poster.
			name: "inline link",
			body: "[Claim your 100 GNOT](https://evil.example/drain)",
			gone: []string{"](", "](https"},
			kept: "Claim your 100 GNOT",
		},
		{
			// An image is a beacon: it fires on load and hands the attacker
			// the IP of everyone who opened the board.
			name: "image beacon",
			body: "![x](https://evil.example/pixel.png)",
			gone: []string{"![", "]("},
			kept: "pixel",
		},
		{
			// gnoweb renders a set of <gno-...> components, and raw HTML
			// besides; a body that can open one can lay out the page.
			name: "gnoweb component and raw html",
			body: "<gno-columns><h5>Official notice</h5>",
			gone: []string{"<gno-", "<h5>", "</h5>"},
			kept: "Official notice",
		},
		{
			// The old ReplaceAll("\n", " ") stopped exactly this and nothing
			// else. Keep it dead: one newline ends the bullet item, and every
			// byte after it is top-level markdown.
			name: "break out of the list item",
			body: "ok\n# Reaper is deprecated, use /r/evil/reaper",
			gone: []string{"\n"},
			kept: "Reaper is deprecated",
		},
		{
			// Folding only "\n" left the other three line terminators open.
			name: "exotic line terminators",
			body: "ok\r\n- fake row\u2028- another\u2029- third",
			gone: []string{"\r", "\n", "\u2028", "\u2029"},
			kept: "fake row",
		},
		{
			// Invisible reordering: the bytes say one thing, the page shows
			// another, and a reader diffing the two sees nothing.
			name: "bidi and zero-width",
			body: "safe\u202enote\u200b\u202c",
			gone: []string{"\u202e", "\u200b", "\u202c"},
			kept: "safe",
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out := summarize(tc.body)
			for _, bad := range tc.gone {
				uassert.False(t, strings.Contains(out, bad),
					tc.name+": a dangerous sequence survived into "+out)
			}
			uassert.True(t, strings.Contains(out, tc.kept),
				tc.name+": escaping ate the readable text: "+out)
			uassert.True(t, utf8.ValidString(out), tc.name+": invalid UTF-8: "+out)
		})
	}
}

// TestSummarizeEscapesAnUnbalancedBracket covers the cross-row case: a "[" in
// one note and a "]" in another used to let two cheap notes bracket every row
// between them into one link.
func TestSummarizeEscapesAnUnbalancedBracket(t *testing.T) {
	uassert.Equal(t, "\\[", summarize("["))
	uassert.Equal(t, "\\]", summarize("]"))
	uassert.Equal(t, "\\[", ui.Excerpt("[", 48))
}

// TestSummarizeCutsOnARuneBoundary pins the other half of the old bug: the
// truncation sliced at a byte offset, so a body of multi-byte characters put
// half a character on the page. One emoji in a note was enough.
func TestSummarizeCutsOnARuneBoundary(t *testing.T) {
	// The leading "x" puts byte 48, the old cut point, in the middle of a
	// 4-byte rune rather than on a boundary.
	out := summarize("x" + strings.Repeat("\U0001F33E", 60))
	uassert.True(t, utf8.ValidString(out), "cut mid-rune: "+out)
	uassert.True(t, strings.HasSuffix(out, ui.Ellipsis), "long body should be elided: "+out)

	// A short body comes back whole, with no elision and nothing to escape.
	short := summarize("plain note")
	uassert.Equal(t, "plain note", short)
}

// TestRenderEscapesTheBoard is the end-to-end half: the sanitizer is only
// worth anything if Render is what calls it, and the board is the one place a
// stranger's bytes reach the page.
func TestRenderEscapesTheBoard(cur realm, t *testing.T) {
	clear(cur, t)
	testing.SetRealm(testing.NewUserRealm(poster))
	Post(cross(cur), "[Claim 100 GNOT](https://evil.example)\n# Official", 0)

	out := Render("")
	uassert.False(t, strings.Contains(out, "](https://evil.example)"), out)
	uassert.False(t, strings.Contains(out, "\n# Official"), out)
	// The note stays legible, just inert: the text survives, the chrome does not.
	uassert.True(t, strings.Contains(out, "Claim 100 GNOT"), out)
	uassert.True(t, utf8.ValidString(out), "Render emitted invalid UTF-8")

	testing.SetRealm(testing.NewUserRealm(stranger))
	Reap(cross(cur), 100)
	Compact(cross(cur))
}

// Package mmr implements a Merkle Mountain Range: an append-only log with a
// root that updates in O(log n) and inclusion proofs of O(log n) size.
//
// # Why not a plain Merkle tree
//
// gno.land/p/moul/x/merkle/v0 commits to a FIXED list. Adding a leaf means
// rebuilding from every leaf, which on chain means re-reading the whole set
// and re-hashing it, every time. An MMR never rebuilds: an append hashes at
// most log2(n) times and touches nothing else.
//
// That is the shape any on-chain log wants. A wiki committing to its revision
// history, a forge committing to its objects, an agent realm committing to the
// receipts it issued: all append, none rewrite.
//
// # The structure
//
// An MMR is a list of perfect binary trees ("mountains") of strictly
// decreasing height, one per set bit of the leaf count. Eleven leaves is
// 8 + 2 + 1, so three mountains of height 3, 1 and 0. Appending a leaf pushes
// a height-0 mountain and merges equal-height neighbours, exactly like
// incrementing a binary counter.
//
// The root is the peaks "bagged" right to left:
//
//	root = InnerHash(p0, InnerHash(p1, InnerHash(p2, …)))
//
// Hashing is gno.land/p/moul/x/merkle/v0's, which is Tendermint's: leaves are
// tagged 0x00 and inner nodes 0x01. Leaf and inner preimages therefore cannot
// collide, so the second-preimage forgery that works against untagged schemes
// does not apply here. See that package for the worked attack.
//
// # This IS the Tendermint tree
//
// The root above equals the Tendermint simple-tree root over the same leaves,
// at every size and not merely at powers of two. Tendermint splits an n-leaf
// tree at the largest power of two below n: that left half is exactly the
// first mountain, and the right half recurses through the remaining set bits,
// which is exactly the bagging. The two constructions coincide.
//
// So this package is a drop-in INCREMENTAL BUILDER for Tendermint roots.
// Append in O(log n) on chain and hand out a root that any Tendermint verifier
// accepts; proofs cross over in both directions, which
// TestMerkleProofVerifiesAgainstMMRRoot pins. Use merkle.New when the leaf set
// is fixed and you want the simpler proof encoding, use this when the log
// grows.
//
// # Proofs are bound to position and to size
//
// A Proof carries the leaf index and the leaf count the MMR had when it was
// issued. The verifier recomputes the whole peak structure from that count,
// which fixes the number of peaks, which mountain holds the leaf, the local
// index inside it, and therefore the exact expected length of every component
// of the proof. A proof cannot be replayed at another index, against another
// size, or padded.
//
// Because the root changes on every append, a proof is valid against the root
// at its own Total and no other. A realm that wants old proofs to keep
// verifying must keep the historical roots; Roots grow by one 32-byte hash per
// append, which is the price of an auditable log.
//
// # Storage
//
// Append stores one node per leaf plus one per merge, so 2n-popcount(n) hashes
// for n leaves, under 64 bytes per leaf amortised. That is what on-chain proof
// generation costs. A realm that only ever needs to VERIFY proofs, with the
// tree living off chain, should store the root alone and use
// gno.land/p/moul/x/merkle/v0's Verify instead.
//
// Live demo: gno.land/r/moul/x/provable/v0
package mmr

import (
	"encoding/hex"
	"errors"

	"gno.land/p/moul/x/merkle/v0"
)

// HashSize is the length in bytes of every node hash.
const HashSize = merkle.HashSize

// MaxPeaks caps the peak count a Proof may claim. A 64-peak MMR would hold
// more than 2^64 leaves.
const MaxPeaks = 64

var (
	ErrEmpty      = errors.New("mmr: log is empty")
	ErrIndexRange = errors.New("mmr: leaf index out of range")
	ErrBadHex     = errors.New("mmr: hash is not valid hex")
	ErrBadSize    = errors.New("mmr: hash is not 32 bytes")
	ErrTooManyPeaks = errors.New("mmr: more peaks than MaxPeaks")
)

// peak is one mountain: the position of its root in nodes, and its height.
type peak struct {
	pos    int
	height int
}

// MMR is an append-only Merkle mountain range.
//
// The zero value is an empty, ready-to-use log.
type MMR struct {
	nodes  [][]byte // every node, in postorder: [left subtree][right subtree][root]
	peaks  []peak
	leaves int
}

// New returns an empty MMR.
func New() *MMR { return &MMR{} }

// Size returns the number of leaves appended so far.
func (m *MMR) Size() int { return m.leaves }

// Nodes returns the number of stored hashes, leaves and merges together. Use
// it to reason about storage growth.
func (m *MMR) Nodes() int { return len(m.nodes) }

// Append adds a leaf and returns its index. O(log n) hashes, no rebuild.
func (m *MMR) Append(leaf []byte) int {
	index := m.leaves
	m.nodes = append(m.nodes, merkle.LeafHash(leaf))
	m.peaks = append(m.peaks, peak{pos: len(m.nodes) - 1, height: 0})
	for len(m.peaks) >= 2 {
		right := m.peaks[len(m.peaks)-1]
		left := m.peaks[len(m.peaks)-2]
		if left.height != right.height {
			break
		}
		m.nodes = append(m.nodes, merkle.InnerHash(m.nodes[left.pos], m.nodes[right.pos]))
		m.peaks = m.peaks[:len(m.peaks)-2]
		m.peaks = append(m.peaks, peak{pos: len(m.nodes) - 1, height: left.height + 1})
	}
	m.leaves++
	return index
}

// Root returns the current root, nil while the log is empty.
func (m *MMR) Root() []byte {
	if len(m.peaks) == 0 {
		return nil
	}
	return bag(m.peakHashes())
}

// RootHex returns Root hex-encoded.
func (m *MMR) RootHex() string { return hex.EncodeToString(m.Root()) }

// PeakHashes returns the current peak hashes, left to right. This is the whole
// state a verifier needs, and it is O(log n).
func (m *MMR) PeakHashes() [][]byte { return m.peakHashes() }

func (m *MMR) peakHashes() [][]byte {
	out := make([][]byte, len(m.peaks))
	for i, p := range m.peaks {
		out[i] = m.nodes[p.pos]
	}
	return out
}

// bag folds peaks right to left: InnerHash(p0, InnerHash(p1, …)).
func bag(peaks [][]byte) []byte {
	if len(peaks) == 0 {
		return nil
	}
	acc := peaks[len(peaks)-1]
	for i := len(peaks) - 2; i >= 0; i-- {
		acc = merkle.InnerHash(peaks[i], acc)
	}
	return acc
}

// Proof is an inclusion proof for one leaf of a log that held Total leaves.
//
// Path holds the sibling hashes inside the leaf's own mountain, leaf first.
// Before and After hold the other peak hashes, in left-to-right order.
type Proof struct {
	Index  int
	Total  int
	Path   [][]byte
	Before [][]byte
	After  [][]byte
}

// Proof returns the inclusion proof for the leaf at index, against the current
// root.
func (m *MMR) Proof(index int) (Proof, error) {
	if m.leaves == 0 {
		return Proof{}, ErrEmpty
	}
	if index < 0 || index >= m.leaves {
		return Proof{}, ErrIndexRange
	}
	j, local := locate(m.leaves, index)
	hashes := m.peakHashes()
	return Proof{
		Index:  index,
		Total:  m.leaves,
		Path:   m.pathIn(m.peaks[j], local),
		Before: hashes[:j],
		After:  hashes[j+1:],
	}, nil
}

// pathIn walks down the perfect tree rooted at p, collecting the sibling at
// each level, and returns them leaf first.
//
// The layout is postorder, so for a node at position pos and height h the
// right child root sits at pos-1 and the left child root at pos-1-(2^h - 1),
// a perfect subtree of height h-1 holding 2^h - 1 nodes.
func (m *MMR) pathIn(p peak, local int) [][]byte {
	var out [][]byte
	pos, h := p.pos, p.height
	for h > 0 {
		rightRoot := pos - 1
		leftRoot := pos - 1 - ((1 << uint(h)) - 1)
		half := 1 << uint(h-1)
		if local < half {
			out = append([][]byte{m.nodes[rightRoot]}, out...)
			pos = leftRoot
		} else {
			out = append([][]byte{m.nodes[leftRoot]}, out...)
			pos = rightRoot
			local -= half
		}
		h--
	}
	return out
}

package mmr

import (
	"strconv"
	"testing"

	"gno.land/p/moul/x/merkle/v0"
)

func leafAt(i int) []byte { return []byte("entry-" + strconv.Itoa(i)) }

func build(n int) *MMR {
	m := New()
	for i := 0; i < n; i++ {
		if got := m.Append(leafAt(i)); got != i {
			panic("Append returned the wrong index")
		}
	}
	return m
}

// The property that matters: for every log size up to 40, every leaf ever
// appended has a proof that verifies against the root at that size.
func TestEveryProofVerifies(t *testing.T) {
	for n := 1; n <= 40; n++ {
		m := build(n)
		root := m.Root()
		for i := 0; i < n; i++ {
			p, err := m.Proof(i)
			if err != nil {
				t.Fatalf("n=%d i=%d: Proof: %v", n, i, err)
			}
			if !Verify(root, leafAt(i), p) {
				t.Errorf("n=%d i=%d: valid proof rejected", n, i)
			}
		}
	}
}

// A one-leaf MMR is a single height-0 mountain, so its root is just the
// tagged leaf hash and the proof is empty.
func TestSingleLeaf(t *testing.T) {
	m := build(1)
	if string(m.Root()) != string(merkle.LeafHash(leafAt(0))) {
		t.Error("one-leaf root is not the leaf hash")
	}
	p, err := m.Proof(0)
	if err != nil {
		t.Fatal(err)
	}
	if len(p.Path) != 0 || len(p.Before) != 0 || len(p.After) != 0 {
		t.Error("one-leaf proof should be empty")
	}
}

// The Tendermint simple tree and a right-bagged MMR are the SAME tree, at
// every size and not only at powers of two. Tendermint splits an n-leaf tree
// at the largest power of two below n: that left half is exactly the first
// mountain, and the right half recurses into the remaining set bits, which is
// exactly the bagging. So an MMR is a drop-in incremental builder for
// Tendermint roots: append in O(log n) on chain, hand out a root any
// Tendermint verifier accepts.
func TestRootMatchesTendermintTreeAtEverySize(t *testing.T) {
	for n := 1; n <= 40; n++ {
		ls := make([][]byte, n)
		for i := range ls {
			ls[i] = leafAt(i)
		}
		if got, want := build(n).RootHex(), merkle.New(ls).RootHex(); got != want {
			t.Errorf("n=%d: MMR root %s, Tendermint tree root %s", n, got, want)
		}
	}
}

// The consequence of the equality above: a proof produced by the fixed-list
// Tendermint tree verifies against the root an MMR maintained incrementally,
// and both packages agree leaf by leaf.
func TestMerkleProofVerifiesAgainstMMRRoot(t *testing.T) {
	for _, n := range []int{1, 2, 3, 5, 7, 11, 16, 23} {
		ls := make([][]byte, n)
		for i := range ls {
			ls[i] = leafAt(i)
		}
		m := build(n)
		tree := merkle.New(ls)
		for i := 0; i < n; i++ {
			tp, err := tree.Proof(i)
			if err != nil {
				t.Fatalf("n=%d i=%d: %v", n, i, err)
			}
			if !tp.Verify(m.Root(), leafAt(i)) {
				t.Errorf("n=%d i=%d: Tendermint proof rejected by the MMR root", n, i)
			}
			mp, err := m.Proof(i)
			if err != nil {
				t.Fatalf("n=%d i=%d: %v", n, i, err)
			}
			if !Verify(tree.Root(), leafAt(i), mp) {
				t.Errorf("n=%d i=%d: MMR proof rejected by the tree root", n, i)
			}
		}
	}
}

func TestPeakStructure(t *testing.T) {
	tests := []struct {
		leaves int
		want   []int
	}{
		{1, []int{0}},
		{2, []int{1}},
		{3, []int{1, 0}},
		{4, []int{2}},
		{7, []int{2, 1, 0}},
		{11, []int{3, 1, 0}},
		{16, []int{4}},
	}
	for _, tc := range tests {
		if got := len(peakHeights(tc.leaves)); got != len(tc.want) {
			t.Errorf("n=%d: %d peaks, want %d", tc.leaves, got, len(tc.want))
			continue
		}
		for i, h := range peakHeights(tc.leaves) {
			if h != tc.want[i] {
				t.Errorf("n=%d: peak %d height %d, want %d", tc.leaves, i, h, tc.want[i])
			}
		}
		if got := len(build(tc.leaves).peaks); got != len(tc.want) {
			t.Errorf("n=%d: MMR built %d peaks, want %d", tc.leaves, got, len(tc.want))
		}
	}
}

func TestRejects(t *testing.T) {
	m := build(11)
	root := m.Root()
	p3, _ := m.Proof(3)
	p7, _ := m.Proof(7)

	tests := []struct {
		name  string
		root  []byte
		leaf  []byte
		proof Proof
	}{
		{"forged leaf", root, []byte("never-appended"), p3},
		{"another real leaf", root, leafAt(4), p3},
		{"proof replayed at another index", root, leafAt(3), Proof{Index: 4, Total: p3.Total, Path: p3.Path, Before: p3.Before, After: p3.After}},
		{"another leaf's proof", root, leafAt(3), p7},
		{"wrong total", root, leafAt(3), Proof{Index: 3, Total: 10, Path: p3.Path, Before: p3.Before, After: p3.After}},
		{"padded path", root, leafAt(3), Proof{Index: 3, Total: 11, Path: append(append([][]byte{}, p3.Path...), make([]byte, HashSize)), Before: p3.Before, After: p3.After}},
		{"truncated path", root, leafAt(3), Proof{Index: 3, Total: 11, Path: p3.Path[:len(p3.Path)-1], Before: p3.Before, After: p3.After}},
		{"peaks swapped", root, leafAt(3), Proof{Index: 3, Total: 11, Path: p3.Path, Before: p3.After, After: p3.Before}},
		{"index beyond total", root, leafAt(3), Proof{Index: 11, Total: 11, Path: p3.Path, Before: p3.Before, After: p3.After}},
		{"negative index", root, leafAt(3), Proof{Index: -1, Total: 11, Path: p3.Path, Before: p3.Before, After: p3.After}},
		{"zero total", root, leafAt(3), Proof{Index: 0, Total: 0}},
		{"short root", root[:31], leafAt(3), p3},
		{"short hash in path", root, leafAt(3), Proof{Index: 3, Total: 11, Path: [][]byte{{1, 2, 3}, p3.Path[1]}, Before: p3.Before, After: p3.After}},
	}
	for _, tc := range tests {
		if Verify(tc.root, tc.leaf, tc.proof) {
			t.Errorf("%s: accepted, must be rejected", tc.name)
		}
	}
}

// A proof is issued against one size. Appending moves the root, and the old
// proof must stop verifying against the new one rather than quietly pass.
func TestProofIsBoundToItsSize(t *testing.T) {
	m := build(5)
	old, _ := m.Proof(2)
	oldRoot := m.Root()
	if !Verify(oldRoot, leafAt(2), old) {
		t.Fatal("proof does not verify against its own root")
	}
	m.Append(leafAt(5))
	if Verify(m.Root(), leafAt(2), old) {
		t.Error("a stale proof verified against the new root")
	}
	fresh, _ := m.Proof(2)
	if !Verify(m.Root(), leafAt(2), fresh) {
		t.Error("a reissued proof does not verify")
	}
	if !Verify(oldRoot, leafAt(2), old) {
		t.Error("the old proof stopped verifying against the old root")
	}
}

func TestEmptyAndRange(t *testing.T) {
	m := New()
	if m.Size() != 0 || m.Root() != nil || m.Nodes() != 0 {
		t.Error("a fresh MMR is not empty")
	}
	if _, err := m.Proof(0); err != ErrEmpty {
		t.Errorf("empty Proof: err = %v, want %v", err, ErrEmpty)
	}
	m.Append(leafAt(0))
	for _, i := range []int{-1, 1, 99} {
		if _, err := m.Proof(i); err != ErrIndexRange {
			t.Errorf("index %d: err = %v, want %v", i, err, ErrIndexRange)
		}
	}
}

// Storage claim from the package doc: 2n - popcount(n) stored hashes.
func TestNodeCount(t *testing.T) {
	for n := 1; n <= 40; n++ {
		want := 2*n - popcount(n)
		if got := build(n).Nodes(); got != want {
			t.Errorf("n=%d: %d nodes, want 2n-popcount(n) = %d", n, got, want)
		}
	}
}

func popcount(n int) int {
	c := 0
	for n != 0 {
		c += n & 1
		n >>= 1
	}
	return c
}

func TestParseProofRoundTrip(t *testing.T) {
	m := build(11)
	for i := 0; i < 11; i++ {
		want, _ := m.Proof(i)
		path, before, after := want.Hex()
		got, err := ParseProof(i, 11, path, before, after)
		if err != nil {
			t.Fatalf("i=%d: ParseProof: %v", i, err)
		}
		if !Verify(m.Root(), leafAt(i), got) {
			t.Errorf("i=%d: reparsed proof does not verify", i)
		}
	}
}

func TestParseProofErrors(t *testing.T) {
	if _, err := ParseProof(0, 2, "zz", "", ""); err != ErrBadHex {
		t.Errorf("bad hex: err = %v", err)
	}
	if _, err := ParseProof(0, 2, "abcd", "", ""); err != ErrBadSize {
		t.Errorf("bad size: err = %v", err)
	}
}

// PeakHashes is the whole verifier-side state, and it must stay logarithmic.
func TestPeakCountIsLogarithmic(t *testing.T) {
	m := build(1023)
	if got := len(m.PeakHashes()); got != 10 {
		t.Errorf("1023 leaves: %d peaks, want 10", got)
	}
	if got := len(build(1024).PeakHashes()); got != 1 {
		t.Errorf("1024 leaves: %d peaks, want 1", got)
	}
}

package mmr

import (
	"encoding/hex"
	"strings"

	"gno.land/p/moul/x/merkle/v0"
)

// peakHeights returns the mountain heights of a log of total leaves, left to
// right. They are the set bits of total, high to low: 11 leaves is 8 + 2 + 1,
// so heights 3, 1, 0.
func peakHeights(total int) []int {
	var out []int
	for h := 62; h >= 0; h-- {
		if total&(1<<uint(h)) != 0 {
			out = append(out, h)
		}
	}
	return out
}

// locate returns which mountain holds the leaf at index, and the leaf's index
// within that mountain. It returns -1 when index is out of range.
func locate(total, index int) (int, int) {
	offset := 0
	for j, h := range peakHeights(total) {
		size := 1 << uint(h)
		if index < offset+size {
			return j, index - offset
		}
		offset += size
	}
	return -1, 0
}

// Verify reports whether leaf really sits at p.Index of a log that held
// p.Total leaves and whose root is root.
//
// Every dimension of the proof is checked against p.Total rather than trusted:
// the peak count, which mountain holds the leaf, the local index, the path
// length and both peak-list lengths are all recomputed. A proof that does not
// have exactly the shape p.Total implies is rejected before any hashing.
//
// Failures are false, never a panic, so a realm chooses whether a bad proof
// aborts or branches.
func Verify(root, leaf []byte, p Proof) bool {
	if len(root) != HashSize || p.Total <= 0 || p.Index < 0 || p.Index >= p.Total {
		return false
	}
	heights := peakHeights(p.Total)
	if len(heights) > MaxPeaks {
		return false
	}
	j, local := locate(p.Total, p.Index)
	if j < 0 {
		return false
	}
	if len(p.Path) != heights[j] || len(p.Before) != j || len(p.After) != len(heights)-1-j {
		return false
	}
	if !allHashes(p.Path) || !allHashes(p.Before) || !allHashes(p.After) {
		return false
	}

	node := merkle.LeafHash(leaf)
	for d, sib := range p.Path {
		if (local>>uint(d))&1 == 1 {
			node = merkle.InnerHash(sib, node)
		} else {
			node = merkle.InnerHash(node, sib)
		}
	}

	peaks := make([][]byte, 0, len(heights))
	peaks = append(peaks, p.Before...)
	peaks = append(peaks, node)
	peaks = append(peaks, p.After...)
	return equal(bag(peaks), root)
}

func allHashes(hs [][]byte) bool {
	for _, h := range hs {
		if len(h) != HashSize {
			return false
		}
	}
	return true
}

func equal(a, b []byte) bool {
	if len(a) != len(b) || len(a) == 0 {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// Hex renders the three hash lists as comma-separated hex, in the order
// path|before|after, which is what a realm call takes as arguments.
func (p Proof) Hex() (path, before, after string) {
	return joinHex(p.Path), joinHex(p.Before), joinHex(p.After)
}

func joinHex(hs [][]byte) string {
	parts := make([]string, len(hs))
	for i, h := range hs {
		parts[i] = hex.EncodeToString(h)
	}
	return strings.Join(parts, ",")
}

// ParseProof rebuilds a Proof from realm-call arguments. Each of path, before
// and after is a comma-separated hex list, possibly empty.
func ParseProof(index, total int, path, before, after string) (Proof, error) {
	ph, err := splitHex(path)
	if err != nil {
		return Proof{}, err
	}
	bh, err := splitHex(before)
	if err != nil {
		return Proof{}, err
	}
	ah, err := splitHex(after)
	if err != nil {
		return Proof{}, err
	}
	if len(bh)+len(ah)+1 > MaxPeaks {
		return Proof{}, ErrTooManyPeaks
	}
	return Proof{Index: index, Total: total, Path: ph, Before: bh, After: ah}, nil
}

func splitHex(s string) ([][]byte, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, nil
	}
	var out [][]byte
	for _, raw := range strings.Split(s, ",") {
		raw = strings.TrimSpace(raw)
		if raw == "" {
			continue
		}
		b, err := hex.DecodeString(raw)
		if err != nil {
			return nil, ErrBadHex
		}
		if len(b) != HashSize {
			return nil, ErrBadSize
		}
		out = append(out, b)
	}
	return out, nil
}

// Package memfs is a RAM file server: Plan 9's ramfs, in a realm's heap.
//
// It is the reference implementation of gno.land/p/moul/x/plan9/ninep's File
// and Mutable, and the tree a namespace server hands out as a user's private
// root. Children live in an avl.Tree, so a directory listing is ordered by
// name and therefore identical on every validating node; a map would make
// Render a consensus bug.
//
// Mutable is IN-REALM ONLY. A non-crossing method runs in the caller's frame,
// so a foreign realm calling Create or Write here would be mutating objects it
// does not own. Reads (the ninep.File half) are safe from anywhere, which is
// what makes a memfs tree mountable into somebody else's namespace.
//
// The caller supplies the clock (a block height) on every mutation rather than
// the tree reading chain state itself, so the same tree is exercisable in a
// plain unit test.
//
// NOTICE. Plan 9 from Bell Labs is the work of the Computing Science Research
// Center at Bell Labs; the name and the marks are theirs, and the copyright is
// held by the Plan 9 Foundation (https://p9f.org). This package is not
// affiliated with, endorsed by, or sponsored by them, and contains no Plan 9
// code: it borrows the vocabulary so that the design reads without a glossary,
// and it is an homage, asking what that ecosystem's spirit looks like on a
// chain. Full attribution: NOTICE.md at the root of moul/gno-contracts.
package memfs

import (
	"strings"

	"gno.land/p/nt/avl/v0"

	ninep "gno.land/p/moul/x/plan9/ninep/v0"
)

// FS is a mutable in-memory file tree.
type FS struct {
	root *node
	next uint64 // qid path allocator, unique for this server's lifetime
	uid  string
}

type node struct {
	fs       *FS
	name     string
	perm     ninep.Perm
	qid      ninep.Qid
	data     string
	children *avl.Tree // name -> *node; nil for a plain file
	mtime    int64
	uid      string
	gid      string
	muid     string
}

// New returns an empty file server owned by uid, with its root created at
// block height now.
func New(uid string, now int64) *FS {
	fs := &FS{uid: uid}
	fs.root = fs.newNode("/", ninep.DirPerm, now)
	return fs
}

// Root returns the server's root directory.
func (fs *FS) Root() ninep.File { return fs.root }

// RootMutable returns the root as a Mutable. Only call it from the realm that
// owns this FS.
func (fs *FS) RootMutable() ninep.Mutable { return fs.root }

// Uid returns the owner this server stamps on new files.
func (fs *FS) Uid() string { return fs.uid }

func (fs *FS) newNode(name string, perm ninep.Perm, now int64) *node {
	fs.next++
	qt := ninep.QTFILE
	var kids *avl.Tree
	if perm.IsDir() {
		qt = ninep.QTDIR
		kids = avl.NewTree()
	}
	return &node{
		fs:       fs,
		name:     name,
		perm:     perm,
		qid:      ninep.Qid{Type: qt, Version: 0, Path: fs.next},
		children: kids,
		mtime:    now,
		uid:      fs.uid,
		gid:      fs.uid,
		muid:     fs.uid,
	}
}

// Stat implements ninep.File.
func (n *node) Stat() ninep.Stat {
	length := int64(len(n.data))
	if n.perm.IsDir() {
		length = 0 // 9P reports zero for a directory
	}
	return ninep.Stat{
		Qid:    n.qid,
		Mode:   n.perm,
		Mtime:  n.mtime,
		Length: length,
		Name:   n.name,
		Uid:    n.uid,
		Gid:    n.gid,
		Muid:   n.muid,
	}
}

// Walk implements ninep.File.
func (n *node) Walk(name string) (ninep.File, error) {
	if !n.perm.IsDir() {
		return nil, ninep.ErrNotDir
	}
	if !ninep.ValidName(name) {
		return nil, ninep.ErrBadName
	}
	v := n.children.Get(name) // avl.Get returns ONE value in gno
	if v == nil {
		return nil, ninep.ErrNotExist
	}
	return v.(*node), nil
}

// Read implements ninep.File.
func (n *node) Read(off, count int64) (string, error) {
	if n.perm.IsDir() {
		return "", ninep.ErrIsDir
	}
	return ninep.Slice(n.data, off, count), nil
}

// ReadDir implements ninep.File.
func (n *node) ReadDir() ([]ninep.Stat, error) {
	if !n.perm.IsDir() {
		return nil, ninep.ErrNotDir
	}
	out := []ninep.Stat{}
	n.children.Iterate("", "", func(_ string, v any) bool {
		out = append(out, v.(*node).Stat())
		return false
	})
	return out, nil
}

// Create implements ninep.Mutable.
func (n *node) Create(name string, perm ninep.Perm, now int64) (ninep.File, error) {
	if !n.perm.IsDir() {
		return nil, ninep.ErrNotDir
	}
	if !ninep.ValidName(name) {
		return nil, ninep.ErrBadName
	}
	if n.children.Has(name) {
		return nil, ninep.ErrExist
	}
	child := n.fs.newNode(name, perm, now)
	n.children.Set(name, child)
	n.touch(now)
	return child, nil
}

// Remove implements ninep.Mutable. A non-empty directory is refused, as in
// Plan 9.
func (n *node) Remove(name string) error {
	if !n.perm.IsDir() {
		return ninep.ErrNotDir
	}
	v := n.children.Get(name)
	if v == nil {
		return ninep.ErrNotExist
	}
	child := v.(*node)
	if child.perm.IsDir() && child.children.Size() > 0 {
		return ninep.ErrNotEmpty
	}
	n.children.Remove(name)
	n.touch(n.mtime)
	return nil
}

// Write implements ninep.Mutable. Writing past the end extends the file with
// NUL bytes, as a 9P server does.
func (n *node) Write(off int64, data string, now int64) (int64, error) {
	if n.perm.IsDir() {
		return 0, ninep.ErrIsDir
	}
	if off < 0 {
		off = 0
	}
	if n.perm&ninep.DMAPPEND != 0 {
		off = int64(len(n.data))
	}
	cur := n.data
	if off > int64(len(cur)) {
		cur += strings.Repeat("\x00", int(off)-len(cur))
	}
	end := off + int64(len(data))
	tail := ""
	if end < int64(len(cur)) {
		tail = cur[end:]
	}
	n.data = cur[:off] + data + tail
	n.touch(now)
	return int64(len(data)), nil
}

// Truncate implements ninep.Mutable.
func (n *node) Truncate(size int64, now int64) error {
	if n.perm.IsDir() {
		return ninep.ErrIsDir
	}
	if size < 0 {
		size = 0
	}
	switch {
	case size < int64(len(n.data)):
		n.data = n.data[:size]
	case size > int64(len(n.data)):
		n.data += strings.Repeat("\x00", int(size)-len(n.data))
	}
	n.touch(now)
	return nil
}

// touch bumps the qid version and the mtime. A client that kept a qid can tell
// the file changed without reading it, which is the whole point of Qid.Version.
func (n *node) touch(now int64) {
	n.qid.Version++
	n.mtime = now
	n.muid = n.fs.uid
}

// MkdirAll creates p and every missing parent, and returns the leaf. An
// existing directory is not an error; an existing plain file on the path is.
func (fs *FS) MkdirAll(p string, now int64) (ninep.File, error) {
	cur := fs.root
	for _, e := range ninep.Elems(p) {
		v := cur.children.Get(e)
		if v == nil {
			f, err := cur.Create(e, ninep.DirPerm, now)
			if err != nil {
				return nil, err
			}
			cur = f.(*node)
			continue
		}
		cur = v.(*node)
		if !cur.perm.IsDir() {
			return nil, ninep.ErrNotDir
		}
	}
	return cur, nil
}

// WriteFile creates or replaces the file at p, creating parent directories as
// needed. It is the seeding helper a realm wants at init.
func (fs *FS) WriteFile(p, data string, now int64) error {
	dir, err := fs.MkdirAll(ninep.Dir(p), now)
	if err != nil {
		return err
	}
	name := ninep.Base(p)
	d := dir.(*node)
	v := d.children.Get(name)
	if v == nil {
		f, err := d.Create(name, ninep.FilePerm, now)
		if err != nil {
			return err
		}
		_, err = f.(*node).Write(0, data, now)
		return err
	}
	target := v.(*node)
	if err := target.Truncate(0, now); err != nil {
		return err
	}
	_, err = target.Write(0, data, now)
	return err
}

package memfs

import (
	"testing"

	ninep "gno.land/p/moul/x/plan9/ninep/v0"
)

func TestRootStat(t *testing.T) {
	fs := New("glenda", 100)
	s := fs.Root().Stat()
	if s.Name != "/" {
		t.Errorf("root name: got %q", s.Name)
	}
	if !s.IsDir() {
		t.Error("root should be a directory")
	}
	if s.Length != 0 {
		t.Errorf("a directory reports length 0 in 9P, got %d", s.Length)
	}
	if s.Uid != "glenda" || s.Gid != "glenda" {
		t.Errorf("owner: got %q/%q", s.Uid, s.Gid)
	}
	if s.Mtime != 100 {
		t.Errorf("mtime: got %d, want 100", s.Mtime)
	}
}

func TestCreateWalkRead(t *testing.T) {
	fs := New("glenda", 1)
	root := fs.RootMutable()

	f, err := root.Create("greeting", ninep.FilePerm, 2)
	if err != nil {
		t.Fatalf("create: %v", err)
	}
	m := f.(ninep.Mutable)
	n, err := m.Write(0, "hello world", 3)
	if err != nil {
		t.Fatalf("write: %v", err)
	}
	if n != 11 {
		t.Errorf("wrote %d bytes, want 11", n)
	}

	got, err := root.Walk("greeting")
	if err != nil {
		t.Fatalf("walk: %v", err)
	}
	data, err := ninep.ReadAll(got)
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	if data != "hello world" {
		t.Errorf("read back %q", data)
	}
	if l := got.Stat().Length; l != 11 {
		t.Errorf("length %d, want 11", l)
	}
}

func TestWalkErrors(t *testing.T) {
	fs := New("glenda", 1)
	root := fs.RootMutable()
	root.Create("file", ninep.FilePerm, 1)

	if _, err := root.Walk("absent"); err != ninep.ErrNotExist {
		t.Errorf("missing name: got %v, want ErrNotExist", err)
	}
	if _, err := root.Walk("a/b"); err != ninep.ErrBadName {
		t.Errorf("slash in name: got %v, want ErrBadName", err)
	}
	f, _ := root.Walk("file")
	if _, err := f.Walk("x"); err != ninep.ErrNotDir {
		t.Errorf("walk through a file: got %v, want ErrNotDir", err)
	}
	if _, err := f.ReadDir(); err != ninep.ErrNotDir {
		t.Errorf("readdir of a file: got %v, want ErrNotDir", err)
	}
	if _, err := root.Read(0, -1); err != ninep.ErrIsDir {
		t.Errorf("read of a directory: got %v, want ErrIsDir", err)
	}
}

func TestReadDirIsOrdered(t *testing.T) {
	fs := New("glenda", 1)
	root := fs.RootMutable()
	for _, name := range []string{"zulu", "alpha", "mike", "bravo"} {
		if _, err := root.Create(name, ninep.FilePerm, 1); err != nil {
			t.Fatalf("create %s: %v", name, err)
		}
	}
	ents, err := root.ReadDir()
	if err != nil {
		t.Fatalf("readdir: %v", err)
	}
	want := []string{"alpha", "bravo", "mike", "zulu"}
	if len(ents) != len(want) {
		t.Fatalf("got %d entries, want %d", len(ents), len(want))
	}
	for i, w := range want {
		if ents[i].Name != w {
			t.Errorf("entry %d: got %q, want %q", i, ents[i].Name, w)
		}
	}
}

func TestCreateDuplicate(t *testing.T) {
	fs := New("glenda", 1)
	root := fs.RootMutable()
	root.Create("x", ninep.FilePerm, 1)
	if _, err := root.Create("x", ninep.FilePerm, 1); err != ninep.ErrExist {
		t.Errorf("got %v, want ErrExist", err)
	}
	if _, err := root.Create("", ninep.FilePerm, 1); err != ninep.ErrBadName {
		t.Errorf("empty name: got %v, want ErrBadName", err)
	}
	if _, err := root.Create("..", ninep.FilePerm, 1); err != ninep.ErrBadName {
		t.Errorf("dotdot: got %v, want ErrBadName", err)
	}
}

func TestRemove(t *testing.T) {
	fs := New("glenda", 1)
	root := fs.RootMutable()
	root.Create("file", ninep.FilePerm, 1)
	d, _ := root.Create("dir", ninep.DirPerm, 1)
	d.(ninep.Mutable).Create("inner", ninep.FilePerm, 1)

	if err := root.Remove("absent"); err != ninep.ErrNotExist {
		t.Errorf("remove missing: got %v", err)
	}
	if err := root.Remove("dir"); err != ninep.ErrNotEmpty {
		t.Errorf("remove non-empty dir: got %v, want ErrNotEmpty", err)
	}
	if err := d.(ninep.Mutable).Remove("inner"); err != nil {
		t.Fatalf("remove inner: %v", err)
	}
	if err := root.Remove("dir"); err != nil {
		t.Fatalf("remove emptied dir: %v", err)
	}
	if err := root.Remove("file"); err != nil {
		t.Fatalf("remove file: %v", err)
	}
	ents, _ := root.ReadDir()
	if len(ents) != 0 {
		t.Errorf("root should be empty, has %d entries", len(ents))
	}
}

func TestWriteOffsets(t *testing.T) {
	tests := []struct {
		name  string
		start string
		off   int64
		data  string
		want  string
	}{
		{"append at end", "abc", 3, "def", "abcdef"},
		{"overwrite middle", "abcdef", 2, "XY", "abXYef"},
		{"overwrite past end", "abc", 2, "XYZ", "abXYZ"},
		{"from zero", "abcdef", 0, "ZZ", "ZZcdef"},
		{"gap is nul filled", "ab", 4, "Z", "ab\x00\x00Z"},
		{"negative offset clamps", "abc", -2, "Z", "Zbc"},
	}
	for _, tt := range tests {
		fs := New("glenda", 1)
		root := fs.RootMutable()
		f, _ := root.Create("f", ninep.FilePerm, 1)
		m := f.(ninep.Mutable)
		m.Write(0, tt.start, 1)
		m.Write(tt.off, tt.data, 2)
		got, _ := ninep.ReadAll(f)
		if got != tt.want {
			t.Errorf("%s: got %q, want %q", tt.name, got, tt.want)
		}
	}
}

func TestAppendOnlyIgnoresOffset(t *testing.T) {
	fs := New("glenda", 1)
	root := fs.RootMutable()
	f, _ := root.Create("log", ninep.DMAPPEND|0644, 1)
	m := f.(ninep.Mutable)
	m.Write(0, "one\n", 1)
	m.Write(0, "two\n", 2) // offset 0, but append-only pins it to the end
	got, _ := ninep.ReadAll(f)
	if got != "one\ntwo\n" {
		t.Errorf("got %q", got)
	}
}

func TestTruncate(t *testing.T) {
	fs := New("glenda", 1)
	root := fs.RootMutable()
	f, _ := root.Create("f", ninep.FilePerm, 1)
	m := f.(ninep.Mutable)
	m.Write(0, "abcdef", 1)

	m.Truncate(3, 2)
	if got, _ := ninep.ReadAll(f); got != "abc" {
		t.Errorf("shrink: got %q", got)
	}
	m.Truncate(5, 3)
	if got, _ := ninep.ReadAll(f); got != "abc\x00\x00" {
		t.Errorf("grow: got %q", got)
	}
	m.Truncate(0, 4)
	if got, _ := ninep.ReadAll(f); got != "" {
		t.Errorf("zero: got %q", got)
	}
}

func TestQidVersionAndPath(t *testing.T) {
	fs := New("glenda", 1)
	root := fs.RootMutable()
	a, _ := root.Create("a", ninep.FilePerm, 1)
	b, _ := root.Create("b", ninep.FilePerm, 1)

	if a.Stat().Qid.Path == b.Stat().Qid.Path {
		t.Error("two files share a qid path")
	}
	v0 := a.Stat().Qid.Version
	a.(ninep.Mutable).Write(0, "x", 2)
	if a.Stat().Qid.Version != v0+1 {
		t.Errorf("version did not advance on write: %d -> %d", v0, a.Stat().Qid.Version)
	}
	if a.Stat().Mtime != 2 {
		t.Errorf("mtime: got %d, want 2", a.Stat().Mtime)
	}
}

func TestMkdirAllAndWriteFile(t *testing.T) {
	fs := New("glenda", 1)
	if _, err := fs.MkdirAll("/usr/glenda/lib", 1); err != nil {
		t.Fatalf("mkdirall: %v", err)
	}
	// idempotent
	if _, err := fs.MkdirAll("/usr/glenda", 1); err != nil {
		t.Fatalf("mkdirall again: %v", err)
	}
	if err := fs.WriteFile("/usr/glenda/lib/profile", "font=pelm\n", 2); err != nil {
		t.Fatalf("writefile: %v", err)
	}
	f, err := ninep.Walk(fs.Root(), ninep.Elems("/usr/glenda/lib/profile"))
	if err != nil {
		t.Fatalf("walk: %v", err)
	}
	if got, _ := ninep.ReadAll(f); got != "font=pelm\n" {
		t.Errorf("got %q", got)
	}
	// rewriting replaces rather than appends
	if err := fs.WriteFile("/usr/glenda/lib/profile", "font=lucida\n", 3); err != nil {
		t.Fatalf("rewrite: %v", err)
	}
	f, _ = ninep.Walk(fs.Root(), ninep.Elems("/usr/glenda/lib/profile"))
	if got, _ := ninep.ReadAll(f); got != "font=lucida\n" {
		t.Errorf("rewrite got %q", got)
	}
}

func TestMkdirAllThroughAFileFails(t *testing.T) {
	fs := New("glenda", 1)
	fs.WriteFile("/etc", "not a directory", 1)
	if _, err := fs.MkdirAll("/etc/passwd", 2); err != ninep.ErrNotDir {
		t.Errorf("got %v, want ErrNotDir", err)
	}
}

func TestWalkDepthLimit(t *testing.T) {
	fs := New("glenda", 1)
	elems := []string{}
	for i := 0; i <= ninep.MaxDepth; i++ {
		elems = append(elems, "x")
	}
	if _, err := ninep.Walk(fs.Root(), elems); err != ninep.ErrTooDeep {
		t.Errorf("got %v, want ErrTooDeep", err)
	}
}

// Package ns is a Plan 9 namespace: a private, mutable mount table over
// gno.land/p/moul/x/plan9/ninep file trees.
//
// This is the idea the rest of the suite exists for. Plan 9's leverage does
// not come from "everything is a file", it comes from every process owning its
// own name-to-resource mapping, so a name can be REPLACED and any service can
// be composed, shadowed, sandboxed or mocked without the program knowing. Gno
// has one global tree and no way to hold a view of it; an Ns is that view.
//
// Bind flags follow bind(2): MREPL replaces, MBEFORE splices the new directory
// in front of the old one, MAFTER behind it, and MCREATE (OR'd onto any of
// them) marks the union member that new files are created in.
//
// Two Plan 9 properties are load-bearing and reproduced deliberately:
//
//   - A union is TOP LEVEL ONLY. Binding /a onto /b unions the two directories
//     at /b; /b/c resolves in whichever member won the walk, and is not itself
//     a union unless something is bound there too.
//   - A bind captures a CHANNEL, not a name. The source is resolved once, at
//     bind time, and the resulting file is what is stored. Rebinding the
//     source afterwards does not retroactively move the target.
//
// ".." is removed lexically before resolution starts and never reaches a
// server, per "Lexical File Names in Plan 9, or Getting Dot-Dot Right".
//
// NOTICE. Plan 9 from Bell Labs is the work of the Computing Science Research
// Center at Bell Labs; the name and the marks are theirs, and the copyright is
// held by the Plan 9 Foundation (https://p9f.org). This package is not
// affiliated with, endorsed by, or sponsored by them, and contains no Plan 9
// code: it borrows the vocabulary so that the design reads without a glossary,
// and it is an homage, asking what that ecosystem's spirit looks like on a
// chain. Full attribution: NOTICE.md at the root of moul/gno-contracts.
package ns

import (
	"errors"
	"strings"

	"gno.land/p/nt/avl/v0"

	ninep "gno.land/p/moul/x/plan9/ninep/v0"
)

// Flag is a bind(2) mount flag. The low two bits pick the mode; MCREATE is
// OR'd onto it.
type Flag uint32

// Mount flags, with Plan 9's values.
const (
	MREPL   Flag = 0x0000 // replace the old file with the new one
	MBEFORE Flag = 0x0001 // union, new directory first
	MAFTER  Flag = 0x0002 // union, new directory last
	MCREATE Flag = 0x0004 // creates in this union go here
)

func (f Flag) mode() Flag    { return f & 0x0003 }
func (f Flag) creates() bool { return f&MCREATE != 0 }

// String renders the flag as the command-line letters bind(1) uses.
func (f Flag) String() string {
	s := ""
	switch f.mode() {
	case MBEFORE:
		s = "-b"
	case MAFTER:
		s = "-a"
	}
	if f.creates() {
		if s == "" {
			s = "-c"
		} else {
			s += "c"
		}
	}
	return s
}

// Limits. Resolution costs one call per element per union member, and those
// calls may cross a realm boundary, so both are capped rather than trusted.
const (
	MaxUnion = 8 // members in one union
	MaxOps   = 64
)

var (
	// ErrNoRoot means the namespace has nothing bound at "/".
	ErrNoRoot = errors.New("no root in namespace")
	// ErrWideUnion means a bind would exceed MaxUnion members.
	ErrWideUnion = errors.New("union too wide")
	// ErrTooManyOps means the namespace has reached MaxOps bindings.
	ErrTooManyOps = errors.New("too many namespace operations")
	// ErrNotBound means unmount was asked to remove something that is not
	// bound at that name.
	ErrNotBound = errors.New("not bound")
)

// member is one element of a union. A nil file is the placeholder standing for
// "whatever walking to this name would have found", which is how MBEFORE and
// MAFTER keep the original directory in the union.
type member struct {
	file   ninep.File
	create bool
}

type entry struct {
	members []member
}

// Op records one bind or mount, in application order, so that String can print
// the namespace the way Plan 9's ns(1) does.
type Op struct {
	Verb   string // "bind" or "mount"
	Flag   Flag
	Source string
	Target string
}

// Ns is one namespace: a mount table, a working directory, and the ordered
// list of operations that produced them.
type Ns struct {
	table *avl.Tree // cleaned target path -> *entry
	ops   []Op
	cwd   string
}

// New returns a namespace whose root is the given file. The root is the one
// binding that cannot be expressed as a bind of something else, so it is
// installed directly.
func New(root ninep.File) *Ns {
	n := &Ns{table: avl.NewTree(), cwd: "/"}
	n.table.Set("/", &entry{members: []member{{file: root, create: true}}})
	return n
}

// Cwd returns the working directory.
func (n *Ns) Cwd() string { return n.cwd }

// Cd sets the working directory, which must resolve to a directory.
func (n *Ns) Cd(p string) error {
	abs := n.Abs(p)
	st, err := n.Stat(abs)
	if err != nil {
		return err
	}
	if !st.IsDir() {
		return ninep.ErrNotDir
	}
	n.cwd = abs
	return nil
}

// Abs resolves p against the working directory.
func (n *Ns) Abs(p string) string { return ninep.Abs(n.cwd, p) }

func (n *Ns) entry(p string) *entry {
	v := n.table.Get(p)
	if v == nil {
		return nil
	}
	return v.(*entry)
}

// expand substitutes the walk result for the placeholder member.
func expand(ms []member, under []member) []member {
	out := []member{}
	for _, m := range ms {
		if m.file == nil {
			out = append(out, under...)
			continue
		}
		out = append(out, m)
	}
	return out
}

// resolve walks p and returns the union found there, richest form: members
// still carry their create bit, and bound reports whether a mount entry
// applied at the final element.
func (n *Ns) resolve(p string) ([]member, error) {
	root := n.entry("/")
	if root == nil {
		return nil, ErrNoRoot
	}
	cur := expand(root.members, nil)
	if len(cur) == 0 {
		return nil, ErrNoRoot
	}
	elems := ninep.Elems(ninep.Clean(p))
	if len(elems) > ninep.MaxDepth {
		return nil, ninep.ErrTooDeep
	}
	prefix := ""
	for _, e := range elems {
		// First match wins. Walking INTO a union does not produce a union
		// of the members' subdirectories: in Plan 9 a union is top level
		// only, and a walk returns one channel.
		walked := []member{}
		for _, m := range cur {
			f, err := m.file.Walk(e)
			if err == nil {
				walked = append(walked, member{file: f})
				break
			}
		}
		prefix += "/" + e
		next := walked
		if ent := n.entry(prefix); ent != nil {
			next = expand(ent.members, walked)
		}
		if len(next) == 0 {
			return nil, ninep.ErrNotExist
		}
		cur = next
	}
	return cur, nil
}

// Resolve returns every union member visible at p, in search order.
func (n *Ns) Resolve(p string) ([]ninep.File, error) {
	ms, err := n.resolve(n.Abs(p))
	if err != nil {
		return nil, err
	}
	out := []ninep.File{}
	for _, m := range ms {
		out = append(out, m.file)
	}
	return out, nil
}

// Open returns the file a name resolves to: the first member of its union,
// which is the one a walk through this name would reach.
func (n *Ns) Open(p string) (ninep.File, error) {
	fs, err := n.Resolve(p)
	if err != nil {
		return nil, err
	}
	return fs[0], nil
}

// Stat returns the entry for p, with the name replaced by the last element of
// the path as asked for, so that a union member's own name never leaks.
func (n *Ns) Stat(p string) (ninep.Stat, error) {
	f, err := n.Open(p)
	if err != nil {
		return ninep.Stat{}, err
	}
	st := f.Stat()
	st.Name = ninep.Base(n.Abs(p))
	return st, nil
}

// ReadFile reads the whole file at p.
func (n *Ns) ReadFile(p string) (string, error) {
	f, err := n.Open(p)
	if err != nil {
		return "", err
	}
	return ninep.ReadAll(f)
}

// ReadDir lists p. A union directory is the CONCATENATION of its members'
// contents, as in Plan 9, so duplicate names can appear and shadowing is
// visible. Pass unique to collapse them first-wins instead, which is the set
// of names a walk can actually reach.
func (n *Ns) ReadDir(p string, unique bool) ([]ninep.Stat, error) {
	ms, err := n.resolve(n.Abs(p))
	if err != nil {
		return nil, err
	}
	if len(ms) == 1 && !ms[0].file.Stat().IsDir() {
		return nil, ninep.ErrNotDir
	}
	out := []ninep.Stat{}
	seen := map[string]bool{}
	for _, m := range ms {
		ents, err := m.file.ReadDir()
		if err != nil {
			continue // a non-directory member contributes nothing
		}
		for _, e := range ents {
			if unique {
				if seen[e.Name] {
					continue
				}
				seen[e.Name] = true
			}
			out = append(out, e)
		}
	}
	return out, nil
}

// CreateTarget returns the directory that a create at p should happen in.
//
// For a plain directory that is just the directory. For a union it is the
// first member carrying MCREATE, and if no member has it, creation is refused,
// which is bind(2)'s rule.
func (n *Ns) CreateTarget(p string) (ninep.Mutable, error) {
	abs := n.Abs(p)
	ms, err := n.resolve(abs)
	if err != nil {
		return nil, err
	}
	isUnion := n.entry(abs) != nil && len(ms) > 1
	for _, m := range ms {
		if isUnion && !m.create {
			continue
		}
		mu, ok := m.file.(ninep.Mutable)
		if !ok {
			continue // a read-only server, for instance a mounted realm
		}
		if !mu.Stat().IsDir() {
			continue
		}
		return mu, nil
	}
	if isUnion {
		return nil, ninep.ErrNoCreate
	}
	return nil, ninep.ErrPerm
}

// Bind makes source visible at target, as bind(1) does. Both names are
// resolved in THIS namespace, and the source is resolved once: what is stored
// is the file it names today, not the name.
func (n *Ns) Bind(source, target string, flag Flag) error {
	return n.BindVerb("bind", source, target, flag)
}

// BindVerb is Bind with the verb that String should print. Plan 9 spells the
// same operation "bind" or "mount" depending on whether the source is a name
// or a channel, and ns(1) echoes back whichever was used.
func (n *Ns) BindVerb(verb, source, target string, flag Flag) error {
	ms, err := n.resolve(n.Abs(source))
	if err != nil {
		return err
	}
	files := []ninep.File{}
	for _, m := range ms {
		files = append(files, m.file)
	}
	return n.graft(verb, source, target, flag, files)
}

// Mount grafts a file tree that has no name in this namespace yet, which is
// how a service posted by another realm gets in. source is a label, used only
// when printing the namespace.
func (n *Ns) Mount(f ninep.File, source, target string, flag Flag) error {
	return n.graft("mount", source, target, flag, []ninep.File{f})
}

func (n *Ns) graft(verb, source, target string, flag Flag, files []ninep.File) error {
	if len(n.ops) >= MaxOps {
		return ErrTooManyOps
	}
	abs := n.Abs(target)
	// bind(1) requires the target to exist: you can only rebind a name that
	// already resolves to something.
	if _, err := n.resolve(abs); err != nil {
		return err
	}
	add := []member{}
	for _, f := range files {
		add = append(add, member{file: f, create: flag.creates()})
	}

	ent := n.entry(abs)
	var members []member
	switch {
	case ent == nil:
		// The name has never been bound: its current contents are the
		// placeholder. It does NOT carry MCREATE, which is why creating
		// in a freshly unioned directory is refused until some member is
		// bound with -c.
		members = []member{{file: nil}}
	default:
		members = ent.members
	}
	switch flag.mode() {
	case MBEFORE:
		members = append(add, members...)
	case MAFTER:
		members = append(members, add...)
	default: // MREPL: the old file is gone, not unioned
		members = add
	}
	if len(members) > MaxUnion {
		return ErrWideUnion
	}
	n.table.Set(abs, &entry{members: members})
	n.ops = append(n.ops, Op{Verb: verb, Flag: flag, Source: source, Target: abs})
	return nil
}

// Unmount undoes bindings at target. With an empty source it removes every
// binding there, restoring the name to whatever it resolved to originally.
func (n *Ns) Unmount(source, target string) error {
	abs := n.Abs(target)
	ent := n.entry(abs)
	if ent == nil {
		return ErrNotBound
	}
	if source == "" {
		n.table.Remove(abs)
		n.dropOps(abs, "")
		return nil
	}
	ms, err := n.resolve(n.Abs(source))
	if err != nil {
		return err
	}
	kept := []member{}
	removed := false
	for _, m := range ent.members {
		drop := false
		for _, s := range ms {
			if m.file != nil && m.file == s.file {
				drop = true
				break
			}
		}
		if drop {
			removed = true
			continue
		}
		kept = append(kept, m)
	}
	if !removed {
		return ErrNotBound
	}
	if onlyPlaceholders(kept) {
		// Nothing but "whatever was here originally" is left, so the entry
		// is a no-op: drop it rather than leave a phantom binding behind.
		n.table.Remove(abs)
	} else {
		n.table.Set(abs, &entry{members: kept})
	}
	n.dropOps(abs, source)
	return nil
}

func onlyPlaceholders(ms []member) bool {
	for _, m := range ms {
		if m.file != nil {
			return false
		}
	}
	return true
}

func (n *Ns) dropOps(target, source string) {
	kept := []Op{}
	for _, op := range n.ops {
		if op.Target == target && (source == "" || op.Source == source) {
			continue
		}
		kept = append(kept, op)
	}
	n.ops = kept
}

// Ops returns the bindings in application order.
func (n *Ns) Ops() []Op { return n.ops }

// String prints the namespace the way Plan 9's ns(1) does: one line per
// binding, in the order they were applied, then the working directory.
func (n *Ns) String() string {
	var b strings.Builder
	for _, op := range n.ops {
		b.WriteString(op.Verb)
		if f := op.Flag.String(); f != "" {
			b.WriteString(" " + f)
		}
		b.WriteString(" " + quote(op.Source) + " " + quote(op.Target) + "\n")
	}
	b.WriteString("cd " + quote(n.cwd) + "\n")
	return b.String()
}

// quote applies rc quoting: single quotes when the word contains a space or a
// quote, with an embedded quote doubled.
func quote(s string) string {
	if s != "" && !strings.ContainsAny(s, " \t'") {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

package ns

import (
	"testing"

	memfs "gno.land/p/moul/x/plan9/memfs/v0"
	ninep "gno.land/p/moul/x/plan9/ninep/v0"
)

// newNs builds a namespace over a fresh ram tree seeded with files.
func newNs(t *testing.T, files ...string) (*Ns, *memfs.FS) {
	t.Helper()
	fs := memfs.New("glenda", 1)
	for _, f := range files {
		if err := fs.WriteFile(f, "contents of "+f+"\n", 1); err != nil {
			t.Fatalf("seed %s: %v", f, err)
		}
	}
	return New(fs.Root()), fs
}

func names(ents []ninep.Stat) []string {
	out := []string{}
	for _, e := range ents {
		out = append(out, e.Name)
	}
	return out
}

func eq(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func TestResolveRoot(t *testing.T) {
	n, _ := newNs(t, "/bin/ls", "/bin/cat")
	st, err := n.Stat("/")
	if err != nil {
		t.Fatalf("stat root: %v", err)
	}
	if !st.IsDir() {
		t.Error("root is not a directory")
	}
	ents, err := n.ReadDir("/", false)
	if err != nil {
		t.Fatalf("readdir: %v", err)
	}
	if !eq(names(ents), []string{"bin"}) {
		t.Errorf("root listing: %v", names(ents))
	}
}

func TestReadFileAndMissing(t *testing.T) {
	n, _ := newNs(t, "/bin/ls")
	got, err := n.ReadFile("/bin/ls")
	if err != nil {
		t.Fatalf("readfile: %v", err)
	}
	if got != "contents of /bin/ls\n" {
