// v1 asserted that its own padID() padded to width 6. That is the narrowest
// ceiling in this repo: padID(10^6) is 7 characters and sorts before
// padID(10^6-1), so from the millionth piece on the gallery would have
// rendered out of order. The store key is 8 bytes for every id.
func TestPadID(t *testing.T) {
	if a, b := store.ID(2).Key(), store.ID(10).Key(); !(a < b) {
		t.Error("id 2 should sort before id 10")
	}
	if a, b := store.ID(999999).Key(), store.ID(1000000).Key(); !(a < b) {
		t.Error("ordering should survive one past v1's width-6 ceiling")
	}
}

// Crossing: Generate mutates realm state, so the test needs `cur realm`.
func TestGenerateAddsToGallery(cur realm, t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	art := Generate(cross(cur), "checker", 3)
	if art != RenderChecker(3) {
		t.Fatal("Generate should return the rendered art")
	}
	if gallery.LastID() != 1 {
		t.Fatalf("LastID = %s, want 1", gallery.LastID())
	}

	// The store's Get returns (value, ok), so a stored nil is distinguishable
	// from an absent id, which avl/v0's single-value Get cannot express.
	v, ok := gallery.Get(1)
	if !ok {
		t.Fatal("expected piece #1 to exist in the gallery")
	}
	p := v.(*piece)
	if p.Pattern != "checker" || p.Size != 3 || p.Author != alice {
		t.Fatalf("unexpected piece: %+v", p)
	}
}

func TestGenerateRejectsOutOfRangeSize(cur realm, t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	rec := revive(func() { Generate(cross(cur), "diamond", 0) })
	if rec == nil {
		t.Fatal("expected panic for size < 1")
	}
	rec = revive(func() { Generate(cross(cur), "diamond", maxSize+1) })
	if rec == nil {
		t.Fatal("expected panic for size > maxSize")
	}
}

// Non-crossing: Render is a plain read.
func TestRenderHomeEmptyGallery(t *testing.T) {
	resetState()
	out := Render("")
	if !strings.Contains(out, "nothing generated yet") {
		t.Fatal(`Render("") on an empty gallery should say so`)
	}
}

func TestRenderPieceNotFound(t *testing.T) {
	resetState()
	out := Render("99")
	if !strings.Contains(out, "No such piece") {
		t.Fatal(`Render("99") on a missing piece should say so`)
	}
}

// Package blog is a multi-author on-chain blog realm for gno.land.
//
// Any caller can Publish a post; posts are stored persistently and rendered
// newest-first. Each post records its author (the calling address) and the
// block height at which it was published.
package blog

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/moul/kit/store/v0"
)

// Post is a single blog entry. It carries no id field: the id belongs to the
// store, which hands it back on lookup and iteration.
type Post struct {
	Title  string
	Body   string
	Author address
	Height int64
}

// posts holds every published post. The store keys by seqid, so iteration is
// in publication order for any number of posts; v0 kept its own nextID plus a
// key() that zero-padded to width 12 and stopped ordering past it.
var posts = store.Named("post")

// Publish creates a new post authored by the caller and returns its id.
// It is a state-mutating exported function, so it takes `cur realm`.
func Publish(cur realm, title string, body string) int {
	title = strings.TrimSpace(title)
	body = strings.TrimSpace(body)
	if title == "" {
		panic("blog: title must not be empty")
	}
	if body == "" {
		panic("blog: body must not be empty")
	}

	author := unsafe.PreviousRealm().Address()
	id := posts.Add(&Post{
		Title:  title,
		Body:   body,
		Author: author,
		Height: runtime.ChainHeight(),
	})

	chain.Emit(
		"PostPublished",
		"id", id.String(),
		"author", author.String(),
	)
	return int(id)
}

// PostCount returns the number of published posts.
func PostCount() int {
	return posts.Len()
}

// snippet returns a short one-line preview of the body.
func snippet(body string) string {
	// collapse newlines so the preview stays on a single markdown line
	s := strings.ReplaceAll(body, "\n", " ")
	s = strings.TrimSpace(s)
	const max = 140
	if len(s) > max {
		return s[:max] + "…"
	}
	return s
}

// Render lists all posts newest-first at the root, or a single post's full
// text at path "/<id>". Render is NOT a crossing function.
func Render(path string) string {
	path = strings.TrimSpace(path)
	if path == "" || path == "/" {
		return renderList()
	}
	idStr := strings.TrimPrefix(path, "/")
	id, ok := store.ParseID(idStr)
	if !ok {
		return "# Not found\n\nInvalid post path: `" + path + "`\n\n[← back](/r/REPLACE_ADDR/blog)\n"
	}
	v, ok := posts.Get(id)
	if !ok {
		return "# Not found\n\nNo post with id " + idStr + ".\n\n[← back](/r/REPLACE_ADDR/blog)\n"
	}
	return renderPost(v.(*Post))
}

func renderList() string {
	var b strings.Builder
	b.WriteString("# 📝 Blog\n\n")
	if posts.Len() == 0 {
		b.WriteString("_No posts yet. Be the first to `Publish`._\n")
		return b.String()
	}
	b.WriteString(strconv.Itoa(posts.Len()) + " post(s), newest first.\n\n")

	// Ids ascend with publication, so reverse iteration is newest-first.
	posts.EachReverse(func(id store.ID, v any) {
		p := v.(*Post)
		b.WriteString("## [")
		b.WriteString(p.Title)
		b.WriteString("](/r/REPLACE_ADDR/blog:/")
		b.WriteString(id.String())
		b.WriteString(")\n\n")
		b.WriteString("by `")
		b.WriteString(p.Author.String())
		b.WriteString("` · height ")
		b.WriteString(strconv.FormatInt(p.Height, 10))
		b.WriteString("\n\n")
		b.WriteString(snippet(p.Body))
		b.WriteString("\n\n---\n\n")
	})
	return b.String()
}

func renderPost(p *Post) string {
	var b strings.Builder
	b.WriteString("# ")
	b.WriteString(p.Title)
	b.WriteString("\n\n")
	b.WriteString("by `")
	b.WriteString(p.Author.String())
	b.WriteString("` · height ")
	b.WriteString(strconv.FormatInt(p.Height, 10))
	b.WriteString("\n\n")
	b.WriteString(p.Body)
	b.WriteString("\n\n---\n\n[← back to all posts](/r/REPLACE_ADDR/blog)\n")
	return b.String()
}

package blog

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestPublishAndRender(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")

	testing.SetRealm(testing.NewUserRealm(alice))
	// Ids start at 1 in v1: the store never assigns 0, so the zero id stays
	// usable as "absent". v0 handed out 0 for the first post.
	id0 := Publish(cross(cur), "First Post", "Hello from alice.")
	uassert.Equal(t, 1, id0)

	testing.SetRealm(testing.NewUserRealm(bob))
	id1 := Publish(cross(cur), "Second Post", "A longer body\nwith a newline from bob.")
	uassert.Equal(t, 2, id1)

	uassert.Equal(t, 2, PostCount())

	// Root render lists both, newest (bob's) first.
	list := Render("")
	uassert.True(t, strings.Contains(list, "First Post"), "list has first post")
	uassert.True(t, strings.Contains(list, "Second Post"), "list has second post")
	uassert.True(t, strings.Index(list, "Second Post") < strings.Index(list, "First Post"),
		"newest post appears first")
	uassert.True(t, strings.Contains(list, alice.String()), "list shows alice author")

	// Single-post render shows full body + back link.
	single := Render("/2")
	uassert.True(t, strings.Contains(single, "newline from bob"), "full body shown")
	uassert.True(t, strings.Contains(single, "← back"), "back link present")

	// Unknown id.
	uassert.True(t, strings.Contains(Render("/99"), "Not found"), "missing post handled")

	// Id 0 is never assigned, so the path is rejected rather than looked up.
	uassert.True(t, strings.Contains(Render("/0"), "Invalid post path"), "id 0 is not a post")
	uassert.True(t, strings.Contains(Render("/abc"), "Invalid post path"), "a non-numeric path is rejected")
}

func TestPublishEmptyTitleAborts(cur realm, t *testing.T) {
	carol := testutils.TestAddress("carol")
	testing.SetRealm(testing.NewUserRealm(carol))

	uassert.AbortsWithMessage(t, cur, "blog: title must not be empty", func() {
		Publish(cross(cur), "   ", "some body")
	})
	uassert.AbortsWithMessage(t, cur, "blog: body must not be empty", func() {
		Publish(cross(cur), "a title", "")
	})
}

package connect4

import (
	"chain"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/kit/store/v0"
)

const (
	cols = 7
	rows = 6
)

// cell values
const (
	empty = 0
	red   = 1 // 🔴 game creator (caller of NewGame)
	yel   = 2 // 🟡 opponent
)

// Game holds the full state of one Connect Four match.
// board is indexed board[row][col]; row 0 is the BOTTOM row.
// It carries no ID field: the id belongs to the store, which hands it back on
// lookup and iteration.
type Game struct {
	Red      address // 🔴 creator, moves first
	Yellow   address // 🟡 opponent
	Board    [rows][cols]int
	Turn     int  // whose turn: red or yel
	Winner   int  // empty until decided; red/yel = winner
	Draw     bool // true when board full with no winner
	Finished bool
}

// games assigns the game ids. v1 kept its own nextID plus an idKey() that
// zero-padded to width 12, which stopped ordering the Render list past 10^12.
var games = store.Named("game")

// NewGame creates a match between the caller (🔴) and opponent (🟡).
// Returns the new game id.
func NewGame(cur realm, opponent address) int64 {
	caller := unsafe.PreviousRealm().Address()
	if opponent == caller {
		panic("opponent must differ from caller")
	}
	if opponent.String() == "" {
		panic("opponent address is empty")
	}
	id := games.Add(&Game{
		Red:    caller,
		Yellow: opponent,
		Turn:   red,
	})
	chain.Emit("GameCreated",
		"id", id.String(),
		"red", caller.String(),
		"yellow", opponent.String(),
	)
	return int64(id)
}

func getGame(id int64) (*Game, error) {
	v, ok := games.Get(store.ID(id))
	if !ok {
		return nil, errors.New("game not found: " + strconv.FormatInt(id, 10))
	}
	return v.(*Game), nil
}

// Drop places the caller's disc into the given column (0-6).
// Enforces turn order by caller, rejects full columns, and detects
// a 4-in-a-row win or a draw.
func Drop(cur realm, gameID int64, column int) {
	if column < 0 || column >= cols {
		panic("column out of range (0-6)")
	}
	g, err := getGame(gameID)
	if err != nil {
		panic(err.Error())
	}
	if g.Finished {
		panic("game already finished")
	}

	caller := unsafe.PreviousRealm().Address()
	var mover int
	switch caller {
	case g.Red:
		mover = red
	case g.Yellow:
		mover = yel
	default:
		panic("caller is not a player in this game")
	}
	if mover != g.Turn {
		panic("not your turn")
	}

	// find lowest empty row in the column
	placed := -1
	for r := 0; r < rows; r++ {
		if g.Board[r][column] == empty {
			g.Board[r][column] = mover
			placed = r
			break
		}
	}
	if placed == -1 {
		panic("column is full")
	}

	if wins(&g.Board, placed, column, mover) {
		g.Winner = mover
		g.Finished = true
		chain.Emit("GameWon",
			"id", strconv.FormatInt(gameID, 10),
			"winner", caller.String(),
		)
	} else if full(&g.Board) {
		g.Draw = true
		g.Finished = true
		chain.Emit("GameDraw", "id", strconv.FormatInt(gameID, 10))
	} else {
		if g.Turn == red {
			g.Turn = yel
		} else {
			g.Turn = red
		}
		chain.Emit("DiscDropped",
			"id", strconv.FormatInt(gameID, 10),
			"col", strconv.Itoa(column),
			"player", caller.String(),
		)
	}

}

func full(b *[rows][cols]int) bool {
	for c := 0; c < cols; c++ {
		if b[rows-1][c] == empty {
			return false
		}
	}
	return true
}

// wins checks whether the disc just placed at (r,c) for player p completes
// a run of 4 in any of the four directions.
func wins(b *[rows][cols]int, r, c, p int) bool {
	// direction pairs: horizontal, vertical, diag /, diag \
	dirs := [4][2]int{{0, 1}, {1, 0}, {1, 1}, {1, -1}}
	for _, d := range dirs {
		count := 1
		count += run(b, r, c, d[0], d[1], p)
		count += run(b, r, c, -d[0], -d[1], p)
		if count >= 4 {
			return true
		}
	}
	return false
}

func run(b *[rows][cols]int, r, c, dr, dc, p int) int {
	n := 0
	for i := 1; i < 4; i++ {
		rr := r + dr*i
		cc := c + dc*i
		if rr < 0 || rr >= rows || cc < 0 || cc >= cols {
			break
		}
		if b[rr][cc] != p {
			break
		}
		n++
	}
	return n
}

func glyph(v int) string {
	switch v {
	case red:
		return "🔴"
	case yel:
		return "🟡"
	default:
		return "·"
	}
}

// Render draws the board with 🔴🟡· and shows whose turn / the winner.
// path "" lists all games; path "<id>" shows a single board.
func Render(path string) string {
	path = strings.TrimSpace(strings.Trim(path, "/"))
	if path == "" {
		return renderList()
	}
	id, ok := store.ParseID(path)
	if !ok {
		return "# Connect Four\n\nInvalid game id: `" + path + "`\n"
	}
	g, err := getGame(int64(id))
	if err != nil {
		return "# Connect Four\n\n" + err.Error() + "\n"
	}
	return renderGame(id, g)
}

func renderList() string {
	var sb strings.Builder
	sb.WriteString("# Connect Four\n\n")
	sb.WriteString("Two-player Connect Four on a 7×6 board. 🔴 is the game creator, 🟡 the opponent.\n\n")
	if games.Len() == 0 {
		sb.WriteString("_No games yet. Call `NewGame(opponent)` to start one._\n")
		return sb.String()
	}
	sb.WriteString("## Games\n\n")
	sb.WriteString("| ID | 🔴 Red | 🟡 Yellow | Status |\n")
	sb.WriteString("|----|--------|-----------|--------|\n")
	games.Each(func(id store.ID, v any) {
		g := v.(*Game)
		status := ""
		switch {
		case g.Winner == red:
			status = "🔴 won"
		case g.Winner == yel:
			status = "🟡 won"
		case g.Draw:
			status = "draw"
		case g.Turn == red:
			status = "🔴 to move"
		default:
			status = "🟡 to move"
		}
		sb.WriteString("| [" + id.String() + "](/r:" + id.String() + ") | " +
			ui.Addr(g.Red) + " | " + ui.Addr(g.Yellow) + " | " + status + " |\n")
	})
	sb.WriteString("\nOpen a game by its id (e.g. path `1`).\n")
	return sb.String()
}

func renderGame(id store.ID, g *Game) string {
	var sb strings.Builder
	sb.WriteString("# Connect Four — Game " + id.String() + "\n\n")
	sb.WriteString("- 🔴 Red: `" + g.Red.String() + "`\n")
	sb.WriteString("- 🟡 Yellow: `" + g.Yellow.String() + "`\n\n")

	// status line
	switch {
	case g.Winner == red:
		sb.WriteString("**🔴 Red wins!**\n\n")
	case g.Winner == yel:
		sb.WriteString("**🟡 Yellow wins!**\n\n")
	case g.Draw:
		sb.WriteString("**Draw — board full.**\n\n")
	case g.Turn == red:
		sb.WriteString("**Turn: 🔴 Red**\n\n")
	default:
		sb.WriteString("**Turn: 🟡 Yellow**\n\n")
	}

	// board top-down (row rows-1 at top, row 0 at bottom)
	sb.WriteString("```\n")
	for r := rows - 1; r >= 0; r-- {
		for c := 0; c < cols; c++ {
			sb.WriteString(glyph(g.Board[r][c]))
		}
		sb.WriteString("\n")
	}
	// column indices
	for c := 0; c < cols; c++ {
		sb.WriteString(strconv.Itoa(c))
	}
	sb.WriteString("\n```\n\n")

	if !g.Finished {
		sb.WriteString("Drop a disc: `Drop(" + id.String() + ", <col 0-6>)`\n")
	}
	return sb.String()
}

