// Package todos is a shared, on-chain to-do board realm.
//
// Anyone can add an item; the caller's address is recorded as the author.
// Items can be toggled (open/done) or removed. Render exposes the board as
// Markdown checkboxes with open/done counts, newest item first.
package todos

import (
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/kit/store/v0"
)

// item is one entry on the board. `address` is the uverse bech32 type — it is
// persistable (unlike a `realm` value), so it is safe to store across txs.
// It carries no id field: the id belongs to the store, which hands it back on
// lookup and iteration.
type item struct {
	text   string
	done   bool
	author address
}

// items assigns the item ids. v1 kept its own nextID plus an idKey() that
// zero-padded to width 12, which stopped ordering Render past 10^12.
var items = store.Named("todos: item")

// Add appends a new item authored by the caller and returns its id.
//
// Crossing function: takes `cur realm` first (gno 0.9 interrealm convention),
// authenticates with cur.IsCurrent() before trusting cur.Previous().
func Add(cur realm, text string) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	text = strings.TrimSpace(text)
	if text == "" {
		panic("todos: text must not be empty")
	}

	author := cur.Previous().Address()

	return int(items.Add(&item{
		text:   text,
		done:   false,
		author: author,
	}))
}

// Toggle flips the done state of the item with the given id.
func Toggle(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	it := items.MustGet(store.ID(id)).(*item)
	it.done = !it.done
}

// Remove deletes the item with the given id.
func Remove(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if _, removed := items.Remove(store.ID(id)); !removed {
		panic("todos: item #" + strconv.Itoa(id) + " not found")
	}
}

// counts returns the number of open and done items.
func counts() (open, done int) {
	items.Each(func(_ store.ID, v any) {
		if v.(*item).done {
			done++
		} else {
			open++
		}
	})
	return open, done
}

// Render returns the board as Markdown. Newest item (highest id) first.
//
// Render is NOT a crossing function (no `cur realm` param) — it is read-only
// and invoked by gnoweb, not via MsgCall.
func Render(path string) string {
	open, done := counts()

	var b strings.Builder
	b.WriteString("# Shared To-Do Board\n\n")
	b.WriteString(strconv.Itoa(open) + " open · ")
	b.WriteString(strconv.Itoa(done) + " done · ")
	b.WriteString(strconv.Itoa(open+done) + " total\n\n")

	if open+done == 0 {
		b.WriteString("_No items yet. Add one with `Add(text)`._\n")
		return b.String()
	}

	// The store iterates by id, so newest-first is one call rather than a
	// collect-then-walk-backwards.
	items.EachReverse(func(id store.ID, v any) {
		it := v.(*item)
		mark := " "
		if it.done {
			mark = "x"
		}
		b.WriteString("- [" + mark + "] #" + id.String() + " " +
			it.text + " (" + ui.Addr(it.author) + ")\n")
	})

	return b.String()
}

package todos

import (
	"strings"
	"testing"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/nt/testutils/v0"
)

// reset clears package globals between tests (t.Run/subtests do not reset them).
func reset() {
	items = store.Named("todos: item")
}

// TestAddToggleRemove exercises the full lifecycle through the crossing API.
// Crossing test: takes `cur realm` and calls via cross(cur).
func TestAddToggleRemove(cur realm, t *testing.T) {
	reset()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	id1 := Add(cross(cur), "buy milk")
	if id1 != 1 {
		t.Fatalf("Add first id = %d, want 1", id1)
	}
	id2 := Add(cross(cur), "walk dog")
	if id2 != 2 {
		t.Fatalf("Add second id = %d, want 2", id2)
	}

	open, done := counts()
	if open != 2 || done != 0 {
		t.Fatalf("after adds: open=%d done=%d, want 2/0", open, done)
	}

	// Toggle #1 done.
	Toggle(cross(cur), 1)
	open, done = counts()
	if open != 1 || done != 1 {
		t.Fatalf("after toggle: open=%d done=%d, want 1/1", open, done)
	}

	// Toggle #1 back to open.
	Toggle(cross(cur), 1)
	open, done = counts()
	if open != 2 || done != 0 {
		t.Fatalf("after re-toggle: open=%d done=%d, want 2/0", open, done)
	}

	// Remove #1.
	Remove(cross(cur), 1)
	open, done = counts()
	if open != 1 || done != 0 {
		t.Fatalf("after remove: open=%d done=%d, want 1/0", open, done)
	}
	if items.Has(store.ID(1)) {
		t.Fatalf("item #1 still present after Remove")
	}
}

// TestRender checks the Markdown output shape and counts. Render is not a
// crossing function, so this is a plain test — but the Add calls that seed
// state still need a realm, so it also takes `cur realm`.
func TestRender(cur realm, t *testing.T) {
	reset()

	// Empty board.
	empty := Render("")
	if !strings.Contains(empty, "0 open · 0 done · 0 total") {
		t.Fatalf("empty render missing zero counts:\n%s", empty)
	}
	if !strings.Contains(empty, "No items yet") {
		t.Fatalf("empty render missing placeholder:\n%s", empty)
	}

	bob := testutils.TestAddress("bob")
	testing.SetRealm(testing.NewUserRealm(bob))

	Add(cross(cur), "first")
	Add(cross(cur), "second")
	Add(cross(cur), "third")
	Toggle(cross(cur), 2) // mark #2 done

	out := Render("")

	// Counts line: 2 open, 1 done, 3 total.
	if !strings.Contains(out, "2 open · 1 done · 3 total") {
		t.Fatalf("render counts wrong:\n%s", out)
	}
	// Done checkbox for #2.
	if !strings.Contains(out, "- [x] #2 second") {
		t.Fatalf("render missing done item #2:\n%s", out)
	}
	// Open checkbox for #1.
	if !strings.Contains(out, "- [ ] #1 first") {
		t.Fatalf("render missing open item #1:\n%s", out)
	}
	// Newest first: #3 must appear before #1.
	if strings.Index(out, "#3 third") > strings.Index(out, "#1 first") {
		t.Fatalf("render not newest-first:\n%s", out)
	}
	// Author short form present.
	if !strings.Contains(out, "(`g1") {
		t.Fatalf("render missing author short address:\n%s", out)
	}
}

// TestIDKeyOrdering verifies the store key sorts numerically. v1 asserted the
// same thing about its own idKey, which padded to width 12: that held only
// below the width, since idKey(10^12) is 13 characters and sorts before
// idKey(10^12-1). The store key is 8 bytes for every id, so there is no
// ceiling. Non-crossing: plain signature.
func TestIDKeyOrdering(t *testing.T) {
	if store.ID(2).Key() >= store.ID(10).Key() {
		t.Fatal("id 2 should sort before id 10")
	}
	if store.ID(9).Key() >= store.ID(100).Key() {
		t.Fatal("id 9 should sort before id 100")
	}
	if store.ID(999999999999).Key() >= store.ID(1000000000000).Key() {
		t.Fatal("ordering should survive one past v1's width-12 ceiling")
	}
	if len(store.ID(1).Key()) != len(store.ID(1000000000000).Key()) {
		t.Fatal("every key is the same width")
	}
}

// Realm probe is shaped exactly like a generated instance realm: it owns the
// state, and every exported function is a one-line re-export that forwards
// `cur` into the shared pure package.
package probe

import (
	"gno.land/p/moul/x/framelab/v0"
	"gno.land/p/nt/grc20/v0"
)

var (
	Token  *grc20.Token
	ledger *grc20.PrivateLedger
)

func init(cur realm) {
	Token, ledger = grc20.NewToken("Probe", "PRB", 6, 0, cur)
}

// Run is the instance-realm shape under test.
func Run(cur realm, from address, amount int64) address {
	return framelab.Pull(0, cur, Token, from, amount)
}

// Frame reports what pure-package code sees as its own realm identity.
func Frame(cur realm) (string, address, bool) { return framelab.Who(0, cur) }

package probe

import (
	"chain"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const selfPath = "gno.land/r/moul/x/framelab/probe/v0"

func self() address { return chain.PackageAddress(selfPath) }

// The claim: pure-package code called with a forwarded `cur` still runs in the
// importing realm's frame, so it reports that realm's path and address and its
// `cur` is still accepted as current by grc20's spoof check.
func TestPureCodeKeepsImportingRealmFrame(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	path, addr, isCurrent := Frame(cross(cur))
	uassert.Equal(t, selfPath, path)
	uassert.Equal(t, self().String(), addr.String())
	uassert.True(t, isCurrent)
}

// The same claim, exercised through the operation that actually matters: a
// GRC20 pull issued from inside the pure package must credit the instance
// realm's own address.
func TestPureCodePullsToImportingRealm(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	ledger.Mint(alice, 1_000)
	ledger.Approve(alice, self(), 500)

	testing.SetRealm(testing.NewUserRealm(alice))
	bound := Run(cross(cur), alice, 400)

	uassert.Equal(t, self().String(), bound.String())
	uassert.Equal(t, int64(400), Token.BalanceOf(self()))
	uassert.Equal(t, int64(600), Token.BalanceOf(alice))
	uassert.Equal(t, int64(100), Token.Allowance(alice, self()))
}

// Package lastwords is one string, on chain, forever.
//
// There is a single message slot. Pay more than the last writer paid and the
// slot is yours; when the clock finally runs out, whatever is in it stays there
// permanently. The artefact at the end is the point, so the game is a bidding
// war over an epitaph rather than over a prize.
//
// The three rules exist because the obvious version of this game does not end
// and does not pay:
//
//  1. THE CLOCK TERMINATES. Every write pushes the deadline a fifth of the way
//     to a hard end fixed when the slot opened, and no write can push it past
//     that. A constant extension per action has no end: the pot grows faster
//     than the price of the next write, so there is always a rational next
//     write and the game runs until everyone is bored or broke.
//  2. THE LAST WRITER DOES NOT TAKE THE POT. They take the slot, which is what
//     they were bidding for. The pot is split among everyone ELSE who wrote,
//     pro rata to what they paid. Winner-takes-all makes the second-to-last
//     writer the mark and everyone knows it, which is why nobody joins.
//  3. HALF OF EVERY PAYMENT GOES TO THE WRITER BEING DISPLACED, immediately.
//     A zero-sum game minus gas has no reason for a second player. Overwriting
//     somebody pays them, so being overwritten early is not a loss.
//
// Nothing is ever pushed: payouts are credited to an internal ledger and swept
// by Withdraw. A realm that pays inside a loop over its roster is a gas bomb
// that eventually bricks, and the bigger the game gets the more certain that
// is.
//
// The pieces are libraries, and the realm is the wiring:
// [p/moul/x/games/clock](/p/moul/x/games/clock/v0) owns the deadline and its
// guards, [p/moul/x/games/prorata](/p/moul/x/games/prorata/v0) owns the split,
// and [p/moul/x/daily/pullpayment](/p/moul/x/daily/pullpayment/v0) owns the
// credit ledger.
package lastwords

import (
	"strconv"
	"strings"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/moul/x/daily/pullpayment/v0"
	"gno.land/p/moul/x/games/clock/v0"
	"gno.land/p/moul/x/games/prorata/v0"
	"gno.land/p/nt/avl/v0"
)

const denom = "ugnot"

// The rules, fixed at deploy. Times are block heights.
const (
	// Window is how long the slot stays open with nobody writing.
	Window = int64(2000)
	// Floor is the minimum a write leaves on the clock, so the last stretch
	// stays long enough for a transaction to land in. Without it a decaying
	// extension shrinks to nothing and whoever holds at that moment wins by
	// being unreachable rather than by paying.
	Floor = int64(300)
	// Life is the hard end. No write can push the deadline past start+Life.
	Life = int64(100000)
	// BumpPct is how much of the gap to the hard end a write buys.
	BumpPct = int64(20)
	// DividendPct is the share of a payment credited to the writer being
	// displaced; the rest goes to the pot.
	DividendPct = int64(50)

	// MinWrite is the base price of the slot, in ugnot.
	MinWrite = int64(1000000)
	// PerByte is charged on top, in ugnot per byte of the message. The chain's
	// own storage deposit is 100 ugnot per byte, so this is that plus a premium
	// for occupying the only slot there is.
	PerByte = int64(1000)
	// MaxLen caps the message in bytes, because the message IS the storage
	// cost and an uncapped one is an unbounded write priced at a constant.
	MaxLen = 280
)

var (
	clk     *clock.Clock
	ledger  = pullpayment.New()
	message string
	author  address
	paid    int64    // what the current holder paid
	pot     int64    // what settlement will split
	writers avl.Tree // address string -> int64 total paid
	order   []string // writers in first-write order, so the split is deterministic
	writes  int64
	settled bool
)

func init() {
	open(runtime.ChainHeight())
}

// open resets the game to a fresh slot at height h. It is the only place the
// clock is built, so tests and init cannot disagree about the rules.
func open(h int64) {
	c, err := clock.New(h, Window, Floor, Life)
	if err != nil {
		panic("lastwords: " + err.Error())
	}
	clk = c
	ledger = pullpayment.New()
	message = ""
	author = ""
	paid = 0
	pot = 0
	writers = avl.Tree{}
	order = nil
	writes = 0
	settled = false
}

// Price returns what msg costs to write right now, in ugnot: a base, plus a
// charge per byte, and always at least one ugnot more than the current holder
// paid. Query it before sending; an underpaying write is refused, not refunded.
func Price(msg string) int64 {
	price := MinWrite + int64(len(msg))*PerByte
	if next := paid + 1; next > price {
		price = next
	}
	return price
}

// Write puts msg in the slot and makes the caller its holder. The caller must
// send at least Price(msg) ugnot with the transaction.
//
// Half of the payment is credited to the writer being displaced and the rest
// joins the pot. The deadline is pushed a fifth of the way toward the hard end,
// never past it, and never to less than Floor from now.
//
// Only a direct user transaction may write, so the payment envelope cannot be
// spoofed by an ephemeral MsgRun realm.
func Write(cur realm, msg string) {
	if !cur.Previous().IsUserCall() {
		panic("lastwords: write must be a direct user transaction")
	}
	h := runtime.ChainHeight()
	if clk.Expired(h) {
		panic("lastwords: the slot is closed, these are somebody's last words now")
	}
	if msg == "" {
		panic("lastwords: message must not be empty")
	}
	if len(msg) > MaxLen {
		panic("lastwords: message must be at most " + strconv.Itoa(MaxLen) + " bytes")
	}
	if strings.ContainsAny(msg, "\n\r") {
		panic("lastwords: message must be a single line")
	}

	price := Price(msg)
	sent := unsafe.OriginSend().AmountOf(denom)
	if sent < price {
		panic("lastwords: sent " + strconv.FormatInt(sent, 10) +
			" ugnot, price is " + strconv.FormatInt(price, 10))
	}

	caller := cur.Previous().Address()

	// The displaced writer is paid first, out of the payment that displaced
	// them. Credited, never sent: see the package doc.
	dividend := int64(0)
	if author != "" {
		dividend = sent * DividendPct / 100
		if err := ledger.Credit(author.String(), dividend); err != nil {
			panic("lastwords: " + err.Error())
		}
	}
	pot += sent - dividend

	key := caller.String()
	if _, seen := writers.Get(key).(int64); !seen {
		order = append(order, key)
	}
	writers.Set(key, totalPaid(key)+sent)

	message = msg
	author = caller
	paid = sent
	writes++

	deadline, err := clk.BumpShare(h, BumpPct)
	if err != nil {
		panic("lastwords: " + err.Error())
	}

	chain.Emit("Write",
		"author", key,
		"paid", strconv.FormatInt(sent, 10),
		"dividend", strconv.FormatInt(dividend, 10),
		"deadline", strconv.FormatInt(deadline, 10),
	)
}

// Settle closes the game once the clock has run out, splitting the pot among
// every writer EXCEPT the one holding the slot, pro rata to what each paid.
//
// Anyone may call it: leaving settlement to an interested party is how a pot
// stays unclaimed. It moves no coins, it credits the ledger; Withdraw is what
// pays. If the holder is the only writer there is nobody else to split with,
// so the pot returns to them.
func Settle(cur realm) {
	h := runtime.ChainHeight()
	if !clk.Expired(h) {
		panic("lastwords: still open until height " + strconv.FormatInt(clk.Deadline(), 10))
	}
	if settled {
		panic("lastwords: already settled")
	}
	settled = true
	if pot == 0 {
		return
	}

	holder := author.String()
	payees := []string{}
	weights := []int64{}
	for _, k := range order {
		if k == holder {
			continue
		}
		payees = append(payees, k)
		weights = append(weights, totalPaid(k))
	}
	if len(payees) == 0 {
		// The holder wrote every word there is. Nobody to share with.
		payees = []string{holder}
		weights = []int64{1}
	}

	shares, err := prorata.Split(pot, weights)
	if err != nil {
		panic("lastwords: " + err.Error())
	}

	// A zero share is dropped: CreditMany refuses a non-positive amount, and
	// crediting nothing is not a payment anyway.
	dst := []string{}
	amounts := []int64{}
	for i, s := range shares {
		if s > 0 {
			dst = append(dst, payees[i])
			amounts = append(amounts, s)
		}
	}
	if len(dst) > 0 {
		if err := ledger.CreditMany(dst, amounts); err != nil {
			panic("lastwords: " + err.Error())
		}
	}
	pot = 0

	chain.Emit("Settle",
		"holder", holder,
		"writes", strconv.FormatInt(writes, 10),
		"payees", strconv.Itoa(len(dst)),
	)
}

// Withdraw pays the caller everything credited to them and returns the amount.
// Dividends are claimable while the game runs; settlement shares only after
// Settle.
func Withdraw(cur realm) int64 {
	caller := cur.Previous().Address()
	amount, err := ledger.Withdraw(caller.String())
	if err != nil {
		panic("lastwords: " + err.Error())
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amount)))

	chain.Emit("Withdraw", "payee", caller.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Message returns the slot's current contents, raw. Render is what escapes it.
func Message() string { return message }

// Author returns who holds the slot.
func Author() address { return author }

// Pot returns what settlement will split.
func Pot() int64 { return pot }

// Deadline returns the height the slot closes at.
func Deadline() int64 { return clk.Deadline() }

// Owed returns what an address can Withdraw right now.
func Owed(addr address) int64 { return ledger.Balance(addr.String()) }

// totalPaid returns what an address has paid in total, zero if it never wrote.
func totalPaid(key string) int64 {
	v, ok := writers.Get(key).(int64)
	if !ok {
		return 0
	}
	return v
}

func gnot(ugnot int64) string {
	whole := ugnot / 1000000
	frac := ugnot % 1000000
	s := strconv.FormatInt(whole, 10)
	if frac == 0 {
		return s
	}
	f := strconv.FormatInt(frac, 10)
	for len(f) < 6 {
		f = "0" + f
	}
	for len(f) > 1 && f[len(f)-1] == '0' {
		f = f[:len(f)-1]
	}
	return s + "." + f
}

package lastwords

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/moul/kit/ui/v0"
)

// Render shows the slot, the clock and the money. The message is caller-typed
// text, so it goes through ui.Inline: a stored string that renders as markdown
// is a phishing link on a page nobody can edit, and this realm's whole product
// is a string somebody else wrote.
func Render(path string) string {
	h := runtime.ChainHeight()
	var b strings.Builder

	b.WriteString("# Last Words\n\n")

	if message == "" {
		b.WriteString("_The slot is empty. Whoever writes last, writes forever._\n\n")
	} else {
		b.WriteString("> " + ui.Inline(message) + "\n\n")
		b.WriteString("by " + ui.AddrOf(author.String()) + ", for " + gnot(paid) + " GNOT\n\n")
	}

	closed := clk.Expired(h)
	b.WriteString("## The clock\n\n")
	if closed {
		b.WriteString("**Closed** at height " + strconv.FormatInt(clk.Deadline(), 10) + ". ")
		if settled {
			b.WriteString("Settled: the pot has been credited, call `Withdraw` to sweep yours.\n\n")
		} else {
			b.WriteString("Anyone may call `Settle` to split the pot.\n\n")
		}
	} else {
		b.WriteString("Open for another **" + strconv.FormatInt(clk.Remaining(h), 10) +
			"** blocks, until height " + strconv.FormatInt(clk.Deadline(), 10) + ".\n\n")
		if clk.Final() {
			b.WriteString("This is the **last stretch**: the deadline has reached the hard end at " +
				strconv.FormatInt(clk.HardEnd(), 10) + " and no write can move it again.\n\n")
		} else {
			b.WriteString("Hard end at height " + strconv.FormatInt(clk.HardEnd(), 10) +
				". A write buys " + strconv.FormatInt(BumpPct, 10) +
				"% of the gap to it, never less than " + strconv.FormatInt(Floor, 10) + " blocks.\n\n")
		}
	}

	b.WriteString("## The money\n\n")
	b.WriteString("| | |\n|---|---|\n")
	b.WriteString("| Pot | " + gnot(pot) + " GNOT |\n")
	b.WriteString("| Price of the next write | " + gnot(Price("")) + " GNOT, plus " +
		strconv.FormatInt(PerByte, 10) + " ugnot per byte |\n")
	b.WriteString("| Writes | " + strconv.FormatInt(writes, 10) + " |\n")
	b.WriteString("| Writers | " + strconv.Itoa(len(order)) + " |\n")
	b.WriteString("| Owed, unswept | " + gnot(ledger.TotalOwed()) + " GNOT |\n\n")

	b.WriteString("The holder does **not** take the pot. It goes to everyone else who wrote, ")
	b.WriteString("pro rata to what they paid. Half of every payment is credited to the writer ")
	b.WriteString("it displaced, immediately.\n\n")

	if !ledger.IsEmpty() {
		b.WriteString("## Owed\n\n| address | ugnot |\n|---|---|\n")
		shown := 0
		ledger.Iterate(func(payee string, amount int64) bool {
			b.WriteString("| " + ui.AddrOf(payee) + " | " + strconv.FormatInt(amount, 10) + " |\n")
			shown++
			return shown >= 20
		})
		b.WriteString("\nCall `Withdraw` to sweep yours.\n")
	}

	return b.String()
}

package grc20wrapdemo

import (
	"gno.land/p/nt/ufmt/v0"
)

func Render(path string) string {
	if path == "" {
		return renderIndex()
	}
	return renderOne(path)
}

func renderIndex() string {
	s := "# GRC20 wrapper factory\n\n"
	s += "Wrap any token registered in [grc20reg](/r/nt/grc20reg/v0) into a new one "
	s += "with a different personality, or fuse two into one. Permissionless: "
	s += "no allowlist, no owner, no authority over anybody's balance.\n\n"
	s += ufmt.Sprintf("Escrow account to approve: `%s`\n\n", home.String())

	s += "## Modes\n\n"
	s += "| mode | what the wrapped token does |\n"
	s += "|---|---|\n"
	s += "| `plain` | 1:1 custody receipt |\n"
	s += "| `kilo` | 1 underlying unit becomes 1000 wrapped, +3 decimals |\n"
	s += "| `soulbound` | wrap and unwrap freely, never transferable |\n"
	s += "| `pool` | shares in the escrow; `Donate` pays every holder at once |\n"
	s += "| `sticky` | `pool` plus a 1% exit fee, left behind for whoever stays |\n"
	s += "| `fusion` | one meta-token backed by a fixed bundle of two others |\n"

	s += "\n## Issued here\n\n"
	if len(created) == 0 {
		s += "Nothing yet. Be the first.\n"
	} else {
		s += "| symbol | mode | backing | supply | registry key |\n"
		s += "|---|---|---|---|---|\n"
		for _, sym := range created {
			e := must(sym)
			s += ufmt.Sprintf("| [%s](/r/moul/x/grc20wrapdemo/v0:%s) | %s | %s | %d | `%s` |\n",
				e.symbol, e.symbol, e.mode, e.backing(), e.token().TotalSupply(), e.key)
		}
	}

	s += "\n## Try it\n\n"
	s += "Claim play money from [the faucet](/r/moul/x/grc20faucet/v0), let this realm\n"
	s += "spend it, then wrap:\n\n"
	s += "```\n"
	s += "# 1. get RED and BLUE\n"
	s += "maketx call -pkgpath gno.land/r/moul/x/grc20faucet/v0 -func Claim\n\n"
	s += "# 2. let this realm pull your RED\n"
	s += "maketx call -pkgpath gno.land/r/moul/x/grc20faucet/v0 -func Approve \\\n"
	s += ufmt.Sprintf("  -args RED -args %s -args 1000000\n\n", home.String())
	s += "# 3. create a pool wrapper over RED, then deposit into it\n"
	s += "maketx call -pkgpath gno.land/r/moul/x/grc20wrapdemo/v0 -func NewWrapper \\\n"
	s += "  -args gno.land/r/moul/x/grc20faucet/v0.RED -args pool -args pRED\n"
	s += "maketx call -pkgpath gno.land/r/moul/x/grc20wrapdemo/v0 -func Deposit \\\n"
	s += "  -args pRED -args 500000\n"
	s += "```\n\n"
	s += "Built on [p/moul/x/grc20wrap](/p/moul/x/grc20wrap/v0).\n"
	return s
}

func renderOne(symbol string) string {
	e := byName.Get(symbol)
	if e == nil {
		return "# 404\n\nThis realm has not issued `" + symbol + "`.\n"
	}
	en := e.(*entry)

	s := ufmt.Sprintf("# %s\n\n", en.symbol)
	if en.vault != nil {
		s += en.vault.Summary()
	} else {
		s += en.basket.Summary()
	}
	s += ufmt.Sprintf("\n- mode: `%s`\n", en.mode)
	s += ufmt.Sprintf("- registry key: `%s`\n", en.key)
	s += ufmt.Sprintf("- created by: `%s` at block %d\n", en.creator.String(), en.height)
	s += "\n[back to the index](/r/moul/x/grc20wrapdemo/v0)\n"
	return s
}

// backing names what an entry is redeemable for, for the index table.
func (e *entry) backing() string {
	if e.vault != nil {
		return e.vault.Underlying().GetSymbol()
	}
	out := ""
	for i := 0; i < e.basket.Legs(); i++ {
		tok, per, _ := e.basket.Leg(i)
		if i > 0 {
			out += " + "
		}
		out += ufmt.Sprintf("%dx%s", per, tok.GetSymbol())
	}
	return out
}

// Package grc20wrapdemo is a permissionless wrapper factory for GRC20 tokens.
//
// Point it at any token registered in gno.land/r/nt/grc20reg/v0 and it issues a
// new one backed by it, with a personality you pick from a list. Point it at two
// and it issues a meta-token backed by both. Nothing is whitelisted, nothing is
// owned, and the realm never gains authority over anybody's balance: every
// deposit is pulled with an allowance the holder granted to this realm's address.
//
// The five wrapper modes, all from gno.land/p/moul/x/grc20wrap/v0:
//
//	plain      1:1 custody. A receipt. The boring one that proves the rest works.
//	kilo       1 underlying unit becomes 1000 wrapped ones, +3 decimals.
//	soulbound  wrap and unwrap freely, but the wrapped token never changes hands.
//	pool       shares in the escrow: Donate raises what every share redeems for.
//	sticky     pool, plus a 1% exit fee that stays behind for whoever holds on.
//
// And one fusion mode: NewFusion bundles two registered tokens at a fixed
// proportion into a single meta-token, redeemable back into both.
//
// # Wrapping a wrapper
//
// Every token this realm issues is itself registered in grc20reg, so its key can
// be fed straight back into NewWrapper or NewFusion. A pool over a kilo over a
// plain wrap of RED is legal, works, and is a good way to see how thin the
// abstraction really is.
//
// # The one thing a caller must do first
//
// Approve this realm's address on the underlying token, through THAT token's own
// realm. Home() prints the address. Without it every Deposit fails with
// "insufficient allowance", which is the system working.
//
// Play money to try it on: gno.land/r/moul/x/grc20faucet/v0.
package grc20wrapdemo

import (
	"chain/runtime"

	"gno.land/p/moul/x/grc20wrap/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// entry is one issued token: either a wrapper over a single underlying, or a
// fusion over several. Exactly one of vault/basket is set.
type entry struct {
	symbol  string
	mode    string
	key     string // grc20reg key of the issued token
	vault   *grc20wrap.Vault
	basket  *grc20wrap.Basket
	creator address
	height  int64
}

var (
	ids     seqid.ID
	byName  = avl.NewTree() // symbol -> *entry
	created []string        // symbols, in creation order, for a stable Render
	home    address         // this realm's address: the escrow account
)

func init(cur realm) {
	home = cur.Address()
}

// Home is the address to approve on an underlying token before depositing. It
// is where every escrow this realm holds actually sits.
func Home() address { return home }

// NewWrapper issues a token wrapping `tokenKey`, a key in grc20reg, under the
// given mode, and registers it. It returns the new token's own registry key.
//
// `symbol` is yours to choose, must be unique in this realm, and follows the
// GRC20 rules: 1 to 11 characters of [A-Za-z0-9_-].
func NewWrapper(cur realm, tokenKey, mode, symbol string) string {
	who := caller(cur)
	under := grc20reg.MustGet(tokenKey)
	requireFree(symbol)

	pol, extraDecimals := modePolicy(mode)
	decimals := under.GetDecimals() + extraDecimals
	if decimals > 18 {
		panic(ufmt.Sprintf("%s already has %d decimals; mode %q would need %d, over the GRC20 limit of 18",
			under.GetSymbol(), under.GetDecimals(), mode, decimals))
	}
	name := ufmt.Sprintf("%s (%s wrap of %s)", symbol, mode, under.GetSymbol())

	v := grc20wrap.NewVault(under, pol, name, symbol, decimals, ids.Next(), cur)
	key := grc20reg.Register(cross(cur), v.Token(), "")
	record(&entry{
		symbol:  symbol,
		mode:    mode,
		key:     key,
		vault:   v,
		creator: who,
		height:  runtime.ChainHeight(),
	})
	return key
}

// NewFusion issues a meta-token backed by two registered tokens at a fixed
// proportion: one smallest unit of the meta-token is always worth `perA`
// smallest units of A plus `perB` of B. It returns the new token's registry key.
//
// The proportion never changes, and the meta-token is minted and burned only
// against the real thing, so it cannot drift from its backing or be arbitraged.
// What it can do is make the pair one transferable object.
func NewFusion(cur realm, keyA string, perA int64, keyB string, perB int64, symbol string) string {
	who := caller(cur)
	a := grc20reg.MustGet(keyA)
	b := grc20reg.MustGet(keyB)
	requireFree(symbol)

	decimals := a.GetDecimals()
	if b.GetDecimals() > decimals {
		decimals = b.GetDecimals()
	}
	name := ufmt.Sprintf("%s (%s+%s fusion)", symbol, a.GetSymbol(), b.GetSymbol())

	bk := grc20wrap.NewBasket(
		[]*grc20.Token{a, b},
		[]int64{perA, perB},
		name, symbol, decimals, ids.Next(), cur,
	)
	key := grc20reg.Register(cross(cur), bk.Token(), "")
	record(&entry{
		symbol:  symbol,
		mode:    "fusion",
		key:     key,
		basket:  bk,
		creator: who,
		height:  runtime.ChainHeight(),
	})
	return key
}

// Deposit escrows `amount` of the underlying and mints `symbol` to the caller.
// It returns how much was minted, which is not `amount` unless the mode is
// plain. Approve Home() on the underlying first.
func Deposit(cur realm, symbol string, amount int64) int64 {
	who := caller(cur)
	out, err := mustVault(symbol).Wrap(0, cur, who, amount)
	checkErr(err)
	return out
}

// Withdraw burns `amount` of `symbol` and returns the underlying to the caller.
// It returns how much came back.
func Withdraw(cur realm, symbol string, amount int64) int64 {
	who := caller(cur)
	out, err := mustVault(symbol).Unwrap(0, cur, who, amount)
	checkErr(err)
	return out
}

// Donate escrows `amount` of the underlying for `symbol` and mints nothing.
//
// Under a pool or sticky mode this is a gift to every current holder at once,
// and it is irreversible: there is no share to redeem it with. Under any other
// mode it is a gift to nobody, since the rate ignores the escrow.
func Donate(cur realm, symbol string, amount int64) {
	who := caller(cur)
	checkErr(mustVault(symbol).Donate(0, cur, who, amount))
}

// Fuse escrows every leg of `symbol` and mints `units` of it to the caller.
// Approve Home() on BOTH legs first.
func Fuse(cur realm, symbol string, units int64) {
	who := caller(cur)
	checkErr(mustBasket(symbol).Fuse(0, cur, who, units))
}

// Defuse burns `units` of `symbol` and returns every leg to the caller.
func Defuse(cur realm, symbol string, units int64) {
	who := caller(cur)
	checkErr(mustBasket(symbol).Defuse(0, cur, who, units))
}

// Transfer moves the caller's own units of `symbol`. A soulbound wrapper
// refuses here, and nowhere else.
func Transfer(cur realm, symbol string, to address, amount int64) {
	who := caller(cur)
	e := must(symbol)
	if e.vault != nil {
		checkErr(e.vault.Move(who, to, amount))
		return
	}
	checkErr(e.basket.Move(who, to, amount))
}

// Approve lets `spender` draw `amount` of `symbol` from the caller's balance.
func Approve(cur realm, symbol string, spender address, amount int64) {
	who := caller(cur)
	e := must(symbol)
	if e.vault != nil {
		checkErr(e.vault.Allow(who, spender, amount))
		return
	}
	checkErr(e.basket.Allow(who, spender, amount))
}

// TransferFrom spends an allowance the caller was granted on `symbol`.
func TransferFrom(cur realm, symbol string, from, to address, amount int64) {
	who := caller(cur)
	e := must(symbol)
	if e.vault != nil {
		checkErr(e.vault.MoveFrom(who, from, to, amount))
		return
	}
	checkErr(e.basket.MoveFrom(who, from, to, amount))
}

// Key returns the grc20reg key of the token this realm issued as `symbol`.
func Key(symbol string) string { return must(symbol).key }

// TotalSupply returns how much of `symbol` is outstanding.
func TotalSupply(symbol string) int64 { return must(symbol).token().TotalSupply() }

// BalanceOf returns `owner`'s balance of `symbol`.
func BalanceOf(symbol string, owner address) int64 {
	return must(symbol).token().BalanceOf(owner)
}

// Allowance returns what `owner` let `spender` draw of `symbol`.
func Allowance(symbol string, owner, spender address) int64 {
	return must(symbol).token().Allowance(owner, spender)
}

// Escrow returns the underlying escrowed behind a wrapper.
func Escrow(symbol string) int64 { return mustVault(symbol).Held() }

// Legs returns how many components a fusion has.
func Legs(symbol string) int { return mustBasket(symbol).Legs() }

// Leg describes the i-th component of a fusion: its symbol, the units escrowed
// per meta unit, and the units escrowed so far.
func Leg(symbol string, i int) (string, int64, int64) {
	tok, per, held := mustBasket(symbol).Leg(i)
	return tok.GetSymbol(), per, held
}

// Count is how many tokens this realm has issued.
func Count() int { return len(created) }

// internals
//

// modePolicy maps a mode name to its policy and to the extra decimals the
// wrapped token needs to represent the same value.
func modePolicy(mode string) (grc20wrap.Policy, int) {
	switch mode {
	case "plain":
		return grc20wrap.OneToOne{}, 0
	case "kilo":
		return grc20wrap.Ratio{Num: 1_000, Den: 1}, 3
	case "soulbound":
		return grc20wrap.Soulbound{}, 0
	case "pool":
		return grc20wrap.Pool{}, 0
	case "sticky":
		return grc20wrap.Fee{Base: grc20wrap.Pool{}, UnwrapBPS: 100}, 0
	}
	panic("unknown mode " + mode + " (plain, kilo, soulbound, pool, sticky)")
}

func (e *entry) token() *grc20.Token {
	if e.vault != nil {
		return e.vault.Token()
	}
	return e.basket.Token()
}

func record(e *entry) {
	byName.Set(e.symbol, e)
	created = append(created, e.symbol)
}

func requireFree(symbol string) {
	if byName.Has(symbol) {
		panic("symbol " + symbol + " is already issued by this realm")
	}
}

func must(symbol string) *entry {
	e := byName.Get(symbol)
	if e == nil {
		panic("this realm has not issued " + symbol)
	}
	return e.(*entry)
}

func mustVault(symbol string) *grc20wrap.Vault {
	e := must(symbol)
	if e.vault == nil {
		panic(symbol + " is a fusion; use Fuse and Defuse")
	}
	return e.vault
}

func mustBasket(symbol string) *grc20wrap.Basket {
	e := must(symbol)
	if e.basket == nil {
		panic(symbol + " is a wrapper; use Deposit and Withdraw")
	}
	return e.basket
}

// caller is the account or realm that crossed into this one. Every deposit is
// escrowed from, and every mint credited to, exactly this address.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("grc20wrapdemo: stale realm token")
	}
	return cur.Previous().Address()
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

package grc20wrapdemo

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	faucet "gno.land/r/moul/x/grc20faucet/v0"
)

// Realm state carries over between test functions, but the block height does
// not: every test starts from the same height. The faucet's per-account
// cooldown would therefore fire on the second test to reuse an account, so each
// test claims with its own. TestFaucetCooldown covers the cooldown itself.
func fund(cur realm, t *testing.T, name string) address {
	t.Helper()
	who := testutils.TestAddress(name)
	testing.SetRealm(testing.NewUserRealm(who))
	faucet.Claim(cross(cur))
	faucet.Approve(cross(cur), "RED", Home(), faucet.ClaimAmount)
	faucet.Approve(cross(cur), "BLUE", Home(), faucet.ClaimAmount)
	return who
}

// testing.SetRealm only governs crossing calls made from the frame that called
// it: put it in a helper with no crossing call of its own and it is silently
// ignored, and the caller stays whoever it was. fund() gets away with it
// because it crosses into the faucet right after; switching accounts mid-test
// has to be written inline, which is why there is no act() helper here.

// The plain mode is the baseline: it proves custody actually crosses a realm
// boundary. The RED never belonged to this realm, and it can only ever take
// what the faucet's Approve handed over.
func TestPlainWrapperRoundTrip(cur realm, t *testing.T) {
	alice := fund(cur, t, "w-alice")
	before := faucet.BalanceOf("RED", alice)

	key := NewWrapper(cross(cur), faucet.RedKey, "plain", "wRED")
	uassert.True(t, strings.HasSuffix(key, ".wRED"), "registered under its own symbol: "+key)

	minted := Deposit(cross(cur), "wRED", 400_000)
	uassert.Equal(t, int64(400_000), minted)
	uassert.Equal(t, int64(400_000), BalanceOf("wRED", alice))
	uassert.Equal(t, int64(400_000), Escrow("wRED"))
	uassert.Equal(t, before-400_000, faucet.BalanceOf("RED", alice))
	// The escrow really sits at this realm's address, in the faucet's ledger.
	uassert.Equal(t, int64(400_000), faucet.BalanceOf("RED", Home()))

	back := Withdraw(cross(cur), "wRED", 150_000)
	uassert.Equal(t, int64(150_000), back)
	uassert.Equal(t, int64(250_000), TotalSupply("wRED"))
	uassert.Equal(t, before-250_000, faucet.BalanceOf("RED", alice))
}

// Depositing without an allowance is the default state of the world, and it
// fails. This realm holds no standing authority over anybody's balance.
func TestDepositNeedsAnAllowance(cur realm, t *testing.T) {
	fund(cur, t, "noallow")
	NewWrapper(cross(cur), faucet.RedKey, "plain", "noallow")

	// Revoke what fund() granted.
	faucet.Approve(cross(cur), "RED", Home(), 0)
	uassert.AbortsContains(t, cur, "insufficient allowance", func() {
		Deposit(cross(cur), "noallow", 1)
	})
	uassert.Equal(t, int64(0), TotalSupply("noallow"))
}

// kilo re-denominates a token whose own realm will never redeploy for it.
func TestKiloWrapperAddsThreeDecimals(cur realm, t *testing.T) {
	fund(cur, t, "kilo")
	NewWrapper(cross(cur), faucet.RedKey, "kilo", "kRED")

	minted := Deposit(cross(cur), "kRED", 1_000)
	uassert.Equal(t, int64(1_000_000), minted)
	uassert.Equal(t, int64(1_000), Escrow("kRED"))

	back := Withdraw(cross(cur), "kRED", 999_000)
	uassert.Equal(t, int64(999), back)
	// 999 wrapped units cannot buy back a whole underlying one, so the
	// redemption is refused rather than burning them for nothing.
	uassert.AbortsContains(t, cur, "rounds to zero", func() {
		Withdraw(cross(cur), "kRED", 999)
	})
}

func TestSoulboundWrapperRefusesTransfer(cur realm, t *testing.T) {
	fund(cur, t, "soul")
	bob := testutils.TestAddress("soul-bob")
	NewWrapper(cross(cur), faucet.RedKey, "soulbound", "sRED")
	Deposit(cross(cur), "sRED", 300_000)

	uassert.AbortsContains(t, cur, "soulbound", func() {
		Transfer(cross(cur), "sRED", bob, 1)
	})
	uassert.Equal(t, int64(0), BalanceOf("sRED", bob))

	// The exit stays open: unwrap, and the RED moves as freely as ever.
	back := Withdraw(cross(cur), "sRED", 300_000)
	uassert.Equal(t, int64(300_000), back)
	uassert.Equal(t, int64(0), TotalSupply("sRED"))
}

// Pool: a donation is shared by whoever is holding, and the donor can never
// take it back out.
func TestPoolWrapperSharesDonations(cur realm, t *testing.T) {
	alice := fund(cur, t, "pool-a")
	NewWrapper(cross(cur), faucet.RedKey, "pool", "pRED")
	uassert.Equal(t, int64(100_000), Deposit(cross(cur), "pRED", 100_000))

	bob := fund(cur, t, "pool-b")
	Donate(cross(cur), "pRED", 100_000)
	uassert.Equal(t, int64(200_000), Escrow("pRED"))
	uassert.Equal(t, int64(100_000), TotalSupply("pRED"))
	uassert.Equal(t, int64(0), BalanceOf("pRED", bob)) // a donation mints nothing

	// Buying in afterwards costs twice as much per share.
	uassert.Equal(t, int64(50_000), Deposit(cross(cur), "pRED", 100_000))

	// alice walks away with double what she put in.
	testing.SetRealm(testing.NewUserRealm(alice))
	redBefore := faucet.BalanceOf("RED", alice)
	uassert.Equal(t, int64(200_000), Withdraw(cross(cur), "pRED", 100_000))
	uassert.Equal(t, redBefore+200_000, faucet.BalanceOf("RED", alice))

	// And bob gets back exactly the 100_000 he deposited: his own donation
	// was to the holders, and by then that was alice.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.Equal(t, int64(100_000), Withdraw(cross(cur), "pRED", 50_000))
	uassert.Equal(t, int64(0), Escrow("pRED"))
}

// Sticky: the 1% exit fee is collected by nobody, it is left in the pool, so
// whoever stays longest ends up with it.
func TestStickyWrapperChargesOnTheWayOut(cur realm, t *testing.T) {
	alice := fund(cur, t, "stick-a")
	NewWrapper(cross(cur), faucet.RedKey, "sticky", "fRED")
	Deposit(cross(cur), "fRED", 500_000)

	bob := fund(cur, t, "stick-b")
	Deposit(cross(cur), "fRED", 500_000)
	uassert.Equal(t, int64(1_000_000), TotalSupply("fRED"))

	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.Equal(t, int64(495_000), Withdraw(cross(cur), "fRED", 500_000))

	// The 5_000 alice paid on the way out now backs bob's shares.
	uassert.Equal(t, int64(505_000), Escrow("fRED"))
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.Equal(t, int64(499_950), Withdraw(cross(cur), "fRED", 500_000))
}

// Fusion: one token backed by a fixed bundle of two, and nothing else.
func TestFusionOfRedAndBlue(cur realm, t *testing.T) {
	alice := fund(cur, t, "fuse-a")
	bob := testutils.TestAddress("fuse-b")

	key := NewFusion(cross(cur), faucet.RedKey, 1, faucet.BlueKey, 2, "PURPLE")
	uassert.True(t, strings.HasSuffix(key, ".PURPLE"), key)
	uassert.Equal(t, 2, Legs("PURPLE"))

	redBefore := faucet.BalanceOf("RED", alice)
	blueBefore := faucet.BalanceOf("BLUE", alice)
	Fuse(cross(cur), "PURPLE", 100_000)

	uassert.Equal(t, int64(100_000), BalanceOf("PURPLE", alice))
	uassert.Equal(t, redBefore-100_000, faucet.BalanceOf("RED", alice))
	uassert.Equal(t, blueBefore-200_000, faucet.BalanceOf("BLUE", alice))

	sym, per, held := Leg("PURPLE", 1)
	uassert.Equal(t, "BLUE", sym)
	uassert.Equal(t, int64(2), per)
	uassert.Equal(t, int64(200_000), held)

	// PURPLE moves as one object, and whoever ends up with it can split it
	// back into both legs without ever having touched the faucet.
	Transfer(cross(cur), "PURPLE", bob, 40_000)
	testing.SetRealm(testing.NewUserRealm(bob))
	Defuse(cross(cur), "PURPLE", 40_000)
	uassert.Equal(t, int64(40_000), faucet.BalanceOf("RED", bob))
	uassert.Equal(t, int64(80_000), faucet.BalanceOf("BLUE", bob))
	uassert.Equal(t, int64(60_000), TotalSupply("PURPLE"))
}

// Every token issued here is registered too, so it can be wrapped again.
func TestWrappingAWrapper(cur realm, t *testing.T) {
	fund(cur, t, "nest")
	NewWrapper(cross(cur), faucet.RedKey, "plain", "nRED")
	Deposit(cross(cur), "nRED", 800_000)

	// nRED lives in THIS realm, so the allowance is granted through this
	// realm's own Approve. Same shape, one level up.
	NewWrapper(cross(cur), Key("nRED"), "pool", "nnRED")
	Approve(cross(cur), "nRED", Home(), 800_000)
	uassert.Equal(t, int64(600_000), Deposit(cross(cur), "nnRED", 600_000))

	// The outer wrapper escrows the inner token, not the RED.
	uassert.Equal(t, int64(600_000), Escrow("nnRED"))
	uassert.Equal(t, int64(800_000), Escrow("nRED"))
	uassert.Equal(t, int64(600_000), BalanceOf("nRED", Home()))

	// And it unwinds the whole way back down.
	uassert.Equal(t, int64(600_000), Withdraw(cross(cur), "nnRED", 600_000))
	uassert.Equal(t, int64(800_000), Withdraw(cross(cur), "nRED", 800_000))
	uassert.Equal(t, int64(0), TotalSupply("nRED"))
}

func TestAllowanceOnAWrappedToken(cur realm, t *testing.T) {
	alice := fund(cur, t, "allow-a")
	bob := testutils.TestAddress("allow-b")

	NewWrapper(cross(cur), faucet.RedKey, "plain", "aRED")
	Deposit(cross(cur), "aRED", 500_000)
	Approve(cross(cur), "aRED", bob, 120_000)
	uassert.Equal(t, int64(120_000), Allowance("aRED", alice, bob))

	testing.SetRealm(testing.NewUserRealm(bob))
	TransferFrom(cross(cur), "aRED", alice, bob, 120_000)
	uassert.Equal(t, int64(120_000), BalanceOf("aRED", bob))
	uassert.AbortsContains(t, cur, "insufficient allowance", func() {
		TransferFrom(cross(cur), "aRED", alice, bob, 1)
	})
}

func TestFaucetCooldown(cur realm, t *testing.T) {
	who := fund(cur, t, "cooldown")
	uassert.AbortsContains(t, cur, "too soon", func() {
		faucet.Claim(cross(cur))
	})

	next, ok := faucet.NextClaim(who)
	uassert.True(t, ok, "the account has claimed once")
	testing.SkipHeights(faucet.ClaimEvery + 1)
	faucet.Claim(cross(cur))
	uassert.Equal(t, 2*faucet.ClaimAmount, faucet.BalanceOf("RED", who))
	uassert.True(t, next > 0, "a cooldown was recorded")

	_, ok = faucet.NextClaim(testutils.TestAddress("never"))
	uassert.False(t, ok, "an account that never claimed has no cooldown")
}

func TestRejectsBadInput(cur realm, t *testing.T) {
	fund(cur, t, "bad")
	NewWrapper(cross(cur), faucet.RedKey, "plain", "xRED")
	NewFusion(cross(cur), faucet.RedKey, 1, faucet.BlueKey, 1, "xMIX")

	uassert.AbortsContains(t, cur, "unknown mode", func() {
		NewWrapper(cross(cur), faucet.RedKey, "moon", "xMOON")
	})
	uassert.AbortsContains(t, cur, "already issued by this realm", func() {
		NewWrapper(cross(cur), faucet.RedKey, "plain", "xRED")
	})
	uassert.AbortsContains(t, cur, "unknown token", func() {
		NewWrapper(cross(cur), "gno.land/r/nope/nope.NOPE", "plain", "xNOPE")
	})
	uassert.AbortsContains(t, cur, "is a fusion", func() {
		Deposit(cross(cur), "xMIX", 1)
	})
	uassert.AbortsContains(t, cur, "is a wrapper", func() {
		Fuse(cross(cur), "xRED", 1)
	})
	uassert.AbortsContains(t, cur, "has not issued", func() {
		Deposit(cross(cur), "GHOST", 1)
	})
	uassert.AbortsContains(t, cur, "unknown symbol", func() {
		faucet.Transfer(cross(cur), "GREEN", Home(), 1)
	})
}

func TestRender(cur realm, t *testing.T) {
	fund(cur, t, "render")
	NewWrapper(cross(cur), faucet.RedKey, "pool", "rRED")
	Deposit(cross(cur), "rRED", 250_000)

	index := Render("")
	uassert.True(t, strings.Contains(index, "# GRC20 wrapper factory"), "index heading")
	uassert.True(t, strings.Contains(index, Home().String()), "index shows the escrow address")
	uassert.True(t, strings.Contains(index, "| [rRED](/r/moul/x/grc20wrapdemo/v0:rRED) | pool | RED |"),
		"index lists the wrapper:\n"+index)

	detail := Render("rRED")
	uassert.True(t, strings.Contains(detail, "escrowed underlying: 250000"), detail)
	uassert.True(t, strings.Contains(detail, "- mode: `pool`"), detail)
	uassert.True(t, strings.Contains(detail, "solvent: yes"), detail)

	uassert.True(t, strings.Contains(Render("NOPE"), "404"), "unknown symbol renders a 404")
}

// Package pairreg is the registry every AMM pair instance announces itself to,
// and the unified frontend over all of them.
//
// It is the third artifact of the instance-per-realm pattern: one shared
// p/moul/x/pair/v0 holding the logic, N tiny realms holding one pair each, and
// this realm knowing all of them.
//
// # Why registration cannot be faked, and code cannot be trusted
//
// Register keys an instance by cur.Previous().PkgPath(), which the runtime
// supplies, so an instance cannot claim a path that is not its own. That is
// the whole on-chain guarantee. It is NOT a guarantee about the code at that
// path: gno has no way to read another package's source from inside a realm,
// so nothing here can check that an instance really runs the shared template.
// The mirror image of Ethereum's CREATE2, which proves the code and says
// nothing legible about who deployed it.
//
// Consequences a reader of the index must keep in mind:
//
//   - Reserves shown here are CLAIMED. They are read live from the instance's
//     own struct, which is honest for an instance running the template and
//     arbitrary for one that does not.
//   - Several instances may exist for the same token couple. That is allowed
//     on purpose; there is no canonical pair and no factory to enforce one.
//   - Approving tokens to an instance risks exactly what was approved. Read
//     the instance's source (vm/qfile on its path) before funding it.
//
// # Why the registry can read live state at all
//
// Instances register a *pair.Pair pointer, not an address, the way grc20reg
// registers a *grc20.Token. One vm/qrender here therefore renders the real
// state of every instance, with no indexer and no multicall. It is safe
// because pair.Pair holds only concrete types: an interface or a func field
// would let a hostile instance hand foreign code to this realm's frame.
package pairreg

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/moul/x/pair/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Entry is one registered instance.
type Entry struct {
	Path   string     // the instance realm's package path, supplied by the runtime
	Pair   *pair.Pair // live pointer into the instance's own storage
	Height int64      // chain height at registration
}

// entries maps instance path -> *Entry. couples maps a pair ID
// ("keyA~keyB") -> int, how many instances claim that couple.
var (
	entries avl.Tree
	couples avl.Tree
)

// Register records the calling realm as an instance. Call it from the
// instance's init, so that deploying and listing are one transaction:
//
//	func init(cur realm) {
//		p = pair.New(keyA, keyB, grc20reg.MustGet(keyA), grc20reg.MustGet(keyB))
//		pairreg.Register(cross(cur), p)
//	}
//
// Permissionless by design: anyone may deploy an instance under their own
// address namespace and land here. Spam is self funded, since the registering
// transaction pays for the storage it adds.
func Register(cur realm, p *pair.Pair) {
	caller := cur.Previous()
	path := caller.PkgPath()
	if path == "" {
		panic("pairreg: only a realm can register")
	}
	if p == nil {
		panic("pairreg: nil pair")
	}
	if entries.Has(path) {
		panic("pairreg: already registered: " + path)
	}

	entries.Set(path, &Entry{Path: path, Pair: p, Height: runtime.ChainHeight()})
	couples.Set(p.ID(), countFor(p.ID())+1)

	chain.Emit("RegisterPair",
		"path", path,
		"pair", p.ID(),
	)
}

// Get returns the entry for an instance path, or nil.
func Get(path string) *Entry {
	v := entries.Get(path)
	if v == nil {
		return nil
	}
	return v.(*Entry)
}

// Size returns how many instances are registered.
func Size() int { return entries.Size() }

// Couples returns how many distinct token couples are represented.
func Couples() int { return couples.Size() }

// InstancesFor returns the instance paths claiming a given couple id.
func InstancesFor(id string) []string {
	out := []string{}
	entries.Iterate("", "", func(_ string, value any) bool {
		e := value.(*Entry)
		if e.Pair.ID() == id {
			out = append(out, e.Path)
		}
		return false
	})
	return out
}

// Render is the unified frontend: the index of every instance with its live
// state, or one instance's own page when path is an instance path.
func Render(path string) string {
	if path != "" {
		e := Get(path)
		if e == nil {
			return "# 404\n\nNo instance registered at `" + path + "`.\n"
		}
		out := e.Pair.Render("")
		out += "\n---\n\n"
		out += ufmt.Sprintf("Instance: [`%s`](%s) · registered at height %d · %d instance(s) claim this couple.\n",
			e.Path, webPath(e.Path), e.Height, countFor(e.Pair.ID()))
		return out
	}

	out := "# AMM pairs\n\n"
	out += "One realm per token couple, all running [p/moul/x/pair/v0](/p/moul/x/pair/v0). "
	out += "Anyone can deploy one under their own namespace and it lands here.\n\n"

	if entries.Size() == 0 {
		out += "_No instance yet._\n"
		return out
	}

	out += ufmt.Sprintf("%d instance(s), %d couple(s).\n\n", entries.Size(), couples.Size())
	out += "**Reserves below are claimed by each instance, not verified.** "
	out += "Nothing on chain can check that an instance runs the shared template; read its source before funding it.\n\n"
	out += "| pair | reserves | LP shares | providers | instance |\n"
	out += "|---|---|---|---|---|\n"
	entries.Iterate("", "", func(key string, value any) bool {
		e := value.(*Entry)
		symA, symB := e.Pair.Symbols()
		resA, resB := e.Pair.Reserves()
		out += ufmt.Sprintf("| [%s/%s](/r/moul/x/pairreg/v0:%s) | %d %s / %d %s | %d | %d | [`%s`](%s) |\n",
			symA, symB, key,
			resA, symA, resB, symB,
			e.Pair.TotalShares(), e.Pair.Providers(),
			shortPath(e.Path), webPath(e.Path))
		return false
	})
	return out
}

//
// Internals.
//

func countFor(id string) int {
	v := couples.Get(id)
	if v == nil {
		return 0
	}
	return v.(int)
}

// webPath turns a package path into a gnoweb link.
func webPath(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		return pkgPath[i:]
	}
	return "/" + pkgPath
}

// shortPath drops the chain domain, which is the same on every row.
func shortPath(pkgPath string) string {
	if i := strings.Index(pkgPath, "/"); i >= 0 {
		return pkgPath[i+1:]
	}
	return pkgPath
}

