func TestCreateInAUnionNeedsTheFlag(t *testing.T) {
	sh, _ := shell(t, "/bin/ls", "/usr/glenda/bin/rc")
	run(t, sh, "bind -a /usr/glenda/bin /bin")
	if _, err := sh.Run("echo x > /bin/new"); err == nil {
