// Package bfdemo is the playground for the guest-VM work: a realm that runs
// Brainfuck programs on chain, a slice at a time.
//
// It is a demo of two libraries and carries no logic of its own:
// [p/moul/x/vm/bf](/p/moul/x/vm/bf/v0) is the machine, and
// [p/moul/x/vm/vmkit](/p/moul/x/vm/vmkit/v0) is the host ABI, the fuel meter
// and the instance store.
//
// What it exists to show is the thing gno realm code cannot do for itself: a
// program that runs out of fuel does not fail, it pauses. The realm keeps the
// snapshot, and the next caller pays for the next slice. Upload a program,
// call Step a few times, and watch one computation finish across several
// transactions.
package bfdemo

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"time"

	"gno.land/p/moul/x/vm/bf/v0"
	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Caps. Everything a caller can grow is bounded, because all of it is storage
// somebody pays a deposit on.
const (
	// MaxInstances is how many programs the realm keeps at once. Past it,
	// an upload has to wait for someone to remove one.
	MaxInstances = 64
	// MaxOutput caps the bytes one program may write. Past it the guest is
	// trapped rather than truncated, so rendered output is never a lie.
	MaxOutput = 4096
	// MaxInput caps the call input a program can be given.
	MaxInput = 1024
	// DefaultFuel is the budget an upload gets when it asks for none, and
	// the slice size Step uses when asked for none.
	DefaultFuel = 100000
	// MaxSliceFuel bounds one transaction's work regardless of what the
	// caller asked for.
	MaxSliceFuel = 5000000
)

var (
	// store holds the instances: program, snapshot, status, accounting.
	store = vmkit.NewStore()
	// inputs holds each instance's call input, keyed by id. It is separate
	// from the instance so vmkit.Instance stays the VM-agnostic record it
	// is meant to be.
	inputs = avl.NewTree()
	idgen  seqid.ID
	count  int
)

// host is the realm-backed [vmkit.Host]. One is built per call, wrapping the
// instance being stepped, so a guest's output and authority are scoped to it
// and nothing ambient leaks in.
type host struct {
	inst    *vmkit.Instance
	in      []byte
	kv      *avl.Tree
	overrun bool // the guest wrote past MaxOutput
}

func (h *host) Caller() address { return h.inst.Owner }
func (h *host) Origin() address { return h.inst.Owner }
func (h *host) Now() int64      { return time.Now().Unix() }
func (h *host) Height() int64   { return runtime.ChainHeight() }
func (h *host) Input() []byte   { return h.in }

// Get and Set are scoped to the instance by construction: the tree belongs to
// the instance being stepped, so one program cannot reach another's storage
// even though both live in this one realm. bf never calls them; they are here
// because the ABI is the point.
func (h *host) Get(key []byte) []byte {
	v := h.kv.Get(string(key))
	if v == nil {
		return nil
	}
	return v.([]byte)
}

func (h *host) Set(key, val []byte) { h.kv.Set(string(key), val) }

func (h *host) Output(p []byte) {
	if len(h.inst.Output)+len(p) > MaxOutput {
		h.overrun = true
		return
	}
	h.inst.Output = append(h.inst.Output, p...)
}

func (h *host) Emit(typ string, kv ...string) { chain.Emit(typ, kv...) }

// Send is never granted here. The demo funds no instance, so a guest that
// tries to move coins is refused. That is the capability rule doing its job,
// not a missing feature.
func (h *host) Send(to address, amount int64) error { return vmkit.ErrNotGranted }

func (h *host) Log(msg string) {}

// Upload compiles src and stores it as a new instance, returning its id.
//
// Compilation happens here rather than at the first Step, so an unbalanced
// program is rejected by the transaction that submitted it instead of costing
// somebody else the gas later.
func Upload(cur realm, src, input string, budget int64) string {
	if count >= MaxInstances {
		panic("bfdemo: too many instances, remove one first")
	}
	if len(input) > MaxInput {
		panic("bfdemo: input too long")
	}
	if _, err := bf.CompileDefault(src); err != nil {
		panic("bfdemo: " + err.Error())
	}
	if budget <= 0 {
		budget = DefaultFuel
	}

	id := idgen.Next().String()
	owner := unsafe.PreviousRealm().Address()
	store.Set(vmkit.NewInstance(id, owner, bf.VMName, []byte(src), budget))
	if input != "" {
		inputs.Set(id, input)
	}
	count++

	chain.Emit("bf_upload", "id", id, "bytes", ufmt.Sprintf("%d", len(src)))
	return id
}

// Step runs one slice of the instance: up to `fuel` guest ops, then stop and
// keep the snapshot. Anyone may pay for a slice, not only the owner: a paused
// program that only its owner can advance is a worse demo and no safer, since
// the program and its budget were both fixed at upload.
func Step(cur realm, id string, fuel int64) string {
	inst := store.Get(id)
	if inst == nil {
		panic("bfdemo: no such instance")
	}
	if inst.Status != vmkit.Running {
		panic("bfdemo: instance is " + inst.Status.String())
	}
	if fuel <= 0 {
		fuel = DefaultFuel
	}
	if fuel > MaxSliceFuel {
		fuel = MaxSliceFuel
	}

	prog, err := bf.CompileDefault(string(inst.Program))
	if err != nil {
		panic("bfdemo: " + err.Error())
	}
	h := &host{inst: inst, in: []byte(inputOf(id)), kv: avl.NewTree()}
	if err := inst.Run(bf.NewMachine(prog), h, fuel); err != nil {
		panic("bfdemo: " + err.Error())
	}
	if h.overrun {
		inst.Status = vmkit.Trapped
		inst.Trap = "output limit reached"
	}

	chain.Emit("bf_step",
		"id", id,
		"status", inst.Status.String(),
		"fuel", ufmt.Sprintf("%d", inst.FuelUsed),
	)
	return inst.Status.String()
}

// Remove deletes an instance. Owner only.
func Remove(cur realm, id string) {
	inst := store.Get(id)
	if inst == nil {
		panic("bfdemo: no such instance")
	}
	if inst.Owner != unsafe.PreviousRealm().Address() {
		panic("bfdemo: not your instance")
	}
	store.Remove(id)
	inputs.Remove(id)
	count--
}

func inputOf(id string) string {
	v := inputs.Get(id)
	if v == nil {
		return ""
	}
	return v.(string)
}

package bfdemo

import (
	"strings"
	"testing"

	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

const hello = "++++++++++[>+++++++>++++++++++>+++>+<<<<-]>++.>+.+++++++..+++.>++.<<+++++++++++++++.>.+++.------.--------."

// resetState puts the realm globals back where init() left them. Realm state
// persists for the whole test binary, so every test that asserts on ids or on
// the rendered instance list has to start from here.
func resetState() {
	store = vmkit.NewStore()
	inputs = avl.NewTree()
	idgen = seqid.ID(0)
	count = 0
}

func TestUploadAndRunToCompletion(cur realm, t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(alice))

	id := Upload(cross(cur), hello, "", 0)
	uassert.Equal(t, "halted", Step(cross(cur), id, 0))

	inst := store.Get(id)
	uassert.Equal(t, "Hello World", string(inst.Output))
	uassert.Equal(t, int64(1), inst.Slices)
	uassert.Equal(t, alice, inst.Owner)
}

// TestOneProgramAcrossManyTransactions is what the realm exists to
// demonstrate: the same computation, finished over several calls, each paying
// for its own slice.
func TestOneProgramAcrossManyTransactions(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	id := Upload(cross(cur), hello, "", 0)
	status := ""
	slices := 0
	for slices < 500 {
		status = Step(cross(cur), id, 7)
		slices++
		if status != "running" {
			break
		}
	}

	inst := store.Get(id)
	uassert.Equal(t, "halted", status)
	uassert.Equal(t, "Hello World", string(inst.Output))
	uassert.True(t, inst.Slices > 1, "took more than one slice")
}

func TestInputIsReadThroughTheHost(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	// ",[.,]" echoes its input back.
	id := Upload(cross(cur), ",[.,]", "gno.land", 0)
	uassert.Equal(t, "halted", Step(cross(cur), id, 0))
	uassert.Equal(t, "gno.land", string(store.Get(id).Output))
}

func TestBudgetStopsAProgram(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	id := Upload(cross(cur), hello, "", 12)
	uassert.Equal(t, "out of fuel", Step(cross(cur), id, 0))
	uassert.Equal(t, int64(12), store.Get(id).FuelUsed)

	// And it stays stopped rather than quietly continuing.
	uassert.AbortsContains(t, cur, "instance is out of fuel", func() {
		Step(cross(cur), id, 0)
	})
}

func TestUploadRejectsAMalformedProgram(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	// Rejected by the transaction that submitted it, not by whoever pays
	// for the first slice later.
	uassert.AbortsContains(t, cur, "unmatched", func() {
		Upload(cross(cur), "+++[", "", 0)
	})
	uassert.Equal(t, 0, count)
}

func TestRemoveIsOwnerOnly(cur realm, t *testing.T) {
	resetState()
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Upload(cross(cur), hello, "", 0)

	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "not your instance", func() {
		Remove(cross(cur), id)
	})

	// Anyone may pay for a slice, though: the program and its budget were
	// both fixed at upload.
	uassert.Equal(t, "halted", Step(cross(cur), id, 0))

	testing.SetRealm(testing.NewUserRealm(alice))
	Remove(cross(cur), id)
	uassert.Equal(t, 0, count)
	uassert.True(t, store.Get(id) == nil)
}

func TestOutputIsCappedAndTrapped(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	// A cell set to 1 and printed forever: an infinite writer.
	id := Upload(cross(cur), "+[.]", "", 0)
	status := Step(cross(cur), id, 0)

	inst := store.Get(id)
	uassert.Equal(t, "trapped", status)
	uassert.Equal(t, "output limit reached", inst.Trap)
	uassert.Equal(t, MaxOutput, len(inst.Output))
}

func TestRenderUnknownInstance(t *testing.T) {
	resetState()
	uassert.True(t, strings.Contains(Render("/nope"), "No such instance"))
}

// TestRenderEscapesGuestOutput pins the rule that a realm cannot be fixed in
// place once it is live: everything a caller controls is escaped before it
// reaches the page.
func TestRenderEscapesGuestOutput(cur realm, t *testing.T) {
	resetState()
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("alice")))

	// Print a backtick (96), which would otherwise close the code fence.
	src := strings.Repeat("+", 96) + "."
	id := Upload(cross(cur), src, "", 0)
	Step(cross(cur), id, 0)

	page := Render("/" + id)
	uassert.Equal(t, "`", string(store.Get(id).Output))
	uassert.True(t, strings.Contains(page, "\\x60"), "the backtick is escaped")

	// The comment text in a program never reaches the page at all: only
	// the eight operators do.
	uassert.Equal(t, "+++[-]<>", operatorsOnly("+++ this is a comment [-] </script>"))
}

package bfdemo

import (
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/x/vm/bf/v0"
	"gno.land/p/moul/x/vm/vmkit/v0"
	"gno.land/p/nt/ufmt/v0"
)

// samples are the programs the home page offers, so the realm is usable
// without writing Brainfuck by hand.
var samples = []struct {
	name  string
	src   string
	input string
	note  string
}{
	{
		"Hello World",
		"++++++++++[>+++++++>++++++++++>+++>+<<<<-]>++.>+.+++++++..+++.>++.<<+++++++++++++++.>.+++.------.--------.",
		"",
		"385 guest ops, five tape cells. Finishes in one slice.",
	},
	{
		"Echo the input",
		",[.,]",
		"gno.land",
		"Reads through Host.Input, which is what the naive interpreter could not do at all: it panicked on `,`.",
	},
	{
		"Heavy loop",
		"++++++++++[->++++++++++[->++++++++++[-]<]<]",
		"",
		"About 111k guest ops. Give it 20000 fuel and it takes six slices, which is the point.",
	},
}

// Render is the realm's gnoweb view.
//
//   - "/"      the samples, the instance list, and how the thing works.
//   - "/<id>"  one instance: its program, status, fuel and output.
func Render(path string) string {
	id := strings.TrimPrefix(path, "/")
	id = strings.TrimSpace(id)
	if id == "" {
		return renderHome()
	}
	return renderInstance(id)
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# Brainfuck, on chain, a slice at a time\n\n")
	sb.WriteString("Demo of [`p/moul/x/vm/bf`](/p/moul/x/vm/bf/v0) (the machine) and ")
	sb.WriteString("[`p/moul/x/vm/vmkit`](/p/moul/x/vm/vmkit/v0) (the host ABI, the fuel meter, ")
	sb.WriteString("the instance store). This realm holds no logic of its own.\n\n")
	sb.WriteString("A program here does not run to completion. It runs until its fuel slice is spent, ")
	sb.WriteString("then pauses: the realm keeps the snapshot and the next caller pays for the next slice. ")
	sb.WriteString("Realm code cannot pause itself, and a guest can.\n\n")

	sb.WriteString("## Samples\n\n")
	for _, s := range samples {
		sb.WriteString("**" + ui.Inline(s.name) + "**: " + s.note + "\n\n")
		sb.WriteString("```\n" + s.src + "\n```\n\n")
		sb.WriteString(ui.Action("Upload "+s.name, "Upload",
			"src", s.src, "input", s.input, "budget", "0") + "\n\n")
	}

	sb.WriteString("## Instances\n\n")
	t := ui.NewTable("id", "status", "fuel used", "slices", "output")
	store.ReverseIterate(func(i *vmkit.Instance) bool {
		t.Row(
			"["+i.ID+"](/r/moul/x/vm/bfdemo/v0:"+i.ID+")",
			i.Status.String(),
			ufmt.Sprintf("%d", i.FuelUsed),
			ufmt.Sprintf("%d", i.Slices),
			"`"+ui.Cell(printable(i.Output, 24))+"`",
		)
		return false
	})
	sb.WriteString(t.OrEmpty("No instances yet. Upload one of the samples above."))
	sb.WriteString("\n\n")

	sb.WriteString("## Limits\n\n")
	lt := ui.NewTable("limit", "value")
	lt.Row("instances", ufmt.Sprintf("%d", MaxInstances))
	lt.Row("source bytes", ufmt.Sprintf("%d", bf.MaxSource))
	lt.Row("input bytes", ufmt.Sprintf("%d", MaxInput))
	lt.Row("output bytes", ufmt.Sprintf("%d", MaxOutput))
	lt.Row("fuel per slice", ufmt.Sprintf("%d", MaxSliceFuel))
	lt.Row("tape cells", ufmt.Sprintf("%d", bf.TapeSize))
	sb.WriteString(lt.String())
	return sb.String()
}

func renderInstance(id string) string {
	var sb strings.Builder
	sb.WriteString("# Instance " + ui.Inline(id) + "\n\n")
	sb.WriteString("[← all instances](/r/moul/x/vm/bfdemo/v0)\n\n")

	inst := store.Get(id)
	if inst == nil {
		sb.WriteString("**No such instance.** It was never uploaded, or its owner removed it.\n")
		return sb.String()
	}

	t := ui.NewTable("field", "value")
	t.Row("owner", ui.Addr(inst.Owner))
	t.Row("vm", ui.Cell(inst.VM))
	t.Row("status", inst.Status.String())
	if inst.Trap != "" {
		t.Row("trap", ui.Cell(inst.Trap))
	}
	t.Row("fuel used", ufmt.Sprintf("%d", inst.FuelUsed))
	t.Row("fuel budget", fuelText(inst.FuelBudget))
	t.Row("slices", ufmt.Sprintf("%d", inst.Slices))
	t.Row("source bytes", ufmt.Sprintf("%d", len(inst.Program)))
	t.Row("snapshot bytes", ufmt.Sprintf("%d", len(inst.Snapshot)))
	sb.WriteString(t.String())
	sb.WriteString("\n")

	// The source is caller-supplied, and everything outside the eight
	// operators is a comment that may hold anything at all. Show the
	// program the machine actually compiled, which cannot contain a
	// backtick or a newline and so cannot break out of the fence.
	sb.WriteString("## Program\n\n```\n" + operatorsOnly(string(inst.Program)) + "\n```\n\n")

	sb.WriteString("## Output\n\n")
	if len(inst.Output) == 0 {
		sb.WriteString(ui.Empty("Nothing written yet."))
	} else {
		sb.WriteString("```\n" + printable(inst.Output, MaxOutput) + "\n```\n")
	}
	sb.WriteString("\n")

	if inst.Status == vmkit.Running {
		sb.WriteString(ui.Action("Run 10000 more fuel", "Step", "id", id, "fuel", "10000"))
		sb.WriteString(" · ")
		sb.WriteString(ui.Action("Run 100000 more fuel", "Step", "id", id, "fuel", "100000"))
		sb.WriteString("\n")
	} else {
		sb.WriteString("This instance is **" + inst.Status.String() + "** and cannot be stepped again.\n")
	}
	return sb.String()
}

func fuelText(n int64) string {
	if n == vmkit.Unmetered {
		return "unmetered"
	}
	return ufmt.Sprintf("%d", n)
}

// operatorsOnly strips a program down to the eight characters the language
// defines. Everything else is a comment by definition, and a comment is
// attacker-controlled text that has no business reaching a renderer.
func operatorsOnly(src string) string {
	var sb strings.Builder
	for i := 0; i < len(src); i++ {
		switch src[i] {
		case '+', '-', '<', '>', '[', ']', '.', ',':
			sb.WriteByte(src[i])
		}
	}
	if sb.Len() == 0 {
		return "(no operators: this program does nothing)"
	}
	return sb.String()
}

// printable renders guest output for a code fence: printable ASCII as itself,
// everything else as an escape. A guest writes arbitrary bytes, so this is
// the only form of it that is safe to show.
func printable(b []byte, max int) string {
	if len(b) == 0 {
		return ""
	}
	truncated := false
	if len(b) > max {
		b, truncated = b[:max], true
	}
	const hexDigits = "0123456789abcdef"
	var sb strings.Builder
	for _, c := range b {
		switch {
		case c == '\n':
			sb.WriteString("\\n")
		case c == '\t':
			sb.WriteString("\\t")
		case c == '\\':
			sb.WriteString("\\\\")
		case c == '`':
			sb.WriteString("\\x60")
		case c >= 0x20 && c < 0x7f:
			sb.WriteByte(c)
		default:
			sb.WriteString("\\x")
			sb.WriteByte(hexDigits[c>>4])
			sb.WriteByte(hexDigits[c&0x0f])
		}
	}
	if truncated {
		sb.WriteString("…")
	}
	return sb.String()
}

// Package ns is a Plan 9 namespace server for gno.land.
//
// Every account gets a private, persistent namespace: its own RAM root plus a
// mount table it alone controls. Realms publish file trees into /srv, accounts
// bind those trees wherever they like, and a read-only rc shell renders the
// whole thing in gnoweb.
//
// This is the part of Plan 9 that gno does not otherwise have. The chain has a
// single global tree of realm paths that looks the same to everybody; here a
// name means what YOU bound it to. Composing two realms that were never
// written to work together stops being a redeploy and becomes a transaction:
//
//	gnokey maketx call -pkgpath gno.land/r/moul/x/plan9/ns/v0 -func Exec \
//	  -args 'bind -ac /srv/dev /dev; echo hello > /tmp/greeting'
//
// SECURITY. Mounted trees are READ-ONLY by construction: ninep.File has no
// mutating method, so grafting a foreign realm's tree into your namespace
// cannot be turned into a write against that realm. Writes only ever reach a
// memfs tree this realm created for you. A crossing write method would mint
// THIS realm's frame for the callee, which is the confused-deputy shape that
// r/gov/dao's Executor relies on deliberately and p/nt/grc20's Teller refuses
// deliberately; it is out of scope for v0. See moul/gno-contracts#136.
//
// NOTICE. Plan 9 from Bell Labs is the work of the Computing Science Research
// Center at Bell Labs; the name and the marks are theirs, and the copyright is
// held by the Plan 9 Foundation (https://p9f.org). This realm is not
// affiliated with, endorsed by, or sponsored by them, and contains no Plan 9
// code: it borrows the vocabulary so that the design reads without a glossary,
// and it is an homage, asking what that ecosystem's spirit looks like on a
// chain. Full attribution: NOTICE.md at the root of moul/gno-contracts.
package ns

import (
	"chain/runtime"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"

	"gno.land/p/moul/realmpath/v0"

	memfs "gno.land/p/moul/x/plan9/memfs/v0"
	ninep "gno.land/p/moul/x/plan9/ninep/v0"
	nspkg "gno.land/p/moul/x/plan9/ns/v0"
	rc "gno.land/p/moul/x/plan9/rc/v0"
)

// DemoKey names the namespace gnoweb browses when no ?u= is given. It is a
// plain string rather than an address so it can never collide with one.
const DemoKey = "demo"

type service struct {
	file  ninep.File
	owner string  // pkgpath of the realm that posted it
	addr  address // that realm's address
	since int64   // block height of the posting
}

type space struct {
	fs *memfs.FS
	ns *nspkg.Ns
}

var (
	services = avl.NewTree() // name -> *service
	spaces   = avl.NewTree() // address string (or DemoKey) -> *space
)

func init() {
	seedDemo()
}

// ---------------------------------------------------------------- /srv

// srvDir is the synthetic directory that makes posted services reachable by
// name. It is written out by hand rather than built with synfs because its
// contents change as realms post, and because implementing ninep.File
// directly is meant to look easy: four methods, no state of its own.
type srvDir struct{}

func (d *srvDir) Stat() ninep.Stat {
	return ninep.Stat{
		Qid:   ninep.Qid{Type: ninep.QTDIR, Path: 1},
		Mode:  ninep.DMDIR | 0555,
		Mtime: runtime.ChainHeight(),
		Name:  "srv",
		Uid:   "sys",
		Gid:   "sys",
		Muid:  "sys",
	}
}

func (d *srvDir) Walk(name string) (ninep.File, error) {
	if !ninep.ValidName(name) {
		return nil, ninep.ErrBadName
	}
	v := services.Get(name)
	if v == nil {
		return nil, ninep.ErrNotExist
	}
	return v.(*service).file, nil
}

func (d *srvDir) Read(off, count int64) (string, error) { return "", ninep.ErrIsDir }

func (d *srvDir) ReadDir() ([]ninep.Stat, error) {
	out := []ninep.Stat{}
	services.Iterate("", "", func(k string, v any) bool {
		st := v.(*service).file.Stat()
		st.Name = k // the posted name, not whatever the server calls its root
		out = append(out, st)
		return false
	})
	return out, nil
}

var srvRoot = &srvDir{}

// ---------------------------------------------------------------- posting

// Post publishes a file tree under name in /srv, where any account can bind
// it. The posting realm is recorded and is the only one that may Unpost.
//
// Names are first come, first served, which is fine for an experiment and
// would not be for anything else.
func Post(cur realm, name string, f ninep.File) {
	if !cur.IsCurrent() {
		panic("post: cur is not the caller's live realm")
	}
	if !ninep.ValidName(name) {
		panic("post: " + ninep.ErrBadName.Error())
	}
	if f == nil {
		panic("post: nil file server")
	}
	prev := cur.Previous()
	if existing := services.Get(name); existing != nil {
		if existing.(*service).owner != prev.PkgPath() {
			panic("post: " + name + " is already posted by " + existing.(*service).owner)
		}
	}
	services.Set(name, &service{
		file:  f,
		owner: prev.PkgPath(),
		addr:  prev.Address(),
		since: runtime.ChainHeight(),
	})
}

// Unpost withdraws a service. Only the realm that posted it may do so.
func Unpost(cur realm, name string) {
	if !cur.IsCurrent() {
		panic("unpost: cur is not the caller's live realm")
	}
	v := services.Get(name)
	if v == nil {
		panic("unpost: " + ninep.ErrNotExist.Error())
	}
	if v.(*service).owner != cur.Previous().PkgPath() {
		panic("unpost: " + name + " belongs to " + v.(*service).owner)
	}
	services.Remove(name)
}

// Services lists the posted service names, in order.
func Services() []string {
	out := []string{}
	services.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

// ---------------------------------------------------------------- namespaces

// newSpace builds the default namespace, which is this chain's /lib/namespace:
// a private ram root, the mount points that Plan 9 requires to exist before
// anything can be bound onto them, /srv mounted, and /dev bound from it when a
// device server has been posted.
func newSpace(owner string) *space {
	now := runtime.ChainHeight()
	fs := memfs.New(owner, now)
	fs.MkdirAll("/srv", now)
	fs.MkdirAll("/dev", now)
	fs.MkdirAll("/tmp", now)

	n := nspkg.New(fs.Root())
	n.Mount(srvRoot, "#s", "/srv", nspkg.MREPL)
	if services.Has("dev") {
		n.Bind("/srv/dev", "/dev", nspkg.MREPL)
	}
	return &space{fs: fs, ns: n}
}

func spaceFor(key string) *space {
	if v := spaces.Get(key); v != nil {
		return v.(*space)
	}
	sp := newSpace(key)
	spaces.Set(key, sp)
	return sp
}

func peek(key string) *space {
	if v := spaces.Get(key); v != nil {
		return v.(*space)
	}
	return nil
}

// seedDemo builds the namespace gnoweb shows by default. It is deliberately
// reproducible: an example test resets it before rendering.
func seedDemo() {
	spaces.Remove(DemoKey)
	sp := spaceFor(DemoKey)
	now := runtime.ChainHeight()
	sp.fs.WriteFile("/tmp/greeting", "hello from a namespace\n", now)
	sp.fs.MkdirAll("/usr/glenda/bin", now)
	sp.fs.WriteFile("/usr/glenda/bin/rc", "#!/bin/rc\n", now)
	sp.fs.MkdirAll("/bin", now)
	sp.fs.WriteFile("/bin/ls", "system ls\n", now)
	sp.ns.Bind("/usr/glenda/bin", "/bin", nspkg.MAFTER|nspkg.MCREATE)
	sp.ns.Cd("/usr/glenda")
}

// ResetDemo rebuilds the demo namespace. Anyone may call it: it is a demo, and
// the alternative is a demo that the first visitor ruins for everybody.
func ResetDemo(cur realm) { seedDemo() }

// ---------------------------------------------------------------- shell

// Exec runs a command line against the CALLER's namespace and returns its
// output. The namespace belongs to cur.Previous().Address(), so a user gets
// theirs and a realm gets its own.
//
// An error panics, so a half-applied command line reverts with the
// transaction rather than leaving a namespace nobody asked for.
func Exec(cur realm, line string) string {
	if !cur.IsCurrent() {
		panic("exec: cur is not the caller's live realm")
	}
	key := cur.Previous().Address().String()
	sp := spaceFor(key)
	sh := rc.New(sp.ns, rc.ReadWrite, runtime.ChainHeight)
	out, err := sh.Run(line)
	if err != nil {
		panic(err.Error())
	}
	return out
}

// Reset discards the caller's namespace, so the next use rebuilds the default.
func Reset(cur realm) {
	if !cur.IsCurrent() {
		panic("reset: cur is not the caller's live realm")
	}
	spaces.Remove(cur.Previous().Address().String())
}

// Run executes a READ-ONLY command line against key's namespace. It is the
// query side of Exec: no transaction, no writes, safe from Render.
func Run(key, line string) (string, error) {
	sp := peek(key)
	if sp == nil {
		return "", errors.New("no namespace for " + key)
	}
	sh := rc.New(sp.ns, rc.ReadOnly, runtime.ChainHeight)
	return sh.Run(line)
}

// Namespace returns key's mount table, in ns(1) format.
func Namespace(key string) string {
	sp := peek(key)
	if sp == nil {
		return ""
	}
	return sp.ns.String()
}

// Keys lists the namespaces that exist, in order.
func Keys() []string {
	out := []string{}
	spaces.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

// ---------------------------------------------------------------- render

// Render browses a namespace.
//
//	Render("")                  overview, posted services, how to drive it
//	Render("ns?u=<key>")        the mount table
//	Render("ls/bin?u=<key>")    a directory listing (ls -l)
//	Render("cat/tmp/greeting")  a file
//	Render("stat/bin")          the 9P stat, with the union width
//	Render("walk/bin/rc")       how each element of a path resolves
//	Render("rc?c=<command>")    any read-only rc command line
//
// ?u= selects the namespace; it defaults to the demo one.
func Render(path string) string {
	req := realmpath.Parse(path)
	key := req.Query.Get("u")
	if key == "" {
		key = DemoKey
	}
	parts := req.PathParts()
	if len(parts) == 0 || parts[0] == "" {
		return renderHome(key)
	}

	cmd := parts[0]
	rest := "/" + strings.Join(parts[1:], "/")
	var line string
	switch cmd {
	case "ns":
		return renderCmd(key, "ns", "ns")
	case "ls":
		line = "ls -l " + quote(rest)
	case "cat":
		line = "cat " + quote(rest)
	case "stat":
		line = "stat " + quote(rest)
	case "walk":
		line = "walk " + quote(rest)
	case "rc":
		line = req.Query.Get("c")
		if line == "" {
			line = "help"
		}
	default:
		return "# 404\n\nunknown command `" + cmd + "`. Try `ls`, `cat`, `stat`, `walk`, `ns` or `rc?c=...`.\n"
	}
	return renderCmd(key, line, cmd+" "+rest)
}

func renderCmd(key, line, title string) string {
	var b strings.Builder
	b.WriteString("# " + title + "\n\n")
	b.WriteString("namespace: `" + key + "`\n\n")
	out, err := Run(key, line)
	if err != nil {
		b.WriteString("```\n" + err.Error() + "\n```\n")
	} else if out == "" {
		b.WriteString("_(no output)_\n")
	} else {
		b.WriteString("```\n" + out + "```\n")
	}
	b.WriteString("\n[namespace](:ns?u=" + key + ") · [root](:ls?u=" + key +
		") · [home](:)\n")
	return b.String()
}

func renderHome(key string) string {
	var b strings.Builder
	b.WriteString("# plan9: namespaces for gno\n\n")
	b.WriteString("A Plan 9 namespace server. Every account owns a private mount table over ")
	b.WriteString("[9P-shaped](https://9p.io/sys/doc/9.html) file trees: realms post trees ")
	b.WriteString("into `/srv`, you `bind` them where you want them, and a name means what ")
	b.WriteString("*you* bound it to.\n\n")

	b.WriteString("## /srv\n\n")
	if services.Size() == 0 {
		b.WriteString("_No service is posted yet._\n\n")
	} else {
		b.WriteString("| name | posted by | since |\n|---|---|---|\n")
		services.Iterate("", "", func(k string, v any) bool {
			s := v.(*service)
			b.WriteString("| `" + k + "` | [`" + s.owner + "`](" +
				strings.TrimPrefix(s.owner, "gno.land") + ") | " +
				strconv.FormatInt(s.since, 10) + " |\n")
			return false
		})
		b.WriteString("\n")
	}

	b.WriteString("## The demo namespace\n\n")
	b.WriteString("```\n" + Namespace(DemoKey) + "```\n\n")
	b.WriteString("`/bin` is a union: the system `/bin` first, then `/usr/glenda/bin`, ")
	b.WriteString("with `-c` so new files land in the second. Listing it shows both members ")
	b.WriteString("because a Plan 9 union is a concatenation, so shadowing stays visible.\n\n")
	b.WriteString("- [ns](:ns) · [ls /](:ls) · [ls /bin](:ls/bin) · ")
	b.WriteString("[cat /tmp/greeting](:cat/tmp/greeting) · [walk /bin/rc](:walk/bin/rc)\n")
	b.WriteString("- any read-only command: [`rc?c=ls -l /srv`](:rc?c=ls%20-l%20/srv)\n\n")

	b.WriteString("## Your own namespace\n\n")
	b.WriteString("```\n")
	b.WriteString("gnokey maketx call -pkgpath gno.land/r/moul/x/plan9/ns/v0 \\\n")
	b.WriteString("  -func Exec -args 'bind -ac /srv/dev /dev; echo hi > /tmp/f'\n")
	b.WriteString("```\n\n")
	b.WriteString("Then browse it with `?u=<your address>`. `Reset` throws it away.\n\n")

	b.WriteString("## Namespaces\n\n")
	keys := Keys()
	for _, k := range keys {
		b.WriteString("- [`" + k + "`](:ns?u=" + k + ")\n")
	}
	b.WriteString("\nDesign and analysis: ")
	b.WriteString("[moul/gno-contracts#136](https://github.com/moul/gno-contracts/issues/136).\n")
	b.WriteString("\n_Not affiliated with Plan 9. Plan 9 from Bell Labs is the ")
	b.WriteString("work of the Computing Science Research Center at Bell Labs; the name ")
	b.WriteString("and the marks are theirs, and the copyright is held by the ")
	b.WriteString("[Plan 9 Foundation](https://p9f.org). This realm borrows the ")
	b.WriteString("vocabulary and none of the code: it is an homage, asking what that ")
	b.WriteString("ecosystem's spirit looks like on a chain._\n")
	return b.String()
}

// quote wraps a path for rc if it needs it.
func quote(s string) string {
	if !strings.ContainsAny(s, " \t'") {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

package ns

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"

	ninep "gno.land/p/moul/x/plan9/ninep/v0"
	synfs "gno.land/p/moul/x/plan9/synfs/v0"
)

// probe is a tiny read-only server, standing in for another realm's tree.
func probe(name, contents string) ninep.File {
	t := synfs.New(name, "sys", func() int64 { return 1 })
	t.Root().Add("value", func() string { return contents })
	return t.Root()
}

func TestDemoNamespaceIsSeeded(t *testing.T) {
	seedDemo()
	out, err := Run(DemoKey, "ls -u /bin")
	if err != nil {
		t.Fatalf("ls: %v", err)
	}
	if out != "ls\nrc\n" {
		t.Errorf("the demo /bin should be a union of two directories: %q", out)
	}
	if got := Namespace(DemoKey); !strings.Contains(got, "bind -ac /usr/glenda/bin /bin") {
		t.Errorf("mount table: %q", got)
	}
	if got, _ := Run(DemoKey, "cat /tmp/greeting"); got != "hello from a namespace\n" {
		t.Errorf("greeting: %q", got)
	}
}

func TestRunIsReadOnly(t *testing.T) {
	seedDemo()
	if _, err := Run(DemoKey, "echo x > /tmp/f"); err == nil {
		t.Fatal("Render's shell must refuse a write")
	}
	if _, err := Run(DemoKey, "rm /tmp/greeting"); err == nil {
		t.Fatal("Render's shell must refuse a remove")
	}
	if _, err := Run("nobody", "ls /"); err == nil {
		t.Fatal("an unknown namespace should not be created by a read")
	}
}

func TestPostAndBind(cur realm, t *testing.T) {
	services.Remove("probe")
	Post(cross(cur), "probe", probe("probe", "42"))

	found := false
	for _, s := range Services() {
		if s == "probe" {
			found = true
		}
	}
	if !found {
		t.Fatalf("probe is not in /srv: %v", Services())
	}

	// A fresh namespace sees it through /srv without importing anything.
	spaces.Remove("tester")
	spaceFor("tester")
	defer spaces.Remove("tester")
	out, err := Run("tester", "cat /srv/probe/value")
	if err != nil {
		t.Fatalf("cat through /srv: %v", err)
	}
	if out != "42" {
		t.Errorf("got %q, want 42", out)
	}
	services.Remove("probe")
}

func TestExecWritesToTheCallersOwnNamespace(cur realm, t *testing.T) {
	alice := testutils.TestAddress("alice")
	bob := testutils.TestAddress("bob")
	spaces.Remove(alice.String())
	spaces.Remove(bob.String())

	testing.SetRealm(testing.NewUserRealm(alice))
	Exec(cross(cur), "echo 'alice was here' > /tmp/note")

	testing.SetRealm(testing.NewUserRealm(bob))
	Exec(cross(cur), "echo 'bob was here' > /tmp/note")

	got, err := Run(alice.String(), "cat /tmp/note")
	if err != nil {
		t.Fatalf("alice: %v", err)
	}
	if got != "alice was here\n" {
		t.Errorf("alice's namespace: %q", got)
	}
	if got, _ = Run(bob.String(), "cat /tmp/note"); got != "bob was here\n" {
		t.Errorf("bob's namespace: %q", got)
	}

	// Reset throws a namespace away; the next use rebuilds the default.
	testing.SetRealm(testing.NewUserRealm(alice))
	Reset(cross(cur))
	if _, err := Run(alice.String(), "cat /tmp/note"); err == nil {
		t.Error("the namespace should be gone after Reset")
	}
	spaces.Remove(alice.String())
	spaces.Remove(bob.String())
}

func TestExecBindsIntoTheCallersNamespace(cur realm, t *testing.T) {
	services.Remove("probe")
	Post(cross(cur), "probe", probe("probe", "42"))
	defer services.Remove("probe")

	erin := testutils.TestAddress("erin")
	spaces.Remove(erin.String())
	testing.SetRealm(testing.NewUserRealm(erin))
	Exec(cross(cur), "bind /srv/probe /dev")

	if got := mustRun(t, erin.String(), "cat /dev/value"); got != "42" {
		t.Errorf("read through the mount: %q", got)
	}
	if ns := Namespace(erin.String()); !strings.Contains(ns, "bind /srv/probe /dev") {
		t.Errorf("mount table: %q", ns)
	}
	spaces.Remove(erin.String())
}

func TestSrvListingUsesThePostedName(cur realm, t *testing.T) {
	services.Remove("aliased")
	// The server calls its own root "probe"; /srv must show it as "aliased".
	Post(cross(cur), "aliased", probe("probe", "x"))
	defer services.Remove("aliased")

	spaces.Remove("lister")
	spaceFor("lister")
	out := mustRun(t, "lister", "ls /srv")
	if !strings.Contains(out, "aliased") {
		t.Errorf("ls /srv: %q", out)
	}
	if strings.Contains(out, "probe") {
		t.Errorf("/srv leaked the server's own root name: %q", out)
	}
	spaces.Remove("lister")
}

func mustRun(t *testing.T, key, line string) string {
	t.Helper()
	out, err := Run(key, line)
	if err != nil {
		t.Fatalf("%s: %v", line, err)
	}
	return out
}

// --- the boundary. Three properties the suite would be unsafe without. -------

// A /srv name belongs to the realm that posted it: first come, first served,
// and then locked.
func TestPostRejectsASecondOwner(cur realm, t *testing.T) {
	services.Remove("taken")
	Post(cross(cur), "taken", probe("taken", "first"))
	defer services.Remove("taken")

	testing.SetRealm(testing.NewCodeRealm("gno.land/r/other/thing/v0"))
	uassert.AbortsWithMessage(t, cur,
		"post: taken is already posted by gno.land/r/moul/x/plan9/ns/v0",
		func() { Post(cross(cur), "taken", probe("taken", "second")) })
}

// Grafting another realm's tree into your namespace gives you reads and
// nothing else. ninep.File has no mutating method, so there is no route from a
// mount to a write against the realm that posted it.
func TestMountedTreesAreReadOnly(cur realm, t *testing.T) {
	services.Remove("probe")
	Post(cross(cur), "probe", probe("probe", "read me"))
	defer services.Remove("probe")

	frank := testutils.TestAddress("frank")
	spaces.Remove(frank.String())
	defer spaces.Remove(frank.String())

	testing.SetRealm(testing.NewUserRealm(frank))
	Exec(cross(cur), "bind /srv/probe /dev")
	uassert.Equal(t, "read me", mustRun(t, frank.String(), "cat /dev/value"))
	uassert.AbortsWithMessage(t, cur, "echo: read-only file server",
		func() { Exec(cross(cur), "echo nope > /dev/value") })
}

// A command line stops at the first error and the error leaves the realm as an
// abort, so a half-applied Exec reverts with its transaction instead of
// leaving a namespace nobody asked for.
func TestExecAbortsAtTheFirstError(cur realm, t *testing.T) {
	grace := testutils.TestAddress("grace")
	spaces.Remove(grace.String())
	defer spaces.Remove(grace.String())

	testing.SetRealm(testing.NewUserRealm(grace))
	uassert.AbortsWithMessage(t, cur, "cat: file does not exist",
		func() { Exec(cross(cur), "echo ok > /tmp/a; cat /absent; echo never > /tmp/b") })
}

func TestRenderUnknownCommand(t *testing.T) {
	if got := Render("nope/x"); !strings.Contains(got, "404") {
		t.Errorf("got %q", got)
	}
}

